def weird_algorithm(n: int) -> int:
    result = n
    while result != 1:
        if result % 2 == 0:
            result //= 2
        else:
            result = result * 3 + 1
    return result

def number_spiral(y: int, x: int) -> int:
    if y > x:
        ans = (y - 1) * (y - 1)
        return ans + x if y % 2 != 0 else ans + 2 * y - x
    else:
        ans = (x - 1) * (x - 1)
        return ans + y if x % 2 == 0 else ans + 2 * x - y

