def apartments(k: int, a: List[int], b: List[int]) -> int:
    a = sorted(a)
    b = sorted(b)
    i = j = count = 0
    while i < len(a) and j < len(b):
        if abs(a[i] - b[j]) <= k:
            i += 1; j += 1; count += 1
        elif a[i] < b[j]:
            i += 1
        else:
            j += 1
    return count

