import bisect

def concert_tickets(prices: List[int], payments: List[int]) -> List[int]:
    sorted_prices = sorted(prices)
    result = []
    for pay in payments:
        idx = bisect.bisect_right(sorted_prices, pay) - 1
        if idx < 0:
            result.append(-1)
        else:
            result.append(sorted_prices[idx])
            sorted_prices.pop(idx)
    return result

def dice_combinations(dice: int, target: int) -> int:
    dp = [0] * (target + 1)
    dp[0] = 1
    for i in range(1, target + 1):
        for j in range(1, min(i, dice) + 1):
            dp[i] = (dp[i] + dp[i - j]) % 1000000007
    return dp[target]

