def removing_digits(n: int) -> int:
    dp = [float('inf')] * (n + 1)
    dp[0] = 0
    for i in range(1, n + 1):
        temp = i
        while temp > 0:
            d = temp % 10
            if d > 0:
                dp[i] = min(dp[i], dp[i - d] + 1)
            temp //= 10
    return dp[n]

