def shortest_routes(graph: List[List[int]], start: int) -> List[float]:
    distances = [float('inf')] * len(graph)
    distances[start] = 0
    queue = [start]
    while queue:
        current_node = queue.pop(0)
        for i in range(len(graph)):
            if graph[current_node][i] != 0 and distances[current_node] + graph[current_node][i] < distances[i]:
                distances[i] = distances[current_node] + graph[current_node][i]
                queue.append(i)
    return distances

def shortest_routes(n: int, edges: list, src: int, dest: int) -> int:
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))
    distance = [float('inf')] * n
    distance[src] = 0
    pq = [(src, 0)]
    while pq:
        current_node, current_distance = pq.pop(0)
        if current_distance > distance[current_node]:
            continue
        for neighbor, weight in graph[current_node]:
            new_distance = current_distance + weight
            if new_distance < distance[neighbor]:
                distance[neighbor] = new_distance
                pq.append((neighbor, new_distance))
                pq.sort(key=lambda x: x[1])
    return -1 if distance[dest] == float('inf') else distance[dest]

