        self.val = val
        self.next = next

def merge_k_lists(lists: List[Optional[ListNode]]) -> Optional[ListNode]:
    min_heap = []
    for i in range(len(lists)):
        if lists[i]:
            min_heap.append((lists[i].val, i, lists[i]))
    dummy = ListNode(0)
    current = dummy
    while min_heap:
        min_heap.sort(key=lambda x: x[0])
        val, list_index, node = min_heap.pop(0)
        current.next = node
        current = current.next
        if node.next:
            min_heap.append((node.next.val, list_index, node.next))
    return dummy.next

