def divide(dividend: int, divisor: int) -> int:
    sign = -1 if (dividend < 0) ^ (divisor < 0) else 1
    a = abs(dividend)
    b = abs(divisor)
    quotient = 0
    while a >= b:
        shift = 0
        while (b << shift) <= a:
            shift += 1
        a -= b << (shift - 1)
        quotient += 1 << (shift - 1)
    quotient *= sign
    return max(-2**31, min(quotient, 2**31 - 1))

