def is_valid_sudoku(board):
    rows = [set() for _ in range(9)]
    cols = [set() for _ in range(9)]
    boxes = [set() for _ in range(9)]
    for i in range(9):
        for j in range(9):
            val = board[i][j]
            if val == '.':
                continue
            if val in rows[i]:
                return False
            rows[i].add(val)
            if val in cols[j]:
                return False
            cols[j].add(val)
            box_index = (i // 3) * 3 + (j // 3)
            if val in boxes[box_index]:
                return False
            boxes[box_index].add(val)
    return True

def solve():
    data = sys.stdin.read()
    if not data.strip():
        return
    lines = [line.strip() for line in data.strip().splitlines() if line.strip()]
    board = []
    if len(lines) == 9 and all(len(line) >= 9 for line in lines):
        for line in lines:
            row = []
            for ch in line:
                if ch in '123456789.':
                    row.append(ch)
                if len(row) == 9:
                    break
            if len(row) < 9:
                # fallback to regex parsing
                break
            board.append(row)
    if len(board) != 9:
        chars = re.findall(r'[1-9.]', data)
        if len(chars) < 81:
            # insufficient data, cannot form board
            return
        board = [chars[i*9:(i+1)*9] for i in range(9)]
    result = is_valid_sudoku(board)
    sys.stdout.write(str(result).lower())

