def solve_sudoku(board: List[List[str]]) -> None:
    def is_valid(row: int, col: int, val: str) -> bool:
        for i in range(9):
            if board[row][i] == val:
                return False
            if board[i][col] == val:
                return False
            sub_r = 3 * (row // 3) + i // 3
            sub_c = 3 * (col // 3) + i % 3
            if board[sub_r][sub_c] == val:
                return False
        return True

    def backtrack() -> bool:
        for r in range(9):
            for c in range(9):
                if board[r][c] == '.':
                    for d in map(str, range(1, 10)):
                        if is_valid(r, c, d):
                            board[r][c] = d
                            if backtrack():
                                return True
                            board[r][c] = '.'
                    return False
        return True

    backtrack()
