    match_index = 0
    while s_index < len(s):
        if p_index < len(p) and p[p_index] == '*':
            star_index = p_index
            match_index = s_index
            p_index += 1
        elif p_index < len(p) and (p[p_index] == '?' or p[p_index] == s[s_index]):
            p_index += 1
            s_index += 1
        elif star_index != -1:
            p_index = star_index + 1
            match_index += 1
            s_index = match_index
