                return False
        return True

    def place_queens(board: list[int], row: int) -> int:
        if row == n:
            return 1
        count = 0
        for col in range(n):
            if is_safe(board, row, col):
                board[row] = col
                count += place_queens(board, row + 1)
        return count

    board = [-1] * n
    return place_queens(board, 0)

