def is_scramble(s1: str, s2: str) -> bool:
    @lru_cache(None)
    def dfs(a: str, b: str) -> bool:
        if a == b:
            return True
        if len(a) != len(b):
            return False
        if sorted(a) != sorted(b):
            return False
        n = len(a)
        for i in range(1, n):
            # without swapping
            if dfs(a[:i], b[:i]) and dfs(a[i:], b[i:]):
                return True
            # with swapping
            if dfs(a[:i], b[-i:]) and dfs(a[i:], b[:-i]):
                return True
        return False

    return dfs(s1, s2)

