def gray_code(n: int) -> List[int]:
    result = []
    for i in range(int(pow(2, n))):
        j = i >> 1
        if (i ^ j) == (i ^ (i >> 1)):
            result.append(i)
    gray_code_sequence = []
    if n == 0:
        gray_code_sequence.append(0)
    else:
        sub_sequence = gray_code(n - 1)
        for i in range(len(sub_sequence)):
            gray_code_sequence.append(sub_sequence[i])
        for i in range(len(sub_sequence) - 1, -1, -1):
            gray_code_sequence.append(sub_sequence[i] + pow(2, n - 1))
    return gray_code_sequence

