    dp = [[0] * (s_length + 1) for _ in range(t_length + 1)]
    for j in range(s_length + 1):
        dp[0][j] = 1
    for i in range(1, t_length + 1):
        for j in range(1, s_length + 1):
            if t[i - 1] == s[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + dp[i][j - 1]
            else:
                dp[i][j] = dp[i][j - 1]
    return dp[t_length][s_length]

