def find_ladders(begin_word: str, end_word: str, word_list: List[str]) -> List[List[str]]:
    word_set = set(word_list)
    if end_word not in word_set:
        return []
    queue = deque([[begin_word]])
    visited = set([begin_word])
    shortest_path_length = float('inf')
    result: List[List[str]] = []
    while queue:
        path = queue.popleft()
        current_word = path[-1]
        for i in range(len(current_word)):
            for j in range(26):
                next_word = current_word[:i] + chr(97 + j) + current_word[i + 1:]
                if next_word in word_set and next_word not in visited:
                    if next_word == end_word:
                        if len(path) + 1 < shortest_path_length:
                            shortest_path_length = len(path) + 1
                            result = [path + [next_word]]
                        elif len(path) + 1 == shortest_path_length:
                            result.append(path + [next_word])
                    else:
                        queue.append(path + [next_word])
                        visited.add(next_word)
    return result

