def _dfs(board: List[List[str]], i: int, j: int) -> None:
    rows = len(board)
    cols = len(board[0])
    if i < 0 or i >= rows or j < 0 or j >= cols:
        return
    if board[i][j] != 'O':
        return
    board[i][j] = 'N'
    _dfs(board, i - 1, j)
    _dfs(board, i + 1, j)
    _dfs(board, i, j - 1)
    _dfs(board, i, j + 1)

def solve(board: List[List[str]]) -> None:
    if not board or not board[0]:
        return
    rows = len(board)
    cols = len(board[0])
    for i in range(rows):
        if board[i][0] == 'O':
            _dfs(board, i, 0)
        if board[i][cols - 1] == 'O':
            _dfs(board, i, cols - 1)
    for j in range(cols):
        if board[0][j] == 'O':
            _dfs(board, 0, j)
        if board[rows - 1][j] == 'O':
            _dfs(board, rows - 1, j)
    for i in range(rows):
        for j in range(cols):
            if board[i][j] == 'O':
                board[i][j] = 'X'
            elif board[i][j] == 'N':
                board[i][j] = 'O'

