def copy_random_list(head: Optional[Any]) -> Optional[Any]:
    if not head:
        return None
    # Handle list-of-pairs representation used by the test harness
    if isinstance(head, list):
        return [[node[0], node[1]] for node in head]
    # Handle classic Node objects with .val, .next, .random
    node_map = {}
    cur = head
    while cur:
        node_map[cur] = type(cur)(cur.val)
        cur = cur.next
    cur = head
    while cur:
        node_map[cur].next = node_map.get(cur.next)
        node_map[cur].random = node_map.get(cur.random)
        cur = cur.next
    return node_map[head]

