def calculate_slope(p1: List[int], p2: List[int]) -> Union[str, Tuple[int, int]]:
    if p1[0] == p2[0]:
        return 'inf'
    dy = p2[1] - p1[1]
    dx = p2[0] - p1[0]
    g = math.gcd(dy, dx)
    dy //= g
    dx //= g
    if dx < 0:
        dy = -dy
        dx = -dx
    return (dy, dx)

