        for j in range(i + 1, n):
            slope = calculate_slope(points[i], points[j])
            if slope == 'inf' and points[i][0] == points[j][0] and points[i][1] == points[j][1]:
                same_point += 1
            else:
                slope_map[slope] = slope_map.get(slope, 0) + 1
        max_points = max(max_points, max(slope_map.values(), default=0) + same_point)
    return max_points

