def min_stack() -> Tuple[Callable[[int], None], Callable[[], None], Callable[[], int], Callable[[], int]]:
    stack: List[int] = []
    min_stack: List[int] = []

    def push(x: int) -> None:
        stack.append(x)
        if not min_stack or x <= min_stack[-1]:
            min_stack.append(x)

    def pop() -> None:
        if stack:
            val = stack.pop()
            if val == min_stack[-1]:
                min_stack.pop()

    def top() -> int:
        return stack[-1]

    def get_min() -> int:
        return min_stack[-1]

    return push, pop, top, get_min

