        for c in word:
            node = node.setdefault(c, {})
        node['_end'] = True
    def search(word: str) -> bool:
        def dfs(node, i):
            if i == len(word):
                return node.get('_end', False)
            ch = word[i]
            if ch == '.':
                for k, child in node.items():
                    if k == '_end':
                        continue
                    if dfs(child, i + 1):
                        return True
                return False
            child = node.get(ch)
            if not child:
                return False
            return dfs(child, i + 1)
        return dfs(trie, 0)
    return {'add_word': add_word, 'search': search}

