def find_words(board: List[List[str]], words: List[str]) -> List[str]:
    result: List[str] = []
    trie: dict = {}
    for word in words:
        node = trie
        for ch in word:
            node = node.setdefault(ch, {})
        node['end'] = word

    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def backtrack(i: int, j: int, node: dict) -> None:
        if board[i][j] not in node:
            return
        nxt = node[board[i][j]]
        if 'end' in nxt and nxt['end'] is not None:
            result.append(nxt['end'])
            nxt['end'] = None
        temp = board[i][j]
        board[i][j] = '#'
        for di, dj in dirs:
            ni, nj = i + di, j + dj
            if 0 <= ni < len(board) and 0 <= nj < len(board[0]):
                backtrack(ni, nj, nxt)
        board[i][j] = temp

    if board and board[0]:
        for i in range(len(board)):
            for j in range(len(board[0])):
                backtrack(i, j, trie)

    result.sort()
