def diff_ways_to_compute(expression: str) -> List[int]:
    memo: dict[str, List[int]] = {}
    def compute(expr: str) -> List[int]:
        if expr in memo:
            return memo[expr]
        results: List[int] = []
        if expr.isdigit():
            results.append(int(expr))
        else:
            for i, ch in enumerate(expr):
                if ch in '+-*':
                    left = compute(expr[:i])
                    right = compute(expr[i + 1 :])
                    for l in left:
                        for r in right:
                            if ch == '+':
                                results.append(l + r)
                            elif ch == '-':
                                results.append(l - r)
                            else:
                                results.append(l * r)
        results.sort()
        memo[expr] = results
        return results
    return compute(expression)

