def add_operators(num: str, target: int) -> List[str]:
    result: List[str] = []

    def backtrack(index: int, path: str, value: int, prev: int) -> None:
        if index == len(num):
            if value == target:
                result.append(path)
            return

        for i in range(index, len(num)):
            # avoid numbers with leading zeros
            if i != index and num[index] == '0':
                break
            curr_str = num[index:i + 1]
            curr_num = int(curr_str)

            if not path:
                backtrack(i + 1, curr_str, curr_num, curr_num)
            else:
                backtrack(i + 1, f"{path}+{curr_str}", value + curr_num, curr_num)
                backtrack(i + 1, f"{path}-{curr_str}", value - curr_num, -curr_num)
                backtrack(i + 1, f"{path}*{curr_str}", value - prev + prev * curr_num, prev * curr_num)

    backtrack(0, "", 0, 0)
    result.sort()
    return result

class PeekingIterator:
    def __init__(self, iterator):
        self.iterator = iterator; self.peeked = None; self.has_peeked = False
    def peek(self):
        if not self.has_peeked:
            self.peeked = next(self.iterator); self.has_peeked = True
        return self.peeked
    def next(self):
        if self.has_peeked:
            val = self.peeked; self.has_peeked = False; return val
        return next(self.iterator)
    def hasNext(self):
        if self.has_peeked: return True
        try:
            self.peeked = next(self.iterator); self.has_peeked = True; return True
        except StopIteration:
            return False

