def is_additive_number(num: str) -> bool:
    def is_valid(s: str) -> bool:
        return not (len(s) > 1 and s[0] == '0')
    def backtrack(start: int, path: list[str]) -> bool:
        if start == len(num) and len(path) >= 3:
            return True
        for i in range(start, len(num)):
            curr_num = num[start:i + 1]
            if not is_valid(curr_num):
                continue
            if len(path) < 2:
                if backtrack(i + 1, path + [curr_num]):
                    return True
            elif int(path[-1]) + int(path[-2]) == int(curr_num):
                if backtrack(i + 1, path + [curr_num]):
                    return True
        return False
    return backtrack(0, [])

class NumArray:
    def __init__(self, nums):
        self.n = len(nums); self.tree = [0]*(self.n+1); self.nums = [0]*self.n
        for i,v in enumerate(nums): self.update(i,v)
    def update(self, index, val):
        delta = val - self.nums[index]; self.nums[index] = val
        i = index+1
        while i <= self.n: self.tree[i] += delta; i += i & (-i)
    def _prefix(self, i):
        s=0; i+=1
        while i>0: s+=self.tree[i]; i -= i&(-i)
        return s
    def sumRange(self, left, right): return self._prefix(right) - (self._prefix(left-1) if left>0 else 0)

