    for i, ch in enumerate(s):
        last_occurrence[ch] = i
    stack = []
    seen = {}
    for i, ch in enumerate(s):
        if seen.get(ch):
            continue
        while stack and stack[-1] > ch and last_occurrence[stack[-1]] > i:
            seen[stack.pop()] = False
        stack.append(ch)
        seen[ch] = True
    return ''.join(stack)

