def merge_sort(sums: List[int], lower: int, upper: int, left: int, right: int) -> int:
    if left >= right:
        return 0
    mid = (left + right) // 2
    count = merge_sort(sums, lower, upper, left, mid) + merge_sort(sums, lower, upper, mid + 1, right)
    j = k = mid + 1
    temp = []
    for i in range(left, mid + 1):
        while k <= right and sums[k] - sums[i] < lower:
            k += 1
        while j <= right and sums[j] - sums[i] <= upper:
            j += 1
        count += j - k
    l, r = left, mid + 1
    while l <= mid and r <= right:
        if sums[l] <= sums[r]:
            temp.append(sums[l])
            l += 1
        else:
            temp.append(sums[r])
            r += 1
    while l <= mid:
        temp.append(sums[l])
        l += 1
    while r <= right:
        temp.append(sums[r])
        r += 1
    sums[left:right + 1] = temp
    return count

