def longest_increasing_path(matrix: List[List[int]]) -> int:
    if not matrix:
        return 0
    rows = len(matrix)
    cols = len(matrix[0])
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    memo = [[0] * cols for _ in range(rows)]

    def dfs(row: int, col: int) -> int:
        if memo[row][col] != 0:
            return memo[row][col]
        longest_path = 1
        for dr, dc in directions:
            nr = row + dr
            nc = col + dc
            if 0 <= nr < rows and 0 <= nc < cols and matrix[nr][nc] > matrix[row][col]:
                longest_path = max(longest_path, 1 + dfs(nr, nc))
        memo[row][col] = longest_path
        return longest_path

    max_length = 0
    for i in range(rows):
        for j in range(cols):
            max_length = max(max_length, dfs(i, j))
    return max_length

