def can_measure_water(x: int, y: int, target: int) -> bool:
    queue = [[0, 0]]
    visited = {"0,0"}
    while queue:
        currX, currY = queue.pop(0)
        if currX + currY == target:
            return True
        next_states = [
            [x, currY],
            [currX, y],
            [0, currY],
            [currX, 0],
            [max(0, currX - (y - currY)), min(y, currY + currX)],
            [min(x, currX + currY), max(0, currY - (x - currX))]
        ]
        for state in next_states:
            state_str = f"{state[0]},{state[1]}"
            if state_str not in visited:
                queue.append(state)
                visited.add(state_str)
    return False

def is_perfect_square(num: int) -> bool:
