    high = matrix[n - 1][n - 1]
    while low < high:
        mid = (low + high) // 2
        count = 0
        j = n - 1
        for i in range(n):
            while j >= 0 and matrix[i][j] > mid:
                j -= 1
            count += j + 1
        if count < k:
