def deserialize(s):
    if s[0] != '[':
        return int(s)
    stack = []
    curr_num = ''
    for ch in s:
        if ch == '-' or ch.isdigit():
            curr_num += ch
        elif ch == ',':
            if curr_num != '':
                stack[-1].append(int(curr_num))
                curr_num = ''
        elif ch == '[':
            stack.append([])
        elif ch == ']':
            if curr_num != '':
                stack[-1].append(int(curr_num))
                curr_num = ''
            if len(stack) > 1:
                popped = stack.pop()
                stack[-1].append(popped)
    return stack[0]

