def is_rectangle_cover(rectangles: List[List[int]]) -> bool:
    area = 0
    min_x = float('inf')
    min_y = float('inf')
    max_x = float('-inf')
    max_y = float('-inf')
    corners = {}
    for rectangle in rectangles:
        x, y, a, b = rectangle
        area += (a - x) * (b - y)
        min_x = min(min_x, x)
        min_y = min(min_y, y)
        max_x = max(max_x, a)
        max_y = max(max_y, b)
        points = [(x, y), (x, b), (a, y), (a, b)]
        for point in points:
            key = f"{point[0]},{point[1]}"
            if corners.get(key) == 1:
                del corners[key]
            else:
                corners[key] = 1
    if area != (max_x - min_x) * (max_y - min_y):
        return False
    required_keys = {
        f"{min_x},{min_y}",
        f"{min_x},{max_y}",
        f"{max_x},{min_y}",
        f"{max_x},{max_y}",
    }
    if len(corners) != 4 or not required_keys.issubset(corners.keys()):
        return False
    return True

