def calc_equation(equations: List[List[str]], values: List[float], queries: List[List[str]]) -> List[float]:
    graph: Dict[str, List[Tuple[str, float]]] = {}
    for i in range(len(equations)):
        a, b = equations[i]
        if a not in graph:
            graph[a] = []
        if b not in graph:
            graph[b] = []
        graph[a].append((b, values[i]))
        graph[b].append((a, 1 / values[i]))
    def dfs(a: str, b: str, visited: Set[str]) -> float:
        if a == b:
            return 1.0
        visited.add(a)
        for neighbor, value in graph[a]:
            if neighbor == b and neighbor not in visited:
                return value
            if neighbor not in visited:
                result = dfs(neighbor, b, visited)
                if result != -1:
                    return value * result
        return -1.0
    result: List[float] = []
    for a, b in queries:
        if a not in graph or b not in graph:
            result.append(-1.0)
        else:
            result.append(dfs(a, b, set()))
    return result

