def to_hex(num: int) -> str:
    if num == 0:
        return '0'
    result = ''
    is_negative = num < 0
    if is_negative:
        num = num + (1 << 32)
    while num > 0:
        remainder = num % 16
        if remainder < 10:
            result = chr(48 + remainder) + result
        else:
            result = chr(87 + remainder) + result
        num //= 16
    return result

