    for i in range(total_length):
        ch = password[i]
        if 'a' <= ch <= 'z':
            one = True
        elif 'A' <= ch <= 'Z':
            upper = True
        elif '0' <= ch <= '9':
            digit = True

    if one:
        missing_types -= 1
    if upper:
        missing_types -= 1
    if digit:
        missing_types -= 1

    if total_length < 6:
        changes += 6 - total_length
    elif total_length > 20:
        changes += total_length - 20

    i = 2
    while i < total_length:
        if password[i] == password[i - 1] == password[i - 2]:
            length = 2
            while i + 1 < total_length and password[i] == password[i + 1]:
                i += 1
                length += 1
            changes += length // 3
        i += 1

    return max(missing_types, changes)

