def find_maximum_xor(nums: List[int]) -> int:
    maximum_xor = 0
    root = {}
    for num in nums:
        node = root
        for i in range(31, -1, -1):
            bit = (num >> i) & 1
            if bit not in node:
                node[bit] = {}
            node = node[bit]
    for num in nums:
        node = root
        current_xor = 0
        for i in range(31, -1, -1):
            bit = (num >> i) & 1
            opposite = 1 - bit
            if opposite in node:
                current_xor |= (1 << i)
                node = node[opposite]
            else:
                node = node[bit]
        maximum_xor = max(maximum_xor, current_xor)
    return maximum_xor

