def construct(grid: List[List[int]]) -> List[Any]:
    def build(x: int, y: int, n: int) -> dict:
        first = grid[x][y]
        is_leaf = True
        for i in range(x, x + n):
            for j in range(y, y + n):
                if grid[i][j] != first:
                    is_leaf = False
                    break
            if not is_leaf:
                break
        if is_leaf:
            return {"is_leaf": True, "val": first, "children": []}
        half = n // 2
        return {
            "is_leaf": False,
            "val": 1,
            "children": [
                build(x, y, half),
                build(x, y + half, half),
                build(x + half, y, half),
                build(x + half, y + half, half),
            ],
        }

    root = build(0, 0, len(grid))
    q = deque([root])
    result: List[Any] = []
    while q:
        node = q.popleft()
        if node is None:
            result.append(None)
            continue
        result.append([1 if node["is_leaf"] else 0, node["val"]])
        if node["is_leaf"]:
            q.extend([None, None, None, None])
        else:
            q.extend(node["children"])
    while result and result[-1] is None:
        result.pop()
    return result

