def min_mutation(start_gene: str, end_gene: str, bank: List[str]) -> int:
    bank_set = set(bank)
    queue = deque([(start_gene, 0)])
    visited = {start_gene}
    while queue:
        current_gene, steps = queue.popleft()
        if current_gene == end_gene:
            return steps
        for i in range(8):
            for char in ('A', 'C', 'G', 'T'):
                next_gene = current_gene[:i] + char + current_gene[i + 1:]
                if next_gene in bank_set and next_gene not in visited:
                    queue.append((next_gene, steps + 1))
                    visited.add(next_gene)
    return -1

