class AllOne:
    # doubly-linked list of frequency buckets, each holding the set of keys at that frequency, for true O(1)
    class Node:
        __slots__ = ('count','keys','prev','next')
        def __init__(self, count):
            self.count = count; self.keys = set(); self.prev = None; self.next = None
    def __init__(self):
        self.head = self.Node(0); self.tail = self.Node(0)
        self.head.next = self.tail; self.tail.prev = self.head
        self.key_node = {}
    def _insert_after(self, node, count):
        new_node = self.Node(count)
        new_node.prev = node; new_node.next = node.next
        node.next.prev = new_node; node.next = new_node
        return new_node
    def _remove(self, node):
        node.prev.next = node.next; node.next.prev = node.prev
    def inc(self, key):
        if key not in self.key_node:
            new_node = self.head.next if self.head.next.count == 1 else self._insert_after(self.head, 1)
            new_node.keys.add(key); self.key_node[key] = new_node
        else:
            node = self.key_node[key]; node.keys.discard(key)
            new_node = node.next if node.next.count == node.count + 1 else self._insert_after(node, node.count + 1)
            new_node.keys.add(key); self.key_node[key] = new_node
            if not node.keys: self._remove(node)
    def dec(self, key):
        node = self.key_node[key]; node.keys.discard(key)
        if node.count == 1:
            del self.key_node[key]
        else:
            if node.prev.count == node.count - 1:
                new_node = node.prev
            else:
                new_node = self.Node(node.count - 1)
                new_node.prev = node.prev; new_node.next = node
                node.prev.next = new_node; node.prev = new_node
            new_node.keys.add(key); self.key_node[key] = new_node
        if not node.keys: self._remove(node)
    def getMaxKey(self):
        return '' if self.tail.prev is self.head else next(iter(self.tail.prev.keys))
    def getMinKey(self):
        return '' if self.head.next is self.tail else next(iter(self.head.next.keys))

