def find_right_interval(intervals: List[List[int]]) -> List[int]:
    n = len(intervals)
    result = [0] * n
    interval_indices = []
    for i in range(n):
        interval_indices.append([intervals[i][0], i])
    interval_indices.sort(key=lambda x: x[0])
    for i in range(n):
        target = intervals[i][1]
        left, right = 0, n - 1
        while left <= right:
            mid = (left + right) // 2
            if interval_indices[mid][0] >= target:
                right = mid - 1
            else:
                left = mid + 1
        result[i] = interval_indices[left][1] if left < n else -1
    return result

def path_sum(root, target_sum: int) -> int:
    count = 0
    def dfs(node, current_sum):
        nonlocal count
        if not node:
            return
        current_sum += node.val
        if current_sum == target_sum:
            count += 1
        dfs(node.left, current_sum)
        dfs(node.right, current_sum)
    def traverse(node):
        if not node:
            return
        dfs(node, 0)
        traverse(node.left)
        traverse(node.right)
    traverse(root)
    return count

def find_anagrams(s: str, p: str) -> list[int]:
    result = []
    p_count = {}
    s_count = {}

    for char in p:
        if char not in p_count:
            p_count[char] = 0
        p_count[char] += 1

    left = 0
    right = 0
    while right < len(s):
        if s[right] not in s_count:
            s_count[s[right]] = 0
        s_count[s[right]] += 1

        if right - left + 1 == len(p):
            is_anagram = True
            for char in p_count:
                if p_count[char] != s_count.get(char, 0):
                    is_anagram = False
                    break
            if is_anagram:
                result.append(left)

            s_count[s[left]] -= 1
            if s_count[s[left]] == 0:
                del s_count[s[left]]
            left += 1

        right += 1

    return result

