def circular_array_loop(nums: List[int]) -> bool:
    n = len(nums)

    def next_index(cur: int, direction: bool) -> int:
        move = nums[cur]
        if move == 0:
            return -1
        if (move > 0) != direction:
            return -1
        nxt = (cur + move) % n
        if nxt == cur:
            return -1
        return nxt

    for i in range(n):
        if nums[i] == 0:
            continue
        direction = nums[i] > 0
        slow, fast = i, i
        while True:
            slow = next_index(slow, direction)
            if slow == -1:
                break
            fast = next_index(fast, direction)
            if fast == -1:
                break
            fast = next_index(fast, direction)
            if fast == -1:
                break
            if slow == fast:
                return True
        # mark all nodes visited in this pass as 0
        cur = i
        while nums[cur] != 0:
            nxt = (cur + nums[cur]) % n
            nums[cur] = 0
            if nxt == cur:
                break
            cur = nxt
    return False

