def lfu_cache(capacity):
    from collections import OrderedDict
    key_map = {}
    freq_map = {}
    min_freq = 1

    def _add_to_freq(key, freq):
        if freq not in freq_map:
            freq_map[freq] = OrderedDict()
        freq_map[freq][key] = None

    def get(key):
        nonlocal min_freq
        if key not in key_map:
            return -1
        value, freq = key_map[key]
        freq_list = freq_map[freq]
        del freq_list[key]
        if not freq_list:
            del freq_map[freq]
            if min_freq == freq:
                min_freq += 1
        new_freq = freq + 1
        _add_to_freq(key, new_freq)
        key_map[key] = (value, new_freq)
        return value

    def put(k, v):
        nonlocal min_freq
        if capacity == 0:
            return
        if k in key_map:
            key_map[k] = (v, key_map[k][1])
            get(k)
            return
        if len(key_map) >= capacity:
            evict_key, _ = freq_map[min_freq].popitem(last=False)
            del key_map[evict_key]
            if not freq_map[min_freq]:
                del freq_map[min_freq]
        key_map[k] = (v, 1)
        _add_to_freq(k, 1)
        min_freq = 1

    return get, put

