def valid_ip_address(query_ip: str) -> str:
    if '.' in query_ip:
        parts = query_ip.split('.')
        if len(parts) != 4:
            return 'Neither'
        for part in parts:
            if not part.isdigit():
                return 'Neither'
            if len(part) > 1 and part[0] == '0':
                return 'Neither'
            num = int(part)
            if num < 0 or num > 255:
                return 'Neither'
        return 'IPv4'
    elif ':' in query_ip:
        parts = query_ip.split(':')
        if len(parts) != 8:
            return 'Neither'
        for part in parts:
            if len(part) > 4 or not re.fullmatch(r'[0-9a-fA-F]+', part):
                return 'Neither'
        return 'IPv6'
    else:
        return 'Neither'

