    if start == len(word):
        return True
    if start in memo:
        return memo[start]
    for end in range(start + 1, len(word) + 1):
        if word[start:end] in word_set:
            if can_be_concatenated(word, word_set, end, memo):
                memo[start] = True
                return True
    memo[start] = False
    return False

