def makesquare(matchsticks: List[int]) -> bool:
    total_length = 0
    for i in range(len(matchsticks)):
        total_length += matchsticks[i]
    if total_length % 4 != 0:
        return False
    side_length = total_length // 4
    sides = [0, 0, 0, 0]
    matchsticks.sort(reverse=True)
    def backtrack(index: int) -> bool:
        if index == len(matchsticks):
            return sides[0] == side_length and sides[1] == side_length and sides[2] == side_length and sides[3] == side_length
        for i in range(4):
            if sides[i] + matchsticks[index] > side_length:
                continue
            sides[i] += matchsticks[index]
            if backtrack(index + 1):
                return True
            sides[i] -= matchsticks[index]
        return False
    return backtrack(0)

from typing import Dict

def can_i_win(max_choosable_integer: int, desired_total: int) -> bool:
    # quick checks
    if desired_total <= 0:
        return True
    if max_choosable_integer * (max_choosable_integer + 1) // 2 < desired_total:
        return False
    if max_choosable_integer >= desired_total:
        return True

    memo: Dict[int, bool] = {}

    def dfs(used: int, total: int) -> bool:
        if used in memo:
            return memo[used]
        # if the current total already reaches or exceeds the target,
        # the player who just moved wins, so the current player loses
        if total >= desired_total:
            memo[used] = False
            return False
        for i in range(1, max_choosable_integer + 1):
            bit = 1 << (i - 1)
            if used & bit == 0:
                # if the opponent cannot win after this move, current player wins
                if not dfs(used | bit, total + i):
                    memo[used] = True
                    return True
        memo[used] = False
        return False

    return dfs(0, 0)

