from typing import List

def median_sliding_window(nums: List[int], k: int) -> List[float]:
    lo: List[int] = []   # max-heap (store negatives)
    hi: List[int] = []   # min-heap
    delayed: dict[int, int] = {}
    lo_size = 0
    hi_size = 0
    res: List[float] = []

    def prune(heap: List[int]) -> None:
        while heap:
            num = -heap[0] if heap is lo else heap[0]
            if num in delayed:
                delayed[num] -= 1
                if delayed[num] == 0:
                    del delayed[num]
                heapq.heappop(heap)
            else:
                break

    def balance() -> None:
        nonlocal lo_size, hi_size
        if lo_size > hi_size + 1:
            val = -heapq.heappop(lo)
            lo_size -= 1
            heapq.heappush(hi, val)
            hi_size += 1
            prune(lo)
        elif lo_size < hi_size:
            val = heapq.heappop(hi)
            hi_size -= 1
            heapq.heappush(lo, -val)
            lo_size += 1
            prune(hi)

    def add_num(num: int) -> None:
        nonlocal lo_size, hi_size
        if not lo or num <= -lo[0]:
            heapq.heappush(lo, -num)
            lo_size += 1
        else:
            heapq.heappush(hi, num)
            hi_size += 1
        balance()

    def remove_num(num: int) -> None:
        nonlocal lo_size, hi_size
        delayed[num] = delayed.get(num, 0) + 1
        if num <= -lo[0]:
            lo_size -= 1
            if num == -lo[0]:
                prune(lo)
        else:
            hi_size -= 1
            if hi and num == hi[0]:
                prune(hi)
        balance()

    def get_median() -> float:
        prune(lo)
        prune(hi)
        if k % 2:
            return float(-lo[0])
        else:
            return (-lo[0] + hi[0]) / 2.0

    for i in range(k):
        add_num(nums[i])
    res.append(get_median())

    for i in range(k, len(nums)):
        add_num(nums[i])
        remove_num(nums[i - k])
        res.append(get_median())

    return res

