def license_key_formatting(s: str, k: int) -> str:
    s_no_dashes = s.replace('-', '').upper()
    first_group_length = len(s_no_dashes) % k
    parts = []
    if first_group_length > 0:
        parts.append(s_no_dashes[:first_group_length])
    i = first_group_length
    while i < len(s_no_dashes):
        if parts:
            parts.append('-')
        parts.append(s_no_dashes[i:i + k])
        i += k
    return ''.join(parts)

import math

def smallest_good_base(n: str) -> str:
    num = int(n)
    max_len = int(math.log(num) / math.log(2)) + 1
    for length in range(max_len, 1, -1):
        left, right = 2, num - 1
        while left <= right:
            mid = (left + right) // 2
            total = 0
            for _ in range(length):
                total = total * mid + 1
            if total == num:
                return str(mid)
            elif total < num:
                left = mid + 1
            else:
                right = mid - 1
    return str(num - 1)

