def find_min_step(board: str, hand: str) -> int:
    memo: Dict[str, int] = {}

    def collapse(s: str) -> str:
        i = 0
        while i < len(s):
            j = i
            while j < len(s) and s[j] == s[i]:
                j += 1
            if j - i >= 3:
                s = s[:i] + s[j:]
                i = 0
                continue
            i += 1
        return s

    def dfs(b: str, h: str) -> int:
        key = b + ',' + ''.join(sorted(h))
        if key in memo:
            return memo[key]
        if not b:
            memo[key] = 0
            return 0
        if not h:
            memo[key] = -1
            return -1

        best = float('inf')
        for i in range(len(h)):
            ball = h[i]
            new_hand = h[:i] + h[i + 1:]
            for pos in range(len(b) + 1):
                new_board = b[:pos] + ball + b[pos:]
                new_board = collapse(new_board)
                if not new_board:
                    memo[key] = 1
                    return 1
                sub = dfs(new_board, new_hand)
                if sub != -1:
                    best = min(best, 1 + sub)

        memo[key] = -1 if best == float('inf') else best
        return memo[key]

    return dfs(board, hand)

