        if len(current) >= 2:
            result.add(tuple(current))
        for i in range(start, len(nums)):
            if not current or nums[i] >= current[-1]:
                current.append(nums[i])
                backtrack(i + 1, current)
                current.pop()
    backtrack(0, [])
    return [list(seq) for seq in sorted(result)]

