    n = len(ring)
    m = len(key)
    dp = [[float('inf')] * n for _ in range(m)]
    for j in range(n):
        if ring[j] == key[0]:
            dp[0][j] = min(dp[0][j], min(j, n - j) + 1)
    for i in range(1, m):
        for j in range(n):
            for k in range(n):
                if ring[k] == key[i - 1]:
                    dp[i][j] = min(dp[i][j], dp[i - 1][k] + min(abs(j - k), n - abs(j - k)) + 1)
    min_steps = float('inf')
    for j in range(n):
        if ring[j] == key[m - 1]:
            min_steps = min(min_steps, dp[m - 1][j])
    return int(min_steps)

