        self.m = m; self.n = n; self.total = m*n; self.mapping = {}
    def flip(self):
        r = random.randint(0, self.total-1); self.total -= 1
        x = self.mapping.get(r, r)
        self.mapping[r] = self.mapping.get(self.total, self.total)
        return [x // self.n, x % self.n]
    def reset(self):
        self.total = self.m * self.n; self.mapping = {}

