def update_board(board: List[List[str]], click: List[int]) -> List[List[str]]:
    rows, cols = len(board), len(board[0])
    r, c = click[0], click[1]

    if board[r][c] == 'M':
        board[r][c] = 'X'
        return board

    def dfs(row: int, col: int) -> None:
        if not (0 <= row < rows and 0 <= col < cols):
            return
        if board[row][col] != 'E':
            return

        # Count adjacent mines
        mine_cnt = 0
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                nr, nc = row + dr, col + dc
                if 0 <= nr < rows and 0 <= nc < cols and board[nr][nc] == 'M':
                    mine_cnt += 1

        if mine_cnt > 0:
            board[row][col] = str(mine_cnt)
        else:
            board[row][col] = 'B'
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == 0 and dc == 0:
                        continue
                    dfs(row + dr, col + dc)

    dfs(r, c)
    return board

