def remove_boxes(boxes: List[int]) -> int:
    n = len(boxes)
    memo: Dict[Tuple[int, int, int], int] = {}

    def dp(left: int, right: int, k: int) -> int:
        if left > right:
            return 0
        # merge boxes of the same color as boxes[right] that are contiguous to the left
        while right > left and boxes[right] == boxes[right - 1]:
            right -= 1
            k += 1
        key = (left, right, k)
        if key in memo:
            return memo[key]

        # option 1: remove the group ending at 'right' now
        best = dp(left, right - 1, 0) + (k + 1) * (k + 1)

        # option 2: try to merge with a previous box of the same color
        for i in range(left, right):
            if boxes[i] == boxes[right]:
                best = max(best, dp(left, i, k + 1) + dp(i + 1, right - 1, 0))

        memo[key] = best
        return best

    return dp(0, n - 1, 0)

