def check_record(n: int) -> int:
    MOD = 1_000_000_007
    dp = [[[0] * 3 for _ in range(2)] for _ in range(n + 1)]
    dp[0][0][0] = 1
    for i in range(n):
        for a in range(2):
            for l in range(3):
                cur = dp[i][a][l]
                if cur == 0:
                    continue
                # add 'P'
                dp[i + 1][a][0] = (dp[i + 1][a][0] + cur) % MOD
                # add 'L'
                if l < 2:
                    dp[i + 1][a][l + 1] = (dp[i + 1][a][l + 1] + cur) % MOD
                # add 'A'
                if a == 0:
                    dp[i + 1][1][0] = (dp[i + 1][1][0] + cur) % MOD
    res = 0
    for a in range(2):
        for l in range(3):
            res = (res + dp[n][a][l]) % MOD
    return res

