def logical_or_of_quad_trees(quadTree1: List, quadTree2: List) -> List:
    class Node:
        __slots__ = ("isLeaf", "val", "topLeft", "topRight", "bottomLeft", "bottomRight")
        def __init__(self, isLeaf: bool, val: bool,
                     topLeft: Optional['Node']=None, topRight: Optional['Node']=None,
                     bottomLeft: Optional['Node']=None, bottomRight: Optional['Node']=None):
            self.isLeaf = isLeaf
            self.val = val
            self.topLeft = topLeft
            self.topRight = topRight
            self.bottomLeft = bottomLeft
            self.bottomRight = bottomRight

    def deserialize(data: List) -> Optional[Node]:
        if not data:
            return None
        it = iter(data)
        root_info = next(it)
        if root_info is None:
            return None
        root = Node(bool(root_info[0]), bool(root_info[1]))
        queue = [root]
        while queue:
            node = queue.pop(0)
            if node.isLeaf:
                continue
            children = []
            for _ in range(4):
                try:
                    info = next(it)
                except StopIteration:
                    info = None
                if info is None:
                    child = None
                else:
                    child = Node(bool(info[0]), bool(info[1]))
                children.append(child)
            node.topLeft, node.topRight, node.bottomLeft, node.bottomRight = children
            for child in children:
                if child and not child.isLeaf:
                    queue.append(child)
        return root

    def max_depth(node: Optional[Node]) -> int:
        if not node or node.isLeaf:
            return 0
        return 1 + max(
            max_depth(node.topLeft),
            max_depth(node.topRight),
            max_depth(node.bottomLeft),
            max_depth(node.bottomRight)
        )

    def fill(node: Optional[Node], x: int, y: int, size: int, mat: List[List[int]]) -> None:
        if not node:
            return
        if node.isLeaf:
            val = 1 if node.val else 0
            for i in range(x, x + size):
                mat[i][y:y + size] = [val] * size
        else:
            half = size // 2
            fill(node.topLeft, x, y, half, mat)
            fill(node.topRight, x, y + half, half, mat)
            fill(node.bottomLeft, x + half, y, half, mat)
            fill(node.bottomRight, x + half, y + half, half, mat)

    def build(mat: List[List[int]], x: int, y: int, size: int) -> Node:
        first = mat[x][y]
        uniform = True
        for i in range(x, x + size):
            for j in range(y, y + size):
                if mat[i][j] != first:
                    uniform = False
                    break
            if not uniform:
                break
        if uniform:
            return Node(True, bool(first))
        half = size // 2
        tl = build(mat, x, y, half)
        tr = build(mat, x, y + half, half)
        bl = build(mat, x + half, y, half)
        br = build(mat, x + half, y + half, half)
        return Node(False, False, tl, tr, bl, br)

    def serialize(root: Optional[Node]) -> List:
        if not root:
            return []
        result = []
        queue = [root]
        while queue:
            node = queue.pop(0)
            if node is None:
                result.append(None)
                continue
            result.append([1 if node.isLeaf else 0, 1 if node.val else 0])
            if not node.isLeaf:
                queue.append(node.topLeft)
                queue.append(node.topRight)
                queue.append(node.bottomLeft)
                queue.append(node.bottomRight)
        while result and result[-1] is None:
            result.pop()
        return result

    # Deserialize both trees
    root1 = deserialize(quadTree1)
    root2 = deserialize(quadTree2)

    # Determine matrix size
    depth = max(max_depth(root1), max_depth(root2))
    n = 1 << depth  # 2 ** depth

    # Build matrices
    mat1 = [[0] * n for _ in range(n)]
    mat2 = [[0] * n for _ in range(n)]
    fill(root1, 0, 0, n, mat1)
    fill(root2, 0, 0, n, mat2)

    # OR operation
    res_mat = [[mat1[i][j] | mat2[i][j] for j in range(n)] for i in range(n)]

    # Build result quad tree
    res_root = build(res_mat, 0, 0, n)

    # Serialize result
    return serialize(res_root)

def check_inclusion(s1: str, s2: str) -> bool:
