    for i in range(len(s1)):
        c1 = s1[i]
        s1_count[c1] = s1_count.get(c1, 0) + 1
        c2 = s2[i]
        s2_count[c2] = s2_count.get(c2, 0) + 1
    matches = 0
    for key, val in s1_count.items():
        if val == s2_count.get(key, 0):
            matches += 1
    left = 0
    for right in range(len(s1), len(s2)):
        left_char = s2[left]
        s2_count[left_char] = s2_count.get(left_char, 0) - 1
        if left_char in s1_count:
            if s2_count[left_char] == s1_count[left_char]:
                matches += 1
            elif s2_count[left_char] == s1_count[left_char] - 1:
                matches -= 1
        right_char = s2[right]
        s2_count[right_char] = s2_count.get(right_char, 0) + 1
        if right_char in s1_count:
            if s2_count[right_char] == s1_count[right_char]:
                matches += 1
            elif s2_count[right_char] == s1_count[right_char] + 1:
                matches -= 1
        if matches == len(s1_count):
            return True
        left += 1
    return matches == len(s1_count)

def is_subtree(root, sub_root):
    def is_identical(t1, t2):
        if t1 is None and t2 is None:
            return True
        if t1 is None or t2 is None:
            return False
        if t1.val != t2.val:
            return False
        return is_identical(t1.left, t2.left) and is_identical(t1.right, t2.right)

    def traverse(t1):
        if t1 is None:
            return False
        if is_identical(t1, sub_root):
            return True
        return traverse(t1.left) or traverse(t1.right)

    return traverse(root)

