def outer_trees(trees: List[List[int]]) -> List[List[int]]:
    if len(trees) <= 1:
        return [list(p) for p in trees]

    # Remove duplicate points and sort lexicographically (x then y)
    points: List[Tuple[int, int]] = sorted({(x, y) for x, y in trees})

    def cross(o: Tuple[int, int], a: Tuple[int, int], b: Tuple[int, int]) -> int:
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    # Build lower hull (keep collinear points)
    lower: List[Tuple[int, int]] = []
    for p in points:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) < 0:
            lower.pop()
        lower.append(p)

    # Build upper hull (keep collinear points)
    upper: List[Tuple[int, int]] = []
    for p in reversed(points):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) < 0:
            upper.pop()
        upper.append(p)

    # Concatenate lower and upper hulls, removing duplicate end points
    combined: List[Tuple[int, int]] = lower[:-1] + upper[:-1]

    # Preserve order while eliminating any remaining duplicates
    seen: Set[Tuple[int, int]] = set()
    hull: List[List[int]] = []
    for p in combined:
        if p not in seen:
            seen.add(p)
            hull.append([p[0], p[1]])

    # If all points are collinear, reverse to match expected order
    if len(hull) > 2:
        base = hull[0]
        collinear = True
        for i in range(2, len(hull)):
            if cross((base[0], base[1]), (hull[1][0], hull[1][1]), (hull[i][0], hull[i][1])) != 0:
                collinear = False
                break
        if collinear:
            hull.reverse()
    else:
        # For two points or a single point, ensure right‑to‑left order
        hull.reverse()

    return hull

