def preorder(root: Any) -> List[int]:
    class Node:
        def __init__(self, val: int):
            self.val: int = val
            self.children: List['Node'] = []

    def build_from_list(data: List[Any]) -> Optional[Node]:
        if not data:
            return None
        root_node = Node(data[0])
        queue: List[Node] = [root_node]
        i = 2  # skip root value and the first None separator
        while i < len(data):
            parent = queue.pop(0)
            while i < len(data) and data[i] is not None:
                child = Node(data[i])
                parent.children.append(child)
                queue.append(child)
                i += 1
            i += 1  # skip the None separator
        return root_node

    # If the input is a serialized list, convert it to a Node tree.
    if isinstance(root, list):
        root = build_from_list(root)

    result: List[int] = []
    if not root:
        return result

    stack: List[Node] = [root]
    while stack:
        node = stack.pop()
        result.append(node.val)
        for child in reversed(node.children):
            stack.append(child)

    return result

def is_valid(code: str) -> bool:
    n = len(code)
    if n == 0:
        return False
    stack: list[str] = []
    i = 0
    while i < n:
        if code[i] == "<":
            # CDATA section
            if i + 9 <= n and code[i : i + 9] == "<![CDATA[":
                if not stack:  # CDATA must be inside a tag
                    return False
                end = code.find("]]>", i + 9)
                if end == -1:
                    return False
                i = end + 3
                continue
            # Closing tag
            if i + 2 < n and code[i + 1] == "/":
                j = i + 2
                while j < n and code[j] != ">":
                    j += 1
                if j == n:
                    return False
                tag_name = code[i + 2 : j]
                if not (1 <= len(tag_name) <= 9) or not tag_name.isupper():
                    return False
                if not stack or stack[-1] != tag_name:
                    return False
                stack.pop()
                i = j + 1
                # after closing the outermost tag, nothing else should follow
                if not stack and i != n:
                    return False
                continue
            # Opening tag
            j = i + 1
            while j < n and code[j] != ">":
                j += 1
            if j == n:
                return False
            tag_name = code[i + 1 : j]
            if not (1 <= len(tag_name) <= 9) or not tag_name.isupper():
                return False
            stack.append(tag_name)
            i = j + 1
            continue
        else:
            # characters outside any tag are invalid
            if not stack:
                return False
            i += 1
    return not stack

