import sys

def count_without_consecutive_ones(n: int) -> int:
    # Precompute Fibonacci numbers up to the highest bit position of n
    fib = [1, 2]  # fib[i] = count of valid strings of length i (i bits)
    max_bit = n.bit_length()
    for i in range(2, max_bit + 1):
        fib.append(fib[-1] + fib[-2])

    result = 0
    prev_bit = 0
    for i in range(max_bit - 1, -1, -1):
        cur_bit = (n >> i) & 1
        if cur_bit:
            result += fib[i]
            if prev_bit:
                # two consecutive ones encountered; n itself is invalid
                return result
            prev_bit = 1
        else:
            prev_bit = 0
    # n itself is valid, include it
    return result + 1

