def add_one_row(root: Optional[Dict[str, Any]], val: int, depth: int) -> Optional[Dict[str, Any]]:
    if depth == 1:
        return {'val': val, 'left': root, 'right': None}
    def traverse(node: Optional[Dict[str, Any]], current_depth: int) -> None:
        if node is None:
            return
        if current_depth == depth - 1:
            node['left'] = {'val': val, 'left': node['left'], 'right': None}
            node['right'] = {'val': val, 'left': None, 'right': node['right']}
        else:
            traverse(node['left'], current_depth + 1)
            traverse(node['right'], current_depth + 1)
    traverse(root, 1)
    return root

