def smallest_range(nums: List[List[int]]) -> List[int]:
    min_heap = []
    for i in range(len(nums)):
        min_heap.append([nums[i][0], i, 0])
    min_heap.sort(key=lambda x: x[0])
    smallest_range = [-float('inf'), float('inf')]
    max_val = max(x[0] for x in min_heap)
    while len(min_heap) == len(nums):
        min_val, list_idx, elem_idx = min_heap.pop(0)
        if max_val - min_val < smallest_range[1] - smallest_range[0]:
            smallest_range = [min_val, max_val]
        if elem_idx + 1 < len(nums[list_idx]):
            next_val = nums[list_idx][elem_idx + 1]
            min_heap.append([next_val, list_idx, elem_idx + 1])
            min_heap.sort(key=lambda x: x[0])
            if next_val > max_val:
                max_val = next_val
        else:
            break
    return smallest_range

