    import math

    def is_perfect_square(x: int) -> bool:
        if x < 0:
            return False
        y = math.isqrt(x)
        return y * y == x

    a = 0
    while a * a <= c:
        if is_perfect_square(c - a * a):
            return True
        a += 1
    return False
# TIME: O(sqrt(c)) SPACE: O(1)

def average_of_levels(root):
