    queue = [root]
    while queue:
        level_size = len(queue)
        total = 0
        for _ in range(level_size):
            node = queue.pop(0)
            total += node.val
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        result.append(total / level_size)
    return result

