def shopping_offers(price: List[int], special: List[List[int]], needs: List[int]) -> int:
    memo = {}
    def dfs(current: List[int]) -> int:
        key = tuple(current)
        if key in memo:
            return memo[key]
        res = sum(current[i] * price[i] for i in range(len(current)))
        for spec in special:
            clone = current[:]
            valid = True
            for i in range(len(clone)):
                clone[i] -= spec[i]
                if clone[i] < 0:
                    valid = False
                    break
            if valid:
                res = min(res, spec[-1] + dfs(clone))
        memo[key] = res
        return res
    return dfs(needs)

def num_decodings(s: str) -> int:
    MOD = 10**9 + 7
    n = len(s)
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(1, n + 1):
        if s[i - 1] != '*':
            if s[i - 1] != '0':
                dp[i] += dp[i - 1]
            if i >= 2 and (s[i - 2] == '1' or (s[i - 2] == '2' and s[i - 1] <= '6')):
                dp[i] += dp[i - 2]
        else:
            dp[i] += dp[i - 1] * 9
            if i >= 2:
                if s[i - 2] == '1':
                    dp[i] += dp[i - 2] * 9
                elif s[i - 2] == '2':
                    dp[i] += dp[i - 2] * 6
        dp[i] %= MOD
    return dp[n]

def solve_equation(equation: str) -> str:
    left_x = 0
    left_val = 0
    right_x = 0
    right_val = 0
    left = True
    num = 0
    sign = 1
    for ch in equation:
        if ch.isdigit():
            num = num * 10 + int(ch)
        elif ch == 'x':
            if num == 0:
                num = 1
            if left:
                left_x += sign * num
            else:
                right_x += sign * num
            num = 0
        elif ch == '+' or ch == '-':
            if num != 0:
                if left:
                    left_val += sign * num
                else:
                    right_val += sign * num
                num = 0
            sign = 1 if ch == '+' else -1
        elif ch == '=':
            left = False
            sign = 1
    if num != 0:
        if left:
            left_val += sign * num
        else:
            right_val += sign * num
    new_x = left_x - right_x
    new_val = right_val - left_val
    if new_x == 0 and new_val == 0:
        return "Infinite solutions"
    if new_x == 0:
        return "No solution"
    result = new_val // new_x if new_val % new_x == 0 else new_val / new_x
    return f"x={result}"

