def replace_words(dictionary: List[str], sentence: str) -> str:
    trie = {}
    for word in dictionary:
        node = trie
        for ch in word:
            if ch not in node:
                node[ch] = {}
            node = node[ch]
        node['$'] = word
    words = sentence.split(' ')
    for i in range(len(words)):
