def width_of_binary_tree(root):
    if not root:
        return 0
    max_width = 0
    queue = [(root, 0)]
    while queue:
        size = len(queue)
        leftmost = queue[0][1]
        rightmost = queue[size - 1][1]
        max_width = max(max_width, rightmost - leftmost + 1)
        for _ in range(size):
            node, index = queue.pop(0)
            if node.left:
                queue.append((node.left, 2 * index))
            if node.right:
                queue.append((node.right, 2 * index + 1))
    return max_width

