def strange_printer(s: str) -> int:
    # Remove consecutive duplicate characters; they can be printed in one turn
    compressed: str = []
    for ch in s:
        if not compressed or compressed[-1] != ch:
            compressed.append(ch)
    s = ''.join(compressed)
    n: int = len(s)
    if n == 0:
        return 0

    dp: List[List[int]] = [[0] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = 1

    for length in range(2, n + 1):
        for i in range(0, n - length + 1):
            j = i + length - 1
            # Print s[j] separately after printing s[i..j-1]
            dp[i][j] = dp[i][j - 1] + 1
            # Try to merge printing of s[j] with a previous same character
            for k in range(i, j):
                if s[k] == s[j]:
                    left = dp[i][k]
                    middle = dp[k + 1][j - 1] if k + 1 <= j - 1 else 0
                    dp[i][j] = min(dp[i][j], left + middle)
    return dp[0][n - 1]

