def max_product(words: List[str]) -> int:
    max_product = 0
    bitmasks = []
    for word in words:
        bitmask = 0
        for char in word:
            bitmask |= 1 << (ord(char) - ord('a'))
        bitmasks.append(bitmask)
    n = len(words)
    for i in range(n):
        for j in range(i + 1, n):
            if (bitmasks[i] & bitmasks[j]) == 0:
                product = len(words[i]) * len(words[j])
                if product > max_product:
                    max_product = product
