def map_sum():
    map_dict: dict[str, int] = {}
    trie: dict = {}

    def insert(key: str, val: int) -> None:
        nonlocal map_dict, trie
        delta = val - map_dict.get(key, 0)
        map_dict[key] = val
        node = trie
        for ch in key:
            if ch not in node:
                node[ch] = {}
            node = node[ch]
            node['_sum'] = node.get('_sum', 0) + delta

    def sum_prefix(prefix: str) -> int:
        node = trie
        for ch in prefix:
            if ch not in node:
                return 0
            node = node[ch]
        return node.get('_sum', 0)

    return {'insert': insert, 'sum': sum_prefix}

