def bfs(forest: List[List[int]], start: Tuple[int, int], target: Tuple[int, int]) -> int:
    m, n = len(forest), len(forest[0])
    visited = [[False] * n for _ in range(m)]
    q = deque()
    q.append((start[0], start[1], 0))
    visited[start[0]][start[1]] = True
    while q:
        x, y, d = q.popleft()
        if (x, y) == target:
            return d
        for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and not visited[nx][ny] and forest[nx][ny] != 0:
                visited[nx][ny] = True
                q.append((nx, ny, d + 1))
    return -1

def cut_off_tree(forest: List[List[int]]) -> int:
    m, n = len(forest), len(forest[0])
    trees = []
    for i in range(m):
        for j in range(n):
            if forest[i][j] > 1:
                trees.append((forest[i][j], i, j))
    trees.sort(key=lambda x: x[0])
    start = (0, 0)
    total_steps = 0
    for _, i, j in trees:
        steps = bfs(forest, start, (i, j))
        if steps == -1:
            return -1
        total_steps += steps
        start = (i, j)
    return total_steps

