def valid_utf8(data: list[int]) -> bool:
    bytes_left = 0
    for byte in data:
        binary = bin(byte)[2:].zfill(8)
        if bytes_left == 0:
            if binary[0] == '0':
                continue
            elif binary[:3] == '110':
                bytes_left = 1
            elif binary[:4] == '1110':
                bytes_left = 2
            elif binary[:5] == '11110':
                bytes_left = 3
            else:
                return False
        else:
            if binary[:2] != '10':
                return False
            bytes_left -= 1
    return bytes_left == 0

