            stack.pop()
            drop -= 1
        stack.append(num)
    return stack[:k]

def greater(nums1: List[int], nums2: List[int]) -> bool:
    i = j = 0
    while i < len(nums1) and j < len(nums2):
        if nums1[i] != nums2[j]:
            return nums1[i] > nums2[j]
        i += 1
        j += 1
    return len(nums1) > len(nums2)

def merge(nums1: List[int], nums2: List[int]) -> List[int]:
    i = j = 0
    merged: List[int] = []
    while i < len(nums1) or j < len(nums2):
        if greater(nums1[i:], nums2[j:]):
            merged.append(nums1[i])
            i += 1
        else:
            merged.append(nums2[j])
            j += 1
    return merged

def max_number(nums1: List[int], nums2: List[int], k: int) -> List[int]:
    result: List[int] = []
    for i in range(max(0, k - len(nums2)), min(k, len(nums1)) + 1):
        subsequence1 = max_subsequence(nums1, i)
        subsequence2 = max_subsequence(nums2, k - i)
        merged = merge(subsequence1, subsequence2)
        if greater(merged, result):
            result = merged
    return result

