def shortest_path_length(graph: List[List[int]]) -> int:
    n = len(graph)
    queue = deque()
    visited = [[float('inf')] * (1 << n) for _ in range(n)]
    for i in range(n):
        queue.append((i, 1 << i, 0))
        visited[i][1 << i] = 0
    all_visited = (1 << n) - 1
    while queue:
        node, state, path_len = queue.popleft()
        if state == all_visited:
            return path_len
        for neighbor in graph[node]:
            new_state = state | (1 << neighbor)
            if visited[neighbor][new_state] > path_len + 1:
                visited[neighbor][new_state] = path_len + 1
                queue.append((neighbor, new_state, path_len + 1))
    return -1

