    count_map = {}
    for num in hand:
        count_map[num] = count_map.get(num, 0) + 1
    keys = sorted(count_map.keys())
    for key in keys:
        if count_map[key] > 0:
            count = count_map[key]
            for i in range(group_size):
                next_num = key + i
                if count_map.get(next_num, 0) < count:
                    return False
                count_map[next_num] -= count
    return True

