def shortest_path_all_keys(grid: List[str]) -> int:
    m = len(grid)
    n = len(grid[0])
    all_keys: Set[str] = set()
    start: Tuple[int, int] = (0, 0)
    for i in range(m):
        for j in range(n):
            cell = grid[i][j]
            if cell == '@':
                start = (i, j)
            if 'a' <= cell <= 'f':
                all_keys.add(cell)
    all_keys_size = len(all_keys)
    queue = deque()
    queue.append((start, set()))
    visited: Set[str] = set()
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    steps = 0
    while queue:
        size = len(queue)
        for _ in range(size):
            (x, y), keys = queue.popleft()
            if len(keys) == all_keys_size:
                return steps
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] != '#':
                    cell = grid[nx][ny]
                    new_keys = set(keys)
                    if 'a' <= cell <= 'f':
                        new_keys.add(cell)
                    if 'A' <= cell <= 'F' and cell.lower() not in keys:
                        continue
                    state = f"{nx},{ny},{''.join(sorted(new_keys))}"
                    if state not in visited:
                        queue.append(((nx, ny), new_keys))
                        visited.add(state)
        steps += 1
    return -1

