class ExamRoom:
    def __init__(self, n: int):
        self.n = n
        self.seats: list[int] = []

    def seat(self) -> int:
        if not self.seats:
            self.seats.append(0)
            return 0
        max_dist = self.seats[0]
        seat_pos = 0
        for i in range(len(self.seats) - 1):
            d = (self.seats[i + 1] - self.seats[i]) // 2
            if d > max_dist:
                max_dist = d
                seat_pos = self.seats[i] + d
        if self.n - 1 - self.seats[-1] > max_dist:
            seat_pos = self.n - 1
        bisect.insort(self.seats, seat_pos)
        return seat_pos

    def leave(self, p: int) -> None:
        self.seats.remove(p)

