import heapq

def mincost_to_hire_workers(quality: List[int], wage: List[int], k: int) -> float:
    # sort workers by their wage-to-quality ratio
    workers = sorted(((w / q, q) for q, w in zip(quality, wage)), key=lambda x: x[0])
    max_heap: List[int] = []          # max-heap of qualities (stored as negative values)
    total_quality = 0
    min_cost = float('inf')
    for ratio, q in workers:
        total_quality += q
        heapq.heappush(max_heap, -q)
        if len(max_heap) > k:
            removed = -heapq.heappop(max_heap)
            total_quality -= removed
        if len(max_heap) == k:
            cost = total_quality * ratio
            if cost < min_cost:
                min_cost = cost
    return round(min_cost, 5)

