def die_simulator(n: int, roll_max: List[int]) -> int:
    MOD = 10**9 + 7
    memo = {}
    def dp(roll: int, last: int, count: int) -> int:
        if roll == n:
            return 1
        key = (roll, last, count)
        if key in memo:
            return memo[key]
        res = 0
        for i in range(1, 7):
            if i == last and count == roll_max[i - 1]:
                continue
            res = (res + dp(roll + 1, i, count + 1 if i == last else 1)) % MOD
        memo[key] = res
        return res
    return dp(0, 0, 0)

