def max_equal_freq(nums: List[int]) -> int:
    count: Dict[int, int] = {}
    freq_count: Dict[int, int] = {}
    max_len = 0
    max_freq = 0

    for i, val in enumerate(nums):
        prev = count.get(val, 0)
        if prev:
            freq_count[prev] -= 1
            if freq_count[prev] == 0:
                del freq_count[prev]

        new = prev + 1
        count[val] = new
        freq_count[new] = freq_count.get(new, 0) + 1
        max_freq = max(max_freq, new)

        distinct = len(count)

        # condition 1: all frequencies are 1
        if max_freq == 1:
            max_len = i + 1
        # condition 2: one number has max_freq, others have max_freq-1
        elif (
            freq_count.get(max_freq, 0) == 1
            and freq_count.get(max_freq - 1, 0) == distinct - 1
        ):
            max_len = i + 1
        # condition 3: one number has frequency 1, others have max_freq
        elif (
            freq_count.get(1, 0) == 1
            and freq_count.get(max_freq, 0) == distinct - 1
        ):
            max_len = i + 1

    return max_len

