        limit = i + k
        while j <= limit and j < n:
            if digits[j] < digits[min_index]:
                min_index = j
            j += 1
        j = min_index
        while j > i:
            digits[j], digits[j - 1] = digits[j - 1], digits[j]
            k -= 1
            if k == 0:
                break
            j -= 1
        if k == 0:
            break
        i += 1
    return ''.join(digits)

