from collections import deque

def min_number_of_semesters(n: int, relations: List[List[int]], k: int) -> int:
    # prerequisites mask for each course (0‑based)
    prereq = [0] * n
    for prev, nxt in relations:
        prev -= 1
        nxt -= 1
        prereq[nxt] |= 1 << prev

    full_mask = (1 << n) - 1
    dp = [float('inf')] * (1 << n)
    dp[0] = 0
    q = deque([0])

    while q:
        mask = q.popleft()
        semesters = dp[mask]
        if mask == full_mask:
            return semesters

        # courses that are ready to be taken
        available = 0
        for i in range(n):
            if not (mask >> i) & 1 and (prereq[i] & mask) == prereq[i]:
                available |= 1 << i

        # if we can take all available courses this semester
        if available.bit_count() <= k:
            nxt = mask | available
            if dp[nxt] > semesters + 1:
                dp[nxt] = semesters + 1
                q.append(nxt)
        else:
            # enumerate non‑empty subsets of available with size ≤ k
            sub = available
            while sub:
                if sub.bit_count() <= k:
                    nxt = mask | sub
                    if dp[nxt] > semesters + 1:
                        dp[nxt] = semesters + 1
                        q.append(nxt)
                sub = (sub - 1) & available

    return dp[full_mask]  # fallback, should never reach here

