def minimum_size(nums: List[int], max_operations: int) -> int:
    def can_divide(max_balls: int) -> bool:
        operations = 0
        for num in nums:
            operations += (num + max_balls - 1) // max_balls - 1
        return operations <= max_operations

    left, right = 1, max(nums)
    while left < right:
        mid = (left + right) // 2
        if can_divide(mid):
            right = mid
        else:
            left = mid + 1
    return left

def maximum_score(a: int, b: int, c: int) -> int:
    score = 0
    while (a > 0 and b > 0) or (a > 0 and c > 0) or (b > 0 and c > 0):
        max_val = max(a, b, c)
        min_val = min(a, b, c)
        mid = a + b + c - max_val - min_val
        if max_val == a:
            if mid == b:
                a -= 1
                b -= 1
            else:
                a -= 1
                c -= 1
        elif max_val == b:
            if mid == a:
                a -= 1
                b -= 1
            else:
                b -= 1
                c -= 1
        else:
            if mid == a:
                a -= 1
                c -= 1
            else:
                b -= 1
                c -= 1
        score += 1
    return score

