def max_value(events: List[List[int]], k: int) -> int:
    events.sort(key=lambda x: x[0])
    n = len(events)
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        start_i, end_i, val_i = events[i - 1]
        for j in range(1, k + 1):
            best = dp[i - 1][j]  # skip current event
            max_prev = 0
            for l in range(i - 1):
                if events[l][1] < start_i:
                    max_prev = max(max_prev, dp[l + 1][j - 1])
            best = max(best, max_prev + val_i)  # take current event
            dp[i][j] = best
    return dp[n][k]

