def find_redundant_directed_connection(edges: List[List[int]]) -> List[int]:
    n = len(edges)
    parent = [0] * (n + 1)
    first = None
    second = None

    for i in range(n):
        u, v = edges[i]
        if parent[v] != 0:
            first = [parent[v], v]
            second = [u, v]
            edges[i] = None
            break
        parent[v] = u

    def union_find_check(skip_edge: List[int] = None) -> List[int]:
        uf_parent = list(range(n + 1))

        def find(x: int) -> int:
            while uf_parent[x] != x:
                uf_parent[x] = uf_parent[uf_parent[x]]
                x = uf_parent[x]
            return x

        def union(u: int, v: int) -> bool:
            ru, rv = find(u), find(v)
            if ru == rv:
                return False
            uf_parent[rv] = ru
            return True

        for e in edges:
            if e is None or e is skip_edge:
                continue
            u, v = e
            if not union(u, v):
                return e
        return None

    if first is None:
        result = union_find_check()
        return result  # type: ignore
    else:
        result = union_find_check()
        if result is not None:
            return first
        return second

def knight_probability(n: int, k: int, row: int, column: int) -> float:
    directions = [(-2, -1), (-2, 1), (-1, -2), (-1, 2), (1, -2), (1, 2), (2, -1), (2, 1)]
    memo = {}
    def dfs(r: int, c: int, moves: int) -> float:
        if moves == 0:
            return 1.0 if 0 <= r < n and 0 <= c < n else 0.0
        key = (r, c, moves)
        if key in memo:
            return memo[key]
        prob = 0.0
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                prob += dfs(nr, nc, moves - 1)
        prob /= 8.0
        memo[key] = prob
        return prob
    return dfs(row, column, k)

