    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + nums[i]
    sums = [0] * (n - k + 1)
    for i in range(n - k + 1):
        sums[i] = prefix[i + k] - prefix[i]
    max_sum = -float('inf')
    result: List[int] = []
    for i in range(n - k + 1):
        for j in range(i + k, n - k + 1):
            for m in range(j + k, n - k + 1):
                total = sums[i] + sums[j] + sums[m]
                if total > max_sum:
                    max_sum = total
                    result = [i, j, m]
                elif total == max_sum:
                    if (i < result[0] or
                        (i == result[0] and j < result[1]) or
                        (i == result[0] and j == result[1] and m < result[2])):
                        result = [i, j, m]
    return result

