    n = len(target)
    full_mask = (1 << n) - 1
    dp = {0: 0}
    for i in range(1, 1 << n):
        dp[i] = float('inf')
    for mask in range(1 << n):
        if dp[mask] == float('inf'):
            continue
        for sticker in stickers:
            new_mask = mask
            for ch in sticker:
                for i in range(n):
