def my_linked_list():
    state = {'head': None, 'tail': None, 'size': 0}

    def get(index):
        if index < 0 or index >= state['size']:
            return -1
        current = state['head']
        for _ in range(index):
            current = current['next']
        return current['val']

    def add_at_head(val):
        new_node = {'val': val, 'next': None}
        if state['head'] is None:
            state['head'] = state['tail'] = new_node
        else:
            new_node['next'] = state['head']
            state['head'] = new_node
        state['size'] += 1

    def add_at_tail(val):
        new_node = {'val': val, 'next': None}
        if state['tail'] is None:
            state['head'] = state['tail'] = new_node
        else:
            state['tail']['next'] = new_node
            state['tail'] = new_node
        state['size'] += 1

    def add_at_index(index, val):
        if index < 0 or index > state['size']:
            return
        if index == 0:
            return add_at_head(val)
        if index == state['size']:
            return add_at_tail(val)
        new_node = {'val': val, 'next': None}
        current = state['head']
        for _ in range(index - 1):
            current = current['next']
        new_node['next'] = current['next']
        current['next'] = new_node
        state['size'] += 1

    def delete_at_index(index):
        if index < 0 or index >= state['size']:
            return
        if index == 0:
            state['head'] = state['head']['next']
            if state['head'] is None:
                state['tail'] = None
        else:
            current = state['head']
            for _ in range(index - 1):
                current = current['next']
            current['next'] = current['next']['next']
            if current['next'] is None:
                state['tail'] = current
        state['size'] -= 1

    return {
        'get': get, 'addAtHead': add_at_head, 'addAtTail': add_at_tail,
        'addAtIndex': add_at_index, 'deleteAtIndex': delete_at_index,
    }

