def range_module():
    ranges = []
    def add_range(left, right):
        nonlocal ranges
        i = 0
        while i < len(ranges) and ranges[i][1] < left:
            i += 1
        start = i  # preserve the original prefix boundary -- the loop below mutates i
        j = i
        while j < len(ranges) and ranges[j][0] <= right:
            j += 1
        merged = [left, right]
        while i < j:
            merged[0] = min(merged[0], ranges[i][0])
            merged[1] = max(merged[1], ranges[i][1])
            i += 1
        ranges = ranges[:start] + [merged] + ranges[j:]
    def query_range(left, right):
        nonlocal ranges
        i = 0
        while i < len(ranges) and ranges[i][1] < left:
            i += 1
        return i < len(ranges) and ranges[i][0] <= left and right <= ranges[i][1]
    def remove_range(left, right):
        nonlocal ranges
        i = 0
        while i < len(ranges) and ranges[i][1] < left:
            i += 1
        j = i
        while j < len(ranges) and ranges[j][0] < right:
            j += 1
        new_ranges = ranges[:i]
        if i < j:
            if ranges[i][0] < left:
                new_ranges.append([ranges[i][0], left])
            if ranges[i][1] > right:
                new_ranges.append([right, ranges[i][1]])
            i += 1
        while i < j:
            if ranges[i][1] > right:
                new_ranges.append([right, ranges[i][1]])
            i += 1
        ranges = new_ranges + ranges[j:]
    return {'addRange': add_range, 'queryRange': query_range, 'removeRange': remove_range}

