def accounts_merge(accounts: List[List[str]]) -> List[List[str]]:
    parent: Dict[str, str] = {}
    email_map: Dict[str, str] = {}

    for account in accounts:
        for email in account[1:]:
            parent[email] = email
            email_map[email] = account[0]

    def find(email: str) -> str:
        if parent[email] != email:
            parent[email] = find(parent[email])
        return parent[email]

    def union(email1: str, email2: str) -> None:
        root1 = find(email1)
        root2 = find(email2)
        if root1 != root2:
            parent[root1] = root2

    for account in accounts:
        for i in range(2, len(account)):
            union(account[i], account[i - 1])

    result: Dict[str, List[str]] = {}
    for email in parent:
        root = find(email)
        if root not in result:
            result[root] = []
        result[root].append(email)

    final_result: List[List[str]] = []
    for root, emails in result.items():
        emails.sort()
        final_result.append([email_map[root]] + emails)

    return final_result

