def count_of_atoms(formula: str) -> str:
    stack = [{}]
    i = 0
    n = len(formula)
    while i < n:
        ch = formula[i]
        if ch == '(':
            stack.append({})
        elif ch == ')':
            current = stack.pop()
            i += 1
            multiplier = 0
            while i < n and formula[i].isdigit():
                multiplier = multiplier * 10 + int(formula[i])
                i += 1
            if multiplier == 0:
                multiplier = 1
            i -= 1
            for name, cnt in current.items():
                stack[-1][name] = stack[-1].get(name, 0) + cnt * multiplier
        else:
            name = formula[i]
            i += 1
            while i < n and 'a' <= formula[i] <= 'z':
                name += formula[i]
                i += 1
            i -= 1
            multiplier = 0
            while i + 1 < n and formula[i + 1].isdigit():
                i += 1
                multiplier = multiplier * 10 + int(formula[i])
            if multiplier == 0:
                multiplier = 1
            stack[-1][name] = stack[-1].get(name, 0) + multiplier
        i += 1
    result = []
    for name, cnt in stack[0].items():
        result.append(name + (str(cnt) if cnt > 1 else ''))
    return ''.join(sorted(result))

