def count_palindromic_subsequences(s: str) -> int:
    MOD = 10**9 + 7
    n = len(s)
    if n == 0:
        return 0
    dp: List[List[int]] = [[0] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = 1

    # next occurrence of each character after position i
    next_idx: List[List[int]] = [[-1] * 26 for _ in range(n)]
    # prev occurrence of each character before position i
    prev_idx: List[List[int]] = [[-1] * 26 for _ in range(n)]

    last = [-1] * 26
    for i in range(n - 1, -1, -1):
        last[ord(s[i]) - 97] = i
        for c in range(26):
            next_idx[i][c] = last[c]

    last = [-1] * 26
    for i in range(n):
        last[ord(s[i]) - 97] = i
        for c in range(26):
            prev_idx[i][c] = last[c]

    for length in range(2, n + 1):
        for i in range(0, n - length + 1):
            j = i + length - 1
            if s[i] == s[j]:
                c = ord(s[i]) - 97
                low = next_idx[i + 1][c] if i + 1 < n else -1
                high = prev_idx[j - 1][c] if j - 1 >= 0 else -1
                if low == -1 or low > j - 1:
                    dp[i][j] = (dp[i + 1][j - 1] * 2 + 2) % MOD
                elif low == high:
                    dp[i][j] = (dp[i + 1][j - 1] * 2 + 1) % MOD
                else:
                    dp[i][j] = (dp[i + 1][j - 1] * 2 - dp[low + 1][high - 1]) % MOD
            else:
                dp[i][j] = (dp[i + 1][j] + dp[i][j - 1] - dp[i + 1][j - 1]) % MOD
            if dp[i][j] < 0:
                dp[i][j] += MOD
    return dp[0][n - 1]

