def evaluate(expression: str) -> int:
    tokens: List[str] = expression.replace('(', ' ( ').replace(')', ' ) ').split()
    n = len(tokens)
    i = 0
    env: List[Dict[str, int]] = [{}]

    def get_var(name: str) -> int:
        for scope in reversed(env):
            if name in scope:
                return scope[name]
        raise ValueError(f"Undefined variable: {name}")

    def eval_expr() -> int:
        nonlocal i
        token = tokens[i]

        if token == '(':
            i += 1  # skip '('
            op = tokens[i]
            i += 1  # skip operator

            if op == 'let':
                env.append({})
                while True:
                    # If the next token starts a final expression
                    if tokens[i] == '(' or (i + 1 < n and tokens[i + 1] == ')'):
                        val = eval_expr()
                        env.pop()
                        i += 1  # skip ')'
                        return val
                    # Otherwise it's a variable assignment
                    var_name = tokens[i]
                    i += 1
                    val = eval_expr()
                    env[-1][var_name] = val
                # unreachable
            elif op == 'add':
                val1 = eval_expr()
                val2 = eval_expr()
                i += 1  # skip ')'
                return val1 + val2
            elif op == 'mult':
                val1 = eval_expr()
                val2 = eval_expr()
                i += 1  # skip ')'
                return val1 * val2
            else:
                raise ValueError(f"Unknown operator: {op}")

        else:
            i += 1
            if token[0].isdigit() or token[0] == '-':
                return int(token)
            else:
                return get_var(token)

    return eval_expr()

