    queue = [('0000', 0)]
    visited = {'0000'}
    while queue:
        lock, turns = queue.pop(0)
        for i in range(4):
            for j in (-1, 1):
                next_digit = (int(lock[i]) + j + 10) % 10
                next_lock = lock[:i] + str(next_digit) + lock[i+1:]
                if next_lock == target:
                    return turns + 1
                if next_lock not in dead and next_lock not in visited:
                    queue.append((next_lock, turns + 1))
                    visited.add(next_lock)
    return -1

