def contain_virus(is_infected: List[List[int]]) -> int:
    m = len(is_infected)
    n = len(is_infected[0]) if m else 0
    total_walls = 0

    while True:
        visited = [[False] * n for _ in range(m)]
        regions: List[Tuple[Set[Tuple[int, int]], Set[Tuple[int, int]], int]] = []

        def dfs(sx: int, sy: int) -> Tuple[Set[Tuple[int, int]], Set[Tuple[int, int]], int]:
            stack = [(sx, sy)]
            region: Set[Tuple[int, int]] = set()
            frontier: Set[Tuple[int, int]] = set()
            walls = 0
            while stack:
                x, y = stack.pop()
                if visited[x][y]:
                    continue
                visited[x][y] = True
                region.add((x, y))
                for dx, dy in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < m and 0 <= ny < n:
                        if is_infected[nx][ny] == 0:
                            walls += 1
                            frontier.add((nx, ny))
                        elif is_infected[nx][ny] == 1 and not visited[nx][ny]:
                            stack.append((nx, ny))
            return region, frontier, walls

        for i in range(m):
            for j in range(n):
                if is_infected[i][j] == 1 and not visited[i][j]:
                    region, frontier, walls = dfs(i, j)
                    regions.append((region, frontier, walls))

        if not regions:
            break

        # choose region with largest frontier
        max_idx = max(range(len(regions)), key=lambda i: len(regions[i][1]))
        _, _, walls_needed = regions[max_idx]
        total_walls += walls_needed

        # quarantine the chosen region
        for x, y in regions[max_idx][0]:
            is_infected[x][y] = -1

        # spread virus from other regions
        for idx, (_, frontier, _) in enumerate(regions):
            if idx == max_idx:
                continue
            for x, y in frontier:
                if is_infected[x][y] == 0:
                    is_infected[x][y] = 1

    return total_walls

