        if char not in frequency_map:
            frequency_map[char] = 0
        frequency_map[char] += 1
    max_heap = []
    for char, freq in frequency_map.items():
        max_heap.append([char, freq])
    max_heap.sort(key=lambda x: x[1], reverse=True)
    result = ""
    while max_heap:
        if result and result[-1] == max_heap[0][0]:
            if len(max_heap) == 1:
                return ""
            second_char = max_heap[1]
            result += second_char[0]
            second_char[1] -= 1
            if second_char[1] == 0:
                del max_heap[1]
            top_char = max_heap.pop(0)
            max_heap.append(top_char)
        else:
            top_char = max_heap.pop(0)
            result += top_char[0]
            top_char[1] -= 1
            if top_char[1] > 0:
                max_heap.append(top_char)
        max_heap.sort(key=lambda x: x[1], reverse=True)
    return result

