def pyramid_transition(bottom: str, allowed: List[str]) -> bool:
    allowed_map: Dict[str, List[str]] = {}
    for pattern in allowed:
        key = pattern[:2]
        allowed_map.setdefault(key, []).append(pattern[2])
    memo: Dict[str, bool] = {}
    def dfs(b: str) -> bool:
        if len(b) == 1:
            return True
        if b in memo:
            return memo[b]
        next_level: List[str] = []
        for i in range(len(b) - 1):
            pair = b[i:i+2]
            if pair not in allowed_map:
                memo[b] = False
                return False
            if not next_level:
                next_level = allowed_map[pair][:]
            else:
                temp: List[str] = []
                for n in next_level:
                    for a in allowed_map[pair]:
                        temp.append(n + a)
                next_level = temp
        for n in next_level:
            if dfs(n):
                memo[b] = True
                return True
        memo[b] = False
        return False
    return dfs(bottom)

