from collections import Counter

def basic_calculator_iv(expression: str, evalvars: List[str], evalints: List[int]) -> List[str]:
    # map of known variable values
    val_map: Dict[str, int] = {v: i for v, i in zip(evalvars, evalints)}

    # tokenization
    tokens = []
    i = 0
    n = len(expression)
    while i < n:
        ch = expression[i]
        if ch == ' ':
            i += 1
            continue
        if ch.isdigit():
            j = i
            while j < n and expression[j].isdigit():
                j += 1
            tokens.append(expression[i:j])
            i = j
        elif ch.isalpha():
            j = i
            while j < n and expression[j].isalpha():
                j += 1
            tokens.append(expression[i:j])
            i = j
        else:
            tokens.append(ch)
            i += 1

    # helper to combine counters
    def add_counter(a: Counter, b: Counter, sign: int = 1) -> Counter:
        res = Counter(a)
        for k, v in b.items():
            res[k] += sign * v
            if res[k] == 0:
                del res[k]
        return res

    def mul_counter(a: Counter, b: Counter) -> Counter:
        res = Counter()
        for vars1, coeff1 in a.items():
            for vars2, coeff2 in b.items():
                new_coeff = coeff1 * coeff2
                new_vars = tuple(sorted(vars1 + vars2))
                res[new_vars] += new_coeff
        # remove zero coeff entries
        zero_keys = [k for k, v in res.items() if v == 0]
        for k in zero_keys:
            del res[k]
        return res

    # recursive descent parser
    idx = 0
    def parse_expression() -> Counter:
        nonlocal idx
        left = parse_term()
        while idx < len(tokens) and tokens[idx] in ('+', '-'):
            op = tokens[idx]
            idx += 1
            right = parse_term()
            if op == '+':
                left = add_counter(left, right, 1)
            else:
                left = add_counter(left, right, -1)
        return left

    def parse_term() -> Counter:
        nonlocal idx
        left = parse_factor()
        while idx < len(tokens) and tokens[idx] == '*':
            idx += 1
            right = parse_factor()
            left = mul_counter(left, right)
        return left

    def parse_factor() -> Counter:
        nonlocal idx
        token = tokens[idx]
        if token == '(':
            idx += 1
            inner = parse_expression()
            # expect ')'
            idx += 1  # skip ')'
            return inner
        elif token.isdigit():
            idx += 1
            return Counter({(): int(token)})
        else:  # variable
            idx += 1
            if token in val_map:
                return Counter({(): val_map[token]})
            else:
                return Counter({(token,): 1})

    # parse whole expression
    result_counter = parse_expression()

    # format output
    terms = []
    for vars_tuple, coeff in result_counter.items():
        if coeff == 0:
            continue
        if not vars_tuple:
            term_str = str(coeff)
        else:
            term_str = f"{coeff}*" + "*".join(vars_tuple)
        terms.append((len(vars_tuple), vars_tuple, term_str))

    # sort by degree descending, then lexicographically
    terms.sort(key=lambda x: (-x[0], x[1]))
    return [t[2] for t in terms]

def reaching_points(sx: int, sy: int, tx: int, ty: int) -> bool:
    while tx > sx and ty > sy:
        if tx > ty:
            tx -= ty
        else:
            ty -= tx
    return (tx == sx and ty >= sy and (ty - sy) % sx == 0) or (ty == sy and tx >= sx and (tx - sx) % sy == 0)

