import heapq

def swim_in_water(grid: List[List[int]]) -> int:
    n = len(grid)
    if n == 0:
        return 0
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = [[False] * n for _ in range(n)]
    heap = [(grid[0][0], 0, 0)]  # (time needed to reach cell, x, y)
    visited[0][0] = True

    while heap:
        time, x, y = heapq.heappop(heap)
        if x == n - 1 and y == n - 1:
            return time
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n and not visited[nx][ny]:
                visited[nx][ny] = True
                heapq.heappush(heap, (max(time, grid[nx][ny]), nx, ny))

    return -1  # should never reach here

def can_transform(start: str, result: str) -> bool:
    start_pointer = 0
    result_pointer = 0
    while start_pointer < len(start) and result_pointer < len(result):
        while start_pointer < len(start) and start[start_pointer] == 'X':
            start_pointer += 1
        while result_pointer < len(result) and result[result_pointer] == 'X':
            result_pointer += 1
        if start_pointer == len(start) and result_pointer == len(result):
            return True
        if start_pointer == len(start) or result_pointer == len(result):
            return False
        if start[start_pointer] != result[result_pointer]:
            return False
        if (start[start_pointer] == 'L' and start_pointer < result_pointer) or (start[start_pointer] == 'R' and start_pointer > result_pointer):
            return False
        start_pointer += 1
        result_pointer += 1
    return True

