def is_ideal_permutation(nums: List[int]) -> bool:
    n = len(nums)
    global_inversions = 0
    local_inversions = 0
    for i in range(n - 1):
        if nums[i] > nums[i + 1]:
            local_inversions += 1
    for i in range(n):
        for j in range(i + 1, n):
            if nums[i] > nums[j]:
                global_inversions += 1
    return global_inversions == local_inversions

