def sliding_puzzle(board: List[List[int]]) -> int:
    target = [[1, 2, 3], [4, 5, 0]]
    directions = [[1, 3], [0, 2, 4], [1, 5], [0, 4], [1, 3, 5], [2, 4]]
    queue = [(board, 0)]
    visited = set()
    visited.add(json.dumps(board))
    while queue:
        state, moves = queue.pop(0)
        if json.dumps(state) == json.dumps(target):
            return moves
        zero_index = -1
        for i in range(2):
            for j in range(3):
                if state[i][j] == 0:
                    zero_index = i * 3 + j
                    break
            if zero_index != -1:
                break
        for nxt in directions[zero_index]:
            next_state = [row[:] for row in state]
            zr, zc = zero_index // 3, zero_index % 3
            nr, nc = nxt // 3, nxt % 3
            next_state[zr][zc], next_state[nr][nc] = next_state[nr][nc], next_state[zr][zc]
            next_state_str = json.dumps(next_state)
            if next_state_str not in visited:
                queue.append((next_state, moves + 1))
                visited.add(next_state_str)
    return -1

