        if char not in frequency:
            frequency[char] = 0
        frequency[char] += 1
    result = ''
    for char in order:
        if frequency.get(char, 0):
            result += char * frequency[char]
            frequency[char] = 0
    for char, count in frequency.items():
        if count > 0:
            result += char * count
    return result

