def preimage_size_fzf(k: int) -> int:
    def trailing_zeroes(x: int) -> int:
        cnt = 0
        while x:
            x //= 5
            cnt += x
        return cnt

    left, right = 0, 5 * k + 5
    while left < right:
        mid = (left + right) // 2
        if trailing_zeroes(mid) < k:
            left = mid + 1
        else:
            right = mid

    return 5 if trailing_zeroes(left) == k else 0

