def rotated_digits(n: int) -> int:
    def rotate_number(num: int) -> int:
        rotated = 0
        while num > 0:
            digit = num % 10
            if digit in (0, 1, 8):
                mapped = digit
            elif digit == 2:
                mapped = 5
            elif digit == 5:
                mapped = 2
            elif digit == 6:
                mapped = 9
            elif digit == 9:
                mapped = 6
            else:
                return -1
            rotated = rotated * 10 + mapped
            num //= 10
        return rotated

    count = 0
    for i in range(1, n + 1):
        rotated = rotate_number(i)
        if rotated != -1 and rotated != i and len(str(rotated)) == len(str(i)):
            count += 1
    return count

