def find_cheapest_price(n: int, flights: List[List[int]], src: int, dst: int, k: int) -> int:
    graph = {i: [] for i in range(n)}
    for frm, to, price in flights:
        graph[frm].append((to, price))
    queue = deque()
    queue.append((src, 0, k + 1))
    prices = [float('inf')] * n
    prices[src] = 0
    while queue:
        city, price, stops = queue.popleft()
        if city == dst:
            prices[dst] = min(prices[dst], price)
        if stops == 0:
            continue
        for neighbor, neighbor_price in graph[city]:
            new_price = price + neighbor_price
            if new_price < prices[neighbor]:
                prices[neighbor] = new_price
                queue.append((neighbor, new_price, stops - 1))
    return -1 if prices[dst] == float('inf') else prices[dst]

