def hit_bricks(grid: List[List[int]], hits: List[List[int]]) -> List[int]:
    rows, cols = len(grid), len(grid[0])
    size = rows * cols
    top = size  # virtual top node index

    def idx(r: int, c: int) -> int:
        return r * cols + c

    class UnionFind:
        __slots__ = ("parent", "sz")
        def __init__(self, n: int):
            self.parent = list(range(n))
            self.sz = [1] * n

        def find(self, x: int) -> int:
            while self.parent[x] != x:
                self.parent[x] = self.parent[self.parent[x]]
                x = self.parent[x]
            return x

        def union(self, x: int, y: int) -> None:
            rx, ry = self.find(x), self.find(y)
            if rx == ry:
                return
            if self.sz[rx] < self.sz[ry]:
                rx, ry = ry, rx
            self.parent[ry] = rx
            self.sz[rx] += self.sz[ry]

        def get_size(self, x: int) -> int:
            return self.sz[self.find(x)]

    # copy grid and apply hits
    cur = [row[:] for row in grid]
    for r, c in hits:
        if 0 <= r < rows and 0 <= c < cols and cur[r][c] == 1:
            cur[r][c] = 0

    uf = UnionFind(size + 1)

    # initial unions
    for r in range(rows):
        for c in range(cols):
            if cur[r][c] != 1:
                continue
            if r == 0:
                uf.union(idx(r, c), top)
            if r > 0 and cur[r - 1][c] == 1:
                uf.union(idx(r, c), idx(r - 1, c))
            if c > 0 and cur[r][c - 1] == 1:
                uf.union(idx(r, c), idx(r, c - 1))

    res = [0] * len(hits)
    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    for i in range(len(hits) - 1, -1, -1):
        r, c = hits[i]
        if not (0 <= r < rows and 0 <= c < cols) or grid[r][c] == 0:
            # no brick originally
            continue
        prev_top = uf.get_size(top)

        # restore brick
        cur[r][c] = 1
        cur_idx = idx(r, c)

        if r == 0:
            uf.union(cur_idx, top)

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and cur[nr][nc] == 1:
                uf.union(cur_idx, idx(nr, nc))

        new_top = uf.get_size(top)
        fallen = new_top - prev_top - 1
        res[i] = fallen if fallen > 0 else 0

    return res
# TIME: O((m*n + hits) * α(m*n)) SPACE: O(m*n)

import math

def soup_servings(n: int) -> float:
    n = math.ceil(n / 25)
    if n >= 179:
        return 1.0
    memo = {}
    def dfs(a: int, b: int) -> float:
        if (a, b) in memo:
            return memo[(a, b)]
        if a <= 0 and b > 0:
            return 1.0
        if a <= 0 and b <= 0:
            return 0.5
        if a > 0 and b <= 0:
            return 0.0
        res = 0.25 * (dfs(a - 4, b) + dfs(a - 3, b - 1) + dfs(a - 2, b - 2) + dfs(a - 1, b - 3))
        memo[(a, b)] = res
        return res
    return dfs(n, n)

