                bus_stops[stop] = []
            bus_stops[stop].append(i)
    queue = [[source, 0]]
    visited_stops = {source}
    visited_buses = set()
    while queue:
        stop, bus_count = queue.pop(0)
        if stop == target:
            return bus_count
        for bus in bus_stops.get(stop, []):
            if bus in visited_buses:
                continue
            visited_buses.add(bus)
            for next_stop in routes[bus]:
                if next_stop in visited_stops:
                    continue
                visited_stops.add(next_stop)
                queue.append([next_stop, bus_count + 1])
    return -1

