def largest_sum_of_averages(nums: List[int], k: int) -> float:
    n = len(nums)
    prefix_sum = [0] * (n + 1)
    for i in range(n):
        prefix_sum[i + 1] = prefix_sum[i] + nums[i]
    dp = [[0] * (k + 1) for _ in range(n)]
    for i in range(n):
        dp[i][1] = prefix_sum[i + 1] / (i + 1)
    for j in range(2, k + 1):
        for i in range(j - 1, n):
            for x in range(j - 2, i):
                dp[i][j] = max(dp[i][j], dp[x][j - 1] + (prefix_sum[i + 1] - prefix_sum[x + 1]) / (i - x))
    return dp[n - 1][k]

