def largest_island(grid: List[List[int]]) -> int:
    n = len(grid)
    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    area: dict[int, int] = {}
    label = 2

    def dfs(i: int, j: int, lbl: int) -> int:
        stack = [(i, j)]
        grid[i][j] = lbl
        cnt = 0
        while stack:
            x, y = stack.pop()
            cnt += 1
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < n and grid[nx][ny] == 1:
                    grid[nx][ny] = lbl
                    stack.append((nx, ny))
        return cnt

    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                area[label] = dfs(i, j, label)
                label += 1

    if not area:  # all water
        return 1

    max_area = 0
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 0:
                seen = set()
                total = 1
                for dx, dy in directions:
                    x, y = i + dx, j + dy
                    if 0 <= x < n and 0 <= y < n:
                        lbl = grid[x][y]
                        if lbl > 1 and lbl not in seen:
                            seen.add(lbl)
                            total += area[lbl]
                max_area = max(max_area, total)

    return max_area if max_area != 0 else n * n

