def new21_game(n: int, k: int, max_pts: int) -> float:
    # Trivial cases where Alice always wins
    if k == 0 or n >= k + max_pts - 1:
        return 1.0

    # dp[i] = probability of having exactly i points (only for i < k)
    dp: List[float] = [0.0] * k
    dp[0] = 1.0
    window_sum = 1.0          # sum of probabilities in the last `max_pts` positions
    answer = 0.0

    for points in range(1, n + 1):
        prob = window_sum / max_pts
        if points < k:
            dp[points] = prob
            window_sum += prob
        else:
            answer += prob

        out_idx = points - max_pts
        if out_idx >= 0 and out_idx < k:
            window_sum -= dp[out_idx]

    # Round to 5 decimal places to match expected output format
    return round(answer, 5)

