def sum_of_distances_in_tree(n: int, edges: List[List[int]]) -> List[int]:
    graph: List[List[int]] = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    count: List[int] = [1] * n
    res: List[int] = [0] * n

    def dfs(node: int, parent: int) -> None:
        for child in graph[node]:
            if child != parent:
                dfs(child, node)
                count[node] += count[child]
                res[0] += count[child]  # distance contribution from child subtree

    def dfs2(node: int, parent: int) -> None:
        for child in graph[node]:
            if child != parent:
                res[child] = res[node] + n - 2 * count[child]
                dfs2(child, node)

    dfs(0, -1)
    dfs2(0, -1)
    return res

