def num_similar_groups(strs: List[str]) -> int:
    parent = {s: s for s in strs}
    def find(x: str) -> str:
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]
    def union(x: str, y: str) -> None:
        root_x = find(x)
        root_y = find(y)
        if root_x != root_y:
            parent[root_x] = root_y
    def is_similar(x: str, y: str) -> bool:
        diff = 0
        for i in range(len(x)):
            if x[i] != y[i]:
                diff += 1
                if diff > 2:
                    return False
        return diff == 0 or diff == 2
    n = len(strs)
    for i in range(n):
        for j in range(i + 1, n):
            if is_similar(strs[i], strs[j]):
                union(strs[i], strs[j])
    groups = set()
    for s in strs:
        groups.add(find(s))
    return len(groups)

