def num_magic_squares_inside(grid: List[List[int]]) -> int:
    def is_magic(square: List[List[int]]) -> bool:
        # check numbers 1..9 distinct
        seen = [False] * 10  # index 0 unused
        for row in square:
            for val in row:
                if val < 1 or val > 9 or seen[val]:
                    return False
                seen[val] = True
        # rows, columns, diagonals sum to 15
        target = 15
        for i in range(3):
            if sum(square[i]) != target:
                return False
            if sum(square[r][i] for r in range(3)) != target:
                return False
        if square[0][0] + square[1][1] + square[2][2] != target:
            return False
        if square[0][2] + square[1][1] + square[2][0] != target:
            return False
        return True

    rows, cols = len(grid), len(grid[0])
    count = 0
    for i in range(rows - 2):
        for j in range(cols - 2):
            sub = [grid[i + k][j:j + 3] for k in range(3)]
            if is_magic(sub):
                count += 1
    return count

