def split_into_fibonacci(num: str) -> List[int]:
    result: List[int] = []

    def backtrack(start: int, path: List[int]) -> bool:
        nonlocal result
        if start == len(num) and len(path) >= 3:
            return True
        for i in range(1, len(num) - start + 1):
            substr = num[start:start + i]
            if len(substr) > 1 and substr[0] == '0':
                continue
            curr_num = int(substr)
            if len(path) < 2:
                path.append(curr_num)
                if backtrack(start + i, path):
                    result = path[:]
                    return True
                path.pop()
            else:
                if curr_num == path[-1] + path[-2]:
                    path.append(curr_num)
                    if backtrack(start + i, path):
                        result = path[:]
                        return True
                    path.pop()
        return False

    backtrack(0, [])
    return result

