def rectangle_area(rectangles: List[List[int]]) -> int:
    MOD = 10**9 + 7
    events: List[List[int]] = []
    for x1, y1, x2, y2 in rectangles:
        events.append([x1, 1, y1, y2])   # entering
        events.append([x2, -1, y1, y2])  # leaving
    events.sort(key=lambda e: e[0])

    active: List[List[int]] = []
    area = 0
    prev_x = events[0][0] if events else 0

    for x, typ, y1, y2 in events:
        # compute covered y-length from current active intervals
        if active:
            # merge intervals
            merged = []
            for a, b in sorted(active, key=lambda iv: iv[0]):
                if not merged or a > merged[-1][1]:
                    merged.append([a, b])
                else:
                    merged[-1][1] = max(merged[-1][1], b)
            covered_y = sum(b - a for a, b in merged)
            width = x - prev_x
            area = (area + covered_y * width) % MOD

        # update active set
        if typ == 1:
            active.append([y1, y2])
        else:
            # remove the exact interval
            for i, iv in enumerate(active):
                if iv[0] == y1 and iv[1] == y2:
                    active.pop(i)
                    break

        prev_x = x

    return area

