            diff.append(i)
    if len(diff) == 0:
        char_count = {}
        for ch in s:
            char_count[ch] = char_count.get(ch, 0) + 1
        for cnt in char_count.values():
            if cnt > 1:
                return True
        return False
    elif len(diff) > 2:
        return False
    elif len(diff) == 2:
        s_arr = list(s)
        s_arr[diff[0]], s_arr[diff[1]] = s_arr[diff[1]], s_arr[diff[0]]
        return ''.join(s_arr) == goal
    return False

