    build_parent_map(root, None)
    visited: Set[int] = set()
    result: List[int] = []
    def dfs(node, distance):
        if not node or node.val in visited:
            return
        visited.add(node.val)
        if distance == k:
            result.append(node.val)
        if distance < k:
            dfs(node.left, distance + 1)
            dfs(node.right, distance + 1)
            dfs(parent_map.get(node.val), distance + 1)
    dfs(target, 0)
    return result

import sys, re

def max_dist_to_closest(seats):
    n = len(seats)
    max_dist = 0
    last = -1
    for i, s in enumerate(seats):
        if s == 1:
            if last == -1:
                max_dist = max(max_dist, i)  # leading zeros
            else:
                gap = i - last - 1
                max_dist = max(max_dist, (gap + 1) // 2)
            last = i
    # trailing zeros
    if last != -1:
        max_dist = max(max_dist, n - 1 - last)
    return max_dist

