def matrix_score(grid: List[List[int]]) -> int:
    rows = len(grid)
    cols = len(grid[0])
    for i in range(rows):
        if grid[i][0] == 0:
            for j in range(cols):
                grid[i][j] = 1 - grid[i][j]
    for j in range(1, cols):
        ones = 0
        zeros = 0
        for i in range(rows):
            if grid[i][j] == 1:
                ones += 1
            else:
                zeros += 1
        if zeros > ones:
            for i in range(rows):
                grid[i][j] = 1 - grid[i][j]
    score = 0
    for i in range(rows):
        row_score = 0
        for j in range(cols):
            row_score += grid[i][j] * (1 << (cols - 1 - j))
        score += row_score
    return score

