    directions = [[0, 1], [1, 0], [0, -1], [-1, 0]]
    current_direction = 0
    current_position = [0, 0]
    obstacle_set = set()
    for obstacle in obstacles:
        obstacle_set.add(','.join(map(str, obstacle)))
    for command in commands:
        if command < 0:
            current_direction = (current_direction + (1 if command == -1 else -1) + 4) % 4
        else:
            for _ in range(command):
                next_position = [
                    current_position[0] + directions[current_direction][0],
                    current_position[1] + directions[current_direction][1]
                ]
                if ','.join(map(str, next_position)) in obstacle_set:
                    break
                current_position = next_position
                distance = current_position[0] * current_position[0] + current_position[1] * current_position[1]
                max_distance = max(max_distance, distance)
    return max_distance

