def nth_magical_number(n, a, b):
    MOD = 10**9 + 7
    left, right = min(a, b), n * min(a, b)
    lcm_ab = a // math.gcd(a, b) * b
    while left < right:
        mid = (left + right) // 2
        count = mid // a + mid // b - mid // lcm_ab
        if count < n:
            left = mid + 1
        else:
            right = mid
    return left % MOD

