def profitable_schemes(n: int, min_profit: int, group: List[int], profit: List[int]) -> int:
    MOD = 10**9 + 7
    dp = [[0] * (min_profit + 1) for _ in range(n + 1)]
    dp[0][0] = 1
    for g, p in zip(group, profit):
        for people in range(n, g - 1, -1):
            for prof in range(min_profit, -1, -1):
                dp[people][prof] = (dp[people][prof] + dp[people - g][max(0, prof - p)]) % MOD
    return sum(dp[i][min_profit] for i in range(n + 1)) % MOD
# TIME: O(n * min_profit * len(group)) SPACE: O(n * min_profit)

