def construct_from_pre_post(preorder: List[int], postorder: List[int]) -> Optional[TreeNode]:
    def build_tree(pre_start: int, pre_end: int, post_start: int, post_end: int) -> Optional[TreeNode]:
        if pre_start > pre_end:
            return None
        root = TreeNode(preorder[pre_start])
        if pre_start == pre_end:
            return root
        left_child_index = pre_start + 1
        left_child_post_index = post_start
        while postorder[left_child_post_index] != preorder[left_child_index]:
            left_child_post_index += 1
        left_tree_length = left_child_post_index - post_start + 1
        root.left = build_tree(left_child_index, left_child_index + left_tree_length - 1, post_start, left_child_post_index)
        root.right = build_tree(left_child_index + left_tree_length, pre_end, left_child_post_index + 1, post_end - 1)
        return root
    return build_tree(0, len(preorder) - 1, 0, len(postorder) - 1)

