def num_perms_di_sequence(s: str) -> int:
    MOD = 10**9 + 7
    n = len(s)
    # dp[i][j]: number of ways for first i characters (i+1 numbers) ending with rank j (0‑based)
    dp: List[List[int]] = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        # prefix sums of previous row for O(1) range queries
        pref: List[int] = [0] * (i + 1)
        pref[0] = dp[i - 1][0]
        for k in range(1, i):
            pref[k] = (pref[k - 1] + dp[i - 1][k]) % MOD

        if s[i - 1] == 'I':
            for j in range(i + 1):
                # sum of dp[i-1][0..j-1]
                if j == 0:
                    dp[i][j] = 0
                else:
                    dp[i][j] = pref[j - 1]
        else:  # 'D'
            total = pref[i - 1]  # sum of dp[i-1][0..i-1]
            for j in range(i + 1):
                # sum of dp[i-1][j..i-1] = total - pref[j-1]
                if j == 0:
                    dp[i][j] = total
                else:
                    dp[i][j] = (total - pref[j - 1]) % MOD

    result = sum(dp[n][j] for j in range(n + 1)) % MOD
    return result

