def all_possible_fbt(n):
    if n % 2 == 0:
        return []
    if n == 1:
        return [TreeNode(0)]
    result = []
    for i in range(1, n, 2):
        left_trees = all_possible_fbt(i)
        right_trees = all_possible_fbt(n - i - 1)
        for left in left_trees:
