def freq_stack():
    frequency_map = {}
    frequency_to_elements = {}
    max_frequency = 0

    def push(x):
        nonlocal max_frequency
        frequency_map[x] = frequency_map.get(x, 0) + 1
        freq = frequency_map[x]
        if freq > max_frequency:
            max_frequency = freq
        if freq not in frequency_to_elements:
            frequency_to_elements[freq] = []
        frequency_to_elements[freq].append(x)

    def pop():
        nonlocal max_frequency
        most_frequent_elements = frequency_to_elements[max_frequency]
        removed_element = most_frequent_elements.pop()
        frequency_map[removed_element] -= 1
        if not most_frequent_elements:
            max_frequency -= 1
        return removed_element

    return {"push": push, "pop": pop}

