def sum_subarray_mins(arr: List[int]) -> int:
    MOD = 10**9 + 7
    n = len(arr)
    left = [-1] * n
    right = [n] * n
    stack = []
    for i in range(n):
        while stack and arr[stack[-1]] >= arr[i]:
            stack.pop()
        if stack:
            left[i] = stack[-1]
        stack.append(i)
    stack.clear()
    for i in range(n - 1, -1, -1):
        while stack and arr[stack[-1]] > arr[i]:
            stack.pop()
        if stack:
            right[i] = stack[-1]
        stack.append(i)
    total = 0
    for i in range(n):
        count = (i - left[i]) * (right[i] - i)
        total = (total + count * arr[i]) % MOD
    return total

