def snakes_and_ladders(board: List[List[int]]) -> int:
    n = len(board)
    cells = [0] * (n * n)
    for i in range(n):
        for j in range(n):
            idx = i * n + j if i % 2 == 0 else i * n + n - j - 1
            cells[idx] = board[n - i - 1][j]
    queue = deque()
    queue.append((0, 0))
    visited = {0}
    while queue:
        curr, rolls = queue.popleft()
        if curr == n * n - 1:
            return rolls
        for dice in range(1, 7):
            nxt = curr + dice
            if nxt >= n * n:
                continue
            if cells[nxt] != -1:
                nxt = cells[nxt] - 1
            if nxt not in visited:
                visited.add(nxt)
                queue.append((nxt, rolls + 1))
    return -1

