from typing import List

def cat_mouse_game(graph: List[List[int]]) -> int:
    n = len(graph)
    # result[mouse][cat][turn] = 0 unknown, 1 mouse wins, 2 cat wins
    result = [[[0, 0] for _ in range(n)] for _ in range(n)]
    # degree[mouse][cat][turn] = number of moves from this state
    degree = [[[0, 0] for _ in range(n)] for _ in range(n)]

    # initialize degrees
    for m in range(n):
        for c in range(n):
            # mouse's turn
            degree[m][c][0] = len(graph[m])
            # cat's turn (cannot move to hole 0)
            cnt = 0
            for nxt in graph[c]:
                if nxt != 0:
                    cnt += 1
            degree[m][c][1] = cnt

    q = deque()

    # terminal states: mouse at hole -> mouse wins
    for c in range(n):
        for turn in (0, 1):
            if result[0][c][turn] == 0:
                result[0][c][turn] = 1
                q.append((0, c, turn))
    # terminal states: cat catches mouse (mouse != 0) -> cat wins
    for m in range(1, n):
        for turn in (0, 1):
            if result[m][m][turn] == 0:
                result[m][m][turn] = 2
                q.append((m, m, turn))

    while q:
        m, c, turn = q.popleft()
        cur_res = result[m][c][turn]
        prev_turn = 1 - turn  # player who moved to reach (m,c,turn)

        if prev_turn == 0:  # mouse moved last
            # predecessors: mouse was at pm, cat stayed at c
            for pm in graph[m]:
                if result[pm][c][prev_turn] != 0:
                    continue
                # if the move leads to a state where mouse wins, mouse can force win
                if cur_res == 1:
                    result[pm][c][prev_turn] = 1
                    q.append((pm, c, prev_turn))
                else:
                    degree[pm][c][prev_turn] -= 1
                    if degree[pm][c][prev_turn] == 0:
                        result[pm][c][prev_turn] = 2
                        q.append((pm, c, prev_turn))
        else:  # cat moved last
            # cat cannot be at hole, so c != 0
            if c == 0:
                continue
            for pc in graph[c]:
                if pc == 0:
                    continue  # cat cannot move to hole
                if result[m][pc][prev_turn] != 0:
                    continue
                # if the move leads to a state where cat wins, cat can force win
                if cur_res == 2:
                    result[m][pc][prev_turn] = 2
                    q.append((m, pc, prev_turn))
                else:
                    degree[m][pc][prev_turn] -= 1
                    if degree[m][pc][prev_turn] == 0:
                        result[m][pc][prev_turn] = 1
                        q.append((m, pc, prev_turn))

    return result[1][2][0]  # start state: mouse at 1, cat at 2, mouse's turn

