def num_music_playlists(n: int, goal: int, k: int) -> int:
    MOD = 10**9 + 7
    if goal < n:
        return 0
    dp = [[0] * (n + 1) for _ in range(goal + 1)]
    dp[0][0] = 1
    for i in range(1, goal + 1):
        for j in range(1, n + 1):
            # add a new unique song
            dp[i][j] = (dp[i][j] + dp[i - 1][j - 1] * (n - j + 1)) % MOD
            # replay an existing song, respecting the k constraint
            if j > k:
                dp[i][j] = (dp[i][j] + dp[i - 1][j] * (j - k)) % MOD
    return dp[goal][n] % MOD

