def cbt_inserter(root):
    q = deque([root])
    queue = deque()  # nodes missing at least one child, in level order
    while q:
        node = q.popleft()
        if not node.left or not node.right:
            queue.append(node)
        if node.left:
            q.append(node.left)
        if node.right:
            q.append(node.right)

    def insert(val):
        node = TreeNode(val)
        parent = queue[0]
        if not parent.left:
            parent.left = node
        else:
            parent.right = node
            queue.popleft()
        queue.append(node)
        return parent.val

    def get_root():
        return root

    return {"insert": insert, "get_root": get_root}

