def sort_array_by_parity_ii(nums: List[int]) -> List[int]:
    even_index = 0
    odd_index = 1
    n = len(nums)
    while even_index < n and odd_index < n:
        if nums[even_index] % 2 == 1:
            while nums[odd_index] % 2 == 1:
                odd_index += 2
            nums[even_index], nums[odd_index] = nums[odd_index], nums[even_index]
        if nums[odd_index] % 2 == 0:
            while nums[even_index] % 2 == 0:
                even_index += 2
            nums[odd_index], nums[even_index] = nums[even_index], nums[odd_index]
        even_index += 2
        odd_index += 2
    return nums

