def three_sum_multi(arr: List[int], target: int) -> int:
    frequency: Dict[int, int] = {}
    for num in arr:
        frequency[num] = frequency.get(num, 0) + 1

    def combination(n: int, r: int) -> int:
        if r == 2:
            return n * (n - 1) // 2
        if r == 3:
            return n * (n - 1) * (n - 2) // 6
        return 0

    count = 0
    keys = sorted(frequency)
    for i_idx, i in enumerate(keys):
        for j_idx in range(i_idx, len(keys)):
            j = keys[j_idx]
            k = target - i - j
            if k < j:  # ensure ordering i <= j <= k
                continue
            if k not in frequency:
                continue
            if i == j == k:
                count += combination(frequency[i], 3)
            elif i == j:
                count += combination(frequency[i], 2) * frequency[k]
            elif j == k:
                count += combination(frequency[j], 2) * frequency[i]
            else:
                count += frequency[i] * frequency[j] * frequency[k]
    return count

