def min_malware_spread(graph: List[List[int]], initial: List[int]) -> int:
    n = len(graph)
    parent = list(range(n))
    size = [1] * n

    def find(x: int) -> int:
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x: int, y: int) -> None:
        root_x = find(x)
        root_y = find(y)
        if root_x != root_y:
            if size[root_x] < size[root_y]:
                parent[root_x] = root_y
                size[root_y] += size[root_x]
            else:
                parent[root_y] = root_x
                size[root_x] += size[root_y]

    for i in range(n):
        for j in range(n):
            if graph[i][j] == 1:
                union(i, j)

    infected = [0] * n
    for node in initial:
        infected[find(node)] += 1

    res = -1
    max_save = 0
    for node in initial:
        root = find(node)
        if infected[root] == 1:
            if size[root] > max_save:
                max_save = size[root]
                res = node
            elif size[root] == max_save:
                res = min(res, node)

    if res == -1:
        res = min(initial)

    return res

