def min_malware_spread(graph: List[List[int]], initial: List[int]) -> int:
    n = len(graph)
    # build adjacency list (ignore self loops)
    neighbors = [[] for _ in range(n)]
    for i in range(n):
        row = graph[i]
        for j in range(n):
            if i != j and row[j]:
                neighbors[i].append(j)

    best_node = min(initial)
    best_infected = n + 1  # larger than any possible infected count

    for removed in initial:
        visited = [False] * n
        visited[removed] = True  # node is removed from the graph

        # spread infection from remaining initially infected nodes
        for src in initial:
            if src == removed or visited[src]:
                continue
            stack = [src]
            visited[src] = True
            while stack:
                cur = stack.pop()
                for nb in neighbors[cur]:
                    if not visited[nb]:
                        visited[nb] = True
                        stack.append(nb)

        infected_cnt = sum(visited) - 1  # exclude the removed node
        if infected_cnt < best_infected or (infected_cnt == best_infected and removed < best_node):
            best_infected = infected_cnt
            best_node = removed

    return best_node
