def shortest_bridge(grid: List[List[int]]) -> int:
    n = len(grid)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # locate and mark the first island using an explicit stack to avoid recursion depth issues
    island_cells: List[tuple[int, int]] = []
    found = False
    for i in range(n):
        if found:
            break
        for j in range(n):
            if grid[i][j] == 1:
                stack = [(i, j)]
                while stack:
                    x, y = stack.pop()
                    if 0 <= x < n and 0 <= y < n and grid[x][y] == 1:
                        grid[x][y] = -1          # mark as visited
                        island_cells.append((x, y))
                        for dx, dy in directions:
                            stack.append((x + dx, y + dy))
                found = True
                break

    # BFS outward from the first island
    q = deque([(x, y, 0) for x, y in island_cells])  # (row, col, distance)
    while q:
        x, y, dist = q.popleft()
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n:
                if grid[nx][ny] == 1:          # reached the second island
                    return dist
                if grid[nx][ny] == 0:          # water, continue expanding
                    grid[nx][ny] = -1
                    q.append((nx, ny, dist + 1))
    return -1  # should never happen with valid input

