def moves_to_stamp(stamp: str, target: str) -> List[int]:
    n, m = len(target), len(stamp)
    t = list(target)
    result: List[int] = []
    visited = [False] * (n - m + 1)
    total_q = 0

    def can_stamp(i: int) -> bool:
        made = False
        for j in range(m):
            if t[i + j] == '?':
                continue
            if t[i + j] != stamp[j]:
                return False
            made = True
        return made

    while total_q < n:
        changed = False
        for i in range(n - m + 1):
            if visited[i]:
                continue
            if can_stamp(i):
                for j in range(m):
                    if t[i + j] != '?':
                        t[i + j] = '?'
                        total_q += 1
                visited[i] = True
                result.append(i)
                changed = True
                break  # restart scanning after a successful stamp
        if not changed:
            return []
    return result[::-1]  # reverse to get the stamping order

