def shortest_superstring(words: List[str]) -> str:
    n = len(words)
    # compute overlap: max suffix of words[i] that matches prefix of words[j]
    overlap = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i == j:
                continue
            max_k = min(len(words[i]), len(words[j]))
            for k in range(max_k, 0, -1):
                if words[i].endswith(words[j][:k]):
                    overlap[i][j] = k
                    break

    # dp[mask][i] = (total_len, path_tuple) for best superstring ending with i covering mask
    dp: List[List[Tuple[int, Tuple[int, ...]]]] = [[None] * n for _ in range(1 << n)]
    for i in range(n):
        dp[1 << i][i] = (len(words[i]), (i,))

    for mask in range(1, 1 << n):
        for i in range(n):
            if not (mask >> i) & 1:
                continue
            prev_mask = mask ^ (1 << i)
            if prev_mask == 0:
                continue
            best = None
            for j in range(n):
                if not (prev_mask >> j) & 1:
                    continue
                prev = dp[prev_mask][j]
                if prev is None:
                    continue
                cand_len = prev[0] + len(words[i]) - overlap[j][i]
                cand_path = prev[1] + (i,)
                cur = dp[mask][i]
                if cur is None or cand_len < cur[0] or (cand_len == cur[0] and cand_path < cur[1]):
                    dp[mask][i] = (cand_len, cand_path)

    full_mask = (1 << n) - 1
    best_len = None
    best_path = None
    for i in range(n):
        entry = dp[full_mask][i]
        if entry is None:
            continue
        if best_len is None or entry[0] < best_len or (entry[0] == best_len and entry[1] < best_path):
            best_len, best_path = entry

    # reconstruct superstring from best_path
    if best_path is None:
        return ""
    result = words[best_path[0]]
    for k in range(1, len(best_path)):
        prev_idx = best_path[k - 1]
        cur_idx = best_path[k]
        ov = overlap[prev_idx][cur_idx]
        result += words[cur_idx][ov:]
    return result

