def remove_stones(stones: List[List[int]]) -> int:
    parent = {}
    rank = {}

    def find(x):
        if x not in parent:
            parent[x] = x
            rank[x] = 0
        if parent[x] == x:
            return x
        parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        root_x = find(x)
        root_y = find(y)
        if root_x == root_y:
            return
        if rank[root_x] > rank[root_y]:
            parent[root_y] = root_x
        elif rank[root_x] < rank[root_y]:
            parent[root_x] = root_y
        else:
            parent[root_y] = root_x
            rank[root_x] += 1

    for i in range(len(stones)):
        for j in range(i + 1, len(stones)):
            if stones[i][0] == stones[j][0] or stones[i][1] == stones[j][1]:
                union(','.join(map(str, stones[i])), ','.join(map(str, stones[j])))

    groups = set()
    for stone in stones:
        groups.add(find(','.join(map(str, stone))))

    return len(stones) - len(groups)

