    parent = {num: num for num in nums}

    for i, num1 in enumerate(nums):
        for num2 in nums[i + 1 :]:
            if get_common_factor(prime_factors[num1], prime_factors[num2]) != -1:
                union(parent, num1, num2)

    component_sizes = {}
    for num in nums:
        root = find(parent, num)
        component_sizes[root] = component_sizes.get(root, 0) + 1

    max_size = 0
    for size in component_sizes.values():
        if size > max_size:
            max_size = size
    return max_size

