    state = ''.join(str(c) for c in cells)
    seen = {}
    days = 0
    while days < n:
        if state in seen:
            cycle_len = days - seen[state]
            remaining = (n - days) % cycle_len
            for _ in range(remaining):
                state = get_next_state(state)
            break
        seen[state] = days
        state = get_next_state(state)
        days += 1
    return [int(ch) for ch in state]

