def regions_by_slashes(grid: List[str]) -> int:
    def dfs(g: List[List[int]], i: int, j: int) -> None:
        stack = [(i, j)]
        n = len(g)
        while stack:
            x, y = stack.pop()
            if x < 0 or x >= n or y < 0 or y >= n or g[x][y] != 0:
                continue
            g[x][y] = 1
            stack.append((x - 1, y))
            stack.append((x + 1, y))
            stack.append((x, y - 1))
            stack.append((x, y + 1))

    n = len(grid)
    size = n * 3
    new_grid = [[0] * size for _ in range(size)]
    for i in range(n):
        for j in range(n):
            if grid[i][j] == '/':
                new_grid[i * 3][j * 3 + 2] = 1
                new_grid[i * 3 + 1][j * 3 + 1] = 1
                new_grid[i * 3 + 2][j * 3] = 1
            elif grid[i][j] == '\\':
                new_grid[i * 3][j * 3] = 1
                new_grid[i * 3 + 1][j * 3 + 1] = 1
                new_grid[i * 3 + 2][j * 3 + 2] = 1
    count = 0
    for i in range(size):
        for j in range(size):
            if new_grid[i][j] == 0:
                dfs(new_grid, i, j)
                count += 1
    return count

