def spellchecker(wordlist: List[str], queries: List[str]) -> List[str]:
    exact_set = set(wordlist)
    case_map = {}
    vowel_map = {}
    for w in wordlist:
        low = w.lower()
        if low not in case_map:
            case_map[low] = w
        dev = re.sub(r'[aeiou]', '*', low)
        if dev not in vowel_map:
            vowel_map[dev] = w
    result = []
    for q in queries:
        if q in exact_set:
            result.append(q)
        else:
            low_q = q.lower()
            if low_q in case_map:
                result.append(case_map[low_q])
            else:
                dev_q = re.sub(r'[aeiou]', '*', low_q)
                result.append(vowel_map.get(dev_q, ''))
    return result

