def nums_same_consec_diff(n: int, k: int) -> List[int]:
    if n == 1:
        return list(range(10))

    result: List[int] = []

    def dfs(num: int, remaining: int) -> None:
        if remaining == 0:
            result.append(num)
            return
        last = num % 10
        candidates: List[int] = []
        nxt = last + k
        if nxt < 10:
            candidates.append(nxt)
        if k != 0:
            nxt2 = last - k
            if nxt2 >= 0:
                candidates.append(nxt2)
        candidates.sort()
        for nxt_digit in candidates:
            dfs(num * 10 + nxt_digit, remaining - 1)

    for i in range(1, 10):
        dfs(i, n - 1)

    return result

