def powerful_integers(x: int, y: int, bound: int) -> List[int]:
    results = set()
    i = 0
    while True:
        xi = x ** i
        if xi > bound:
            break
        j = 0
        while True:
            yj = y ** j
            value = xi + yj
            if value > bound:
                break
            results.add(value)
            if y == 1:
                break
            j += 1
        if x == 1:
            break
        i += 1
    return sorted(results)
# TIME: O(log_x(bound) * log_y(bound)) SPACE: O(k)

