def time_map() -> SimpleNamespace:
    store: Dict[str, List[Tuple[int, str]]] = {}
    def set_(key: str, value: str, timestamp: int) -> None:
        store.setdefault(key, []).append((timestamp, value))
    def get(key: str, timestamp: int) -> str:
        # FIXED: original did an exact-timestamp dict lookup only, ignoring the
        # "most recent value at or before timestamp" requirement entirely.
        # Now keep a sorted-by-timestamp list per key and binary search it.
        arr = store.get(key)
        if not arr:
            return ""
        idx = bisect.bisect_right(arr, (timestamp, chr(0x10FFFF)))
        return arr[idx - 1][1] if idx > 0 else ""
    return SimpleNamespace(set=set_, get=get)

