def string_without_aaa_or_bbb(a: int, b: int) -> str:
    result: list[str] = []
    # start with 'a' if possible, otherwise 'b'
    if a > 0:
        result.append('a')
        a -= 1
    elif b > 0:
        result.append('b')
        b -= 1

    while a > 0 or b > 0:
        # if the last two characters are the same, we must place the opposite character
        if len(result) >= 2 and result[-1] == result[-2]:
            last = result[-1]
            if last == 'a':
                # need a 'b'
                if b == 0:
                    break
                result.append('b')
                b -= 1
            else:
                # need an 'a'
                if a == 0:
                    break
                result.append('a')
                a -= 1
        else:
            # choose the character with the larger remaining count (tie -> 'a')
            if a >= b and a > 0:
                result.append('a')
                a -= 1
            elif b > 0:
                result.append('b')
                b -= 1
            else:
                # no characters left
                break

    return ''.join(result)

