def vertical_traversal(root):
    if not root:
        return []
    column_table = {}
    queue = deque([(root, 0, 0)])  # node, column, row
    min_column = max_column = 0
    while queue:
        node, column, row = queue.popleft()
        if node:
            if column not in column_table:
                column_table[column] = []
            column_table[column].append((row, node.val))
            min_column = min(min_column, column)
            max_column = max(max_column, column)
            queue.append((node.left, column - 1, row + 1))
            queue.append((node.right, column + 1, row + 1))
    result = []
    for i in range(min_column, max_column + 1):
        if i in column_table:
            column_table[i].sort()
            result.append([v for _, v in column_table[i]])
    return result

def equations_possible(equations):
    def find(parent, x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    parent = [i for i in range(26)]

    for equation in equations:
        if equation[1] == '=':
            x = ord(equation[0]) - ord('a')
            y = ord(equation[3]) - ord('a')
            parent[find(parent, x)] = find(parent, y)

    for equation in equations:
        if equation[1] == '!':
            x = ord(equation[0]) - ord('a')
            y = ord(equation[3]) - ord('a')
            if find(parent, x) == find(parent, y):
                return False
    return True

