def num_squareful_perms(nums: List[int]) -> int:
    def is_square(x: int) -> bool:
        r = math.isqrt(x)
        return r * r == x

    # adjacency list for each unique number
    uniq = list(set(nums))
    adj = {v: [] for v in uniq}
    for a in uniq:
        for b in uniq:
            if is_square(a + b):
                adj[a].append(b)

    total_len = len(nums)
    count = 0
    freq = Counter(nums)

    def backtrack(prev: int, remaining: int) -> None:
        nonlocal count
        if remaining == 0:
            count += 1
            return
        for nxt in uniq:
            if freq[nxt] == 0:
                continue
            if prev is not None and nxt not in adj[prev]:
                continue
            freq[nxt] -= 1
            backtrack(nxt, remaining - 1)
            freq[nxt] += 1

    for start in uniq:
        freq[start] -= 1
        backtrack(start, total_len - 1)
        freq[start] += 1

    return count

