def oranges_rotting(grid: List[List[int]]) -> int:
    rows = len(grid)
    cols = len(grid[0])
    queue: List[List[int]] = []
    fresh_count = 0
    minutes = 0

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 2:
                queue.append([i, j])
            elif grid[i][j] == 1:
                fresh_count += 1

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while queue and fresh_count > 0:
        size = len(queue)
        for _ in range(size):
            x, y = queue.pop(0)
            for dx, dy in directions:
                nx = x + dx
                ny = y + dy
                if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] == 1:
                    grid[nx][ny] = 2
                    queue.append([nx, ny])
                    fresh_count -= 1
        minutes += 1

    return minutes if fresh_count == 0 else -1

