def merge_stones(stones: List[int], k: int) -> int:
    n = len(stones)
    if (n - 1) % (k - 1) != 0:
        return -1

    prefix = [0] * (n + 1)
    for i, v in enumerate(stones):
        prefix[i + 1] = prefix[i] + v

    # dp[i][j] = min cost to merge stones[i..j] into the smallest possible number of piles
    dp = [[0] * n for _ in range(n)]

    # length is the size of the interval
    for length in range(2, n + 1):
        for i in range(0, n - length + 1):
            j = i + length - 1
            best = float('inf')
            # try splitting at positions that leave both sides mergeable
            for mid in range(i, j, k - 1):
                cost = dp[i][mid] + dp[mid + 1][j]
                if cost < best:
                    best = cost
            dp[i][j] = best
            # if we can merge the whole interval into one pile, add the sum
            if (length - 1) % (k - 1) == 0:
                dp[i][j] += prefix[j + 1] - prefix[i]

    return dp[0][n - 1]

