def is_escape_possible(blocked: List[List[int]], source: List[int], target: List[int]) -> bool:
    blocked_set: Set[Tuple[int, int]] = {(x, y) for x, y in blocked}
    max_coord = 10**6
    # If there are no blocked cells, we can always escape.
    if not blocked:
        return True

    # The maximum number of steps we need to explore before we can be sure we are not trapped.
    # With at most 20000 blocked cells, exploring more than 20000 cells guarantees escape.
    limit = len(blocked) * 2

    def bfs(start: Tuple[int, int], finish: Tuple[int, int]) -> bool:
        q = deque([start])
        visited: Set[Tuple[int, int]] = {start}
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        while q and len(visited) <= limit:
            x, y = q.popleft()
            if (x, y) == finish:
                return True
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < max_coord and 0 <= ny < max_coord:
                    nxt = (nx, ny)
                    if nxt not in blocked_set and nxt not in visited:
                        visited.add(nxt)
                        q.append(nxt)
        # If we have explored more than limit cells, we are not enclosed.
        return len(visited) > limit

    src = (source[0], source[1])
    tgt = (target[0], target[1])

    return bfs(src, tgt) and bfs(tgt, src)

