def rearrange_barcodes(barcodes: List[int]) -> List[int]:
    freq_map = {}
    for b in barcodes:
        freq_map[b] = freq_map.get(b, 0) + 1

    # sort by descending frequency, then descending barcode value for deterministic output
    items = sorted(freq_map.items(), key=lambda x: (-x[1], -x[0]))

    n = len(barcodes)
    result = [0] * n
    idx = 0  # start with even positions

    for barcode, cnt in items:
