def smallest_equivalent_string(s1: str, s2: str, base_str: str) -> str:
    parent = {chr(ord('a') + i): chr(ord('a') + i) for i in range(26)}
    def find(x: str) -> str:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(a: str, b: str) -> None:
        ra, rb = find(a), find(b)
        if ra == rb:
            return
        if ra < rb:
            parent[rb] = ra
        else:
            parent[ra] = rb
    for c1, c2 in zip(s1, s2):
        union(c1, c2)
    result = []
    for ch in base_str:
        result.append(find(ch))
    return ''.join(result)

