def path_in_zigzag_tree(label: int):
    path = []
    while True:
        path.append(label)
        if label == 1:
            break
        level = label.bit_length()
        # convert label to normal order
        start = 1 << (level - 1)
        end = (1 << level) - 1
        if level % 2 == 0:
            label_normal = start + end - label
        else:
            label_normal = label
        # parent in normal order
        parent_normal = label_normal // 2
        parent_level = level - 1
        if parent_level == 0:
            label = 1
        else:
            start_p = 1 << (parent_level - 1)
            end_p = (1 << parent_level) - 1
            if parent_level % 2 == 0:
                label = start_p + end_p - parent_normal
            else:
                label = parent_normal
    path.reverse()
    return path

