        frequency_map[num] = frequency_map.get(num, 0) + 1
    result = []
    for num in arr2:
        while frequency_map.get(num, 0) > 0:
            result.append(num)
            frequency_map[num] -= 1
    for num in sorted(frequency_map):
        while frequency_map[num] > 0:
            result.append(num)
            frequency_map[num] -= 1
    return result

def lca_deepest_leaves(root):
    max_depth = -1
    lca = None
    def dfs(node, depth):
        nonlocal max_depth, lca
        if not node.left and not node.right and depth > max_depth:
            max_depth = depth
            lca = node
        if node.left:
            dfs(node.left, depth + 1)
        if node.right:
            dfs(node.right, depth + 1)
        if node.left and node.right and depth + 1 == max_depth:
            lca = node
    dfs(root, 0)
    return lca

