def longest_wpi(hours: List[int]) -> int:
    n = len(hours)
    # prefix sum where +1 for >8 hours, -1 otherwise
    prefix = [0] * (n + 1)
    for i, h in enumerate(hours, 1):
        prefix[i] = prefix[i - 1] + (1 if h > 8 else -1)

    # build a decreasing stack of indices of prefix sums
    stack: List[int] = []
    for i, val in enumerate(prefix):
        if not stack or val < prefix[stack[-1]]:
            stack.append(i)

    max_len = 0
    # iterate from the end to find farthest earlier index with smaller prefix
    for j in range(n, -1, -1):
        while stack and prefix[j] > prefix[stack[-1]]:
            i = stack.pop()
            max_len = max(max_len, j - i)
    return max_len

