def smallest_sufficient_team(req_skills: List[str], people: List[List[str]]) -> Optional[List[int]]:
    n = len(req_skills)
    m = len(people)
    skill_to_index = {skill: i for i, skill in enumerate(req_skills)}
    dp = [[None] * (m + 1) for _ in range(1 << n)]

    def get_skill_set(person_skills: List[str]) -> int:
        mask = 0
        for skill in person_skills:
            mask |= 1 << skill_to_index[skill]
        return mask

    for i in range(m):
        skill_set = get_skill_set(people[i])
        dp[skill_set][i] = [i]

    for mask in range(1 << n):
        for i in range(m):
            if dp[mask][i] is None:
                continue
            for j in range(i + 1, m):
                new_mask = mask | get_skill_set(people[j])
                if dp[new_mask][j + 1] is None or len(dp[new_mask][j + 1]) > len(dp[mask][i]) + 1:
                    dp[new_mask][j + 1] = dp[mask][i] + [j]

    full_mask = (1 << n) - 1
    min_size = float('inf')
    result: Optional[List[int]] = None
    for i in range(m + 1):
        team = dp[full_mask][i]
        if team is not None and len(team) < min_size:
            min_size = len(team)
            result = team
    return result

