def shortest_alternating_paths(n: int, red_edges: List[List[int]], blue_edges: List[List[int]]) -> List[int]:
    red_graph = [[] for _ in range(n)]
    blue_graph = [[] for _ in range(n)]
    for u, v in red_edges:
        red_graph[u].append(v)
    for u, v in blue_edges:
        blue_graph[u].append(v)

    result = [-1] * n
    queue = [(0, 0, True), (0, 0, False)]
    result[0] = 0

    while queue:
        node, length, is_red = queue.pop(0)
        if is_red:
            for neighbor in blue_graph[node]:
                if result[neighbor] == -1:
                    result[neighbor] = length + 1
                    queue.append((neighbor, length + 1, False))
        else:
            for neighbor in red_graph[node]:
                if result[neighbor] == -1:
                    result[neighbor] = length + 1
                    queue.append((neighbor, length + 1, True))

    return result

