        tribonacci_sequence.append(tribonacci_sequence[i - 1] + tribonacci_sequence[i - 2] + tribonacci_sequence[i - 3])
    return tribonacci_sequence[n]

def alphabet_board_path(target: str) -> str:
    board = ["abcde", "fghij", "klmno", "pqrst", "uvwxy", "z"]
    pos = {}
    for i, row in enumerate(board):
        for j, ch in enumerate(row):
            pos[ch] = (i, j)

    res = []
    cur_x, cur_y = 0, 0
    for ch in target:
        nxt_x, nxt_y = pos[ch]

        # move vertically up first, then left, then down, then right
        if nxt_x < cur_x:
            res.append("U" * (cur_x - nxt_x))
        if nxt_y < cur_y:
            res.append("L" * (cur_y - nxt_y))
        if nxt_x > cur_x:
            res.append("D" * (nxt_x - cur_x))
        if nxt_y > cur_y:
            res.append("R" * (nxt_y - cur_y))

        res.append("!")
        cur_x, cur_y = nxt_x, nxt_y

    return "".join(res)

