def stone_game_ii(piles: List[int]) -> int:
    n = len(piles)
    suffix_sum = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        suffix_sum[i] = suffix_sum[i + 1] + piles[i]

    memo = [[-1] * (n + 1) for _ in range(n + 1)]

    def dp(i: int, m: int) -> int:
        if i >= n:
            return 0
        if i + 2 * m >= n:
            return suffix_sum[i]
        if memo[i][m] != -1:
            return memo[i][m]
        best = 0
        max_take = 2 * m
        for x in range(1, max_take + 1):
            if i + x > n:
                break
            opponent = dp(i + x, max(m, x))
            current = suffix_sum[i] - opponent
            if current > best:
                best = current
        memo[i][m] = best
        return best

    return dp(0, 1)

