def moves_to_make_zigzag(nums: List[int]) -> int:
    n = len(nums)
    moves_even = 0  # make even indices valleys
    moves_odd = 0   # make odd indices valleys

    for i in range(n):
        left = nums[i - 1] if i > 0 else float('inf')
        right = nums[i + 1] if i < n - 1 else float('inf')
        needed = max(0, nums[i] - min(left, right) + 1)

        if i % 2 == 0:
            moves_even += needed
        else:
            moves_odd += needed

    return min(moves_even, moves_odd)

