def snapshot_array(length: int):
    current_id = 0
    snapshots = {i: [] for i in range(length)}

    def set_(index: int, val: int):
        nonlocal current_id
        snapshots[index].append((current_id, val))

    def snap() -> int:
        nonlocal current_id
        current_id += 1
        return current_id - 1

    def get(index: int, snap_id: int) -> int:
        values = snapshots[index]
        left, right = 0, len(values) - 1
        while left <= right:
            mid = (left + right) // 2
            if values[mid][0] <= snap_id:
                left = mid + 1
            else:
                right = mid - 1
        return values[right][1] if right >= 0 else 0

    return {"set": set_, "snap": snap, "get": get}

def num_rolls_to_target(n: int, k: int, target: int) -> int:
    MOD = 1000000007
    dp = [[0] * (target + 1) for _ in range(n + 1)]
    dp[0][0] = 1
    for i in range(1, n + 1):
        for j in range(1, target + 1):
            for face in range(1, k + 1):
                if j - face >= 0:
                    dp[i][j] = (dp[i][j] + dp[i - 1][j - face]) % MOD
    return dp[n][target]

