def max_rep_opt1(text: str) -> int:
    n = len(text)
    if n == 0:
        return 0

    # total count of each character
    total: Dict[str, int] = {}
    for ch in text:
        total[ch] = total.get(ch, 0) + 1

    # compress into groups of consecutive same characters
    groups: List[Tuple[str, int]] = []
    i = 0
    while i < n:
        j = i + 1
        while j < n and text[j] == text[i]:
            j += 1
        groups.append((text[i], j - i))
        i = j

    ans = 0
    # case 1: extend a single group by swapping in one more same character
    for ch, length in groups:
        ans = max(ans, min(total[ch], length + 1))

    # case 2: merge two groups separated by a single different character
    for idx in range(1, len(groups) - 1):
        ch_mid, len_mid = groups[idx]
        if len_mid != 1:
            continue
        ch_left, len_left = groups[idx - 1]
        ch_right, len_right = groups[idx + 1]
        if ch_left == ch_right and ch_left != ch_mid:
            merged = len_left + len_right
            if total[ch_left] > merged:
                merged += 1
            ans = max(ans, merged)

    return ans

