def remove_zero_sum_sublists(head):
    dummy = ListNode(0)
    dummy.next = head
    prefix = 0
    seen = {0: dummy}
    while head:
        prefix += head.val
        if prefix in seen:
            node = seen[prefix]
            tmp = node.next
            tmp_prefix = prefix + tmp.val
            while tmp is not head:
                del seen[tmp_prefix]
                tmp = tmp.next
                tmp_prefix += tmp.val
            node.next = head.next
        else:
            seen[prefix] = head
        head = head.next
    return dummy.next

def num_prime_arrangements(n: int) -> int:
    def is_prime(num: int) -> bool:
        if num <= 1:
            return False
        i = 2
        while i * i <= num:
            if num % i == 0:
                return False
            i += 1
        return True

    prime_count = 0
    for i in range(1, n + 1):
        if is_prime(i):
            prime_count += 1

    MOD = 10**9 + 7
    prime_permutations = 1
    for i in range(1, prime_count + 1):
        prime_permutations = (prime_permutations * i) % MOD

    non_prime_permutations = 1
    for i in range(1, n - prime_count + 1):
        non_prime_permutations = (non_prime_permutations * i) % MOD

    return (prime_permutations * non_prime_permutations) % MOD

