    for word in words:
        bitmask = 0
        for char in word:
            bitmask |= 1 << (ord(char) - ord('a'))
        word_map[bitmask] = word_map.get(bitmask, 0) + 1
    for i, puzzle in enumerate(puzzles):
        puzzle_bitmask = 0
        for char in puzzle:
            puzzle_bitmask |= 1 << (ord(char) - ord('a'))
        first_char_bit = 1 << (ord(puzzle[0]) - ord('a'))
        submask = puzzle_bitmask
        while submask:
            if submask in word_map and (submask & first_char_bit):
                result[i] += word_map[submask]
            submask = (submask - 1) & puzzle_bitmask
    return result

