import heapq

def dinner_plates(capacity):
    stacks = []
    available = []  # min-heap of candidate indices (lazy deletion of stale/full entries)

    def push(val):
        while available and (available[0] >= len(stacks) or len(stacks[available[0]]) >= capacity):
            heapq.heappop(available)
        if not available:
            stacks.append([val])
            if capacity > 1:
                heapq.heappush(available, len(stacks) - 1)
        else:
            idx = available[0]
            stacks[idx].append(val)
            if len(stacks[idx]) >= capacity:
                heapq.heappop(available)

    def pop():
        while stacks and not stacks[-1]:
            stacks.pop()
        if not stacks:
            return -1
        return pop_at_stack(len(stacks) - 1)

    def pop_at_stack(index):
        if index >= len(stacks) or not stacks[index]:
            return -1
        was_full = len(stacks[index]) == capacity
        val = stacks[index].pop()
        if was_full:
            heapq.heappush(available, index)
        while stacks and not stacks[-1]:
            stacks.pop()
        return val

    return {"push": push, "pop": pop, "pop_at_stack": pop_at_stack}

