from bisect import bisect_right

def make_array_increasing(arr1: List[int], arr2: List[int]) -> int:
    # remove duplicates and sort arr2 for binary search
    arr2 = sorted(set(arr2))
    n = len(arr1)
    INF = float('inf')
    # dp[j] = smallest possible last value after processing current prefix with j replacements
    dp = [INF] * (n + 1)
    dp[0] = -INF

    for a in arr1:
        new_dp = [INF] * (n + 1)
        for j in range(n + 1):
            if dp[j] == INF:
                continue
            # keep current element if it keeps the sequence strictly increasing
            if a > dp[j]:
                if a < new_dp[j]:
                    new_dp[j] = a
            # replace current element with the smallest arr2 element greater than dp[j]
            idx = bisect_right(arr2, dp[j])
            if idx < len(arr2):
                if arr2[idx] < new_dp[j + 1]:
                    new_dp[j + 1] = arr2[idx]
        dp = new_dp

    for j, val in enumerate(dp):
        if val < INF:
            return j
    return -1

