def smallest_string_with_swaps(s: str, pairs: List[List[int]]) -> str:
    parent = list(range(len(s)))
    rank = [0] * len(s)

    def find(x: int) -> int:
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x: int, y: int) -> None:
        root_x = find(x)
        root_y = find(y)
        if root_x != root_y:
            if rank[root_x] < rank[root_y]:
                parent[root_x] = root_y
            elif rank[root_x] > rank[root_y]:
                parent[root_y] = root_x
            else:
                parent[root_y] = root_x
                rank[root_x] += 1

    for x, y in pairs:
        union(x, y)

    groups = {}
    for i in range(len(s)):
        grp = find(i)
        groups.setdefault(grp, []).append(s[i])

    for grp in groups:
        groups[grp].sort()

    result = [''] * len(s)
    for i in range(len(s)):
        grp = find(i)
        result[i] = groups[grp].pop(0)

    return ''.join(result)

import random

class Node:
    __slots__ = ("val", "next")
    def __init__(self, val, level):
        self.val = val
        self.next = [None] * level

class Skiplist:
    def __init__(self):
        self.levels = 16
        self.max_value = 1 << 15
        self.head = Node(self.max_value, self.levels)

    def _random_level(self):
        level = 1
        while random.random() < 0.5 and level < self.levels:
            level += 1
        return level

    def search(self, target: int) -> bool:
        curr = self.head
        for i in range(self.levels - 1, -1, -1):
            while curr.next[i] and curr.next[i].val < target:
                curr = curr.next[i]
        return bool(curr.next[0] and curr.next[0].val == target)

    def add(self, num: int) -> None:
        update = [self.head] * self.levels
        curr = self.head
        for i in range(self.levels - 1, -1, -1):
            while curr.next[i] and curr.next[i].val < num:
                curr = curr.next[i]
            update[i] = curr
        new_node = Node(num, self._random_level())
        for i in range(len(new_node.next)):
            new_node.next[i] = update[i].next[i]
            update[i].next[i] = new_node

    def erase(self, num: int) -> bool:
        update = [self.head] * self.levels
        curr = self.head
        for i in range(self.levels - 1, -1, -1):
            while curr.next[i] and curr.next[i].val < num:
                curr = curr.next[i]
            update[i] = curr
        if curr.next[0] and curr.next[0].val == num:
            for i in range(self.levels):
                if update[i].next[i] and update[i].next[i].val == num:
                    update[i].next[i] = update[i].next[i].next[i]
                else:
                    break
            return True
        return False

