    max_gold = 0

    def backtrack(row: int, col: int, current_gold: int, visited: Set[str]) -> None:
        nonlocal max_gold
        if current_gold > max_gold:
            max_gold = current_gold
        for dr, dc in directions:
            new_row = row + dr
            new_col = col + dc
            key = f"{new_row},{new_col}"
            if 0 <= new_row < m and 0 <= new_col < n and grid[new_row][new_col] != 0 and key not in visited:
                visited.add(key)
                backtrack(new_row, new_col, current_gold + grid[new_row][new_col], visited)
                visited.remove(key)

    for i in range(m):
        for j in range(n):
            if grid[i][j] != 0:
                backtrack(i, j, grid[i][j], {f"{i},{j}"})
    return max_gold

