def max_length(arr: List[str]) -> int:
    max_len = 0

    def is_unique(s: str) -> bool:
        seen = set()
        for ch in s:
            if ch in seen:
                return False
            seen.add(ch)
        return True

    def has_duplicate(s: str) -> bool:
        seen = set()
        for ch in s:
            if ch in seen:
                return True
            seen.add(ch)
        return False

    def backtrack(start: int, path: str) -> None:
        nonlocal max_len
        if is_unique(path):
            max_len = max(max_len, len(path))
        for i in range(start, len(arr)):
            if has_duplicate(path + arr[i]):
                continue
            backtrack(i + 1, path + arr[i])

    backtrack(0, "")
    return max_len

