def balanced_string(s: str) -> int:
    n: int = len(s)
    target: int = n // 4
    total_counts: Dict[str, int] = {"Q": 0, "W": 0, "E": 0, "R": 0}
    for ch in s:
        total_counts[ch] += 1

    # If already balanced
    if all(total_counts[c] == target for c in "QWER"):
        return 0

    left: int = 0
    min_len: int = n
    window_counts: Dict[str, int] = {"Q": 0, "W": 0, "E": 0, "R": 0}

    for right in range(n):
        right_char: str = s[right]
        window_counts[right_char] += 1

        # Try to shrink the window while the remaining string is balanced
        while left <= right and all(
            total_counts[c] - window_counts[c] <= target for c in "QWER"
        ):
            current_len: int = right - left + 1
            if current_len < min_len:
                min_len = current_len
            left_char: str = s[left]
            window_counts[left_char] -= 1
            left += 1

    return min_len

def find_elements(root):
    values = set()
    if not root:
        return values
    stack = [(root, 0)]
    while stack:
        node, val = stack.pop()
        node.val = val
        values.add(val)
        if node.left:
            stack.append((node.left, 2 * val + 1))
        if node.right:
            stack.append((node.right, 2 * val + 2))
    return values

def max_sum_divisible_by_three(nums: list[int]) -> int:
    dp = [0, float("-inf"), float("-inf")]
    for cur in nums:
        mod = cur % 3
        nxt = dp[:]
        for r in range(3):
            new_r = (r + mod) % 3
            nxt[new_r] = max(nxt[new_r], dp[r] + cur)
        dp[0], dp[1], dp[2] = nxt[0], nxt[1], nxt[2]
    return dp[0]

