    k = k % total
    flat = []
    for r in range(rows):
        for c in range(cols):
            flat.append(grid[r][c])
    rotated = [0] * total
    for i in range(total):
        new_idx = (i + k) % total
        rotated[new_idx] = flat[i]
    result = [None] * rows
    for r in range(rows):
        result[r] = [0] * cols
        for c in range(cols):
            result[r][c] = rotated[r * cols + c]
    return result

