def suggested_products(products: List[str], search_word: str) -> List[List[str]]:
    products.sort()
    result: List[List[str]] = []
    n = len(products)

    def lower_bound(target: str) -> int:
        left, right = 0, n
        while left < right:
            mid = (left + right) // 2
            if products[mid] < target:
                left = mid + 1
            else:
                right = mid
        return left

    prefix = ''
    for ch in search_word:
        prefix += ch
        start = lower_bound(prefix)
        suggestions: List[str] = []
        for j in range(start, min(start + 3, n)):
            if products[j].startswith(prefix):
                suggestions.append(products[j])
            else:
                break
        result.append(suggestions)
    return result

def num_ways(steps: int, arr_len: int) -> int:
    MOD = 1000000007
    max_pos = min(arr_len - 1, steps)
    dp = [0] * (max_pos + 1)
    dp[0] = 1
    for step in range(1, steps + 1):
        nxt = [0] * (max_pos + 1)
        for pos in range(max_pos + 1):
            ways = dp[pos]
            if pos > 0:
                ways = (ways + dp[pos - 1]) % MOD
            if pos < max_pos:
                ways = (ways + dp[pos + 1]) % MOD
            nxt[pos] = ways
        dp = nxt
    return dp[0]

