def min_push_box(grid: List[List[str]]) -> int:
    m, n = len(grid), len(grid[0])
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # locate S, B, T
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 'S':
                start_player = (i, j)
            elif grid[i][j] == 'B':
                start_box = (i, j)
            elif grid[i][j] == 'T':
                target = (i, j)

    def reachable(px: int, py: int, tx: int, ty: int, bx: int, by: int) -> bool:
        """Can player walk from (px,py) to (tx,ty) without crossing walls or the box at (bx,by)."""
        if (px, py) == (tx, ty):
            return True
        q = deque()
        q.append((px, py))
        seen = {(px, py)}
        while q:
            x, y = q.popleft()
            for dx, dy in dirs:
                nx, ny = x + dx, y + dy
                if 0 <= nx < m and 0 <= ny < n and (nx, ny) not in seen:
                    if grid[nx][ny] != '#' and not (nx == bx and ny == by):
                        if (nx, ny) == (tx, ty):
                            return True
                        seen.add((nx, ny))
                        q.append((nx, ny))
        return False

    start_state = (start_box[0], start_box[1], start_player[0], start_player[1])
    q = deque()
    q.append((0, start_state))
    visited = {start_state}

    while q:
        pushes, (bx, by, px, py) = q.popleft()
        if (bx, by) == target:
            return pushes
        for dx, dy in dirs:
            nbx, nby = bx + dx, by + dy          # new box position after push
            pbx, pby = bx - dx, by - dy          # player must stand here to push
            if not (0 <= nbx < m and 0 <= nby < n and 0 <= pbx < m and 0 <= pby < n):
                continue
            if grid[nbx][nby] == '#' or grid[pbx][pby] == '#':
                continue
            # check if player can reach the required position without moving the box
            if not reachable(px, py, pbx, pby, bx, by):
                continue
            new_state = (nbx, nby, bx, by)      # after push, player stands at old box cell
            if new_state not in visited:
                visited.add(new_state)
                q.append((pushes + 1, new_state))

    return -1

