def combination_iterator(characters: str, combinationLength: int):
    all_combos = []
    combo = []
    n = len(characters)

    def backtrack(start):
        if len(combo) == combinationLength:
            all_combos.append(''.join(combo))
            return
        for i in range(start, n):
            combo.append(characters[i])
            backtrack(i + 1)
            combo.pop()

    backtrack(0)

    pos = 0

    def next_func():
        nonlocal pos
        result = all_combos[pos]
        pos += 1
        return result

    def has_next_func():
        return pos < len(all_combos)

    return {'next': next_func, 'hasNext': has_next_func}

