def min_flips(mat: List[List[int]]) -> int:
    m = len(mat)
    n = len(mat[0])
    total = m * n

    start = 0
    for i in range(m):
        for j in range(n):
            if mat[i][j] == 1:
                start |= 1 << (i * n + j)

    flip_masks = []
    dirs = [(0, 0), (1, 0), (-1, 0), (0, 1), (0, -1)]
    for i in range(m):
        for j in range(n):
            mask = 0
            for dx, dy in dirs:
                x = i + dx
                y = j + dy
                if 0 <= x < m and 0 <= y < n:
                    mask |= 1 << (x * n + y)
            flip_masks.append(mask)

    queue = deque([start])
    dist = {start: 0}

    while queue:
        cur = queue.popleft()
        steps = dist[cur]
        if cur == 0:
            return steps
        for mask in flip_masks:
            nxt = cur ^ mask
            if nxt not in dist:
                dist[nxt] = steps + 1
                queue.append(nxt)
    return -1

