def max_side_length(mat: List[List[int]], threshold: int) -> int:
    rows = len(mat)
    cols = len(mat[0]) if rows else 0
    prefix = [[0] * (cols + 1) for _ in range(rows + 1)]
    for r in range(1, rows + 1):
        for c in range(1, cols + 1):
            prefix[r][c] = (
                mat[r - 1][c - 1]
                + prefix[r - 1][c]
                + prefix[r][c - 1]
                - prefix[r - 1][c - 1]
            )
    def can_fit(size: int) -> bool:
        for r in range(0, rows - size + 1):
            for c in range(0, cols - size + 1):
                total = (
                    prefix[r + size][c + size]
                    - prefix[r][c + size]
                    - prefix[r + size][c]
                    + prefix[r][c]
                )
                if total <= threshold:
                    return True
        return False
    low, high = 0, min(rows, cols)
    while low < high:
        mid = (low + high + 1) // 2
        if can_fit(mid):
            low = mid
        else:
            high = mid - 1
    return low

