        freq[num] = freq.get(num, 0) + 1
    sorted_keys = sorted(freq.keys())
    for start in sorted_keys:
        count = freq.get(start, 0)
        if count > 0:
            for i in range(k):
                cur = start + i
                cur_count = freq.get(cur, 0)
                if cur_count < count:
                    return False
                freq[cur] = cur_count - count
    return True

def max_freq(s: str, max_letters: int, min_size: int, max_size: int) -> int:
    if len(s) < min_size:
        return 0
    freq_map = {}
    char_count = [0] * 26
    distinct = 0
    best = 0
    for i in range(min_size):
        idx = ord(s[i]) - 97
        if char_count[idx] == 0:
            distinct += 1
        char_count[idx] += 1
    for start in range(len(s) - min_size + 1):
        if distinct <= max_letters:
            sub = s[start:start + min_size]
            new_count = freq_map.get(sub, 0) + 1
            freq_map[sub] = new_count
            if new_count > best:
                best = new_count
        if start + min_size < len(s):
            left_idx = ord(s[start]) - 97
            right_idx = ord(s[start + min_size]) - 97
            char_count[left_idx] -= 1
            if char_count[left_idx] == 0:
                distinct -= 1
            if char_count[right_idx] == 0:
                distinct += 1
            char_count[right_idx] += 1
    return best

