def sum_of_mutated_array_closest_target(arr: List[int], target: int) -> int:
    if not arr:
        return 0

    arr.sort()
    n = len(arr)
    prefix = [0] * (n + 1)
    for i, v in enumerate(arr, 1):
        prefix[i] = prefix[i - 1] + v

    def mutated_sum(x: int) -> int:
        idx = bisect.bisect_right(arr, x)
        return prefix[idx] + x * (n - idx)

    original_sum = prefix[n]
    if target >= original_sum:
        return arr[-1]

    # binary search for smallest x such that mutated_sum(x) >= target
    low, high = 0, arr[-1]
    while low < high:
        mid = (low + high) // 2
        if mutated_sum(mid) < target:
            low = mid + 1
        else:
            high = mid

    best_x = low
    best_diff = abs(mutated_sum(best_x) - target)

    # check the previous value
    if best_x > 0:
        cand = best_x - 1
        diff = abs(mutated_sum(cand) - target)
        if diff < best_diff or (diff == best_diff and cand < best_x):
            best_x = cand
            best_diff = diff

    return best_x

