MOD = 10**9 + 7

def number_of_paths(board: List[str]) -> List[int]:
    n = len(board)
    # dp arrays
    max_score = [[-1] * n for _ in range(n)]
    ways = [[0] * n for _ in range(n)]

    # locate start 'S'
    si = sj = -1
    for i in range(n):
        for j in range(n):
            if board[i][j] == 'S':
                si, sj = i, j
                break
        if si != -1:
            break

    if si == -1:
        return [0, 0]

    max_score[si][sj] = 0
    ways[si][sj] = 1

    # iterate from bottom-right towards top-left
    for i in range(si, -1, -1):
        for j in range(sj, -1, -1):
            if board[i][j] == 'X' or (i == si and j == sj):
                continue

            best = -1
            cnt = 0
            # check three possible predecessors
            for ni, nj in ((i + 1, j), (i, j + 1), (i + 1, j + 1)):
                if 0 <= ni < n and 0 <= nj < n and board[ni][nj] != 'X' and max_score[ni][nj] != -1:
                    cand = max_score[ni][nj]
                    if board[i][j].isdigit():
                        cand += int(board[i][j])
                    # 'E' contributes 0, same as non-digit
                    if cand > best:
                        best = cand
                        cnt = ways[ni][nj]
                    elif cand == best:
                        cnt = (cnt + ways[ni][nj]) % MOD

            if best != -1:
                max_score[i][j] = best
                ways[i][j] = cnt % MOD

    if max_score[0][0] == -1:
        return [0, 0]
    return [max_score[0][0], ways[0][0] % MOD]

