def deepest_leaves_sum(root):
    if not root:
        return 0
    queue = deque([root])
    deepest_sum = 0
    while queue:
        level_size = len(queue)
        level_sum = 0
        for _ in range(level_size):
            node = queue.popleft()
            level_sum += node.val
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        deepest_sum = level_sum
    return deepest_sum

