def max_candies(status: List[int], candies: List[int], keys: List[List[int]],
                containedBoxes: List[List[int]], initialBoxes: List[int]) -> int:
    owned = set(initialBoxes)
    have_key = set()
    opened = set()
    total = 0
    q = deque()

    for b in initialBoxes:
        if status[b] == 1:
            q.append(b)

    while q:
        b = q.popleft()
        if b in opened:
            continue
        opened.add(b)
        total += candies[b]

        for k in keys[b]:
            if k not in have_key:
                have_key.add(k)
                if k in owned and k not in opened:
                    q.append(k)

        for nb in containedBoxes[b]:
            if nb not in owned:
                owned.add(nb)
                if status[nb] == 1 or nb in have_key:
                    q.append(nb)

    return total

