import sys

def is_solvable(words, result):
    # collect unique letters
    letters_set = set()
    leading = set()
    for w in words:
        letters_set.update(w)
        if len(w) > 1:
            leading.add(w[0])
    letters_set.update(result)
    if len(result) > 1:
        leading.add(result[0])
    letters = list(letters_set)

    assign = {}
    used = set()

    # optional early pruning using column sums
    max_len = max(max(len(w) for w in words), len(result))

    # precompute column letters for faster check
    cols = []
    for pos in range(max_len):
        add_letters = []
        for w in words:
            if len(w) > pos:
                add_letters.append(w[-1 - pos])
        res_letter = result[-1 - pos] if len(result) > pos else None
        cols.append((add_letters, res_letter))

    def check_partial():
        # verify columns where all involved letters are assigned
        carry = 0
        for add_letters, res_letter in cols:
            sum_val = carry
            for ch in add_letters:
                if ch not in assign:
                    return True  # cannot verify yet
                sum_val += assign[ch]
            expected_digit = sum_val % 10
            carry = sum_val // 10
            if res_letter is None:
                if expected_digit != 0:
                    return False
                continue
            if res_letter not in assign:
                # if digit already used by another letter, cannot assign later
                if expected_digit in used:
                    return False
                continue
            if assign[res_letter] != expected_digit:
                return False
        return True

    def backtrack(idx):
        if idx == len(letters):
            # final verification
            total = 0
            for w in words:
                num = 0
                for ch in w:
                    num = num * 10 + assign[ch]
                total += num
            res_num = 0
            for ch in result:
                res_num = res_num * 10 + assign[ch]
            return total == res_num
        ch = letters[idx]
        for d in range(10):
            if d in used:
                continue
            if d == 0 and ch in leading:
                continue
            assign[ch] = d
            used.add(d)
            if check_partial() and backtrack(idx + 1):
                return True
            used.remove(d)
            del assign[ch]
        return False

    return backtrack(0)

