def min_insertions(s: str) -> int:
    n = len(s)
    if n == 0:
        return 0
    rev = s[::-1]
    dpPrev = [0] * (n + 1)
    dpCurr = [0] * (n + 1)
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if s[i - 1] == rev[j - 1]:
                dpCurr[j] = dpPrev[j - 1] + 1
            else:
                dpCurr[j] = max(dpPrev[j], dpCurr[j - 1])
        dpPrev, dpCurr = dpCurr, dpPrev
    lpsLength = dpPrev[n]
    return n - lpsLength

