def minimum_distance(word: str) -> int:
    def _dist(a: int, b: int) -> int:
        if a == -1 or b == -1:
            return 0
        ra, ca = divmod(a, 6)  # 6 columns on the keyboard
        rb, cb = divmod(b, 6)
        return abs(ra - rb) + abs(ca - cb)

    if not word:
        return 0
    n = len(word)
    if n == 1:
        return 0

    prev = ord(word[0]) - ord('A')
    dp: Dict[Tuple[int, int], int] = {(prev, -1): 0, (-1, prev): 0}

    for i in range(1, n):
        cur = ord(word[i]) - ord('A')
        new_dp: Dict[Tuple[int, int], int] = {}
        for (p1, p2), val in dp.items():
            if p1 == prev:  # finger1 typed previous character
                # move finger1 to cur
                state1 = (cur, p2)
                cost1 = val + _dist(prev, cur)
                # move finger2 to cur
                state2 = (p1, cur)
                cost2 = val + _dist(p2, cur)
            else:  # finger2 typed previous character
                # move finger2 to cur
                state1 = (p1, cur)
                cost1 = val + _dist(prev, cur)
                # move finger1 to cur
                state2 = (cur, p2)
                cost2 = val + _dist(p1, cur)

            for st, cost in ((state1, cost1), (state2, cost2)):
                if st not in new_dp or cost < new_dp[st]:
                    new_dp[st] = cost
        dp = new_dp
        prev = cur

    return min(dp.values())

