def min_taps(n: int, ranges: List[int]) -> int:
    if n == 0:
        return 0
    max_right = [0] * (n + 1)
    for i in range(n + 1):
        left = max(0, i - ranges[i])
        right = min(n, i + ranges[i])
        if right > max_right[left]:
            max_right[left] = right
    taps = 0
    current_end = 0
    farthest = 0
    pos = 0
    while current_end < n:
        while pos <= current_end:
            if max_right[pos] > farthest:
                farthest = max_right[pos]
            pos += 1
        if farthest <= current_end:
            return -1
        taps += 1
        current_end = farthest
    return taps

