def find_the_city(n: int, edges: List[List[int]], distanceThreshold: int) -> int:
    INF = 10 ** 9
    dist = [[INF] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for u, v, w in edges:
        dist[u][v] = w
        dist[v][u] = w

    for k in range(n):
        dk = dist[k]
        for i in range(n):
            di = dist[i]
            ik = di[k]
            if ik == INF:
                continue
            for j in range(n):
                nd = ik + dk[j]
                if nd < di[j]:
                    di[j] = nd

    best_city = -1
    best_count = n + 1
    for i in range(n):
        cnt = sum(1 for j in range(n) if i != j and dist[i][j] <= distanceThreshold)
        if cnt < best_count or (cnt == best_count and i > best_city):
            best_count = cnt
            best_city = i
    return best_city

