def max_jumps(arr, d):
    n = len(arr)

    @lru_cache(None)
    def dfs(i):
        best = 1
        # jump to the left
        for step in range(1, d + 1):
            j = i - step
            if j < 0:
                break
            if arr[j] < arr[i]:
                best = max(best, 1 + dfs(j))
            else:
                break
        # jump to the right
        for step in range(1, d + 1):
            j = i + step
            if j >= n:
                break
            if arr[j] < arr[i]:
                best = max(best, 1 + dfs(j))
            else:
                break
        return best

    return max(dfs(i) for i in range(n))

