def min_jumps(arr: List[int]) -> int:
    n = len(arr)
    if n <= 1:
        return 0

    value_indices = {}
    for i, v in enumerate(arr):
        value_indices.setdefault(v, []).append(i)

    visited = [False] * n
    queue = deque([0])
    visited[0] = True
    steps = 0

    while queue:
        size = len(queue)
        for _ in range(size):
            idx = queue.popleft()
            if idx == n - 1:
                return steps

            next_nodes = []
            if idx - 1 >= 0:
                next_nodes.append(idx - 1)
            if idx + 1 < n:
                next_nodes.append(idx + 1)

            same_val = value_indices.get(arr[idx], [])
            for j in same_val:
                next_nodes.append(j)
            value_indices[arr[idx]] = []

            for nb in next_nodes:
                if not visited[nb]:
                    visited[nb] = True
                    queue.append(nb)
        steps += 1

    return -1

