    def upper_bound(arr, target):
        lo, hi = 0, len(arr)
        while lo < hi:
            mid = (lo + hi) >> 1
            if arr[mid] <= target:
                lo = mid + 1
            else:
                hi = mid
        return lo
    def record_tweet(tweet_name, time):
        if tweet_name not in data:
            data[tweet_name] = []
        arr = data[tweet_name]
        idx = lower_bound(arr, time)
        arr.insert(idx, time)
    def get_tweet_counts_per_frequency(freq, tweet_name, start_time, end_time):
        if freq == 'minute':
            bucket_size = 60
        elif freq == 'hour':
            bucket_size = 3600
        else:
            bucket_size = 86400
        bucket_count = (end_time - start_time) // bucket_size + 1
        counts = [0] * bucket_count
        arr = data.get(tweet_name)
        if not arr:
            return counts
        left = lower_bound(arr, start_time)
        right = upper_bound(arr, end_time)
        for i in range(left, right):
            bucket = (arr[i] - start_time) // bucket_size
            counts[bucket] += 1
        return counts
    return {'recordTweet': record_tweet, 'getTweetCountsPerFrequency': get_tweet_counts_per_frequency}

