def maxStudents(seats: List[List[str]]) -> int:
    m = len(seats)
    n = len(seats[0])
    # Precompute valid masks for each row
    valid_masks_per_row = []
    popcount = {}
    for i in range(m):
        row_valid = []
        for mask in range(1 << n):
            # no adjacent students in the same row
            if mask & (mask << 1):
                continue
            # seat must be good ('.')
            ok = True
            for j in range(n):
                if (mask >> j) & 1:
                    if seats[i][j] == '#':
                        ok = False
                        break
            if not ok:
                continue
            row_valid.append(mask)
            popcount[mask] = bin(mask).count('1')
        valid_masks_per_row.append(row_valid)

    dp = {0: 0}  # previous row mask -> max students so far
    for i in range(m):
        new_dp = {}
        for mask in valid_masks_per_row[i]:
            for prev_mask, val in dp.items():
                # check upper-left and upper-right conflicts
                if (mask << 1) & prev_mask:
                    continue
                if (mask >> 1) & prev_mask:
                    continue
                new_val = val + popcount[mask]
                if mask not in new_dp or new_val > new_dp[mask]:
                    new_dp[mask] = new_val
        dp = new_dp
    return max(dp.values() or [0])

def create_product_of_numbers():
    prefix = [1]
    def add(num):
        if num == 0:
            prefix[:] = [1]
        else:
            prefix.append(prefix[-1] * num)
    def getProduct(k):
        if k >= len(prefix):
            return 0
        return prefix[-1] // prefix[-1 - k]
    return {'add': add, 'getProduct': getProduct}

