def max_events(events: List[List[int]]) -> int:
    events.sort(key=lambda a: a[0])
    heap: List[int] = []

    def push(val: int) -> None:
        heap.append(val)
        i = len(heap) - 1
        while i > 0:
            p = (i - 1) >> 1
            if heap[p] <= heap[i]:
                break
            heap[p], heap[i] = heap[i], heap[p]
            i = p

    def pop() -> int:
        if not heap:
            return None  # type: ignore
        top = heap[0]
        last = heap.pop()
        if heap:
            heap[0] = last
            i = 0
            while True:
                l = i * 2 + 1
                r = i * 2 + 2
                smallest = i
                if l < len(heap) and heap[l] < heap[smallest]:
                    smallest = l
                if r < len(heap) and heap[r] < heap[smallest]:
                    smallest = r
                if smallest == i:
                    break
                heap[i], heap[smallest] = heap[smallest], heap[i]
                i = smallest
        return top

    def peek() -> int:
        return heap[0] if heap else None  # type: ignore

    i = 0
    day = 0
    attended = 0
    n = len(events)

    while i < n or heap:
        if not heap:
            day = events[i][0]
        while i < n and events[i][0] <= day:
            push(events[i][1])
            i += 1
        while heap and peek() < day:
            pop()
        if heap:
            pop()
            attended += 1
            day += 1
        else:
            day += 1

    return attended

