def validate_binary_tree_nodes(n: int, left_child: List[int], right_child: List[int]) -> bool:
    indegree = [0] * n
    for i in range(n):
        l = left_child[i]
        r = right_child[i]
        if l != -1:
            indegree[l] += 1
        if r != -1:
            indegree[r] += 1

    root = -1
    for i in range(n):
        if indegree[i] == 0:
            if root != -1:
                return False
            root = i
    if root == -1:
        return False

    visited = [False] * n
    stack = [root]
    while stack:
        node = stack.pop()
        if visited[node]:
            return False
        visited[node] = True
        l = left_child[node]
        r = right_child[node]
        if l != -1:
            stack.append(l)
        if r != -1:
            stack.append(r)

    for i in range(n):
        if not visited[i]:
            return False
    return True

