def closest_divisors(num: int) -> list[int]:
    best_diff = float('inf')
    best_pair: list[int] = []
    for product in (num + 1, num + 2):
        limit = int(math.sqrt(product))
        for i in range(limit, 0, -1):
            if product % i == 0:
                j = product // i
                diff = abs(i - j)
                if diff < best_diff:
