def largest_multiple_of_three(digits: List[int]) -> str:
    cnt = [0] * 10
    total = 0
    for d in digits:
        cnt[d] += 1
        total += d
    rem = total % 3

    def remove_one(mod: int) -> bool:
        for i in range(10):
            if i % 3 == mod and cnt[i] > 0:
                cnt[i] -= 1
                return True
        return False

    def remove_two(mod: int) -> bool:
        removed = 0
        for i in range(10):
            while i % 3 == mod and cnt[i] > 0 and removed < 2:
                cnt[i] -= 1
                removed += 1
                if removed == 2:
                    return True
        return False

    if rem == 1:
        if not remove_one(1):
            if not remove_two(2):
                return ""
    elif rem == 2:
        if not remove_one(2):
            if not remove_two(1):
                return ""

    # Build result
    result_digits = []
    for d in range(9, -1, -1):
        result_digits.extend([str(d)] * cnt[d])

    if not result_digits:
        return ""
    # If the highest digit is 0, the number is all zeros
    if result_digits[0] == '0':
        return "0"
    return "".join(result_digits)

