def is_sub_path(head: Optional["ListNode"], root: Optional["TreeNode"]) -> bool:
    if not head:
        return True

    def dfs(node: Optional["TreeNode"]) -> bool:
        if not node:
            return False
        if match(head, node):
            return True
        return dfs(node.left) or dfs(node.right)

    def match(list_node: Optional["ListNode"], tree_node: Optional["TreeNode"]) -> bool:
        if not list_node:
            return True
        if not tree_node:
            return False
        if list_node.val != tree_node.val:
            return False
        return match(list_node.next, tree_node.left) or match(list_node.next, tree_node.right)

    return dfs(root)

