        if not node:
            return (0, 0)
        left_child = dfs(node.left)
        right_child = dfs(node.right)
        left_zig = 1 + left_child[1] if node.left else 0
        right_zig = 1 + right_child[0] if node.right else 0
        if left_zig > best:
            best = left_zig
        if right_zig > best:
            best = right_zig
        return (left_zig, right_zig)
    dfs(root)
    return best

