def custom_stack(max_size):
    stack = []
    inc = [0] * max_size

    def push(x):
        if len(stack) < max_size:
            stack.append(x)

    def pop():
        if not stack:
            return -1
        i = len(stack) - 1
        val = stack.pop() + inc[i]
        if i > 0:
            inc[i - 1] += inc[i]
        inc[i] = 0
        return val

    def increment(k, val):
        idx = min(k, len(stack)) - 1
        if idx >= 0:
            inc[idx] += val

    return {'push': push, 'pop': pop, 'increment': increment}

