    def power(x: int) -> int:
        if x in memo:
            return memo[x]
        nxt = x // 2 if x % 2 == 0 else 3 * x + 1
        p = 1 + power(nxt)
        memo[x] = p
        return p
    lst = []
    for i in range(lo, hi + 1):
        lst.append((i, power(i)))
