def sum_four_divisors(nums: List[int]) -> int:
    total = 0
    for n in nums:
        divisor_count = 0
        divisor_sum = 0
        i = 1
        limit = math.isqrt(n)
        while i <= limit:
            if n % i == 0:
                divisor_count += 1
                divisor_sum += i
                other = n // i
                if other != i:
