MOD = 10**9 + 7

def solve(n: int, s1: str, s2: str, evil: str) -> int:
    m = len(evil)

    # Build KMP prefix function for evil
    pi: List[int] = [0] * m
    for i in range(1, m):
        j = pi[i - 1]
        while j > 0 and evil[i] != evil[j]:
            j = pi[j - 1]
        if evil[i] == evil[j]:
            j += 1
        pi[i] = j

    # Build automaton transition table
    nxt: List[List[int]] = [[0] * 26 for _ in range(m)]
    for k in range(m):
        for c in range(26):
            ch = chr(ord('a') + c)
            j = k
            while j > 0 and ch != evil[j]:
                j = pi[j - 1]
            if ch == evil[j]:
                j += 1
            nxt[k][c] = j

    # dp[lower_tight][upper_tight][matched_len]
    dp = [[[0] * m for _ in range(2)] for _ in range(2)]
    dp[1][1][0] = 1

    for pos in range(n):
        ndp = [[[0] * m for _ in range(2)] for _ in range(2)]
        s1c = ord(s1[pos])
        s2c = ord(s2[pos])
        for lower in (0, 1):
            for upper in (0, 1):
                low_char = s1c if lower else ord('a')
                high_char = s2c if upper else ord('z')
                if low_char > high_char:
                    continue
                for matched in range(m):
                    cur = dp[lower][upper][matched]
                    if cur == 0:
                        continue
                    for code in range(low_char, high_char + 1):
                        new_lower = lower and (code == s1c)
                        new_upper = upper and (code == s2c)
                        new_matched = nxt[matched][code - ord('a')]
                        if new_matched == m:
                            continue
                        ndp[new_lower][new_upper][new_matched] = (ndp[new_lower][new_upper][new_matched] + cur) % MOD
        dp = ndp

    ans = 0
    for lower in (0, 1):
        for upper in (0, 1):
            for matched in range(m):
