def stone_game_iii(stone_value: List[int]) -> str:
    n = len(stone_value)
    dp = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        take = 0
        best = -float('inf')
        for k in range(1, 4):
            if i + k > n:
                break
            take += stone_value[i + k - 1]
            net = take - dp[i + k]
            if net > best:
                best = net
        dp[i] = best
    diff = dp[0]
    if diff > 0:
        return "Alice"
    if diff < 0:
        return "Bob"
    return "Tie"

