        return 0
    steps = 0
    carry = 0
    for i in range(len(s) - 1, 0, -1):
        bit = ord(s[i]) - 48
        total = bit + carry
        if total == 0:
            steps += 1
        elif total == 1:
            steps += 2
            carry = 1
        else:
            steps += 1
    steps += carry
    return steps

