def longest_happy_string(a: int, b: int, c: int) -> str:
    heap: List[tuple[int, str]] = []
    for cnt, ch in ((a, 'a'), (b, 'b'), (c, 'c')):
        if cnt > 0:
            heapq.heappush(heap, (-cnt, ch))
    res: List[str] = []
    while heap:
        cnt1, ch1 = heapq.heappop(heap)
        cnt1 = -cnt1
        if len(res) >= 2 and res[-1] == res[-2] == ch1:
            if not heap:
                break
            cnt2, ch2 = heapq.heappop(heap)
            cnt2 = -cnt2
            res.append(ch2)
            cnt2 -= 1
            if cnt2 > 0:
                heapq.heappush(heap, (-cnt2, ch2))
            heapq.heappush(heap, (-cnt1, ch1))
        else:
            res.append(ch1)
            cnt1 -= 1
            if cnt1 > 0:
                heapq.heappush(heap, (-cnt1, ch1))
    return ''.join(res)

def entity_parser(text: str) -> str:
    entity_map = {
        '&quot;': '"',
        '&apos;': "'",
        '&amp;': '&',
        '&gt;': '>',
        '&lt;': '<',
        '&frasl;': '/'
    }
    result = []
    i = 0
    n = len(text)
    while i < n:
        if text[i] == '&':
            matched = False
            for entity, ch in entity_map.items():
                if text.startswith(entity, i):
                    result.append(ch)
                    i += len(entity)
                    matched = True
                    break
            if not matched:
                result.append('&')
                i += 1
        else:
            result.append(text[i])
            i += 1
    return ''.join(result)

def find_min_fibonacci_numbers(k: int) -> int:
    fib = [1, 1]
    while fib[-1] < k:
        fib.append(fib[-1] + fib[-2])

    count = 0
    remaining = k

    while remaining > 0:
        left, right = 0, len(fib) - 1
        while left < right:
            mid = (left + right + 1) // 2
            if fib[mid] <= remaining:
                left = mid
            else:
                right = mid - 1
        remaining -= fib[left]
        count += 1

    return count

