def reformat_string(s: str) -> str:
    letters: list[str] = []
    digits: list[str] = []
    for ch in s:
        if '0' <= ch <= '9':
            digits.append(ch)
        else:
            letters.append(ch)
    if abs(len(letters) - len(digits)) > 1:
        return ""
    # start with the type that has more characters; if equal, start with digit
    start_with_letter = len(letters) > len(digits)
    first = letters if start_with_letter else digits
    second = digits if start_with_letter else letters
    result: list[str] = []
    n = max(len(first), len(second))
    for i in range(n):
        if i < len(first):
            result.append(first[i])
        if i < len(second):
            result.append(second[i])
    return ''.join(result)

def min_number_of_frogs(croak_of_frogs: str) -> int:
    mapping = {'c': 0, 'r': 1, 'o': 2, 'a': 3, 'k': 4}
    cnt = [0] * 5
    frogs = 0
    max_frogs = 0
    for ch in croak_of_frogs:
        if ch not in mapping:
            return -1
        idx = mapping[ch]
        cnt[idx] += 1
        if idx > 0:
            cnt[idx - 1] -= 1
            if cnt[idx - 1] < 0:
                return -1
        if ch == 'c':
            frogs += 1
            if frogs > max_frogs:
                max_frogs = frogs
        elif ch == 'k':
            frogs -= 1
    return max_frogs if frogs == 0 else -1

