MOD = 10**9 + 7

def count_arrays(n: int, m: int, k: int) -> int:
    if n == 0:
        return 1 if k == 0 else 0
    if k == 0 or k > n:
        return 0
    # dp[pos][max_val][cnt]
    dp = [[[0] * (k + 2) for _ in range(m + 1)] for _ in range(n + 1)]
    for v in range(1, m + 1):
        dp[1][v][1] = 1

    for i in range(1, n):
        for max_val in range(1, m + 1):
            for cnt in range(1, k + 1):
                cur = dp[i][max_val][cnt]
                if cur == 0:
                    continue
                # choose a value <= max_val (no new record)
                dp[i + 1][max_val][cnt] = (dp[i + 1][max_val][cnt] + cur * max_val) % MOD
                # choose a value > max_val (new record)
                if cnt + 1 <= k:
                    add = cur
                    for new_max in range(max_val + 1, m + 1):
                        dp[i + 1][new_max][cnt + 1] = (dp[i + 1][new_max][cnt + 1] + add) % MOD

    ans = 0
    for max_val in range(1, m + 1):
        ans = (ans + dp[n][max_val][k]) % MOD
    return ans

