def max_score(card_points: list[int], k: int) -> int:
    n = len(card_points)
    total = 0
    for v in card_points:
        total += v
    window_size = n - k
    if window_size == 0:
        return total
    window_sum = 0
    for i in range(window_size):
        window_sum += card_points[i]
    min_window_sum = window_sum
    for i in range(window_size, n):
        window_sum += card_points[i] - card_points[i - window_size]
        if window_sum < min_window_sum:
            min_window_sum = window_sum
    return total - min_window_sum

