def number_ways(hats: list[list[int]]) -> int:
    MOD = 1000000007
    n = len(hats)
    total_mask = 1 << n

    people_for_hat = [[] for _ in range(41)]
    for person in range(n):
        for h in hats[person]:
            people_for_hat[h].append(person)

    dp = [0] * total_mask
    dp[0] = 1

    for hat in range(1, 41):
        candidates = people_for_hat[hat]
        if not candidates:
            continue
        for mask in range(total_mask - 1, -1, -1):
            cur_ways = dp[mask]
            if cur_ways == 0:
                continue
            for p in candidates:
                if (mask & (1 << p)) == 0:
                    new_mask = mask | (1 << p)
                    dp[new_mask] = (dp[new_mask] + cur_ways) % MOD

    return dp[total_mask - 1]

def kth_smallest_sum(mat, k):
    import heapq
    sums = mat[0][:]
    for row in mat[1:]:
        heap = []
        limit = min(k, len(sums))
        for i in range(limit):
            heapq.heappush(heap, (sums[i] + row[0], i, 0))
        new_sums = []
        while len(new_sums) < k and heap:
            total, i, j = heapq.heappop(heap)
            new_sums.append(total)
            if j + 1 < len(row):
                heapq.heappush(heap, (sums[i] + row[j + 1], i, j + 1))
        sums = new_sums
    return sums[k - 1]

