    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)

    def dfs(node: int, parent: int) -> int:
        time_needed = 0
        for neigh in graph[node]:
            if neigh == parent:
                continue
            child_time = dfs(neigh, node)
            if child_time > 0 or hasApple[neigh]:
                time_needed += child_time + 2
        return time_needed

    return dfs(0, -1)

