from typing import List

MOD = 10**9 + 7

def numberOfWays(pizza: List[str], k: int) -> int:
    n, m = len(pizza), len(pizza[0])
    # suffix sum of apples
    apples = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        for j in range(m - 1, -1, -1):
            apples[i][j] = (1 if pizza[i][j] == 'A' else 0) + apples[i + 1][j] + apples[i][j + 1] - apples[i + 1][j + 1]

    @lru_cache(None)
    def dfs(i: int, j: int, pieces: int) -> int:
        if apples[i][j] == 0:
            return 0
        if pieces == 1:
            return 1
        ans = 0
        # horizontal cuts
        for r in range(i + 1, n):
            if apples[i][j] - apples[r][j] > 0:
                ans = (ans + dfs(r, j, pieces - 1)) % MOD
        # vertical cuts
        for c in range(j + 1, m):
            if apples[i][j] - apples[i][c] > 0:
                ans = (ans + dfs(i, c, pieces - 1)) % MOD
        return ans

    return dfs(0, 0, k) % MOD

