    dp_len[0] = 0
    for i in range(1, target + 1):
        for d in range(1, 10):
            c = cost[d - 1]
            if i >= c and dp_len[i - c] != -1:
                dp_len[i] = max(dp_len[i], dp_len[i - c] + 1)
    if dp_len[target] == -1:
