                    if 0 <= nc1 < cols:
                        for nc2 in (c2 - 1, c2, c2 + 1):
                            if 0 <= nc2 < cols:
                                best = max(best, dp[nc1][nc2])
                newdp[c1][c2] = cur + best
        dp = newdp

    return dp[0][cols - 1]  # robots start at (0,0) and (0, cols-1)

