import math

def get_probability(balls: List[int]) -> float:
    k = len(balls)
    total = sum(balls)
    n = total // 2

    # dp[sel][d1][d2] = number of ways
    dp = [[[0] * (k + 1) for _ in range(k + 1)] for _ in range(n + 1)]
    dp[0][0][0] = 1

    for c in balls:
        newdp = [[[0] * (k + 1) for _ in range(k + 1)] for _ in range(n + 1)]
        for sel in range(n + 1):
            for d1 in range(k + 1):
                for d2 in range(k + 1):
                    cur = dp[sel][d1][d2]
                    if cur == 0:
                        continue
                    for x in range(c + 1):
                        ns = sel + x
                        if ns > n:
                            continue
                        nd1 = d1 + (1 if x > 0 else 0)
                        nd2 = d2 + (1 if c - x > 0 else 0)
                        newdp[ns][nd1][nd2] += cur * math.comb(c, x)
        dp = newdp

    numerator = sum(dp[n][d][d] for d in range(k + 1))
    denominator = math.comb(total, n)
    return round(numerator / denominator, 5)

def has_all_codes(s: str, k: int) -> bool:
    if len(s) < k:
        return False
    total_codes = 1 << k
    seen = set()
    mask = total_codes - 1
    h = 0
    for i in range(len(s)):
        h = ((h << 1) & mask) | (ord(s[i]) - 48)
        if i >= k - 1:
            seen.add(h)
            if len(seen) == total_codes:
                return True
    return len(seen) == total_codes

