def min_reorder(n: int, connections: List[List[int]]) -> int:
    directed = set()
    for a, b in connections:
        directed.add(f"{a}->{b}")

    adj = [[] for _ in range(n)]
    for a, b in connections:
        adj[a].append(b)
        adj[b].append(a)

    visited = [False] * n
    stack = [0]
    visited[0] = True
    reversals = 0

    while stack:
        u = stack.pop()
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                if f"{u}->{v}" in directed:
                    reversals += 1
                stack.append(v)

    return reversals

