def min_cost(houses: List[int], cost: List[List[int]], m: int, n: int, target: int) -> int:
    INF = 10**15
    dp = [[INF] * (n + 1) for _ in range(target + 1)]
    if houses[0] != 0:
        dp[1][houses[0]] = 0
    else:
        for c in range(1, n + 1):
            dp[1][c] = cost[0][c - 1]
    for i in range(1, m):
        new_dp = [[INF] * (n + 1) for _ in range(target + 1)]
        possible_colors = [houses[i]] if houses[i] != 0 else list(range(1, n + 1))
        for prev_t in range(1, target + 1):
            for prev_c in range(1, n + 1):
                prev_cost = dp[prev_t][prev_c]
                if prev_cost == INF:
                    continue
                for cur_c in possible_colors:
                    add_cost = cost[i][cur_c - 1] if houses[i] == 0 else 0
                    cur_t = prev_t if cur_c == prev_c else prev_t + 1
                    if cur_t > target:
                        continue
                    total = prev_cost + add_cost
                    if total < new_dp[cur_t][cur_c]:
                        new_dp[cur_t][cur_c] = total
        dp = new_dp
    answer = INF
    for c in range(1, n + 1):
        if dp[target][c] < answer:
            answer = dp[target][c]
    return -1 if answer == INF else answer

