def min_sum_of_lengths(arr: List[int], target: int) -> int:
    n = len(arr)
    INF = n + 1
    best_left = [INF] * n          # min length of a subarray ending at or before i
    best_right = [INF] * n         # min length of a subarray starting at or after i

    left = 0
    cur = 0
    for right, val in enumerate(arr):
        cur += val
        while cur > target and left <= right:
            cur -= arr[left]
            left += 1
        if cur == target:
            length = right - left + 1
            # record length for the exact end and start positions
            if length < best_left[right]:
                best_left[right] = length
            if length < best_right[left]:
                best_right[left] = length

    # propagate minima to the left (prefix) and to the right (suffix)
    for i in range(1, n):
        if best_left[i - 1] < best_left[i]:
            best_left[i] = best_left[i - 1]

    for i in range(n - 2, -1, -1):
        if best_right[i + 1] < best_right[i]:
            best_right[i] = best_right[i + 1]

    ans = INF * 2
    for i in range(n - 1):
        if best_left[i] < INF and best_right[i + 1] < INF:
            total = best_left[i] + best_right[i + 1]
            if total < ans:
                ans = total

    return -1 if ans >= INF * 2 else ans

