def allocate_mailboxes(houses: List[int], k: int) -> int:
    houses.sort()
    n = len(houses)
    if k >= n:
        return 0
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + houses[i]
    cost = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i, n):
            mid = (i + j) // 2
            left = houses[mid] * (mid - i) - (prefix[mid] - prefix[i])
            right = (prefix[j + 1] - prefix[mid + 1]) - houses[mid] * (j - mid)
            cost[i][j] = left + right
    dp = [[float('inf')] * n for _ in range(k + 1)]
    for i in range(n):
        dp[1][i] = cost[0][i]
    for m in range(2, k + 1):
        for i in range(m - 1, n):
            best = float('inf')
            for p in range(m - 2, i):
                cur = dp[m - 1][p] + cost[p + 1][i]
                if cur < best:
                    best = cur
            dp[m][i] = best
    return dp[k][n - 1]

