    low = min(bloom_day)
    high = max(bloom_day)

    def can_make(day: int) -> bool:
        bouquets = 0
        consecutive = 0
        for d in bloom_day:
            if d <= day:
                consecutive += 1
                if consecutive == k:
                    bouquets += 1
                    consecutive = 0
                    if bouquets >= m:
                        return True
            else:
                consecutive = 0
        return False

