def kth_ancestor(parent: List[int], node: int, k: int) -> int:
    n = len(parent)
    max_power = 0
    while (1 << max_power) <= n:
        max_power += 1
    up = [[-1] * n for _ in range(max_power)]
    for v in range(n):
        up[0][v] = parent[v]
    for p in range(1, max_power):
        for v in range(n):
            mid = up[p - 1][v]
            up[p][v] = -1 if mid == -1 else up[p - 1][mid]
    cur = node
    bit = 0
    while k > 0 and cur != -1:
        if k & 1:
            cur = up[bit][cur]
        k >>= 1
        bit += 1
    return cur

