def find_critical_and_pseudo_critical_edges(n: int, edges: List[List[int]]) -> List[List[int]]:
    # attach original index to each edge
    indexed_edges = [(u, v, w, i) for i, (u, v, w) in enumerate(edges)]

    class DSU:
        __slots__ = ("parent", "rank")
        def __init__(self, size: int):
            self.parent = list(range(size))
            self.rank = [0] * size

        def find(self, x: int) -> int:
            while self.parent[x] != x:
                self.parent[x] = self.parent[self.parent[x]]
                x = self.parent[x]
            return x

        def union(self, a: int, b: int) -> bool:
            ra, rb = self.find(a), self.find(b)
            if ra == rb:
                return False
            if self.rank[ra] < self.rank[rb]:
                ra, rb = rb, ra
            self.parent[rb] = ra
            if self.rank[ra] == self.rank[rb]:
                self.rank[ra] += 1
            return True

    # sort edges by weight
    sorted_edges = sorted(indexed_edges, key=lambda x: x[2])
    INF = 10 ** 15

    def mst_weight(skip: int = -1, force: int = -1) -> int:
        dsu = DSU(n)
        total = 0
        used = 0
        # force inclusion of an edge first
        if force != -1:
            u, v, w, _ = indexed_edges[force]
            if dsu.union(u, v):
                total += w
                used += 1
        for u, v, w, idx in sorted_edges:
            if idx == skip:
                continue
            if dsu.union(u, v):
                total += w
                used += 1
                if used == n - 1:
                    break
        return total if used == n - 1 else INF

    original_weight = mst_weight()

    critical: List[int] = []
    pseudo: List[int] = []

    for _, _, _, idx in indexed_edges:
        # critical test
        if mst_weight(skip=idx) > original_weight:
            critical.append(idx)
        else:
            # pseudo‑critical test
            if mst_weight(force=idx) == original_weight:
                pseudo.append(idx)

    return [critical, pseudo]  # TIME: O(m log m α(n)) SPACE: O(n + m)

def can_pair(arr: list[int], k: int) -> bool:
    remainder_count = {}
    for num in arr:
        r = ((num % k) + k) % k
        remainder_count[r] = remainder_count.get(r, 0) + 1
    for r, cnt in remainder_count.items():
        if r == 0:
            if cnt % 2 != 0:
                return False
        elif k % 2 == 0 and r == k // 2:
            if cnt % 2 != 0:
                return False
        else:
            complement = (k - r) % k
            if cnt != remainder_count.get(complement, 0):
                return False
    return True

