def min_swaps(grid: List[List[int]]) -> int:
    n = len(grid)
    right_one = [0] * n
    for i in range(n):
        pos = -1
        for j in range(n - 1, -1, -1):
            if grid[i][j] == 1:
                pos = j
                break
        right_one[i] = pos
    steps = 0
    for i in range(n):
        if right_one[i] <= i:
            continue
        j = i + 1
        while j < n and right_one[j] > i:
            j += 1
        if j == n:
            return -1
        while j > i:
            right_one[j], right_one[j - 1] = right_one[j - 1], right_one[j]
            steps += 1
            j -= 1
    return steps

def count_pairs(root, distance: int) -> int:
    good_pairs = 0

    def dfs(node):
        nonlocal good_pairs
        if not node:
            return []
        if not node.left and not node.right:
            return [1]
        left_dist = dfs(node.left)
        right_dist = dfs(node.right)
        for l in left_dist:
            for r in right_dist:
                if l + r <= distance:
                    good_pairs += 1
        up = []
        for d in left_dist:
            nd = d + 1
            if nd <= distance:
                up.append(nd)
        for d in right_dist:
            nd = d + 1
            if nd <= distance:
                up.append(nd)
        return up

    dfs(root)
    return good_pairs

