def string_compression_ii(s: str, k: int) -> int:
    n = len(s)

    def get_len(cnt: int) -> int:
        if cnt == 1:
            return 1
        return 1 + len(str(cnt))

    @lru_cache(None)
    def dp(i: int, rem: int) -> int:
        if rem >= n - i:
            return 0
        if i == n:
            return 0

        # option 1: delete s[i]
        best = dp(i + 1, rem - 1) if rem > 0 else float('inf')

        cnt = 0
        del_needed = 0
        for j in range(i, n):
            if s[j] == s[i]:
                cnt += 1
            else:
                del_needed += 1
            if del_needed > rem:
                continue
            cost = get_len(cnt) + dp(j + 1, rem - del_needed)
            if cost < best:
                best = cost
        return best

    return dp(0, k)

