def can_convert_string_in_k_moves(s: str, t: str, k: int) -> bool:
    need = [0] * 26
    for i in range(len(s)):
        a = ord(s[i]) - 97
        b = ord(t[i]) - 97
        if a == b:
            continue
        diff = (b - a + 26) % 26
        need[diff] += 1
    for diff in range(1, 26):
        cnt = need[diff]
        if cnt == 0:
            continue
        if diff > k:
            return False
        max_moves = (k - diff) // 26 + 1
        if cnt > max_moves:
            return False
    return True

def find_winner(arr: list[int], k: int) -> int:
    if k >= len(arr) - 1:
        max_val = arr[0]
        for i in range(1, len(arr)):
            if arr[i] > max_val:
                max_val = arr[i]
        return max_val

    queue = arr[:]
    cur = queue.pop(0)
    win = 0

    while win < k:
        nxt = queue.pop(0)
        if cur > nxt:
            win += 1
            queue.append(nxt)
        else:
            queue.append(cur)
            cur = nxt
            win = 1
    return cur

