def stone_game_v(stoneValue: List[int]) -> int:
    n = len(stoneValue)
    if n <= 1:
        return 0
    prefix = [0] * (n + 1)
    for i, v in enumerate(stoneValue):
        prefix[i + 1] = prefix[i] + v

    dp = [[0] * n for _ in range(n)]

    for length in range(2, n + 1):
        for i in range(0, n - length + 1):
            j = i + length - 1

            # binary search for the largest split where left sum <= right sum
            low, high = i, j - 1
            while low < high:
                mid = (low + high + 1) // 2
                left_sum = prefix[mid + 1] - prefix[i]
                right_sum = prefix[j + 1] - prefix[mid + 1]
                if left_sum <= right_sum:
                    low = mid
                else:
                    high = mid - 1
            k = low

            best = 0
            for split in (k, k + 1):
                if split < i or split >= j:
                    continue
                left_sum = prefix[split + 1] - prefix[i]
                right_sum = prefix[j + 1] - prefix[split + 1]
                if left_sum < right_sum:
                    best = max(best, left_sum + dp[i][split])
                elif left_sum > right_sum:
                    best = max(best, right_sum + dp[split + 1][j])
                else:
                    best = max(best, left_sum + dp[i][split], right_sum + dp[split + 1][j])
            dp[i][j] = best

    return dp[0][n - 1]

