def detect_cycle(grid: List[List[str]]) -> bool:
    m = len(grid)
    n = len(grid[0]) if m else 0
    visited = [[False] * n for _ in range(m)]
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    def dfs(x: int, y: int, px: int, py: int, ch: str) -> bool:
        visited[x][y] = True
        for dx, dy in dirs:
            nx = x + dx
            ny = y + dy
            if nx < 0 or nx >= m or ny < 0 or ny >= n:
                continue
            if grid[nx][ny] != ch:
                continue
            if not visited[nx][ny]:
                if dfs(nx, ny, x, y, ch):
                    return True
            elif nx != px or ny != py:
                return True
        return False

    for i in range(m):
        for j in range(n):
            if not visited[i][j]:
                if dfs(i, j, -1, -1, grid[i][j]):
                    return True
    return False

