    if m <= 0 or k <= 0:
        return False
    if m * k > n:
        return False
    if k == 1:
        return m <= n
    for i in range(0, n - m * k + 1):
        repeats = 1
        while repeats < k:
            same = True
            for j in range(m):
                if arr[i + j] != arr[i + repeats * m + j]:
