def count_routes(locations: List[int], start: int, finish: int, fuel: int) -> int:
    MOD = 1_000_000_007
    n = len(locations)
    memo = [[-1] * (fuel + 1) for _ in range(n)]

    def dfs(city: int, remaining: int) -> int:
        if memo[city][remaining] != -1:
            return memo[city][remaining]
        ways = 1 if city == finish else 0
        for next_city in range(n):
            if next_city == city:
                continue
            cost = abs(locations[city] - locations[next_city])
            if cost <= remaining:
                ways = (ways + dfs(next_city, remaining - cost)) % MOD
        memo[city][remaining] = ways
        return ways

    return dfs(start, fuel)

