def number_of_ways(s: str) -> int:
    n = len(s)
    total = s.count('1')
    if total == 0:
        return ((n - 1) * (n - 2) // 2) % MOD
    if total % 3 != 0:
        return 0
    need = total // 3
    cnt1 = cnt2 = 0
    ones = 0
    for ch in s:
        if ch == '1':
            ones += 1
        if ones == need:
            cnt1 += 1
        elif ones == 2 * need:
            cnt2 += 1
    return (cnt1 * cnt2) % MOD

