def shortest_subarray_to_remove(arr: list[int]) -> int:
    n = len(arr)
    prefix_end = 0
    while prefix_end + 1 < n and arr[prefix_end] <= arr[prefix_end + 1]:
        prefix_end += 1
    if prefix_end == n - 1:
        return 0
    suffix_start = n - 1
    while suffix_start - 1 >= 0 and arr[suffix_start - 1] <= arr[suffix_start]:
        suffix_start -= 1
    min_remove = min(n - prefix_end - 1, suffix_start)
    i, j = 0, suffix_start
    while i <= prefix_end and j < n:
        while j < n and arr[j] < arr[i]:
            j += 1
        if j < n:
            min_remove = min(min_remove, j - i - 1)
        i += 1
    return min_remove

