def max_num_edges_to_remove(n: int, edges: List[List[int]]) -> int:
    class DSU:
        def __init__(self, size: int):
            self.parent = [i for i in range(size + 1)]
            self.rank = [0] * (size + 1)

        def find(self, x: int) -> int:
            while self.parent[x] != x:
                self.parent[x] = self.parent[self.parent[x]]
                x = self.parent[x]
            return x

        def union(self, a: int, b: int) -> bool:
            ra = self.find(a)
            rb = self.find(b)
            if ra == rb:
                return False
            if self.rank[ra] < self.rank[rb]:
                ra, rb = rb, ra
            self.parent[rb] = ra
            if self.rank[ra] == self.rank[rb]:
                self.rank[ra] += 1
            return True

    alice = DSU(n)
    bob = DSU(n)
    used = 0

    for typ, u, v in edges:
        if typ == 3:
            a = alice.union(u, v)
            b = bob.union(u, v)
            if a or b:
                used += 1

    for typ, u, v in edges:
        if typ == 1:
            if alice.union(u, v):
                used += 1
        elif typ == 2:
            if bob.union(u, v):
                used += 1

    def comp_count(ds: DSU) -> int:
        cnt = 0
        for i in range(1, n + 1):
            if ds.find(i) == i:
                cnt += 1
        return cnt

    if comp_count(alice) != 1 or comp_count(bob) != 1:
        return -1

    return len(edges) - used

