def num_triplets(nums1: List[int], nums2: List[int]) -> int:
    def pair_product_counts(arr: List[int]) -> Counter:
        cnt = Counter()
        n = len(arr)
        for i in range(n):
            a = arr[i]
            for j in range(i + 1, n):
                cnt[a * arr[j]] += 1
        return cnt

    cnt1 = pair_product_counts(nums1)
    cnt2 = pair_product_counts(nums2)

