def reorder_spaces(text: str) -> str:
    total_spaces = 0
    for ch in text:
        if ch == ' ':
            total_spaces += 1
    words = text.strip().split()
    word_count = len(words)
    if word_count == 1:
        return words[0] + ' ' * total_spaces
    spaces_between = total_spaces // (word_count - 1)
    extra_spaces = total_spaces - spaces_between * (word_count - 1)
    middle = ' ' * spaces_between
    return middle.join(words) + ' ' * extra_spaces

def max_unique_split(s: str) -> int:
    used = set()
    best = 0

    def dfs(start: int, count: int):
        nonlocal best
        if start == len(s):
            if count > best:
                best = count
            return
        for end in range(start + 1, len(s) + 1):
            sub = s[start:end]
            if sub not in used:
                used.add(sub)
                dfs(end, count + 1)
                used.remove(sub)

    dfs(0, 0)
    return best

