def even_odd_tree(root: Optional["TreeNode"]) -> bool:
    if not root:
        return True
    queue = [root]
    level = 0
    head = 0
    while head < len(queue):
        level_size = len(queue) - head
        prev = -float('inf') if level % 2 == 0 else float('inf')
        for _ in range(level_size):
            node = queue[head]
            head += 1
            if level % 2 == 0:
                if node.val % 2 == 0 or node.val <= prev:
                    return False
            else:
                if node.val % 2 == 1 or node.val >= prev:
                    return False
            prev = node.val
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        level += 1
    return True

