def max_visible_points(points: List[List[int]], angle: float, location: List[int]) -> int:
    same_location = sum(1 for x, y in points if x == location[0] and y == location[1])
    angles = []
    for x, y in points:
        if x == location[0] and y == location[1]:
            continue
        deg = math.atan2(y - location[1], x - location[0]) * 180 / math.pi
        if deg < 0:
            deg += 360
        angles.append(deg)
    if angle >= 360:
        return len(points)
    angles.sort()
    extended = angles + [v + 360 for v in angles]
    max_in_window = 0
    left = 0
    for right in range(len(extended)):
        while extended[right] - extended[left] > angle:
            left += 1
        window_size = right - left + 1
        if window_size > max_in_window:
            max_in_window = window_size
    return max_in_window + same_location

