def number_of_sets(n: int, k: int) -> int:
    """
    Returns the number of ways to choose k non‑overlapping line segments
    from n points on a line, modulo 1e9+7.
    """
    max_val = n + k
    fact = [1] * (max_val + 1)
    for i in range(1, max_val + 1):
        fact[i] = fact[i - 1] * i % MOD

    inv_fact = [1] * (max_val + 1)
    inv_fact[max_val] = pow(fact[max_val], MOD - 2, MOD)
    for i in range(max_val, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % MOD

    def comb(N: int, R: int) -> int:
        if R < 0 or R > N:
            return 0
        return fact[N] * inv_fact[R] % MOD * inv_fact[N - R] % MOD

    return comb(n + k - 1, 2 * k)

