def minimum_effort_path(heights: List[List[int]]) -> int:
    rows = len(heights)
    cols = len(heights[0]) if rows else 0

    if rows == 1 and cols == 1:
        return 0

    min_h = min(min(row) for row in heights)
    max_h = max(max(row) for row in heights)
    low, high = 0, max_h - min_h

    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    def can_reach(limit: int) -> bool:
        q = deque([(0, 0)])
        visited = [[False] * cols for _ in range(rows)]
        visited[0][0] = True
        while q:
            r, c = q.popleft()
            if r == rows - 1 and c == cols - 1:
                return True
            cur_h = heights[r][c]
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc]:
                    if abs(heights[nr][nc] - cur_h) <= limit:
                        visited[nr][nc] = True
                        q.append((nr, nc))
        return False

    while low < high:
        mid = (low + high) // 2
        if can_reach(mid):
            high = mid
        else:
            low = mid + 1

    return low
