def are_connected(n: int, threshold: int, queries: List[List[int]]) -> List[bool]:
    parent = list(range(n + 1))
    size = [1] * (n + 1)

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a: int, b: int) -> None:
        ra, rb = find(a), find(b)
        if ra == rb:
            return
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        size[ra] += size[rb]

    # Connect numbers sharing a divisor greater than threshold
    for d in range(threshold + 1, n + 1):
        first = d
        for multiple in range(2 * d, n + 1, d):
            union(first, multiple)

    return [find(a) == find(b) for a, b in queries]

