def matrix_rank_transform(matrix: List[List[int]]) -> List[List[int]]:
    m = len(matrix)
    n = len(matrix[0]) if m else 0

    cells = []
    for i in range(m):
        for j in range(n):
            cells.append((matrix[i][j], i, j))

    cells.sort(key=lambda x: x[0])

    answer = [[0] * n for _ in range(m)]
    rank = [0] * (m + n)

    idx = 0
    while idx < len(cells):
        same_val = []
        cur_val = cells[idx][0]

        while idx < len(cells) and cells[idx][0] == cur_val:
            same_val.append(cells[idx])
            idx += 1

        parent = {}

        def find(x: int) -> int:
            if x not in parent:
                parent[x] = x
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a: int, b: int) -> None:
            ra = find(a)
            rb = find(b)
            if ra != rb:
                parent[ra] = rb

        for val, row, col in same_val:
            union(row, m + col)

        comp_max = {}
        for val, row, col in same_val:
            root = find(row)
            cur_max = max(rank[row], rank[m + col])
            comp_max[root] = max(comp_max.get(root, 0), cur_max)

        for val, row, col in same_val:
            root = find(row)
            new_rank = comp_max[root] + 1
            answer[row][col] = new_rank
            rank[row] = new_rank
            rank[m + col] = new_rank

    return answer

