def num_ways(words: List[str], target: str) -> int:
    MOD = 1000000007
    m = len(words[0])
    n = len(target)

    count = [[0] * m for _ in range(26)]
    for w in words:
        for pos, ch in enumerate(w):
            idx = ord(ch) - 97
            count[idx][pos] += 1

    dp = [0] * (n + 1)
    dp[0] = 1

    for pos in range(m):
        upper = min(n, pos + 1)
        for i in range(upper, 0, -1):
            char_idx = ord(target[i - 1]) - 97
            ways = count[char_idx][pos]
            if ways:
                dp[i] = (dp[i] + dp[i - 1] * ways) % MOD

    return dp[n]

def count_substrings(s: str, t: str) -> int:
    n, m = len(s), len(t)
    # left[i][j]: length of common suffix ending at s[i-1], t[j-1]
    left = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        si = s[i - 1]
        row = left[i]
        prev_row = left[i - 1]
        for j in range(1, m + 1):
            if si == t[j - 1]:
                row[j] = prev_row[j - 1] + 1
            else:
                row[j] = 0

    # right[i][j]: length of common prefix starting at s[i], t[j]
    right = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        si = s[i]
        row = right[i]
        next_row = right[i + 1]
        for j in range(m - 1, -1, -1):
            if si == t[j]:
                row[j] = next_row[j + 1] + 1
            else:
                row[j] = 0

    total = 0
    for i in range(n):
        for j in range(m):
            if s[i] != t[j]:
                left_len = left[i][j]          # equal chars to the left
                right_len = right[i + 1][j + 1]  # equal chars to the right
                total += (left_len + 1) * (right_len + 1)
    return total

