def furthest_building(heights: List[int], bricks: int, ladders: int) -> int:
    heap: List[int] = []

    def heap_push(val: int) -> None:
        heap.append(val)
        idx = len(heap) - 1
        while idx > 0:
            parent = (idx - 1) >> 1
            if heap[parent] <= heap[idx]:
                break
            heap[parent], heap[idx] = heap[idx], heap[parent]
            idx = parent

    def heap_pop() -> int:
        if len(heap) == 1:
            return heap.pop()
        top = heap[0]
        heap[0] = heap.pop()
        idx = 0
        while True:
            left = idx * 2 + 1
            right = idx * 2 + 2
            smallest = idx
            if left < len(heap) and heap[left] < heap[smallest]:
                smallest = left
            if right < len(heap) and heap[right] < heap[smallest]:
                smallest = right
            if smallest == idx:
                break
            heap[smallest], heap[idx] = heap[idx], heap[smallest]
            idx = smallest
        return top

    for i in range(len(heights) - 1):
        climb = heights[i + 1] - heights[i]
        if climb <= 0:
            continue
        heap_push(climb)
        if len(heap) > ladders:
            smallest_climb = heap_pop()
            bricks -= smallest_climb
            if bricks < 0:
                return i
    return len(heights) - 1

