def create_sorted_array(instructions: List[int]) -> int:
    MOD = 1_000_000_007
    uniq = sorted(set(instructions))
    index_map = {v: i + 1 for i, v in enumerate(uniq)}

    class Fenwick:
        def __init__(self, size: int):
            self.n = size
            self.tree = [0] * (size + 1)

        def add(self, i: int, delta: int) -> None:
            while i <= self.n:
                self.tree[i] += delta
                i += i & -i

        def prefix_sum(self, i: int) -> int:
            s = 0
            while i:
                s += self.tree[i]
                i -= i & -i
            return s

    bit = Fenwick(len(uniq))
    total = 0
    for i, val in enumerate(instructions):
        idx = index_map[val]
        less = bit.prefix_sum(idx - 1)
        leq = bit.prefix_sum(idx)
        greater = i - leq
        total = (total + (less if less < greater else greater)) % MOD
        bit.add(idx, 1)
    return total

