def can_distribute(nums: List[int], quantity: List[int]) -> bool:
    freq_map = {}
    for v in nums:
        freq_map[v] = freq_map.get(v, 0) + 1
    freqs = list(freq_map.values())

    m = len(quantity)
    full_mask = (1 << m) - 1

    quantity.sort(reverse=True)

    subset_sum = [0] * (1 << m)
    for mask in range(1, 1 << m):
        lsb = mask & -mask
        idx = (lsb.bit_length() - 1)
        subset_sum[mask] = subset_sum[mask ^ lsb] + quantity[idx]

    memo = {}

    def dfs(mask: int, i: int) -> bool:
        if mask == 0:
            return True
        if i == len(freqs):
            return False
        key = (mask, i)
        if key in memo:
            return memo[key]

        if dfs(mask, i + 1):
            memo[key] = True
            return True

        sub = mask
        while sub:
            if subset_sum[sub] <= freqs[i]:
                if dfs(mask ^ sub, i + 1):
                    memo[key] = True
                    return True
            sub = (sub - 1) & mask

        memo[key] = False
        return False

    return dfs(full_mask, 0)

def decrypt(code: list[int], k: int) -> list[int]:
    n = len(code)
    result = [0] * n
    if k == 0:
        return result
    steps = abs(k)
    window = 0
    if k > 0:
        for i in range(1, steps + 1):
            window += code[i % n]
        for i in range(n):
            result[i] = window
            window -= code[(i + 1) % n]
            window += code[(i + steps + 1) % n]
    else:
        for i in range(steps):
            window += code[(n - 1 - i + n) % n]
        for i in range(n):
            result[i] = window
            window -= code[(i - steps + n) % n]
            window += code[i]
    return result

