def max_grid_happiness(m, n, introvertsCount, extrovertsCount):
    total_cells = m * n
    grid = [0] * total_cells
    base = {1: 120, 2: 40}
    adj_delta = {
        1: {1: -60, 2: -10},
        2: {1: -10, 2: 40}
    }
    best = 0

    def dfs(pos, intro_left, extro_left, current):
        nonlocal best
        if pos == total_cells:
            if current > best:
                best = current
            return
        if intro_left == 0 and extro_left == 0:
            if current > best:
                best = current
            return

        dfs(pos + 1, intro_left, extro_left, current)

        row = pos // n
        col = pos % n
        left = grid[pos - 1] if col > 0 else 0
        up = grid[pos - n] if row > 0 else 0

        if intro_left > 0:
            add = base[1]
            if left:
                add += adj_delta[1][left]
            if up:
                add += adj_delta[1][up]
            grid[pos] = 1
            dfs(pos + 1, intro_left - 1, extro_left, current + add)
            grid[pos] = 0

        if extro_left > 0:
            add = base[2]
            if left:
                add += adj_delta[2][left]
            if up:
                add += adj_delta[2][up]
            grid[pos] = 2
            dfs(pos + 1, intro_left, extro_left - 1, current + add)
            grid[pos] = 0

    dfs(0, introvertsCount, extrovertsCount, 0)
    return best

