import heapq

def minimum_deviation(nums: List[int]) -> int:
    heap = []
    current_min = float('inf')
    for x in nums:
        if x % 2 == 1:
            x *= 2
        heapq.heappush(heap, -x)
        if x < current_min:
            current_min = x
    best = -heap[0] - current_min
    while (-heap[0]) % 2 == 0:
        max_val = -heapq.heappop(heap)
        reduced = max_val // 2
        heapq.heappush(heap, -reduced)
        if reduced < current_min:
            current_min = reduced
        deviation = -heap[0] - current_min
        if deviation < best:
            best = deviation
    return best

