def minimum_incompatibility(nums: List[int], k: int) -> int:
    n = len(nums)
    if n % k != 0:
        return -1
    size = n // k

    # Quick impossibility check: any value appears more than k times
    cnt = Counter(nums)
    if any(v > k for v in cnt.values()):
        return -1

    full_mask = (1 << n) - 1

    # Pre‑compute all valid subsets of exact size with unique values
    incompat = {}
    subsets_by_first = [[] for _ in range(n)]

    for mask in range(1 << n):
        if mask.bit_count() != size:
            continue
        seen = set()
        ok = True
        mn = sys.maxsize
        mx = -sys.maxsize
        for i in range(n):
            if mask >> i & 1:
                val = nums[i]
                if val in seen:
                    ok = False
                    break
                seen.add(val)
                if val < mn:
                    mn = val
                if val > mx:
                    mx = val
        if not ok:
            continue
        inc = mx - mn
        incompat[mask] = inc
        for i in range(n):
            if mask >> i & 1:
                subsets_by_first[i].append(mask)

    INF = 10 ** 9

    @lru_cache(None)
    def dfs(mask: int) -> int:
        if mask == 0:
            return 0
        # pick the lowest set bit as anchor
        lsb = mask & -mask
        i = lsb.bit_length() - 1
        best = INF
        for sub in subsets_by_first[i]:
            if sub & mask == sub:  # sub is fully contained in mask
                cur = incompat[sub] + dfs(mask ^ sub)
                if cur < best:
                    best = cur
        return best

    ans = dfs(full_mask)
    return ans if ans < INF else -1

