    left = 0
    current_sum = 0
    best = 0
    for right in range(len(nums)):
        val = nums[right]
        if val in last_seen and last_seen[val] >= left:
            while left <= last_seen[val]:
                current_sum -= nums[left]
                left += 1
        current_sum += val
        last_seen[val] = right
        if current_sum > best:
