def distance_limited_paths_exist(n: int, edge_list: List[List[int]], queries: List[List[int]]) -> List[bool]:
    edge_list.sort(key=lambda x: x[2])
    indexed_queries = [(q[0], q[1], q[2], i) for i, q in enumerate(queries)]
    indexed_queries.sort(key=lambda x: x[2])
    parent = list(range(n))
    rank = [0] * n

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x: int, y: int) -> None:
        rx, ry = find(x), find(y)
        if rx == ry:
            return
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1

    answer = [False] * len(queries)
    e = 0
    for p, q, limit, idx in indexed_queries:
        while e < len(edge_list) and edge_list[e][2] < limit:
            union(edge_list[e][0], edge_list[e][1])
            e += 1
        answer[idx] = find(p) == find(q)
    return answer

