def max_eaten_apples(apples: List[int], days: List[int]) -> int:
    heap = []  # list of dicts with keys 'expire' and 'count'
    n = len(apples)
    day = 0
    eaten = 0

    def swap(i: int, j: int) -> None:
        heap[i], heap[j] = heap[j], heap[i]

    def sift_up(idx: int) -> None:
        while idx > 0:
            parent = (idx - 1) >> 1
            if heap[parent]['expire'] <= heap[idx]['expire']:
                break
            swap(parent, idx)
            idx = parent

    def sift_down(idx: int) -> None:
        length = len(heap)
        while True:
            smallest = idx
            left = idx * 2 + 1
            right = left + 1
            if left < length and heap[left]['expire'] < heap[smallest]['expire']:
                smallest = left
            if right < length and heap[right]['expire'] < heap[smallest]['expire']:
                smallest = right
            if smallest == idx:
                break
            swap(idx, smallest)
            idx = smallest

    def push(node: dict) -> None:
        heap.append(node)
        sift_up(len(heap) - 1)

    def pop() -> dict:
        top = heap[0]
        last = heap.pop()
        if heap:
            heap[0] = last
            sift_down(0)
        return top

    while day < n or heap:
        if day < n and apples[day] > 0:
            push({'expire': day + days[day], 'count': apples[day]})
        while heap and (heap[0]['expire'] <= day or heap[0]['count'] == 0):
            pop()
        if heap:
            heap[0]['count'] -= 1
            eaten += 1
            if heap[0]['count'] == 0:
                pop()
        day += 1
    return eaten

