def count_good_meals(deliciousness: List[int]) -> int:
    MOD = 1000000007
    freq = {}
    result = 0

    max_val = 0
    for v in deliciousness:
        if v > max_val:
            max_val = v
    limit = 1
    while limit <= max_val * 2:
        limit <<= 1

    for cur in deliciousness:
        p = 1
        while p <= limit:
            need = p - cur
            if need in freq:
                result = (result + freq[need]) % MOD
            p <<= 1
        freq[cur] = freq.get(cur, 0) + 1

    return result

