def ways_to_split(nums: List[int]) -> int:
    n = len(nums)
    if n < 3:
        return 0
    prefix = [0] * (n + 1)
    for i, v in enumerate(nums):
        prefix[i + 1] = prefix[i] + v
    total = prefix[n]

    ans = 0
    low = 1
    high = 1

    for i in range(n - 2):
        left_sum = prefix[i + 1]

        if low < i + 1:
            low = i + 1
        if high < i + 1:
            high = i + 1

        while low < n - 1 and prefix[low + 1] - prefix[i + 1] < left_sum:
            low += 1

        while high < n - 1 and prefix[high + 1] - prefix[i + 1] <= total - prefix[high + 1]:
            high += 1

        if low < n - 1:
            ans = (ans + max(0, high - low)) % MOD

    return ans

