def min_operations(target: list[int], arr: list[int]) -> int:
    pos = {}
    for i, v in enumerate(target):
        pos[v] = i
    indices = []
    for v in arr:
        if v in pos:
            indices.append(pos[v])
    tails = []
    for x in indices:
        lo, hi = 0, len(tails)
        while lo < hi:
            mid = (lo + hi) >> 1
            if tails[mid] < x:
                lo = mid + 1
            else:
                hi = mid
        if lo == len(tails):
            tails.append(x)
        else:
            tails[lo] = x
    return len(target) - len(tails)

