def construct_largest_valid_sequence(n: int) -> List[int]:
    length = 2 * n - 1
    res = [0] * length
    best: List[int] = []

    def dfs(num: int) -> None:
        nonlocal best
        if num == 0:
            # a complete sequence is formed
            if not best or res > best:  # lexicographic comparison
                best = res.copy()
            return
        if num == 1:
            for i in range(length):
                if res[i] == 0:
                    res[i] = 1
                    dfs(0)
                    res[i] = 0
            return
        for i in range(length):
            if res[i] == 0 and i + num < length and res[i + num] == 0:
                res[i] = res[i + num] = num
                dfs(num - 1)
                res[i] = res[i + num] = 0

    dfs(n)
    return best

