def minimum_hamming_distance(source: List[int], target: List[int], allowed_swaps: List[Tuple[int, int]]) -> int:
    n = len(source)
    parent = list(range(n))

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a: int, b: int) -> None:
        ra = find(a)
        rb = find(b)
        if ra != rb:
            parent[ra] = rb

    for a, b in allowed_swaps:
        union(a, b)

    groups = {}
    for i in range(n):
        root = find(i)
        groups.setdefault(root, []).append(i)

    mismatches = 0
    for indices in groups.values():
        src_count = {}
        for idx in indices:
            val = source[idx]
            src_count[val] = src_count.get(val, 0) + 1
        for idx in indices:
            val = target[idx]
            if src_count.get(val, 0) > 0:
                src_count[val] -= 1
            else:
                mismatches += 1

    return mismatches

