def number_of_ways(pairs: List[List[int]]) -> int:
    adj: Dict[int, Set[int]] = {}
    for a, b in pairs:
        adj.setdefault(a, set()).add(b)
        adj.setdefault(b, set()).add(a)

    nodes = set(adj.keys())
    n = len(nodes)

    # potential roots: nodes connected to all others
    root_candidates = [v for v in nodes if len(adj[v]) == n - 1]
    if not root_candidates:
        return 0

    root = root_candidates[0]
    answer = 2 if len(root_candidates) > 1 else 1

    for v in nodes:
        if v == root:
            continue
        possible_parents = []
        for u in adj[v]:
            # parent must have degree >= child's degree
            if len(adj[u]) < len(adj[v]):
                continue
            # all neighbors of v (except possibly u) must be neighbors of u
            if all(w == u or w in adj[u] for w in adj[v]):
                possible_parents.append(u)

        if not possible_parents:
            return 0

        min_deg = min(len(adj[u]) for u in possible_parents)
        best_parents = [u for u in possible_parents if len(adj[u]) == min_deg]

        if len(best_parents) > 1:
            answer = 2

    return answer

