def minimum_time_required(jobs: List[int], k: int) -> int:
    jobs.sort(reverse=True)
    low, high = max(jobs), sum(jobs)

    def can_finish(limit: int) -> bool:
        loads = [0] * k

        def dfs(idx: int) -> bool:
            if idx == len(jobs):
                return True
            cur = jobs[idx]
            seen = set()
            for i in range(k):
                if loads[i] + cur > limit:
                    continue
                if loads[i] in seen:
                    continue
                seen.add(loads[i])
                loads[i] += cur
                if dfs(idx + 1):
                    return True
                loads[i] -= cur
                if loads[i] == 0 or loads[i] + cur == limit:
                    break
            return False

        return dfs(0)

    while low < high:
        mid = (low + high) // 2
        if can_finish(mid):
            high = mid
        else:
            low = mid + 1
    return low

