from collections import deque

def cat_and_mouse(grid: List[str], catJump: int, mouseJump: int) -> bool:
    rows, cols = len(grid), len(grid[0])
    total = rows * cols

    mouse_start = cat_start = food = -1
    for i in range(rows):
        for j in range(cols):
            ch = grid[i][j]
            if ch == 'M':
                mouse_start = i * cols + j
            elif ch == 'C':
                cat_start = i * cols + j
            elif ch == 'F':
                food = i * cols + j

    passable = [[grid[i][j] != '#' for j in range(cols)] for i in range(rows)]
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def compute_moves(jump: int) -> List[List[int]]:
        moves = [[] for _ in range(total)]
        for r in range(rows):
            for c in range(cols):
                if not passable[r][c]:
                    continue
                idx = r * cols + c
                moves[idx].append(idx)  # stay
                for dr, dc in dirs:
                    nr, nc = r, c
                    for _ in range(jump):
                        nr += dr
                        nc += dc
                        if not (0 <= nr < rows and 0 <= nc < cols):
                            break
                        if not passable[nr][nc]:
                            break
                        moves[idx].append(nr * cols + nc)
        return moves

    mouse_moves = compute_moves(mouseJump)
    cat_moves = compute_moves(catJump)

    mouse_rev = [[] for _ in range(total)]
    cat_rev = [[] for _ in range(total)]
    for src in range(total):
        for dst in mouse_moves[src]:
            mouse_rev[dst].append(src)
        for dst in cat_moves[src]:
            cat_rev[dst].append(src)

    result = {}
    degree = {}

    for m in range(total):
        for c in range(total):
            if not passable[m // cols][m % cols] or not passable[c // cols][c % cols]:
                continue
            for turn in (0, 1):
                key = (m, c, turn)
                degree[key] = len(mouse_moves[m]) if turn == 0 else len(cat_moves[c])
                if m == food:
                    result[key] = 1
                elif c == food or m == c:
                    result[key] = -1

    q = deque([k for k, v in result.items()])

    while q:
        m, c, turn = cur = q.popleft()
        cur_res = result[cur]

        if turn == 0:  # mouse's turn, came from cat's turn
            for pc in cat_rev[c]:
                pred = (m, pc, 1)
                if pred in result:
                    continue
                if cur_res == -1:  # cat can force mouse loss
                    result[pred] = -1
                    q.append(pred)
                else:
                    degree[pred] -= 1
                    if degree[pred] == 0:
                        result[pred] = 1
                        q.append(pred)
        else:  # cat's turn, came from mouse's turn
            for pm in mouse_rev[m]:
                pred = (pm, c, 0)
                if pred in result:
                    continue
                if cur_res == 1:  # mouse can force win
                    result[pred] = 1
                    q.append(pred)
                else:
                    degree[pred] -= 1
                    if degree[pred] == 0:
                        result[pred] = -1
                        q.append(pred)

    return result.get((mouse_start, cat_start, 0), -1) == 1
