def min_changes(a: str, b: str) -> int:
    freq_a: List[int] = [0] * 26
    freq_b: List[int] = [0] * 26
    for ch in a:
        freq_a[ord(ch) - 97] += 1
    for ch in b:
        freq_b[ord(ch) - 97] += 1

    total_a = len(a)
    total_b = len(b)

    prefix_a: List[int] = [0] * 26
    prefix_b: List[int] = [0] * 26
    s = 0
    for i in range(26):
        s += freq_a[i]
        prefix_a[i] = s
    s = 0
    for i in range(26):
        s += freq_b[i]
        prefix_b[i] = s

    INF = 10 ** 9
    min_cond1 = INF
    # a chars < b chars
    for i in range(25):  # split after character i (0..24)
        changes = (total_a - prefix_a[i]) + prefix_b[i]
        if changes < min_cond1:
            min_cond1 = changes

    min_cond2 = INF
    # a chars > b chars
    for i in range(25):
        changes = (total_b - prefix_b[i]) + prefix_a[i]
        if changes < min_cond2:
            min_cond2 = changes

    max_common = 0
    for i in range(26):
        common = freq_a[i] + freq_b[i]
        if common > max_common:
            max_common = common
    min_cond3 = total_a + total_b - max_common

    return min(min_cond1, min_cond2, min_cond3)

