            d += 1 if d == 2 else 2
        if k > 1:
            exps.append(1)
        return exps

    # first pass to find limits
    for n, k in queries:
        if n > max_n:
            max_n = n
        if k != 1:
            for e in factor_exponents(k):
                if e > max_e:
                    max_e = e

    limit = max_n + max_e + 5  # small safety margin

    # pre‑compute factorials and inverse factorials up to limit
    fact = [1] * (limit + 1)
    for i in range(1, limit + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv_fact = [1] * (limit + 1)
    inv_fact[limit] = pow(fact[limit], MOD - 2, MOD)
    for i in range(limit, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % MOD

    def comb(n: int, k: int) -> int:
        if k < 0 or k > n:
            return 0
        return fact[n] * inv_fact[k] % MOD * inv_fact[n - k] % MOD

    answers: List[int] = []
    for n, k in queries:
        if k == 1:
            answers.append(1)
            continue
        exps = factor_exponents(k)
        res = 1
        for e in exps:
            res = res * comb(e + n - 1, n - 1) % MOD
        answers.append(res)
    return answers
# TIME: O(N * sqrt(K) + L) SPACE: O(L) where L = max_n + max_exponent

def check_partitioning(s: str) -> bool:
