    if n < 3:
        return False
    is_pal = [[False] * n for _ in range(n)]
    for length in range(1, n + 1):
        for i in range(0, n - length + 1):
            j = i + length - 1
            if s[i] == s[j] and (length <= 2 or is_pal[i + 1][j - 1]):
                is_pal[i][j] = True
    for i in range(1, n - 1):
        if not is_pal[0][i - 1]:
            continue
        for j in range(i + 1, n):
            if is_pal[i][j - 1] and is_pal[j][n - 1]:
                return True
    return False

