def min_abs_difference(nums: List[int], goal: int) -> int:
    n = len(nums)
    mid = n // 2
    left = nums[:mid]
    right = nums[mid:]

    def gen_sums(arr: List[int]) -> List[int]:
        m = len(arr)
        total = 1 << m
        sums = [0] * total
        for mask in range(total):
            s = 0
            for i in range(m):
                if mask & (1 << i):
                    s += arr[i]
            sums[mask] = s
        return sums

    left_sums = gen_sums(left)
    right_sums = gen_sums(right)
    right_sums.sort()

    best = float('inf')

    def lower_bound(arr: List[int], target: int) -> int:
        lo, hi = 0, len(arr)
        while lo < hi:
            mid = (lo + hi) >> 1
            if arr[mid] < target:
                lo = mid + 1
            else:
                hi = mid
        return lo

    for s1 in left_sums:
        need = goal - s1
        idx = lower_bound(right_sums, need)

        if idx < len(right_sums):
            cur = abs(s1 + right_sums[idx] - goal)
            if cur < best:
                best = cur

        if idx > 0:
            cur = abs(s1 + right_sums[idx - 1] - goal)
            if cur < best:
                best = cur

        if best == 0:
            return 0

    return int(best)

