def largest_merge(word1: str, word2: str) -> str:
    i = 0
    j = 0
    merge = ""

    def suffix_greater(p: int, q: int) -> bool:
        while p < len(word1) and q < len(word2):
            if word1[p] != word2[q]:
                return word1[p] > word2[q]
            p += 1
            q += 1
        return p < len(word1)

    while i < len(word1) or j < len(word2):
        if i == len(word1):
            merge += word2[j:]
            break
        if j == len(word2):
            merge += word1[i:]
            break
        if suffix_greater(i, j):
            merge += word1[i]
            i += 1
        else:
            merge += word2[j]
            j += 1
    return merge

