def min_operations(nums1: List[int], nums2: List[int]) -> int:
    sum1 = sum(nums1)
    sum2 = sum(nums2)

    if sum1 == sum2:
        return 0

    if sum1 > sum2:
        nums1, nums2 = nums2, nums1
        sum1, sum2 = sum2, sum1

    diff = sum2 - sum1

    cnt = [0] * 6
    for v in nums1:
        cnt[6 - v] += 1
    for v in nums2:
        cnt[v - 1] += 1

    ops = 0
    for g in range(5, 0, -1):
        if diff <= 0:
            break
        if cnt[g] == 0:
            continue
        need = (diff + g - 1) // g
        use = cnt[g] if cnt[g] < need else need
        diff -= use * g
        ops += use

    return -1 if diff > 0 else ops

