def countRestrictedPaths(n: int, edges: List[List[int]]) -> int:
    adj = [[] for _ in range(n + 1)]
    for u, v, w in edges:
        adj[u].append((v, w))
        adj[v].append((u, w))

    # Dijkstra from node n
    dist = [float('inf')] * (n + 1)
    dist[n] = 0
    heap = [(0, n)]
    while heap:
        d, u = heapq.heappop(heap)
        if d != dist[u]:
            continue
        for v, w in adj[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(heap, (nd, v))

    sys.setrecursionlimit(10**6)
    memo = {}

    def dfs(u: int) -> int:
        if u == n:
            return 1
        if u in memo:
            return memo[u]
        total = 0
        for v, _ in adj[u]:
            if dist[v] < dist[u]:
                total = (total + dfs(v)) % MOD
        memo[u] = total
        return total

    return dfs(1)

