def min_operations(nums: List[int], k: int) -> int:
    n = len(nums)
    # If segment length k is greater than or equal to array length,
    # we only need the XOR of the whole array to be zero.
    if k >= n:
        return 0 if (0 ^ sum(nums)) == 0 else 1  # XOR of whole array

    m = k  # period length
    classes: List[List[int]] = [[] for _ in range(m)]
    for i, v in enumerate(nums):
        classes[i % m].append(v)

    INF = 10 ** 9
    dp = [INF] * 1024
    dp[0] = 0

    for cls in classes:
        size = len(cls)
        freq = {}
        for v in cls:
            freq[v] = freq.get(v, 0) + 1

        global_min = min(dp)
        dp_next = [INF] * 1024
        for x in range(1024):
            best = global_min
            for v, f in freq.items():
                cand = dp[x ^ v] - f
                if cand < best:
                    best = cand
            dp_next[x] = size + best
        dp = dp_next

    return dp[0]

