def max_average_ratio(classes: List[Tuple[int, int]], extra_students: int) -> float:
    def gain(p: int, t: int) -> float:
        return (p + 1) / (t + 1) - p / t

    heap: List[Tuple[float, int, int]] = []
    for p, t in classes:
        heapq.heappush(heap, (-gain(p, t), p, t))

    for _ in range(extra_students):
        _, p, t = heapq.heappop(heap)
        p += 1
        t += 1
        heapq.heappush(heap, (-gain(p, t), p, t))

    total = 0.0
    while heap:
        _, p, t = heapq.heappop(heap)
        total += p / t

    return round(total / len(classes), 5)  # TIME: O((n+extra_students) log n) SPACE: O(n)

