def maxScore(nums: List[int]) -> int:
    m = len(nums)
    # precompute gcd for all pairs
    gcd_mat = [[0] * m for _ in range(m)]
    for i in range(m):
        for j in range(i + 1, m):
            gcd_mat[i][j] = math.gcd(nums[i], nums[j])

    @lru_cache(None)
    def dp(mask: int) -> int:
        used = mask.bit_count()
        if used == m:
            return 0
        op = used // 2 + 1
        # find first unused index to reduce symmetric work
        for i in range(m):
            if not (mask >> i) & 1:
                break
        best = 0
        for j in range(i + 1, m):
            if not (mask >> j) & 1:
                new_mask = mask | (1 << i) | (1 << j)
                score = op * gcd_mat[i][j] + dp(new_mask)
                if score > best:
                    best = score
        return best

    return dp(0)

