def get_number_of_backlog_orders(orders):
    MOD = 10**9 + 7

    def heap_push(heap, node, cmp):
        heap.append(node)
        i = len(heap) - 1
        while i > 0:
            p = (i - 1) >> 1
            if cmp(heap[p], heap[i]):
                break
            heap[p], heap[i] = heap[i], heap[p]
            i = p

    def heap_pop(heap, cmp):
        top = heap[0]
        last = heap.pop()
        if heap:
            heap[0] = last
            i = 0
            while True:
                l = i * 2 + 1
                r = i * 2 + 2
                best = i
                if l < len(heap) and not cmp(heap[best], heap[l]):
                    best = l
                if r < len(heap) and not cmp(heap[best], heap[r]):
                    best = r
                if best == i:
                    break
                heap[i], heap[best] = heap[best], heap[i]
                i = best
        return top

    def heap_peek(heap):
        return heap[0]

    def heap_size(heap):
        return len(heap)

    buy_heap = []
    buy_cmp = lambda a, b: a['price'] >= b['price']

    sell_heap = []
    sell_cmp = lambda a, b: a['price'] <= b['price']

    for price, amount, typ in orders:
        if typ == 0:  # BUY
            while amount > 0 and heap_size(sell_heap) and heap_peek(sell_heap)['price'] <= price:
                sell = heap_peek(sell_heap)
                matched = amount if amount < sell['amount'] else sell['amount']
                amount -= matched
                sell['amount'] -= matched
                if sell['amount'] == 0:
                    heap_pop(sell_heap, sell_cmp)
            if amount > 0:
                heap_push(buy_heap, {'price': price, 'amount': amount}, buy_cmp)
        else:  # SELL
            while amount > 0 and heap_size(buy_heap) and heap_peek(buy_heap)['price'] >= price:
                buy = heap_peek(buy_heap)
                matched = amount if amount < buy['amount'] else buy['amount']
                amount -= matched
                buy['amount'] -= matched
                if buy['amount'] == 0:
                    heap_pop(buy_heap, buy_cmp)
            if amount > 0:
                heap_push(sell_heap, {'price': price, 'amount': amount}, sell_cmp)

    total = 0
    for node in buy_heap:
        total = (total + node['amount']) % MOD
    for node in sell_heap:
        total = (total + node['amount']) % MOD
    return total

