def max_value(n: int, index: int, max_sum: int) -> int:
    def side_sum(length: int, peak: int) -> int:
        if length <= peak:
            return length * (2 * peak - length + 1) // 2
        return peak * (peak + 1) // 2 + (length - peak)

    low, high = 1, max_sum
    while low < high:
        mid = (low + high + 1) // 2
        left = side_sum(index, mid - 1)
        right = side_sum(n - index - 1, mid - 1)
        total = left + right + mid
        if total <= max_sum:
            low = mid
        else:
            high = mid - 1
    return low

