def count_pairs(nums: List[int], low: int, high: int) -> int:
    def count_leq(bound: int) -> int:
        if bound < 0:
            return 0
        max_val = max(nums) if nums else 0
        max_bit = max(max_val, bound).bit_length()
        if max_bit == 0:
            max_bit = 1

        def new_node():
            return {'cnt': 0, 'child': [None, None]}

        root = new_node()

        def insert(num: int) -> None:
            node = root
            for i in range(max_bit - 1, -1, -1):
                bit = (num >> i) & 1
                if node['child'][bit] is None:
                    node['child'][bit] = new_node()
                node = node['child'][bit]
                node['cnt'] += 1

        def query(num: int) -> int:
            node = root
            total = 0
            for i in range(max_bit - 1, -1, -1):
                if node is None:
                    break
                bit_num = (num >> i) & 1
                bit_k = (bound >> i) & 1
                if bit_k == 1:
                    child = node['child'][bit_num]
                    if child is not None:
                        total += child['cnt']
                    node = node['child'][1 - bit_num]
                else:
                    node = node['child'][bit_num]
            if node is not None:
                total += node['cnt']
            return total

        ans = 0
        for num in nums:
            ans += query(num)
            insert(num)
        return ans

    return count_leq(high) - count_leq(low - 1)

