def max_happy_groups(batchSize: int, groups: List[int]) -> int:
    # Count groups that are already multiples of batchSize
    base_happy = 0
    remainder_counts = [0] * batchSize
    for g in groups:
        r = g % batchSize
        if r == 0:
            base_happy += 1
        else:
            remainder_counts[r] += 1

    # State: tuple of counts for remainders 1..batchSize-1
    initial_state: Tuple[int, ...] = tuple(remainder_counts[1:])

    @lru_cache(None)
    def dfs(state: Tuple[int, ...], cur_mod: int) -> int:
        if not any(state):
            return 0
        best = 0
        for r in range(1, batchSize):
            idx = r - 1
            if state[idx] == 0:
                continue
            # use one group with remainder r
            new_state = list(state)
            new_state[idx] -= 1
            new_state = tuple(new_state)
            new_mod = (cur_mod + r) % batchSize
            add = 1 if cur_mod == 0 else 0
            best = max(best, add + dfs(new_state, new_mod))
        return best

    return base_happy + dfs(initial_state, 0)

