    original_sum = 0
    max_gain = 0

    for i in range(n):
        diff = abs(nums1[i] - nums2[i])
        original_sum = (original_sum + diff) % MOD

        pos = lower_bound(sorted_vals, nums2[i])

        best = diff
        if pos < n:
            cand = abs(sorted_vals[pos] - nums2[i])
            if cand < best:
                best = cand
        if pos > 0:
            cand = abs(sorted_vals[pos - 1] - nums2[i])
            if cand < best:
                best = cand

        gain = diff - best
        if gain > max_gain:
            max_gain = gain

    return (original_sum - max_gain + MOD) % MOD

