def min_side_jumps(obstacles: List[int]) -> int:
    INF = 10 ** 9
    dp = [1, 0, 1]  # costs for lanes 1,2,3 at the current position
    n = len(obstacles) - 1

    for i in range(1, n + 1):
        blocked = obstacles[i] - 1
        if blocked >= 0:
            dp[blocked] = INF

        min_dp = min(dp)  # best cost among all lanes at this position
        for lane in range(3):
            if obstacles[i] == lane + 1:  # this lane is blocked now
                continue
            dp[lane] = min(dp[lane], 1 + min_dp)

    return min(dp)

