class Fenwick:
    def __init__(self, size: int):
        self.n = size
        self.cnt = [0] * (size + 1)
        self.sums = [0] * (size + 1)

    def _add(self, bit, idx, delta):
        while idx <= self.n:
            bit[idx] += delta
            idx += idx & -idx

    def update(self, idx: int, delta_cnt: int, delta_sum: int):
        self._add(self.cnt, idx, delta_cnt)
        self._add(self.sums, idx, delta_sum)

    def _prefix(self, bit, idx):
        res = 0
        while idx > 0:
            res += bit[idx]
            idx -= idx & -idx
        return res

    def prefix_cnt(self, idx: int) -> int:
        return self._prefix(self.cnt, idx)

    def prefix_sum(self, idx: int) -> int:
        return self._prefix(self.sums, idx)

    def find_kth(self, k: int) -> int:
        """return smallest idx such that prefix count >= k (k >= 1)"""
        idx = 0
        bitmask = 1 << (self.n.bit_length())
        while bitmask:
            nxt = idx + bitmask
            if nxt <= self.n and self.cnt[nxt] < k:
                k -= self.cnt[nxt]
                idx = nxt
            bitmask >>= 1
        return idx + 1

def solve() -> None:
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    it = iter(data)
    m_k = next(it).split()
    m = int(m_k[0])
    k = int(m_k[1])
    q = int(next(it))
    MAXV = 100000  # given constraint for num
    fenwick = Fenwick(MAXV)
    window = deque()
    total_sum = 0
    out_lines = []

    def sum_smallest(x: int) -> int:
        if x <= 0:
            return 0
        pos = fenwick.find_kth(x)
        cnt_before = fenwick.prefix_cnt(pos - 1)
        sum_before = fenwick.prefix_sum(pos - 1)
        remaining = x - cnt_before
        return sum_before + remaining * pos

    for _ in range(q):
        parts = next(it).split()
        if parts[0] == 'add':
            val = int(parts[1])
            window.append(val)
            fenwick.update(val, 1, val)
            total_sum += val
            if len(window) > m:
                old = window.popleft()
                fenwick.update(old, -1, -old)
                total_sum -= old
        else:  # calculate
            if len(window) < m:
                out_lines.append("-1")
            else:
                mid_sum = sum_smallest(m - k) - sum_smallest(k)
                avg = mid_sum // (m - 2 * k)
                out_lines.append(str(avg))

    sys.stdout.write("\n".join(out_lines))

