def get_order(tasks: List[List[int]]) -> List[int]:
    tasks_with_idx = [(t[0], t[1], i) for i, t in enumerate(tasks)]
    tasks_with_idx.sort(key=lambda x: x[0])

    heap: List[List[int]] = []

    def compare(a: List[int], b: List[int]) -> int:
        if a[0] != b[0]:
            return a[0] - b[0]
        return a[1] - b[1]

    def heap_push(node: List[int]) -> None:
        heap.append(node)
        i = len(heap) - 1
        while i > 0:
            p = (i - 1) >> 1
            if compare(heap[p], heap[i]) <= 0:
                break
            heap[p], heap[i] = heap[i], heap[p]
            i = p

    def heap_pop() -> List[int]:
        top = heap[0]
        last = heap.pop()
        if heap:
            heap[0] = last
            i = 0
            while True:
                l = i * 2 + 1
                r = i * 2 + 2
                smallest = i
                if l < len(heap) and compare(heap[l], heap[smallest]) < 0:
                    smallest = l
                if r < len(heap) and compare(heap[r], heap[smallest]) < 0:
                    smallest = r
                if smallest == i:
                    break
                heap[i], heap[smallest] = heap[smallest], heap[i]
                i = smallest
        return top

    result: List[int] = []
    time = 0
    i = 0
    n = len(tasks_with_idx)

    while len(result) < n:
        while i < n and tasks_with_idx[i][0] <= time:
            heap_push([tasks_with_idx[i][1], tasks_with_idx[i][2]])
            i += 1
        if heap:
            proc, idx = heap_pop()
            time += proc
            result.append(idx)
        else:
            time = tasks_with_idx[i][0]

    return result

