    from functools import lru_cache

    @lru_cache(None)
    def dfs(pos: int, prev: int) -> bool:
        if pos == n:
            return True
        expected = prev - 1
        if expected < 0:
            return False
        for end in range(pos + 1, n + 1):
            cur = int(s[pos:end])
            if cur == expected:
                if dfs(end, cur):
                    return True
            elif cur > expected:
                break
        return False

    for i in range(1, n):
        first = int(s[:i])
        if dfs(i, first):
            return True
    return False

