def min_interval(intervals: List[List[int]], queries: List[int]) -> List[int]:
    intervals.sort(key=lambda x: x[0])
    qs = [(v, i) for i, v in enumerate(queries)]
    qs.sort(key=lambda x: x[0])
    res = [-1] * len(queries)
    heap: List[dict] = []

    def push(node: dict) -> None:
        heap.append(node)
        cur = len(heap) - 1
        while cur > 0:
            parent = (cur - 1) >> 1
            if heap[parent]['size'] <= heap[cur]['size']:
                break
            heap[parent], heap[cur] = heap[cur], heap[parent]
            cur = parent

    def pop() -> dict:
        top = heap[0]
        last = heap.pop()
        if heap:
            heap[0] = last
            cur = 0
            while True:
                left = cur * 2 + 1
                right = left + 1
                if left >= len(heap):
                    break
                smallest = left
                if right < len(heap) and heap[right]['size'] < heap[left]['size']:
                    smallest = right
                if heap[cur]['size'] <= heap[smallest]['size']:
                    break
                heap[cur], heap[smallest] = heap[smallest], heap[cur]
                cur = smallest
        return top

    def peek() -> dict:
        return heap[0]

    i = 0
    for q, idx in qs:
        while i < len(intervals) and intervals[i][0] <= q:
            left, right = intervals[i]
            push({'size': right - left + 1, 'right': right})
            i += 1
        while heap and peek()['right'] < q:
            pop()
        if heap:
            res[idx] = peek()['size']
    return res

