def rotate_the_box(box_grid: List[List[str]]) -> List[List[str]]:
    m = len(box_grid)
    n = len(box_grid[0])

    for i in range(m):
        empty_pos = n - 1
        for j in range(n - 1, -1, -1):
            cell = box_grid[i][j]
            if cell == '*':
                empty_pos = j - 1
            elif cell == '#':
                if empty_pos != j:
                    box_grid[i][empty_pos] = '#'
                    box_grid[i][j] = '.'
                empty_pos -= 1

    rotated = [[None] * m for _ in range(n)]
