    max_val = 0
    for v in nums:
        if v > max_val:
            max_val = v
    cnt = [0] * (max_val + 1)
    for v in nums:
        cnt[v] += 1
    pref = [0] * (max_val + 1)
    for i in range(1, max_val + 1):
        pref[i] = pref[i - 1] + cnt[i]
    answer = 0
    for d in range(1, max_val + 1):
        if cnt[d] == 0:
            continue
        freq_den = cnt[d]
        max_k = max_val // d
        for k in range(1, max_k + 1):
            left = k * d
            right = (k + 1) * d - 1
            if right > max_val:
                right = max_val
            range_count = pref[right] - pref[left - 1]
            if range_count == 0:
                continue
            answer += freq_den * k * range_count
    return answer

