def min_skips(dist: List[int], speed: int, hours_before: int) -> int:
    n = len(dist)
    INF = float('inf')
    dp = [INF] * (n + 1)
    dp[0] = 0.0

    for i in range(n - 1):
        travel = dist[i] / speed
        ndp = [INF] * (n + 1)
        for k in range(n):
            cur = dp[k]
            if cur == INF:
                continue
            # not skip: wait until next integer hour
            t_wait = math.ceil(cur + travel - 1e-9)
            if t_wait < ndp[k]:
                ndp[k] = t_wait
            # skip: no waiting
            t_skip = cur + travel
            if t_skip < ndp[k + 1]:
                ndp[k + 1] = t_skip
        dp = ndp

    # last road, no waiting after it
    travel = dist[-1] / speed
    for k in range(n + 1):
        if dp[k] != INF:
            dp[k] += travel

    for k in range(n + 1):
        if dp[k] <= hours_before + 1e-9:
            return k
    return -1

