def minimum_xor_sum(nums1: List[int], nums2: List[int]) -> int:
    n = len(nums1)
    total_mask = 1 << n
    dp = [float('inf')] * total_mask
    dp[0] = 0

    def popcount(x: int) -> int:
        cnt = 0
        while x:
            x &= x - 1
            cnt += 1
        return cnt

    for mask in range(1, total_mask):
        i = popcount(mask) - 1
        for j in range(n):
            if mask & (1 << j):
                prev = mask ^ (1 << j)
                candidate = dp[prev] + (nums1[i] ^ nums2[j])
                if candidate < dp[mask]:
                    dp[mask] = candidate
    return dp[total_mask - 1]

