    m = 2 * n
    diff0 = [0] * m
    diff1 = [0] * m
    for i, ch in enumerate(s2):
        expected0 = '0' if i % 2 == 0 else '1'
        expected1 = '1' if i % 2 == 0 else '0'
        diff0[i] = 1 if ch != expected0 else 0
        diff1[i] = 1 if ch != expected1 else 0

    def min_window(arr):
        cur = sum(arr[:n])
        best = cur
        for i in range(n, m):
            cur += arr[i] - arr[i - n]
            if cur < best:
                best = cur
        return best

    return min(min_window(diff0), min_window(diff1))

