import math

def min_wasted_space(packages: List[int], boxes: List[List[int]]) -> int:
    MOD = 1_000_000_007
    packages.sort()
    n = len(packages)
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + packages[i]

    def upper_bound(arr: List[int], target: int) -> int:
        lo, hi = 0, len(arr)
        while lo < hi:
            mid = (lo + hi) // 2
            if arr[mid] <= target:
                lo = mid + 1
            else:
                hi = mid
        return lo

    best = math.inf

    for supplier in boxes:
        supplier.sort()
        if supplier[-1] < packages[-1]:
            continue
        waste = 0
        prev_idx = 0
        for size in supplier:
            idx = upper_bound(packages, size)
            cnt = idx - prev_idx
            if cnt > 0:
                waste += size * cnt - (prefix[idx] - prefix[prev_idx])
            prev_idx = idx
            if prev_idx == n:
                break
        if prev_idx == n:
            best = min(best, waste)

    return -1 if best is math.inf else best % MOD

def can_be_rotated(mat: list[list[int]], target: list[list[int]]) -> bool:
    n = len(mat)

    def equal(a, b):
        for i in range(n):
            for j in range(n):
                if a[i][j] != b[i][j]:
                    return False
        return True

    def rotate(a):
        res = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                res[j][n - 1 - i] = a[i][j]
        return res

    cur = mat
    for _ in range(4):
        if equal(cur, target):
            return True
        cur = rotate(cur)
    return False

