def largest_magic_square(grid: List[List[int]]) -> int:
    m = len(grid)
    n = len(grid[0])
    # Row prefix sums
    row_prefix = [[0] * (n + 1) for _ in range(m)]
    for i in range(m):
        for j in range(n):
            row_prefix[i][j + 1] = row_prefix[i][j] + grid[i][j]
    # Column prefix sums
    col_prefix = [[0] * n for _ in range(m + 1)]
    for j in range(n):
        for i in range(m):
            col_prefix[i + 1][j] = col_prefix[i][j] + grid[i][j]

    max_k = min(m, n)
    for k in range(max_k, 0, -1):
        for i in range(m - k + 1):
            for j in range(n - k + 1):
                target = row_prefix[i][j + k] - row_prefix[i][j]
                ok = True
                # check rows
                for r in range(i, i + k):
                    if row_prefix[r][j + k] - row_prefix[r][j] != target:
                        ok = False
                        break
                if not ok:
                    continue
                # check columns
                for c in range(j, j + k):
                    if col_prefix[i + k][c] - col_prefix[i][c] != target:
                        ok = False
                        break
                if not ok:
                    continue
                # main diagonal
                diag_sum = 0
                for d in range(k):
                    diag_sum += grid[i + d][j + d]
                if diag_sum != target:
                    continue
                # anti-diagonal
                anti_sum = 0
                for d in range(k):
                    anti_sum += grid[i + d][j + k - 1 - d]
                if anti_sum != target:
                    continue
                return k
    return 1

