def earliest_latest_round(n: int, firstPlayer: int, secondPlayer: int) -> List[int]:
    specials = {firstPlayer, secondPlayer}
    min_round = float('inf')
    max_round = 0

    def dfs(players: List[int], round_num: int) -> None:
        nonlocal min_round, max_round
        m = len(players)
        # check if they meet this round
        for i in range(m // 2):
            a = players[i]
            b = players[m - 1 - i]
            if (a == firstPlayer and b == secondPlayer) or (a == secondPlayer and b == firstPlayer):
                if round_num < min_round:
                    min_round = round_num
                if round_num > max_round:
                    max_round = round_num
                return

        # generate all possible winner sets for next round
        pairs = [(players[i], players[m - 1 - i]) for i in range(m // 2)]
        middle = players[m // 2] if m % 2 == 1 else None

        def backtrack(idx: int, cur: List[int]) -> None:
            if idx == len(pairs):
                nxt = cur[:]
                if middle is not None:
                    nxt.append(middle)
                nxt.sort()
                dfs(nxt, round_num + 1)
                return
            a, b = pairs[idx]
            if a in specials:
                backtrack(idx + 1, cur + [a])
            elif b in specials:
                backtrack(idx + 1, cur + [b])
            else:
                backtrack(idx + 1, cur + [a])
                backtrack(idx + 1, cur + [b])

        backtrack(0, [])

    initial_players = list(range(1, n + 1))
    dfs(initial_players, 1)
    return [min_round, max_round]

