    def dfs(r: int, c: int) -> bool:
        if r < 0 or r >= rows or c < 0 or c >= cols or grid2[r][c] == 0:
            return True
        grid2[r][c] = 0
        is_sub = grid1[r][c] == 1
        up = dfs(r - 1, c)
        down = dfs(r + 1, c)
        left = dfs(r, c - 1)
        right = dfs(r, c + 1)
