class MovieRentingSystem:
    def __init__(self, n: int, entries: List[List[int]]):
        self.price: Dict[Tuple[int, int], int] = {}
        self.available: Dict[int, List[Tuple[int, int]]] = {}
        self.rented_heap: List[Tuple[int, int, int]] = []
        self.rented_set: Set[Tuple[int, int]] = set()
        for shop, movie, price in entries:
            self.price[(shop, movie)] = price
            if movie not in self.available:
                self.available[movie] = []
            heapq.heappush(self.available[movie], (price, shop))

    def search(self, movie: int) -> List[int]:
        if movie not in self.available:
            return []
        heap = self.available[movie]
        result: List[int] = []
        temp: List[Tuple[int, int]] = []
        while heap and len(result) < 5:
            price, shop = heapq.heappop(heap)
            if (shop, movie) in self.rented_set:
                continue
            result.append(shop)
            temp.append((price, shop))
        for item in temp:
            heapq.heappush(heap, item)
        return result

    def rent(self, shop: int, movie: int) -> None:
        self.rented_set.add((shop, movie))
        price = self.price[(shop, movie)]
        heapq.heappush(self.rented_heap, (price, shop, movie))

    def drop(self, shop: int, movie: int) -> None:
        self.rented_set.discard((shop, movie))
        price = self.price[(shop, movie)]
        heapq.heappush(self.available[movie], (price, shop))

    def report(self) -> List[List[int]]:
        result: List[List[int]] = []
        temp: List[Tuple[int, int, int]] = []
        while self.rented_heap and len(result) < 5:
            price, shop, movie = heapq.heappop(self.rented_heap)
            if (shop, movie) not in self.rented_set:
                continue
            result.append([shop, movie])
            temp.append((price, shop, movie))
        for item in temp:
            heapq.heappush(self.rented_heap, item)
        return result

