def longest_common_subpath(n: int, paths: List[List[int]]) -> int:
    if not paths:
        return 0
    min_len = min(len(p) for p in paths)
    if min_len == 0:
        return 0

    base = random.randint(100000, 1000000)
    mod1 = 10**9 + 7
    mod2 = 10**9 + 9

    pow1 = [1] * (min_len + 1)
    pow2 = [1] * (min_len + 1)
    for i in range(1, min_len + 1):
        pow1[i] = (pow1[i - 1] * base) % mod1
        pow2[i] = (pow2[i - 1] * base) % mod2

    prefixes = []
    for p in paths:
        pre1 = [0] * (len(p) + 1)
        pre2 = [0] * (len(p) + 1)
        for i, v in enumerate(p):
            x = v + 1  # shift to avoid zero issues
            pre1[i + 1] = (pre1[i] * base + x) % mod1
            pre2[i + 1] = (pre2[i] * base + x) % mod2
        prefixes.append((pre1, pre2))

    def exists_common(L: int) -> bool:
        if L == 0:
            return True
        common_hashes = None
        for pre1, pre2 in prefixes:
            length = len(pre1) - 1
            if length < L:
                return False
            cur_set = set()
            for i in range(length - L + 1):
                h1 = (pre1[i + L] - pre1[i] * pow1[L]) % mod1
                h2 = (pre2[i + L] - pre2[i] * pow2[L]) % mod2
                cur_set.add((h1, h2))
            if common_hashes is None:
                common_hashes = cur_set
                if not common_hashes:
                    return False
            else:
                common_hashes &= cur_set
                if not common_hashes:
                    return False
        return bool(common_hashes)

    lo, hi = 0, min_len
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if exists_common(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo

