def can_merge(trees):
    root_map = {}
    leaf_vals = set()
    for t in trees:
        root_map[t.val] = t
        if t.left:
            leaf_vals.add(t.left.val)
        if t.right:
            leaf_vals.add(t.right.val)
    candidates = [v for v in root_map if v not in leaf_vals]
    if len(candidates) != 1:
        return None
    root_val = candidates[0]
    root = root_map.pop(root_val)

    def merge(node, low, high):
        if not node:
            return None
        if not (low < node.val < high):
            raise ValueError
        if node.left is None and node.right is None and node.val in root_map:
            new_root = root_map.pop(node.val)
            node = new_root
        node.left = merge(node.left, low, node.val)
        node.right = merge(node.right, node.val, high)
        return node

    try:
        root = merge(root, float('-inf'), float('inf'))
    except ValueError:
        return None
    if root_map:
        return None
    return root

def min_cost(max_time, edges, passing_fees):
    n = len(passing_fees)
    adj = [[] for _ in range(n)]
    for u, v, t in edges:
        adj[u].append((v, t))
        adj[v].append((u, t))
    INF = 2**63 - 1
    best = [[INF] * (max_time + 1) for _ in range(n)]
    best[0][0] = passing_fees[0]
    import heapq
    heap = [(passing_fees[0], 0, 0)]
    while heap:
        cost, city, time = heapq.heappop(heap)
        if cost != best[city][time]:
            continue
        if city == n - 1:
            return cost
        for nxt, road_time in adj[city]:
            new_time = time + road_time
            if new_time > max_time:
                continue
            new_cost = cost + passing_fees[nxt]
            if new_cost < best[nxt][new_time]:
                best[nxt][new_time] = new_cost
                heapq.heappush(heap, (new_cost, nxt, new_time))
    answer = INF
    for t in range(max_time + 1):
        if best[n - 1][t] < answer:
            answer = best[n - 1][t]
    return -1 if answer == INF else answer

