MOD = 10**9 + 7

def solve(m: int, n: int) -> int:
    # generate all column patterns where adjacent cells differ vertically
    patterns: List[Tuple[int, ...]] = []
    def generate(col: List[int], row: int) -> None:
        if row == m:
            patterns.append(tuple(col))
            return
        for color in range(3):
            if row == 0 or color != col[row - 1]:
                col.append(color)
                generate(col, row + 1)
                col.pop()
    generate([], 0)

    s = len(patterns)

    # pre‑compute compatibility between patterns (no horizontal equal colors)
    compat: List[List[int]] = [[] for _ in range(s)]
    for i, a in enumerate(patterns):
        for j, b in enumerate(patterns):
            ok = True
            for k in range(m):
                if a[k] == b[k]:
                    ok = False
                    break
            if ok:
                compat[i].append(j)

    # DP over columns
    dp = [1] * s  # first column
    for _ in range(1, n):
        ndp = [0] * s
        for i, val in enumerate(dp):
            if val:
                for j in compat[i]:
                    ndp[j] = (ndp[j] + val) % MOD
        dp = ndp

    return sum(dp) % MOD

