class _TrieNode:
    __slots__ = ("child", "cnt")
    def __init__(self):
        self.child = [None, None]
        self.cnt = 0

class _BinaryTrie:
    def __init__(self, max_bit: int = 20):
        self.root = _TrieNode()
        self.max_bit = max_bit

    def insert(self, num: int, delta: int) -> None:
        node = self.root
        for b in range(self.max_bit - 1, -1, -1):
            bit = (num >> b) & 1
            if node.child[bit] is None:
                node.child[bit] = _TrieNode()
            node = node.child[bit]
            node.cnt += delta

    def max_xor(self, num: int) -> int:
        node = self.root
        ans = 0
        for b in range(self.max_bit - 1, -1, -1):
            bit = (num >> b) & 1
            togg = 1 - bit
            if node.child[togg] is not None and node.child[togg].cnt > 0:
                ans |= (1 << b)
                node = node.child[togg]
            else:
                node = node.child[bit]
        return ans

def maxGeneticDifference(parents: List[int], queries: List[List[int]]) -> List[int]:
    n = len(parents)
    children = [[] for _ in range(n)]
    root = -1
    for i, p in enumerate(parents):
        if p == -1:
            root = i
        else:
            children[p].append(i)

    q_by_node = [[] for _ in range(n)]
    for idx, (node, val) in enumerate(queries):
        q_by_node[node].append((idx, val))

    answers = [0] * len(queries)
    trie = _BinaryTrie()

    def dfs(u: int) -> None:
        trie.insert(u, 1)
        for idx, val in q_by_node[u]:
            answers[idx] = trie.max_xor(val)
        for v in children[u]:
            dfs(v)
        trie.insert(u, -1)

    dfs(root)
    return answers

