def smallest_chair(times, target_friend):
    n = len(times)
    events = []
    for idx, (arrival, leave) in enumerate(times):
        events.append((arrival, 0, idx))
        events.append((leave, 1, idx))
    events.sort(key=lambda x: (x[0], x[1]))
    import heapq
    available = []
    occupied = {}
    next_chair = 0
    for time, typ, idx in events:
        if typ == 0:
            if available:
                chair = heapq.heappop(available)
            else:
                chair = next_chair
                next_chair += 1
            occupied[idx] = chair
            if idx == target_friend:
                return chair
        else:
            chair = occupied.pop(idx)
            heapq.heappush(available, chair)

def sum_of_digits_after_convert(s: str, k: int) -> int:
    total = 0
    for ch in s:
        val = ord(ch) - 96
        if val >= 10:
            total += val // 10 + (val % 10)
        else:
            total += val
    for _ in range(1, k):
        sum_ = 0
        while total > 0:
            sum_ += total % 10
            total //= 10
        total = sum_
    return total

def maximum_compatibility_sum(students, mentors):
    m = len(students)
    n = len(students[0])
    score = [[0] * m for _ in range(m)]
    for i in range(m):
        for j in range(m):
            same = 0
            for k in range(n):
                if students[i][k] == mentors[j][k]:
                    same += 1
            score[i][j] = same
    total_masks = 1 << m
    dp = [float('-inf')] * total_masks
    dp[0] = 0
    for mask in range(total_masks):
        student_idx = mask.bit_count()
        if student_idx >= m:
            continue
        for mentor in range(m):
            if (mask & (1 << mentor)) == 0:
                new_mask = mask | (1 << mentor)
                cand = dp[mask] + score[student_idx][mentor]
                if cand > dp[new_mask]:
                    dp[new_mask] = cand
    return int(dp[total_masks - 1])

from typing import List, Dict

def delete_duplicate_folder(paths: List[List[str]]) -> List[List[str]]:
    class Node:
        __slots__ = ("name", "children", "serial", "delete")
        def __init__(self, name: str):
            self.name: str = name
            self.children: Dict[str, Node] = {}
            self.serial: str = ""
            self.delete: bool = False

    root = Node("")

    # Build trie preserving insertion order
    for p in paths:
        cur = root
        for name in p:
            if name not in cur.children:
                cur.children[name] = Node(name)
            cur = cur.children[name]

    counter: Dict[str, int] = {}

    # Post‑order serialization
    def dfs(node: Node) -> None:
        for child in node.children.values():
            dfs(child)
        parts = [child.name + child.serial for child in node.children.values()]
        parts.sort()
        node.serial = "(" + "".join(parts) + ")"
        if node.serial != "()":
            counter[node.serial] = counter.get(node.serial, 0) + 1

    dfs(root)

    # Mark duplicate subtrees for deletion
    def mark(node: Node) -> None:
        if node.serial != "()" and counter.get(node.serial, 0) > 1:
            node.delete = True
            return
        for child in node.children.values():
            mark(child)

    mark(root)

    # Collect remaining paths respecting descending lexical order of folder names
    ans: List[List[str]] = []

    def collect(node: Node, path: List[str]) -> None:
        for name in sorted(node.children.keys(), reverse=True):
            child = node.children[name]
            if child.delete:
                continue
            new_path = path + [child.name]
            ans.append(new_path)
            collect(child, new_path)

    collect(root, [])
    return ans

