def can_see_persons_count(heights: List[int]) -> List[int]:
    n = len(heights)
    answer = [0] * n
    stack = []
    for i in range(n - 1, -1, -1):
        while stack and heights[i] > heights[stack[-1]]:
            stack.pop()
            answer[i] += 1
        if stack:
            answer[i] += 1
        stack.append(i)
    return answer

import math

def has_three_divisors(n: int) -> bool:
    if n < 4:
        return False
    root = int(math.sqrt(n))
    if root * root != n:
        return False
    if root < 2:
        return False
    i = 2
    while i * i <= root:
        if root % i == 0:
            return False
        i += 1
    return True

def largest_number(num: str, change: list[int]) -> str:
