    i = 0
    n = len(digits)
    while i < n and change[int(digits[i])] <= int(digits[i]):
        i += 1
    while i < n and change[int(digits[i])] >= int(digits[i]):
        digits[i] = str(change[int(digits[i])])
        i += 1
    return ''.join(digits)

