def count_special_subsequences(nums: List[int]) -> int:
    MOD = 10**9 + 7
    cnt0 = cnt1 = cnt2 = 0
    for x in nums:
        if x == 0:
            cnt0 = (cnt0 * 2 + 1) % MOD
        elif x == 1:
            cnt1 = (cnt1 * 2 + cnt0) % MOD
        elif x == 2:
            cnt2 = (cnt2 * 2 + cnt1) % MOD
    return cnt2 % MOD

