def min_perimeter(needed_apples: int) -> int:
    def total(k: int) -> int:
        return 2 * k * (k + 1) * (2 * k + 1)

    lo = 0
    hi = 1
    while total(hi) < needed_apples:
        hi <<= 1

    while lo < hi:
        mid = (lo + hi) // 2
        if total(mid) >= needed_apples:
            hi = mid
        else:
            lo = mid + 1
    return 8 * lo

