def min_total_waste(nums: List[int], k: int) -> int:
    n = len(nums)
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + nums[i]

    # cost[l][r]: waste if a single size is used for interval [l, r]
    cost = [[0] * n for _ in range(n)]
    for l in range(n):
        cur_max = 0
        for r in range(l, n):
            cur_max = max(cur_max, nums[r])
            total = cur_max * (r - l + 1) - (prefix[r + 1] - prefix[l])
            cost[l][r] = total

    max_segments = k + 1
    INF = 10 ** 18
    dp = [[INF] * (max_segments + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(1, n + 1):
        for seg in range(1, max_segments + 1):
            best = INF
            # previous split point p, segment [p, i-1]
            for p in range(seg - 1, i):
                val = dp[p][seg - 1] + cost[p][i - 1]
                if val < best:
                    best = val
            dp[i][seg] = best

    answer = INF
    for seg in range(1, max_segments + 1):
        if dp[n][seg] < answer:
            answer = dp[n][seg]
    return answer

