def min_stone_sum(piles: List[int], k: int) -> int:
    max_heap = [-x for x in piles]
    heapq.heapify(max_heap)
    for _ in range(k):
        largest = -heapq.heappop(max_heap)
        remaining = largest - largest // 2
        heapq.heappush(max_heap, -remaining)
    return -sum(max_heap)

