def min_swaps(s: str) -> int:
    balance = 0
    imbalance = 0
    for ch in s:
        if ch == '[':
            balance += 1
        else:  # ch == ']'
            balance -= 1
        if balance < 0:
            imbalance += 1
            balance = 0
    return (imbalance + 1) // 2

