    ans = [0] * n
    tails: List[int] = []
    for i in range(n):
        v = obstacles[i]
        l, r = 0, len(tails)
        while l < r:
            m = (l + r) >> 1
            if tails[m] > v:
                r = m
            else:
                l = m + 1
        pos = l
        ans[i] = pos + 1
        if pos == len(tails):
            tails.append(v)
        else:
            tails[pos] = v
    return ans

