import sys

def max_product(s: str) -> int:
    n = len(s)
    d1 = [0] * n
    l = 0
    r = -1
    for i in range(n):
        k = 1 if i > r else min(d1[l + r - i], r - i + 1)
        while i - k >= 0 and i + k < n and s[i - k] == s[i + k]:
            k += 1
        d1[i] = k
        if i + k - 1 > r:
            l = i - k + 1
            r = i + k - 1

    left_max = [0] * n
    right_max = [0] * n
    for i in range(n):
        length = 2 * d1[i] - 1
        start = i - d1[i] + 1
        end = i + d1[i] - 1
        if length > left_max[end]:
            left_max[end] = length
        if length > right_max[start]:
            right_max[start] = length

    left_best = [0] * n
    cur = 0
    for i in range(n):
        if left_max[i] > cur:
            cur = left_max[i]
        left_best[i] = cur

    right_best = [0] * n
    cur = 0
    for i in range(n - 1, -1, -1):
        if right_max[i] > cur:
            cur = right_max[i]
        right_best[i] = cur

    ans = 0
    for i in range(n - 1):
        prod = left_best[i] * right_best[i + 1]
        if prod > ans:
            ans = prod
    return ans

def solve() -> None:
    data = sys.stdin.read().split()
