from collections import deque

def latest_day_to_cross(row: int, col: int, cells: List[List[int]]) -> int:
    left, right, answer = 0, len(cells), 0
    while left <= right:
        mid = (left + right) // 2
        grid = [[0] * col for _ in range(row)]
        for i in range(mid):
            r, c = cells[i]
            grid[r - 1][c - 1] = 1
        queue = deque()
        visited = [[False] * col for _ in range(row)]
        for c in range(col):
            if grid[0][c] == 0:
                queue.append((0, c))
                visited[0][c] = True
        can_cross = False
        dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]
        while queue:
            r, c = queue.popleft()
            if r == row - 1:
                can_cross = True
                break
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if 0 <= nr < row and 0 <= nc < col and not visited[nr][nc] and grid[nr][nc] == 0:
                    visited[nr][nc] = True
                    queue.append((nr, nc))
        if can_cross:
            answer = mid
            left = mid + 1
        else:
            right = mid - 1
    return answer

