def rearrange_array(nums: List[int]) -> List[int]:
    # Try descending order first
    desc = sorted(nums, reverse=True)

    def has_bad_average(arr: List[int]) -> bool:
        for i in range(1, len(arr) - 1):
            if (arr[i - 1] + arr[i + 1]) % 2 == 0:
                if arr[i] == (arr[i - 1] + arr[i + 1]) // 2:
                    return True
        return False

    if not has_bad_average(desc):
        return desc

    # Fallback: ascending order with the median element moved to the end
    asc = sorted(nums)
    n = len(asc)
    median = asc[n // 2]
    result = asc[: n // 2] + asc[n // 2 + 1 :] + [median]
    return result

