def valid_path(n: int, edges: List[List[int]], source: int, destination: int) -> bool:
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    visited = [False] * n
    queue = [source]
    visited[source] = True

    while queue:
        node = queue.pop(0)
        if node == destination:
            return True
        for nb in adj[node]:
            if not visited[nb]:
                visited[nb] = True
                queue.append(nb)
    return False

