def number_of_ways(n: int, roads: List[Tuple[int, int, int]]) -> int:
    MOD = 1000000007

    adj: List[List[Tuple[int, int]]] = [[] for _ in range(n)]
    for u, v, w in roads:
        adj[u].append((v, w))
        adj[v].append((u, w))

    dist = [float('inf')] * n
    ways = [0] * n
    dist[0] = 0
    ways[0] = 1

    heap: List[Tuple[int, int]] = []

    def heap_push(item: Tuple[int, int]) -> None:
        heap.append(item)
        i = len(heap) - 1
        while i > 0:
            p = (i - 1) >> 1
            if heap[p][0] <= heap[i][0]:
                break
            heap[p], heap[i] = heap[i], heap[p]
            i = p

    def heap_pop() -> Tuple[int, int] | None:
        if not heap:
            return None
        top = heap[0]
        last = heap.pop()
        if heap:
            heap[0] = last
            i = 0
            while True:
                l = i * 2 + 1
                r = i * 2 + 2
                smallest = i
                if l < len(heap) and heap[l][0] < heap[smallest][0]:
                    smallest = l
                if r < len(heap) and heap[r][0] < heap[smallest][0]:
                    smallest = r
                if smallest == i:
                    break
                heap[i], heap[smallest] = heap[smallest], heap[i]
                i = smallest
        return top

    heap_push((0, 0))

    while heap:
        d_u = heap_pop()
        if d_u is None:
            break
        d, u = d_u
        if d != dist[u]:
            continue
        for v, w in adj[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                ways[v] = ways[u]
                heap_push((nd, v))
            elif nd == dist[v]:
                ways[v] = (ways[v] + ways[u]) % MOD

    return ways[n - 1] % MOD

