def find_gcd(nums: List[int]) -> int:
    min_val = nums[0]
    max_val = nums[0]
    for i in range(1, len(nums)):
        if nums[i] < min_val:
            min_val = nums[i]
        if nums[i] > max_val:
            max_val = nums[i]
    a = min_val
    b = max_val
    while b != 0:
        temp = b
        b = a % b
        a = temp
    return a

