def min_absolute_difference(mat: List[List[int]], target: int) -> int:
    if not mat:
        return abs(target)
    max_sum = sum(max(row) for row in mat)
    dp = [False] * (max_sum + 1)
    for v in mat[0]:
        if v <= max_sum:
            dp[v] = True
    for row in mat[1:]:
        new_dp = [False] * (max_sum + 1)
        for s, reachable in enumerate(dp):
            if reachable:
                for v in row:
                    ns = s + v
                    if ns <= max_sum:
                        new_dp[ns] = True
        dp = new_dp
    best = float('inf')
    for s, reachable in enumerate(dp):
        if reachable:
            diff = abs(target - s)
            if diff < best:
                best = diff
                if best == 0:
                    break
    return best

