def recover_array(n: int, sums: List[int]) -> List[int]:
    sums = sorted(sums)
    ans = []
    cur = sums
    for _ in range(n):
        diff = cur[1] - cur[0]
        cnt = Counter(cur)
        left_list = []
        right_list = []
        for x in cur:
            if cnt[x] <= 0:
                continue
            if cnt.get(x + diff, 0) > 0:
                cnt[x] -= 1
                cnt[x + diff] -= 1
                left_list.append(x)
                right_list.append(x + diff)
        if 0 in left_list:
            ans.append(diff)
            cur = left_list
        else:
            ans.append(-diff)
            cur = right_list
    return ans

def all_subset_sums(arr):
    n = len(arr)
    res = []
    for mask in range(1 << n):
        s = 0
        for i in range(n):
            if mask & (1 << i):
                s += arr[i]
        res.append(s)
    return sorted(res)

