def min_sessions(tasks: List[int], session_time: int) -> int:
    n = len(tasks)
    total_mask = 1 << n
    dp = [None] * total_mask
    dp[0] = {'sessions': 1, 'cur': 0}
    for mask in range(1, total_mask):
        dp[mask] = {'sessions': n + 1, 'cur': 0}
        for i in range(n):
            if mask & (1 << i):
                prev = mask ^ (1 << i)
                prev_state = dp[prev]
                sessions = prev_state['sessions']
                cur = prev_state['cur'] + tasks[i]
                if cur > session_time:
                    sessions += 1
                    cur = tasks[i]
                if sessions < dp[mask]['sessions'] or (sessions == dp[mask]['sessions'] and cur < dp[mask]['cur']):
                    dp[mask] = {'sessions': sessions, 'cur': cur}
    return dp[total_mask - 1]['sessions']

