def minimum_difference(nums: List[int], k: int) -> int:
    if k <= 1:
        return 0
    nums.sort()
    best = float('inf')
    last_start = len(nums) - k
    for start in range(last_start + 1):
        diff = nums[start + k - 1] - nums[start]
        if diff < best:
            best = diff
    return best

