def locking_tree(parent):
    n = len(parent)
    children = [[] for _ in range(n)]
    for i in range(1, n):
        children[parent[i]].append(i)
    locked_by = [-1] * n

    def lock(node, user):
        if locked_by[node] != -1:
            return False
        locked_by[node] = user
        return True

    def unlock(node, user):
        if locked_by[node] != user:
            return False
        locked_by[node] = -1
        return True

    def upgrade(node, user):
        if locked_by[node] != -1:
            return False
        cur = parent[node]
        while cur != -1:
            if locked_by[cur] != -1:
                return False
            cur = parent[cur]
        stack = [node]
        locked_descendants = []
        while stack:
            cur = stack.pop()
            for child in children[cur]:
                if locked_by[child] != -1:
                    locked_descendants.append(child)
                stack.append(child)
        if not locked_descendants:
            return False
        for d in locked_descendants:
            locked_by[d] = -1
        locked_by[node] = user
        return True

    return {"lock": lock, "unlock": unlock, "upgrade": upgrade}

