class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x):
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, a, b):
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return
        if self.rank[ra] < self.rank[rb]:
            self.parent[ra] = rb
        elif self.rank[ra] > self.rank[rb]:
            self.parent[rb] = ra
        else:
            self.parent[rb] = ra
            self.rank[ra] += 1

def can_sort(nums):
    n = len(nums)
    if n <= 1:
        return True
    max_val = max(nums)
    spf = list(range(max_val + 1))
    for i in range(2, int(max_val ** 0.5) + 1):
        if spf[i] == i:
            step = i
            start = i * i
            for j in range(start, max_val + 1, step):
                if spf[j] == j:
                    spf[j] = i

    def prime_factors(x):
        factors = []
        while x > 1:
            p = spf[x]
            factors.append(p)
            while x % p == 0:
                x //= p
        return factors

    dsu = DSU(n)
    factor_to_index = {}
    for i, val in enumerate(nums):
        for p in set(prime_factors(val)):
            if p in factor_to_index:
                dsu.union(i, factor_to_index[p])
            else:
                factor_to_index[p] = i

    sorted_nums = sorted(nums)
    comp_vals = defaultdict(list)
    comp_target = defaultdict(list)
    for i in range(n):
        root = dsu.find(i)
        comp_vals[root].append(nums[i])
        comp_target[root].append(sorted_nums[i])

    for root in comp_vals:
        comp_vals[root].sort()
        comp_target[root].sort()
        if comp_vals[root] != comp_target[root]:
            return False
    return True

