def smallest_missing_genetic_value(parents: List[int], nums: List[int]) -> List[int]:
    n = len(parents)
    children = [[] for _ in range(n)]
    for i in range(1, n):
        children[parents[i]].append(i)

    try:
        node_one = nums.index(1)
    except ValueError:
        return [1] * n

    max_val = max(nums) + 2
    visited = [False] * (max_val + 1)

    def add_subtree(root: int) -> None:
        stack = [root]
        while stack:
            u = stack.pop()
            val = nums[u]
            if not visited[val]:
                visited[val] = True
            for v in children[u]:
                stack.append(v)

    # Process subtree containing value 1
    add_subtree(node_one)

    cur = 1
    while visited[cur]:
        cur += 1

    ans = [1] * n
    ans[node_one] = cur

    cur_node = node_one
    while parents[cur_node] != -1:
        parent = parents[cur_node]

        # add all sibling subtrees of the current node
        for child in children[parent]:
            if child != cur_node:
                add_subtree(child)

        # add the parent node itself
        val_parent = nums[parent]
        if not visited[val_parent]:
            visited[val_parent] = True

        while visited[cur]:
            cur += 1
        ans[parent] = cur
        cur_node = parent

    return ans
# TIME: O(n) SPACE: O(max(nums))

