    if idx == -1:
        return word
    arr = list(word)
    left, right = 0, idx
    while left < right:
        tmp = arr[left]
        arr[left] = arr[right]
        arr[right] = tmp
        left += 1
        right -= 1
    return ''.join(arr)

def max_product(s: str) -> int:
    n = len(s)
    total = 1 << n
    pal_len = [0] * total

    for mask in range(total):
        # build subsequence
        subseq = []
        for i in range(n):
            if mask >> i & 1:
                subseq.append(s[i])
        # check palindrome
        if subseq == subseq[::-1]:
            pal_len[mask] = len(subseq)

    ans = 0
    for mask1 in range(total):
        if pal_len[mask1] == 0:
            continue
        for mask2 in range(mask1 + 1, total):
            if mask1 & mask2:
                continue
            if pal_len[mask2] == 0:
                continue
            prod = pal_len[mask1] * pal_len[mask2]
            if prod > ans:
                ans = prod
    return ans

