def find_original(changed):
    if len(changed) % 2 != 0:
        return []
    cnt = Counter(changed)
    original = []
    for x in sorted(cnt):
        if cnt[x] == 0:
            continue
        if x * 2 not in cnt or cnt[x * 2] < cnt[x]:
            return []
        cnt[x * 2] -= cnt[x]
        original.extend([x] * cnt[x])
        cnt[x] = 0
    return original

