def longest_subsequence_repeated_k_times(s: str, k: int) -> str:
    n = len(s)
    freq: List[int] = [0] * 26
    for ch in s:
        freq[ord(ch) - 97] += 1

    def can_form(t: str) -> bool:
        """Return True if t can be obtained as a subsequence of s at least k times."""
        if not t:
            return True
        idx = 0
        completed = 0
        t_len = len(t)
        for ch in s:
            if ch == t[idx]:
                idx += 1
                if idx == t_len:
                    completed += 1
                    if completed >= k:
                        return True
                    idx = 0
        return False

    best: str = ""

    def dfs(prefix: str) -> None:
        nonlocal best
        for c in range(25, -1, -1):
            if freq[c] < k:
                continue
            cand = prefix + chr(97 + c)
            if can_form(cand):
                if len(cand) > len(best) or (len(cand) == len(best) and cand > best):
                    best = cand
                dfs(cand)

    dfs("")
    return best

