def detect_squares():
    points: dict[int, dict[int, int]] = {}

    def add(point: tuple[int, int]) -> None:
        x, y = point
        if x not in points:
            points[x] = {}
        col = points[x]
        col[y] = col.get(y, 0) + 1

    def count(point: tuple[int, int]) -> int:
        x, y = point
        if x not in points:
            return 0
        total = 0
        col = points[x]
        for y2, cntY2 in col.items():
            if y2 == y:
                continue
            d = abs(y2 - y)
            for dir in (-1, 1):
                x2 = x + dir * d
                colX2 = points.get(x2)
                if colX2 is None:
                    continue
                cnt1 = colX2.get(y, 0)
                cnt2 = colX2.get(y2, 0)
                total += cntY2 * cnt1 * cnt2
        return total

    return {"add": add, "count": count}

