def place_word_in_crossword(board: List[List[str]], word: str) -> bool:
    m, n = len(board), len(board[0])
    L = len(word)

    def segment_matches(seg: List[str], w: str) -> bool:
        for ch_board, ch_word in zip(seg, w):
            if ch_board != ' ' and ch_board != ch_word:
                return False
        return True

    # check rows
    for i in range(m):
        j = 0
        while j < n:
            if board[i][j] == '#':
                j += 1
                continue
            start = j
            while j < n and board[i][j] != '#':
                j += 1
            seg = board[i][start:j]
            if len(seg) == L:
                if segment_matches(seg, word) or segment_matches(seg, word[::-1]):
                    return True

    # check columns
    for j in range(n):
        i = 0
        while i < m:
            if board[i][j] == '#':
                i += 1
                continue
            start = i
            while i < m and board[i][j] != '#':
                i += 1
            seg = [board[x][j] for x in range(start, i)]
            if len(seg) == L:
                if segment_matches(seg, word) or segment_matches(seg, word[::-1]):
                    return True

    return False
# TIME: O(m*n) SPACE: O(max(m,n))

