def stock_price():
    price_map = {}
    latest_timestamp = 0
    max_heap = []
    min_heap = []

    def heap_push(heap, item, better):
        heap.append(item)
        i = len(heap) - 1
        while i > 0:
            p = (i - 1) >> 1
            if better(heap[p], heap[i]):
                break
            heap[p], heap[i] = heap[i], heap[p]
            i = p

    def heap_pop(heap, better):
        top = heap[0]
        last = heap.pop()
        if heap:
            heap[0] = last
            heapify_down(heap, 0, better)
        return top

    def heapify_down(heap, i, better):
        n = len(heap)
        while True:
            left = i * 2 + 1
            right = i * 2 + 2
            best = i
            if left < n and not better(heap[best], heap[left]):
                best = left
            if right < n and not better(heap[best], heap[right]):
                best = right
            if best == i:
                break
            heap[i], heap[best] = heap[best], heap[i]
            i = best

    def clean(heap, better):
        while heap:
            price, ts = heap[0]
            if price_map.get(ts) != price:
                heap_pop(heap, better)
            else:
                break

    def update(timestamp, price):
        nonlocal latest_timestamp
        price_map[timestamp] = price
        if timestamp >= latest_timestamp:
            latest_timestamp = timestamp
        heap_push(max_heap, [price, timestamp], lambda a, b: a[0] > b[0])
        heap_push(min_heap, [price, timestamp], lambda a, b: a[0] < b[0])

    def current():
        return price_map.get(latest_timestamp)

    def maximum():
        clean(max_heap, lambda a, b: a[0] > b[0])
        return max_heap[0][0] if max_heap else None

    def minimum():
        clean(min_heap, lambda a, b: a[0] < b[0])
        return min_heap[0][0] if min_heap else None

    return {
        'update': update,
        'current': current,
        'maximum': maximum,
        'minimum': minimum
    }

