import sys

def smallest_subsequence(s: str, k: int, letter: str, repetition: int) -> str:
    n = len(s)
    # suffix[i] = number of occurrences of letter in s[i:]
    suffix = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        suffix[i] = suffix[i + 1] + (1 if s[i] == letter else 0)

    stack = []
    used_letter = 0

    for i, c in enumerate(s):
        # Try to pop larger characters while keeping feasibility
        while stack:
            top = stack[-1]
            if c < top:
                after_used_letter = used_letter - (1 if top == letter else 0)
                # Can we still reach length k after popping?
                if (len(stack) - 1 + (n - i) >= k) and (after_used_letter + suffix[i] >= repetition):
                    stack.pop()
                    used_letter = after_used_letter
                else:
                    break
            else:
                break

        # Decide whether to push current character
        if len(stack) < k:
            if c == letter:
                stack.append(c)
                used_letter += 1
            else:
                needed = repetition - used_letter
                slots_left = k - (len(stack) + 1)
                if slots_left >= needed:
                    stack.append(c)
                # else skip this character
        # else skip (already have k characters)

    return ''.join(stack)

