def network_become_idle(edges: List[List[int]], patience: List[int]) -> int:
    n = len(patience)
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    dist = [-1] * n
    dist[0] = 0
    q = deque([0])
    while q:
        u = q.popleft()
        for v in adj[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                q.append(v)

    max_time = 0
    for i in range(1, n):
        round_trip = 2 * dist[i]
        if patience[i] >= round_trip:
            last_send = 0
        else:
            last_send = ((round_trip - 1) // patience[i]) * patience[i]
        max_time = max(max_time, last_send + round_trip)

    return max_time + 1

