        total = 0
        for d in range(1, 10):
            if mask & (1 << (d - 1)):
                digits.append(d)
                total += d
        subsets_by_len.setdefault(total, []).append(digits)

    # Helper: smallest arrangement for remaining counts (sorted ascending)
    def smallest_from_counts(cnt: Dict[int, int]) -> str:
        parts = []
        for d in range(1, 10):
            if cnt.get(d, 0):
                parts.append(str(d) * cnt[d])
        return "".join(parts)

    # Recursive search for the minimal permutation >= target for a given multiset
    def build_min_ge(target_str: str, cnt: Dict[int, int]) -> str | None:
        length = len(target_str)

        def dfs(pos: int, tight: bool) -> str | None:
            if pos == length:
                return ""  # successfully built whole number
            start = int(target_str[pos]) if tight else 1
            for d in range(start, 10):
                if cnt.get(d, 0):
                    cnt[d] -= 1
                    next_tight = tight and (d == start)
                    if not next_tight:
                        # we can fill the rest with the smallest possible arrangement
                        suffix = smallest_from_counts(cnt)
                        cnt[d] += 1
                        return str(d) + suffix
                    else:
                        sub = dfs(pos + 1, True)
                        if sub is not None:
                            cnt[d] += 1
                            return str(d) + sub
                    cnt[d] += 1
            return None

        return dfs(0, True)

    # Try lengths from the length of target upwards
    for L in range(len(target), max_len + 1):
        if L not in subsets_by_len:
            continue
        best: int | None = None
        for digits in subsets_by_len[L]:
            # initialise counts: each chosen digit d appears exactly d times
            cnt: Dict[int, int] = {d: d for d in digits}
            if L > len(target):
                # any arrangement works; smallest is digits sorted ascending
                cand_str = smallest_from_counts(cnt)
                cand = int(cand_str)
                if best is None or cand < best:
                    best = cand
            else:
                cand_str = build_min_ge(target, cnt)
                if cand_str is not None:
                    cand = int(cand_str)
                    if best is None or cand < best:
                        best = cand
        if best is not None:
            return best
    return -1

