def minimum_time(n: int, relations: List[List[int]], time: List[int]) -> int:
    adj = [[] for _ in range(n)]
    indeg = [0] * n
    for pre, nxt in relations:
        u = pre - 1
        v = nxt - 1
        adj[u].append(v)
        indeg[v] += 1

    finish = [0] * n
    q = deque()
    for i in range(n):
        if indeg[i] == 0:
            finish[i] = time[i]
            q.append(i)

    while q:
        u = q.popleft()
        for v in adj[u]:
            cand = finish[u] + time[v]
            if cand > finish[v]:
                finish[v] = cand
            indeg[v] -= 1
            if indeg[v] == 0:
                q.append(v)

    ans = 0
    for f in finish:
        if f > ans:
            ans = f
    return ans

def count_valid_words(sentence: str) -> int:
    def is_valid(token: str) -> bool:
        hyphen_used = False
        punctuation_used = False
        for i, ch in enumerate(token):
            if ch.isdigit():
                return False
            if ch.isalpha():
                continue
            if ch == '-':
                if hyphen_used:
                    return False
                # hyphen must be surrounded by letters
                if i == 0 or i == len(token) - 1:
                    return False
                if not token[i - 1].isalpha() or not token[i + 1].isalpha():
                    return False
                hyphen_used = True
            elif ch in "!.,?":
                if punctuation_used:
                    return False
                # punctuation only allowed at the end
                if i != len(token) - 1:
                    return False
                punctuation_used = True
            else:
                return False
        return True

    tokens = [t for t in sentence.split(' ') if t]
    valid_count = 0
    for token in tokens:
        if is_valid(token):
            valid_count += 1
    return valid_count

