def possibly_equals(s1: str, s2: str) -> bool:
    n1, n2 = len(s1), len(s2)
    memo: Dict[Tuple[int, int, int], bool] = {}

    def dfs(i: int, j: int, diff: int) -> bool:
        # diff > 0 : s1 has diff extra characters pending to be matched by s2
        # diff < 0 : s2 has -diff extra characters pending to be matched by s1
        if i == n1 and j == n2:
            return diff == 0
        key = (i, j, diff)
        if key in memo:
            return memo[key]

        res = False

        if diff > 0:
            # need to consume characters from s2
            if j < n2 and s2[j].isalpha():
                res = dfs(i, j + 1, diff - 1)
            if not res and j < n2 and s2[j].isdigit():
                num = 0
                for k in range(j, n2):
                    if not s2[k].isdigit():
                        break
                    num = num * 10 + int(s2[k])
                    if dfs(i, k + 1, diff - num):
                        res = True
                        break
        elif diff < 0:
            # need to consume characters from s1
            if i < n1 and s1[i].isalpha():
                res = dfs(i + 1, j, diff + 1)
            if not res and i < n1 and s1[i].isdigit():
                num = 0
                for k in range(i, n1):
                    if not s1[k].isdigit():
                        break
                    num = num * 10 + int(s1[k])
                    if dfs(k + 1, j, diff + num):
                        res = True
                        break
        else:  # diff == 0
            # match letters directly
            if i < n1 and j < n2 and s1[i].isalpha() and s2[j].isalpha() and s1[i] == s2[j]:
                res = dfs(i + 1, j + 1, 0)

            # expand a number from s1
            if not res and i < n1 and s1[i].isdigit():
                num = 0
                for k in range(i, n1):
                    if not s1[k].isdigit():
                        break
                    num = num * 10 + int(s1[k])
                    if dfs(k + 1, j, num):
                        res = True
                        break

            # expand a number from s2
            if not res and j < n2 and s2[j].isdigit():
                num = 0
                for k in range(j, n2):
                    if not s2[k].isdigit():
                        break
                    num = num * 10 + int(s2[k])
                    if dfs(i, k + 1, -num):
                        res = True
                        break

        memo[key] = res
        return res

    return dfs(0, 0, 0)

