def max_path_quality(values: List[int], edges: List[List[int]], max_time: int) -> int:
    n = len(values)
    graph = [[] for _ in range(n)]
    for u, v, t in edges:
        graph[u].append((v, t))
        graph[v].append((u, t))
    visited = [False] * n
    best = 0

    def dfs(node: int, time_left: int, quality: int):
        nonlocal best
        if node == 0:
            if quality > best:
                best = quality
        for nxt, cost in graph[node]:
            if cost > time_left:
                continue
            if not visited[nxt]:
                visited[nxt] = True
                dfs(nxt, time_left - cost, quality + values[nxt])
                visited[nxt] = False
            else:
                dfs(nxt, time_left - cost, quality)

    visited[0] = True
    dfs(0, max_time, values[0])
    return best

