def minimum_operations(nums: List[int], start: int, goal: int) -> int:
    if start == goal:
        return 0
    visited = [False] * 1001
    q = collections.deque()
    q.append((start, 0))
    visited[start] = True
    while q:
        x, steps = q.popleft()
        for num in nums:
            for nx in (x + num, x - num):
                if nx == goal:
                    return steps + 1
                if 0 <= nx <= 1000 and not visited[nx]:
                    visited[nx] = True
                    q.append((nx, steps + 1))
    return -1

