def count_vowel_substrings(word: str) -> int:
    vowel_set: Set[str] = {'a', 'e', 'i', 'o', 'u'}
    vowel_to_idx = {'a': 0, 'e': 1, 'i': 2, 'o': 3, 'u': 4}
    n: int = len(word)
    total: int = 0
    i: int = 0

    while i < n:
        if word[i] not in vowel_set:
            i += 1
            continue
        block_start: int = i
        while i < n and word[i] in vowel_set:
            i += 1
        block_end: int = i

        last: list[int] = [-1, -1, -1, -1, -1]  # positions of a, e, i, o, u
        for j in range(block_start, block_end):
            ch: str = word[j]
            idx: int = vowel_to_idx[ch]
            last[idx] = j
            if -1 not in last:
                min_last: int = min(last)
                total += (min_last - block_start + 1)

    return total

def robot_simulation(width: int, height: int):
    dx = [1, 0, -1, 0]
    dy = [0, 1, 0, -1]
    dir_name = ['East', 'North', 'West', 'South']

    state = {'x': 0, 'y': 0, 'dir_idx': 0}

    def move(num: int) -> None:
        for _ in range(num):
            nx = state['x'] + dx[state['dir_idx']]
            ny = state['y'] + dy[state['dir_idx']]
            if nx < 0 or nx >= width or ny < 0 or ny >= height:
                state['dir_idx'] = (state['dir_idx'] + 1) % 4
                nx = state['x'] + dx[state['dir_idx']]
                ny = state['y'] + dy[state['dir_idx']]
            state['x'], state['y'] = nx, ny

    def get_pos():
        return [state['x'], state['y']]

    def get_dir() -> str:
        return dir_name[state['dir_idx']]

    return {'move': move, 'getPos': get_pos, 'getDir': get_dir}

