def minimized_maximum(n: int, quantities: list[int]) -> int:
    low = 1
    high = max(quantities)
    while low < high:
        mid = (low + high) // 2
        required = 0
        for q in quantities:
            required += math.ceil(q / mid)
        if required <= n:
            high = mid
        else:
            low = mid + 1
    return low

