def decode_slanted_cipher(encoded_text: str, rows: int) -> str:
    if rows == 1:
        return encoded_text
    n = len(encoded_text)
    cols = n // rows
    res = []
    for c in range(cols):
        r, j = 0, c
        while r < rows and j < cols:
            res.append(encoded_text[r * cols + j])
            r += 1
            j += 1
    result = ''.join(res)
    return result.rstrip(' ')

