def process_friend_requests(n: int, restrictions: List[List[int]], requests: List[List[int]]) -> List[bool]:
    parent = list(range(n))
    rank = [0] * n

    def find(x: int) -> int:
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x: int, y: int) -> None:
        rx, ry = find(x), find(y)
        if rx == ry:
            return
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1

    answer: List[bool] = []

    for u, v in requests:
        ru, rv = find(u), find(v)
        if ru == rv:
            answer.append(True)
            continue

        ok = True
        for x, y in restrictions:
            rx, ry = find(x), find(y)
            if (rx == ru and ry == rv) or (rx == rv and ry == ru):
                ok = False
                break

        if ok:
            union(ru, rv)
            answer.append(True)
        else:
            answer.append(False)

    return answer

