def range_freq_query(nums: List[int]):
    positions = {}
    for i, v in enumerate(nums):
        positions.setdefault(v, []).append(i)

    def lower_bound(arr, target):
        lo, hi = 0, len(arr)
        while lo < hi:
            mid = (lo + hi) >> 1
            if arr[mid] < target:
                lo = mid + 1
            else:
                hi = mid
        return lo

    def upper_bound(arr, target):
        lo, hi = 0, len(arr)
        while lo < hi:
            mid = (lo + hi) >> 1
            if arr[mid] <= target:
                lo = mid + 1
            else:
                hi = mid
        return lo

    def query(left, right, value):
        lst = positions.get(value)
        if lst is None:
            return 0
        l = lower_bound(lst, left)
        r = upper_bound(lst, right)
        return r - l

    return {"query": query}

