def count_fertile_pyramids(grid: List[List[int]]) -> int:
    if not grid or not grid[0]:
        return 0
    m, n = len(grid), len(grid[0])

    # dp_up[i][j] = max height of an upright pyramid with apex at (i, j)
    dp_up: List[List[int]] = [[0] * n for _ in range(m)]
    # dp_down[i][j] = max height of an inverted pyramid with apex at (i, j)
    dp_down: List[List[int]] = [[0] * n for _ in range(m)]

    # Compute upright pyramids (apex at top, base expands downward)
    for i in range(m - 1, -1, -1):
        for j in range(n):
            if grid[i][j] == 1:
                if i == m - 1:
                    dp_up[i][j] = 1
                else:
                    left = dp_up[i + 1][j - 1] if j > 0 else 0
                    mid = dp_up[i + 1][j]
                    right = dp_up[i + 1][j + 1] if j + 1 < n else 0
                    dp_up[i][j] = 1 + min(left, mid, right)

    # Compute inverted pyramids (apex at bottom, base expands upward)
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                if i == 0:
                    dp_down[i][j] = 1
                else:
                    left = dp_down[i - 1][j - 1] if j > 0 else 0
                    mid = dp_down[i - 1][j]
                    right = dp_down[i - 1][j + 1] if j + 1 < n else 0
                    dp_down[i][j] = 1 + min(left, mid, right)

    total = 0
    for i in range(m):
        for j in range(n):
            total += max(0, dp_up[i][j] - 1)
            total += max(0, dp_down[i][j] - 1)

    return total

