def get_averages(nums: List[int], k: int) -> List[int]:
    n = len(nums)
    result = [-1] * n
    window_size = 2 * k + 1
    if window_size > n:
        return result
    total = 0
    for i in range(n):
        total += nums[i]
        if i >= window_size:
            total -= nums[i - window_size]
        if i >= window_size - 1:
            center = i - k
            result[center] = int(total / window_size)
    return result

