def find_even_numbers(digits):
    freq = {}
    for d in digits:
        freq[d] = freq.get(d, 0) + 1
    results = set()
    def backtrack(pos, current):
        if pos == 3:
            if (current % 10) % 2 == 0:
                results.add(current)
            return
        for digit in freq:
            if freq[digit] == 0:
                continue
            if pos == 0 and digit == 0:
                continue
            freq[digit] -= 1
            backtrack(pos + 1, current * 10 + digit)
            freq[digit] += 1
    backtrack(0, 0)
    return sorted(results)

