def minimum_deletions(nums: List[int]) -> int:
    n = len(nums)
    min_idx = 0
    max_idx = 0
    for i in range(1, n):
        if nums[i] < nums[min_idx]:
            min_idx = i
        if nums[i] > nums[max_idx]:
            max_idx = i
    front_only = max(min_idx, max_idx) + 1
    back_only = max(n - min_idx, n - max_idx)
    front_then_back = min(min_idx, max_idx) + 1 + (n - max(min_idx, max_idx))
    back_then_front = front_then_back
    return min(front_only, back_only, front_then_back, back_then_front)

