def find_all_people(n: int, meetings: List[List[int]], firstPerson: int) -> List[int]:
    knows = [False] * n
    knows[0] = True
    knows[firstPerson] = True

    meetings.sort(key=lambda x: x[2])

    i = 0
    while i < len(meetings):
        cur_time = meetings[i][2]
        group = []
        persons = set()

        while i < len(meetings) and meetings[i][2] == cur_time:
            x, y = meetings[i][0], meetings[i][1]
            group.append([x, y])
            persons.add(x)
            persons.add(y)
            i += 1

        adj = {p: [] for p in persons}
        for x, y in group:
            adj[x].append(y)
            adj[y].append(x)

        visited = set()
        for start in persons:
            if start in visited:
                continue
            stack = [start]
            component = []
            has_secret = False
            visited.add(start)

            while stack:
                cur = stack.pop()
                component.append(cur)
                if knows[cur]:
                    has_secret = True
                for nb in adj[cur]:
                    if nb not in visited:
                        visited.add(nb)
                        stack.append(nb)

            if has_secret:
                for node in component:
                    knows[node] = True

    return [idx for idx, val in enumerate(knows) if val]

