def find_good_days(security: List[int], time: int) -> List[int]:
    n = len(security)
    left = [0] * n
    right = [0] * n
    for i in range(1, n):
        if security[i - 1] >= security[i]:
            left[i] = left[i - 1] + 1
    for i in range(n - 2, -1, -1):
        if security[i] <= security[i + 1]:
            right[i] = right[i + 1] + 1
    result = []
    for i in range(time, n - time):
        if left[i] >= time and right[i] >= time:
            result.append(i)
    return result

def get_directions(root: 'TreeNode', startValue: int, destValue: int) -> str:
    def dfs(node: 'TreeNode', target: int, cur_path: str):
        if not node:
            return None
        if node.val == target:
            return cur_path
        left = dfs(node.left, target, cur_path + "L")
        if left is not None:
            return left
        right = dfs(node.right, target, cur_path + "R")
        if right is not None:
            return right
        return None

    path_to_start = dfs(root, startValue, "")
    path_to_dest = dfs(root, destValue, "")

    i = 0
    while i < len(path_to_start) and i < len(path_to_dest) and path_to_start[i] == path_to_dest[i]:
        i += 1

    up_moves = "U" * (len(path_to_start) - i)
    down_moves = path_to_dest[i:]
    return up_moves + down_moves

from typing import List

def max_fruits_harvested(fruits: List[List[int]], startPos: int, k: int) -> int:
    # positions are assumed sorted; if not, sort them together with amounts
    pos = [p for p, _ in fruits]
    amt = [a for _, a in fruits]
    n = len(fruits)

    # prefix sums for quick interval sums
    pref = [0] * (n + 1)
    for i in range(n):
        pref[i + 1] = pref[i] + amt[i]

    def steps_needed(l: int, r: int) -> int:
        """minimum steps to visit all fruits from pos[l] to pos[r] starting at startPos."""
        left_pos = pos[l]
        right_pos = pos[r]
        left_dist = startPos - left_pos
        if left_dist < 0:
            left_dist = 0
        right_dist = right_pos - startPos
        if right_dist < 0:
            right_dist = 0
        # two possible orders: left first then right, or right first then left
        return min(right_dist + 2 * left_dist, left_dist + 2 * right_dist)

    ans = 0
    for l in range(n):
        # early break: if even reaching pos[l] exceeds k, further left positions are farther
        if startPos - pos[l] > k and pos[l] <= startPos:
            continue
        lo, hi = l, n - 1
        best = l - 1
        while lo <= hi:
            mid = (lo + hi) // 2
            if steps_needed(l, mid) <= k:
                best = mid
                lo = mid + 1
            else:
                hi = mid - 1
        if best >= l:
            total = pref[best + 1] - pref[l]
            if total > ans:
                ans = total
    return ans

