def maximum_detonation(bombs: List[List[int]]) -> int:
    n = len(bombs)
    adj: List[List[int]] = [[] for _ in range(n)]

    for i in range(n):
        xi, yi, ri = bombs[i]
        ri2 = ri * ri
        for j in range(n):
            if i == j:
                continue
            xj, yj, _ = bombs[j]
            dx = xi - xj
            dy = yi - yj
            if dx * dx + dy * dy <= ri2:
                adj[i].append(j)

    best = 0
    for start in range(n):
        visited = [False] * n
        queue = [start]
        visited[start] = True
        count = 0
        while queue:
            cur = queue.pop(0)
            count += 1
            for nxt in adj[cur]:
                if not visited[nxt]:
                    visited[nxt] = True
                    queue.append(nxt)
        if count > best:
            best = count
    return best

