def min_operations(arr: List[int], k: int) -> int:
    operations = 0
    n = len(arr)
    for offset in range(k):
        subsequence = []
        i = offset
        while i < n:
            subsequence.append(arr[i])
            i += k

        tails = []
        for value in subsequence:
            left, right = 0, len(tails)
            while left < right:
                mid = (left + right) >> 1
                if tails[mid] > value:
                    right = mid
                else:
                    left = mid + 1
            if left == len(tails):
                tails.append(value)
            else:
                tails[left] = value

        operations += len(subsequence) - len(tails)
    return operations

