def can_be_valid(s: str, locked: str) -> bool:
    n = len(s)
    if n % 2 == 1:
        return False
    low = high = 0
    for i in range(n):
        if locked[i] == '1':
            if s[i] == '(':
                low += 1
                high += 1
            else:
                low -= 1
                high -= 1
        else:
            # unlocked: can be '(' or ')'
            low -= 1      # assume ')'
            high += 1     # assume '('
        if high < 0:
            return False
        if low < 0:
            low = 0
    return low == 0

