def sum_intervals(arr: List[int]) -> List[int]:
    n = len(arr)
    answer = [0] * n
    groups = {}
    for i, val in enumerate(arr):
        if val not in groups:
            groups[val] = []
        groups[val].append(i)
    for indices in groups.values():
        k = len(indices)
        if k == 1:
            continue
        prefix = [0] * k
        prefix[0] = indices[0]
        for i in range(1, k):
            prefix[i] = prefix[i - 1] + indices[i]
        total = prefix[-1]
        for i in range(k):
            idx = indices[i]
            left_count = i
            right_count = k - 1 - i
            left_sum = prefix[i - 1] if i > 0 else 0
            right_sum = total - prefix[i]
            answer[idx] = idx * left_count - left_sum + right_sum - idx * right_count
    return answer

