def recover_array(nums):
    nums.sort()
    n = len(nums) // 2
    for j in range(1, len(nums)):
        diff = nums[j] - nums[0]
        if diff % 2 != 0:
            continue
        k = diff // 2
        if k == 0:
            continue
        cnt = Counter(nums)
        arr = []
        ok = True
        for x in nums:
            if cnt[x] == 0:
                continue
            cnt[x] -= 1
            partner = x + 2 * k
            if cnt[partner] == 0:
                ok = False
                break
            cnt[partner] -= 1
            arr.append(x + k)
        if ok and len(arr) == n:
            return arr
    return []

