def min_swaps(nums: List[int]) -> int:
    n = len(nums)
    total_ones = 0
    for i in range(n):
        total_ones += nums[i]
    if total_ones <= 1:
        return 0
    window_ones = 0
    for i in range(total_ones):
        window_ones += nums[i]
    min_zeros = total_ones - window_ones
    for start in range(1, n):
        window_ones -= nums[start - 1]
        entering_idx = (start + total_ones - 1) % n
        window_ones += nums[entering_idx]
        zeros = total_ones - window_ones
        if zeros < min_zeros:
            min_zeros = zeros
    return min_zeros

def longest_palindrome(words: list[str]) -> int:
    freq: dict[str, int] = {}
    for w in words:
        freq[w] = freq.get(w, 0) + 1

    length = 0
    has_center = False

    for word, cnt in list(freq.items()):
        if cnt == 0:
            continue
        rev = word[1] + word[0]
        if word == rev:
            pairs = cnt // 2
            length += pairs * 4
            if cnt % 2 == 1:
                has_center = True
        else:
            rev_cnt = freq.get(rev, 0)
            pair_cnt = min(cnt, rev_cnt)
            length += pair_cnt * 4
            freq[word] = cnt - pair_cnt
            freq[rev] = rev_cnt - pair_cnt

    if has_center:
        length += 2

    return length

