def possible_to_stamp(grid: List[List[int]], stampHeight: int, stampWidth: int) -> bool:
    m = len(grid)
    if m == 0:
        return True
    n = len(grid[0])
    # Prefix sum of ones
    ps = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m):
        row_sum = 0
        for j in range(n):
            row_sum += grid[i][j]
            ps[i + 1][j + 1] = ps[i][j + 1] + row_sum
    # Difference array for coverage
    diff = [[0] * (n + 1) for _ in range(m + 1)]
    max_i = m - stampHeight
    max_j = n - stampWidth
    for i in range(max_i + 1):
        for j in range(max_j + 1):
            total = (
                ps[i + stampHeight][j + stampWidth]
                - ps[i][j + stampWidth]
                - ps[i + stampHeight][j]
                + ps[i][j]
            )
            if total == 0:
                diff[i][j] += 1
                diff[i + stampHeight][j] -= 1
                diff[i][j + stampWidth] -= 1
                diff[i + stampHeight][j + stampWidth] += 1
    # Build coverage from diff
    for i in range(m):
        for j in range(n):
            if i > 0:
                diff[i][j] += diff[i - 1][j]
            if j > 0:
                diff[i][j] += diff[i][j - 1]
            if i > 0 and j > 0:
                diff[i][j] -= diff[i - 1][j - 1]
            if grid[i][j] == 0 and diff[i][j] == 0:
                return False
    return True

