def groups_of_strings(words: List[str]) -> List[int]:
    # Convert each word to a bitmask and count occurrences
    mask_counts = {}
    for w in words:
        mask = 0
        for ch in w:
            mask |= 1 << (ord(ch) - 97)
        mask_counts[mask] = mask_counts.get(mask, 0) + 1

    masks = list(mask_counts.keys())
    n = len(masks)
    idx_of_mask = {m: i for i, m in enumerate(masks)}

    parent = list(range(n))
    rank = [0] * n

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a: int, b: int) -> None:
        ra, rb = find(a), find(b)
        if ra == rb:
            return
        if rank[ra] < rank[rb]:
            parent[ra] = rb
        elif rank[ra] > rank[rb]:
            parent[rb] = ra
        else:
            parent[rb] = ra
            rank[ra] += 1

    # Precompute bit information for each mask
    bits_set = []
    bits_unset = []
    for m in masks:
        set_list = [i for i in range(26) if m >> i & 1]
        unset_list = [i for i in range(26) if not (m >> i & 1)]
        bits_set.append(set_list)
        bits_unset.append(unset_list)

    for i, m in enumerate(masks):
        # Add or delete a single letter
        for b in range(26):
            bit = 1 << b
            if m & bit:
                new_mask = m ^ bit          # delete
            else:
                new_mask = m | bit          # add
            j = idx_of_mask.get(new_mask)
            if j is not None:
                union(i, j)

        # Replace one letter by another (two-bit change)
        for b in bits_set[i]:
            for c in bits_unset[i]:
                new_mask = (m ^ (1 << b)) | (1 << c)
                j = idx_of_mask.get(new_mask)
                if j is not None:
                    union(i, j)

    # Aggregate component sizes
    comp_sizes = {}
    for i, m in enumerate(masks):
        root = find(i)
        comp_sizes[root] = comp_sizes.get(root, 0) + mask_counts[m]

    num_groups = len(comp_sizes)
    max_group = max(comp_sizes.values()) if comp_sizes else 0
    return [num_groups, max_group]

