def smallest_rearranged_number(num: int) -> int:
    if num == 0:
        return 0

    sign = (num > 0) - (num < 0)
    digits = list(str(abs(num)))

    if sign >= 0:
        digits.sort()
        if digits[0] == '0':
            first_non_zero = next((i for i, d in enumerate(digits) if d != '0'), -1)
            if first_non_zero != -1:
                digits[0], digits[first_non_zero] = digits[first_non_zero], digits[0]
        return int(''.join(digits))
    else:
        digits.sort(reverse=True)
        return int('-' + ''.join(digits))

def bitset(size: int):
    bits = [0] * size
    flipped = False
    ones_count = 0

    def fix(idx: int):
        nonlocal flipped, ones_count
        if (bits[idx] ^ (1 if flipped else 0)) == 0:
            bits[idx] = 0 if flipped else 1
            ones_count += 1

    def unfix(idx: int):
        nonlocal flipped, ones_count
        if (bits[idx] ^ (1 if flipped else 0)) == 1:
            bits[idx] = 1 if flipped else 0
            ones_count -= 1

    def flip():
        nonlocal flipped, ones_count
        flipped = not flipped
        ones_count = size - ones_count

    def all():
        return 1 if ones_count == size else 0

    def one():
        return 1 if ones_count > 0 else 0

    def count():
        return ones_count

    def toString():
        result = ''
        for i in range(size):
            result += str(bits[i] ^ (1 if flipped else 0))
        return result

    return {
        'fix': fix,
        'unfix': unfix,
        'flip': flip,
        'all': all,
        'one': one,
        'count': count,
        'toString': toString
    }

import sys, collections

def min_operations(nums):
    n = len(nums)
    even_counter = collections.Counter()
    odd_counter = collections.Counter()
    for i, v in enumerate(nums):
        if i % 2 == 0:
            even_counter[v] += 1
        else:
            odd_counter[v] += 1
    even_common = even_counter.most_common(2)
    odd_common = odd_counter.most_common(2)
    even_max_val, even_max_cnt = even_common[0] if even_common else (None, 0)
    even_second_cnt = even_common[1][1] if len(even_common) > 1 else 0
    odd_max_val, odd_max_cnt = odd_common[0] if odd_common else (None, 0)
    odd_second_cnt = odd_common[1][1] if len(odd_common) > 1 else 0
    if even_max_val != odd_max_val:
        keep = even_max_cnt + odd_max_cnt
    else:
        keep = max(even_max_cnt + odd_second_cnt, odd_max_cnt + even_second_cnt)
    return n - keep

