from functools import lru_cache

def max_and_sum(nums: List[int], numSlots: int) -> int:
    n = len(nums)
    total_positions = 2 * numSlots

    @lru_cache(maxsize=None)
    def dfs(mask: int) -> int:
        placed = mask.bit_count()
        if placed == n:
            return 0
        cur = nums[placed]
        best = 0
        for pos in range(total_positions):
            if not (mask >> pos) & 1:
                slot = pos // 2 + 1
                val = (cur & slot) + dfs(mask | (1 << pos))
                if val > best:
                    best = val
        return best

    return dfs(0)
# TIME: O(n * 2^(2*numSlots)) SPACE: O(2^(2*numSlots))

def maximum_split(final_sum):
    if final_sum % 2 != 0:
        return []
    result = []
    nxt = 2
    remaining = final_sum
    while remaining >= nxt:
        result.append(nxt)
        remaining -= nxt
        nxt += 2
    if remaining > 0:
        result[-1] += remaining
    return result

def repeat_limited_string(s: str, repeat_limit: int) -> str:
    cnt = [0] * 26
    for ch in s:
        cnt[ord(ch) - 97] += 1
    res = []
    last_idx = -1
    last_run = 0
    while True:
        i = 25
        while i >= 0 and cnt[i] == 0:
            i -= 1
        if i < 0:
            break
        if i == last_idx and last_run == repeat_limit:
            j = i - 1
            while j >= 0 and cnt[j] == 0:
                j -= 1
            if j < 0:
                break
            res.append(chr(j + 97))
            cnt[j] -= 1
            last_idx = j
            last_run = 1
        else:
            res.append(chr(i + 97))
            cnt[i] -= 1
            if i == last_idx:
                last_run += 1
            else:
                last_idx = i
                last_run = 1
    return ''.join(res)

