def count_pairs(nums: List[int], k: int) -> int:
    def gcd(a: int, b: int) -> int:
        while b != 0:
            t = a % b
            a = b
            b = t
        return a

    freq: dict[int, int] = {}
    result = 0

    for num in nums:
        g = gcd(num, k)
        for prev_g, cnt in freq.items():
            if (g * prev_g) % k == 0:
                result += cnt
        freq[g] = freq.get(g, 0) + 1

    return result

