def get_ancestors(n: int, edges: List[Tuple[int, int]]) -> List[List[int]]:
    adj: List[List[int]] = [[] for _ in range(n)]
    indeg: List[int] = [0] * n
    for frm, to in edges:
        adj[frm].append(to)
        indeg[to] += 1
    ancestors: List[Set[int]] = [set() for _ in range(n)]
    queue: deque[int] = deque(i for i, d in enumerate(indeg) if d == 0)
    while queue:
        u = queue.popleft()
        for v in adj[u]:
            ancestors[v].add(u)
            for anc in ancestors[u]:
                ancestors[v].add(anc)
            indeg[v] -= 1
            if indeg[v] == 0:
                queue.append(v)
    return [sorted(s) for s in ancestors]

