def minimum_time(time: List[int], total_trips: int) -> int:
    left = 1
    right = min(time) * total_trips
    while left < right:
        mid = (left + right) // 2
        trips = 0
        for t in time:
            trips += mid // t
            if trips >= total_trips:
                break
        if trips >= total_trips:
            right = mid
        else:
            left = mid + 1
    return left

