def minimum_finish_time(tires: List[List[int]], changeTime: int, numLaps: int) -> int:
    INF = float('inf')
    best = [INF] * (numLaps + 1)  # best[k]: min time to run k consecutive laps without change
    for f, r in tires:
        lap_time = f
        total = 0
        for k in range(1, numLaps + 1):
            total += lap_time
            if total < best[k]:
                best[k] = total
            # prepare time for next lap
            lap_time *= r
            # if next lap would be slower than resetting (change + fresh tire), stop
            if lap_time > changeTime + f:
                break

    dp = [INF] * (numLaps + 1)
    dp[0] = 0
    for i in range(1, numLaps + 1):
        for k in range(1, i + 1):
            if best[k] == INF:
                continue
            cand = dp[i - k] + best[k] + (0 if i == k else changeTime)
            if cand < dp[i]:
                dp[i] = cand
    return dp[numLaps]

def create_binary_tree(descriptions):
    nodes = {}
    children = set()
    def get_node(val):
        if val not in nodes:
            nodes[val] = {'val': val, 'left': None, 'right': None}
        return nodes[val]
    for parent_val, child_val, is_left in descriptions:
        parent_node = get_node(parent_val)
        child_node = get_node(child_val)
        if is_left == 1:
            parent_node['left'] = child_node
        else:
            parent_node['right'] = child_node
        children.add(child_val)
    for val, node in nodes.items():
        if val not in children:
            return node
    return None

