def min_operations(nums: List[int]) -> int:
    total = 0
    for v in nums:
        total += v
    target = total / 2

    def heap_push(heap: List[float], val: float) -> None:
        heap.append(val)
        i = len(heap) - 1
        while i > 0:
            p = (i - 1) >> 1
            if heap[p] >= heap[i]:
                break
            heap[p], heap[i] = heap[i], heap[p]
            i = p

    def heap_pop(heap: List[float]) -> float:
        max_val = heap[0]
        end = heap.pop()
        if heap:
            heap[0] = end
            i = 0
            while True:
                l = i * 2 + 1
                r = i * 2 + 2
                largest = i
                if l < len(heap) and heap[l] > heap[largest]:
                    largest = l
                if r < len(heap) and heap[r] > heap[largest]:
                    largest = r
                if largest == i:
                    break
                heap[i], heap[largest] = heap[largest], heap[i]
                i = largest
        return max_val

    heap: List[float] = []
    for v in nums:
        heap_push(heap, v)

    saved = 0.0
    ops = 0
    while saved < target:
        cur = heap_pop(heap)
        half = cur / 2
        saved += half
        heap_push(heap, half)
        ops += 1

    return ops

