def maximum_points(num_arrows: int, alice_arrows: List[int]) -> List[int]:
    n = 12
    best_mask = 0
    best_score = -1
    best_diff = float('-inf')
    for mask in range(1 << n):
        needed = 0
        bob_score = 0
        alice_score = 0
        for i in range(n):
            if mask >> i & 1:
                needed += alice_arrows[i] + 1
                bob_score += i
            else:
                if alice_arrows[i] > 0:
                    alice_score += i
        if needed > num_arrows:
            continue
        diff = bob_score - alice_score
        if bob_score > best_score or (bob_score == best_score and diff > best_diff):
            best_score = bob_score
            best_diff = diff
            best_mask = mask
    bob_arrows = [0] * n
    for i in range(n):
        if best_mask >> i & 1:
            bob_arrows[i] = alice_arrows[i] + 1
    leftover = num_arrows - sum(bob_arrows)
    if leftover > 0:
        bob_arrows[0] += leftover
    return bob_arrows

