def max_value_of_coins(piles: list[list[int]], k: int) -> int:
    pref = []
    for p in piles:
        pre = [0]
        for v in p:
            pre.append(pre[-1] + v)
        pref.append(pre)

    dp = [float("-inf")] * (k + 1)
    dp[0] = 0

    for i in range(len(piles)):
        cur_pref = pref[i]
        sz = len(cur_pref) - 1
        nxt = [float("-inf")] * (k + 1)
        for taken in range(k + 1):
            max_x = sz if sz < taken else taken
            for x in range(max_x + 1):
                if dp[taken - x] == float("-inf"):
                    continue
                candidate = dp[taken - x] + cur_pref[x]
                if candidate > nxt[taken]:
                    nxt[taken] = candidate
        dp = nxt

    return dp[k]

