def kth_palindrome(queries: List[int], int_length: int) -> List[int]:
    half_len = (int_length + 1) // 2
    start = 10 ** (half_len - 1)
    total = 9 * start
    result: List[int] = []
    for k in queries:
        if k > total:
            result.append(-1)
            continue
        left_num = start + k - 1
        left_str = str(left_num)
        if int_length % 2 == 0:
            pal_str = left_str + left_str[::-1]
        else:
            # For odd length, mirror all but the last digit of the left part
            if half_len > 1:
                pal_str = left_str + left_str[-2::-1]
            else:
                pal_str = left_str
        result.append(int(pal_str))
    return result

def number_of_ways(s: str) -> int:
    n = len(s)
    if n < 3:
        return 0
    total_zero = s.count('0')
    total_one = n - total_zero
    prefix_zero = 0
    prefix_one = 0
    answer = 0
    for j in range(n):
        if s[j] == '0':
            left = prefix_one
            right = total_one - prefix_one
        else:
            left = prefix_zero
            right = total_zero - prefix_zero
        answer += left * right
        if s[j] == '0':
            prefix_zero += 1
        else:
            prefix_one += 1
    return answer

