def find_winners(matches: List[List[int]]) -> List[List[int]]:
    loss_count = {}
    players = set()
    for winner, loser in matches:
        players.add(winner)
        players.add(loser)
        loss_count[loser] = loss_count.get(loser, 0) + 1
    zero_loss = []
    one_loss = []
    for p in players:
        cnt = loss_count.get(p, 0)
        if cnt == 0:
