def maximum_candies(candies: list[int], k: int) -> int:
    max_pile = 0
    for v in candies:
        if v > max_pile:
            max_pile = v
    low, high, best = 1, max_pile, 0
    while low <= high:
        mid = (low + high) // 2
        total = 0
        for v in candies:
            total += v // mid
            if total >= k:
                break
        if total >= k:
            best = mid
            low = mid + 1
        else:
            high = mid - 1
    return best

def sum_scores(s: str) -> int:
    n = len(s)
    z = [0] * n
    left = right = 0
    for i in range(1, n):
        if i <= right:
            z[i] = min(right - i + 1, z[i - left])
        while i + z[i] < n and s[z[i]] == s[i + z[i]]:
            z[i] += 1
        if i + z[i] - 1 > right:
            left = i
            right = i + z[i] - 1
    total = n
    for i in range(1, n):
        total += z[i]
    return total

def encrypter(keys, values, dictionary):
    enc_map = {}
    for i in range(len(keys)):
        enc_map[keys[i]] = values[i]

    dict_count = {}
    for word in dictionary:
        enc = ""
        possible = True
        for ch in word:
            pair = enc_map.get(ch)
            if pair is None:
                possible = False
                break
            enc += pair
        if possible:
            dict_count[enc] = dict_count.get(enc, 0) + 1

    def encrypt(word):
        enc = ""
        for ch in word:
            pair = enc_map.get(ch)
            if pair is None:
                return ""
            enc += pair
        return enc

    def decrypt(code):
        return dict_count.get(code, 0)

    return {"encrypt": encrypt, "decrypt": decrypt}

def largest_number_after_parity_swaps(num: int) -> int:
