    odd = []
    even = []
    for ch in s:
        d = ord(ch) - 48
        if d % 2:
            odd.append(d)
        else:
            even.append(d)
    odd.sort(reverse=True)
    even.sort(reverse=True)
    oi = 0
    ei = 0
    result = []
    for ch in s:
        d = ord(ch) - 48
        if d % 2:
            result.append(odd[oi])
            oi += 1
        else:
            result.append(even[ei])
            ei += 1
    return int(''.join(map(str, result)))

