def find_closest_number(nums: List[int]) -> int:
    best = nums[0]
    best_abs = abs(best)
    for i in range(1, len(nums)):
        cur = nums[i]
        cur_abs = abs(cur)
        if cur_abs < best_abs:
            best = cur
            best_abs = cur_abs
        elif cur_abs == best_abs and cur > best:
            best = cur
    return best

