class ATM:
    def __init__(self) -> None:
        self._denoms = [20, 50, 100, 200, 500]
        self._counts = [0] * 5

    def deposit(self, banknotesCount: List[int]) -> None:
        for i in range(5):
            self._counts[i] += banknotesCount[i]

    def withdraw(self, amount: int) -> List[int]:
        used = [0] * 5
        for i in range(4, -1, -1):
            denom = self._denoms[i]
            need = amount // denom
            take = min(need, self._counts[i])
            amount -= take * denom
            used[i] = take
        if amount == 0:
