def maximum_score(scores: List[int], edges: List[List[int]]) -> int:
    n = len(scores)
    adj: List[List[int]] = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    top: List[List[int]] = []
    for i in range(n):
        neighbors = adj[i]
        neighbors.sort(key=lambda x: scores[x], reverse=True)
        top.append(neighbors[:3])  # keep up to three best neighbours

    best = -1
    for u, v in edges:
        cand_a = [a for a in top[u] if a != v]
        cand_d = [d for d in top[v] if d != u]
        for a in cand_a:
            for d in cand_d:
                if a == d:
                    continue
                total = scores[a] + scores[u] + scores[v] + scores[d]
                if total > best:
                    best = total
    return best

