def count_lattice_points(circles: List[List[int]]) -> int:
    visited = set()
    for i in range(len(circles)):
        cx, cy, r = circles[i]
        r_sq = r * r
        for x in range(cx - r, cx + r + 1):
            dx = x - cx
            dx_sq = dx * dx
            if dx_sq > r_sq:
                continue
            dy_max = int(math.floor(math.sqrt(r_sq - dx_sq)))
            for y in range(cy - dy_max, cy + dy_max + 1):
                visited.add(f"{x},{y}")
