def full_bloom_flowers(flowers: list[list[int]], people: list[int]) -> list[int]:
    starts = []
    ends = []
    for f in flowers:
        starts.append(f[0])
        ends.append(f[1])
    starts.sort()
    ends.sort()
    def upper_bound(arr: list[int], target: int) -> int:
        lo = 0
        hi = len(arr)
        while lo < hi:
            mid = (lo + hi) >> 1
            if arr[mid] <= target:
                lo = mid + 1
            else:
                hi = mid
        return lo
    def lower_bound(arr: list[int], target: int) -> int:
        lo = 0
        hi = len(arr)
        while lo < hi:
            mid = (lo + hi) >> 1
            if arr[mid] < target:
                lo = mid + 1
            else:
                hi = mid
        return lo
    result = [0] * len(people)
    for i, t in enumerate(people):
        started = upper_bound(starts, t)
        finished = lower_bound(ends, t)
        result[i] = started - finished
    return result

