def count_unguarded(m: int, n: int, guards: List[List[int]], walls: List[List[int]]) -> int:
    grid = [[0] * n for _ in range(m)]
    GUARD, WALL, GUARDED = 1, 2, 3

    for r, c in guards:
        grid[r][c] = GUARD
    for r, c in walls:
        grid[r][c] = WALL

    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for gr, gc in guards:
        for dr, dc in dirs:
            r, c = gr + dr, gc + dc
            while 0 <= r < m and 0 <= c < n and grid[r][c] != WALL and grid[r][c] != GUARD:
                if grid[r][c] == 0:
                    grid[r][c] = GUARDED
                r += dr
                c += dc

    unguarded = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 0:
                unguarded += 1
    return unguarded

from collections import deque

def maximumMinutes(grid):
    m, n = len(grid), len(grid[0])
    INF = float('inf')
    fire = [[INF]*n for _ in range(m)]
    q = deque()
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                fire[i][j] = 0
                q.append((i, j))
    dirs = [(-1,0),(1,0),(0,-1),(0,1)]
    while q:
        i, j = q.popleft()
        for di, dj in dirs:
            ni, nj = i+di, j+dj
            if 0 <= ni < m and 0 <= nj < n and grid[ni][nj] != 2 and fire[ni][nj] == INF:
                fire[ni][nj] = fire[i][j] + 1
                q.append((ni, nj))

    def canReach(wait):
        if wait >= fire[0][0]:
            return False
        person = [[INF]*n for _ in range(m)]
        person[0][0] = wait
        q = deque([(0,0)])
        while q:
            i, j = q.popleft()
            for di, dj in dirs:
                ni, nj = i+di, j+dj
                if 0 <= ni < m and 0 <= nj < n and grid[ni][nj] != 2 and person[ni][nj] == INF:
                    t = person[i][j] + 1
                    if ni == m-1 and nj == n-1:
                        if t <= fire[ni][nj]:
                            person[ni][nj] = t
                            q.append((ni, nj))
                    else:
                        if t < fire[ni][nj]:
                            person[ni][nj] = t
                            q.append((ni, nj))
        return person[m-1][n-1] != INF

    if fire[m-1][n-1] == INF:
        return 1_000_000_000 if canReach(0) else -1
    if not canReach(0):
        return -1
    lo, hi, ans = 0, fire[m-1][n-1], 0
    while lo <= hi:
        mid = (lo+hi)//2
        if canReach(mid):
            ans = mid
            lo = mid+1
        else:
            hi = mid-1
    return ans

