MOD = 10**9 + 7

def count_texts(pressedKeys: str) -> int:
    n = len(pressedKeys)
    # precompute dp for max 3 and max 4
    dp3 = [0] * (n + 1)
    dp4 = [0] * (n + 1)
    dp3[0] = dp4[0] = 1
    for i in range(1, n + 1):
        dp3[i] = dp3[i - 1]
        if i >= 2:
            dp3[i] = (dp3[i] + dp3[i - 2]) % MOD
        if i >= 3:
            dp3[i] = (dp3[i] + dp3[i - 3]) % MOD

        dp4[i] = dp4[i - 1]
        if i >= 2:
            dp4[i] = (dp4[i] + dp4[i - 2]) % MOD
        if i >= 3:
            dp4[i] = (dp4[i] + dp4[i - 3]) % MOD
        if i >= 4:
            dp4[i] = (dp4[i] + dp4[i - 4]) % MOD

    ans = 1
    i = 0
    while i < n:
        j = i
        while j < n and pressedKeys[j] == pressedKeys[i]:
            j += 1
        length = j - i
        digit = pressedKeys[i]
        if digit in ('7', '9'):
            ways = dp4[length]
        else:
            ways = dp3[length]
        ans = (ans * ways) % MOD
        i = j
    return ans

