def has_valid_parentheses_path(grid: List[List[str]]) -> bool:
    m = len(grid)
    n = len(grid[0])
    # Starting cell must be '(' to have non‑negative balance
    if grid[0][0] != '(':
        return False

    dp: List[List[Set[int]]] = [[set() for _ in range(n)] for _ in range(m)]
    dp[0][0].add(1)  # balance after first '('

    for i in range(m):
        for j in range(n):
            if i == 0 and j == 0:
                continue
            cur_set: Set[int] = set()
            for pi, pj in ((i - 1, j), (i, j - 1)):
                if 0 <= pi < m and 0 <= pj < n:
                    for bal in dp[pi][pj]:
                        new_bal = bal + (1 if grid[i][j] == '(' else -1)
                        if new_bal < 0:
                            continue
                        # remaining steps to reach bottom‑right
                        rem = (m - 1 - i) + (n - 1 - j)
                        if new_bal > rem:
                            continue
                        cur_set.add(new_bal)
            dp[i][j] = cur_set

    return 0 in dp[m - 1][n - 1]

def k_beauty(num: int, k: int) -> int:
    s = str(num)
    n = len(s)
    if k > n:
        return 0
    power = 1
    for _ in range(1, k):
        power *= 10
    cur = 0
    for i in range(k):
        cur = cur * 10 + (ord(s[i]) - 48)
    ans = 0
    if cur > 0 and num % cur == 0:
        ans += 1
    for i in range(k, n):
        out_digit = ord(s[i - k]) - 48
        in_digit = ord(s[i]) - 48
        cur = (cur - out_digit * power) * 10 + in_digit
        if cur > 0 and num % cur == 0:
            ans += 1
    return ans

