def count_intervals():
    intervals = []
    total = 0

    def add(left: int, right: int):
        nonlocal total
        lo = 0
        hi = len(intervals)
        while lo < hi:
            mid = (lo + hi) >> 1
            if intervals[mid][0] < left:
                lo = mid + 1
            else:
                hi = mid
        idx = lo
        if idx > 0 and intervals[idx - 1][1] + 1 >= left:
            idx -= 1
        new_l = left
        new_r = right
        while idx < len(intervals) and intervals[idx][0] <= right + 1:
            l, r = intervals[idx]
            new_l = min(new_l, l)
            new_r = max(new_r, r)
            total -= (r - l + 1)
            intervals.pop(idx)
        intervals.insert(idx, [new_l, new_r])
        total += (new_r - new_l + 1)

    def count():
        return total

    return {"add": add, "count": count}

