def book_my_show(n, m):
    rem = [m] * n
    size = 4 * n
    sum_tree = [0] * size
    mx_tree = [0] * size

    def build(node, l, r):
        if l == r:
            sum_tree[node] = m
            mx_tree[node] = m
        else:
            mid = (l + r) >> 1
            build(node * 2, l, mid)
            build(node * 2 + 1, mid + 1, r)
            pull(node)

    def pull(node):
        sum_tree[node] = sum_tree[node * 2] + sum_tree[node * 2 + 1]
        mx_tree[node] = mx_tree[node * 2] if mx_tree[node * 2] > mx_tree[node * 2 + 1] else mx_tree[node * 2 + 1]

    def update(node, l, r, idx, val):
        if l == r:
            sum_tree[node] = val
            mx_tree[node] = val
        else:
            mid = (l + r) >> 1
            if idx <= mid:
                update(node * 2, l, mid, idx, val)
            else:
                update(node * 2 + 1, mid + 1, r, idx, val)
            pull(node)

    def query_sum(node, l, r, ql, qr):
        if ql > r or qr < l:
            return 0
        if ql <= l and r <= qr:
            return sum_tree[node]
        mid = (l + r) >> 1
        return query_sum(node * 2, l, mid, ql, qr) + query_sum(node * 2 + 1, mid + 1, r, ql, qr)

    def query_max(node, l, r, ql, qr):
        if ql > r or qr < l:
            return -float('inf')
        if ql <= l and r <= qr:
            return mx_tree[node]
        mid = (l + r) >> 1
        left = query_max(node * 2, l, mid, ql, qr)
        right = query_max(node * 2 + 1, mid + 1, r, ql, qr)
        return left if left > right else right

    def find_first(node, l, r, qr, need):
        if l > qr or mx_tree[node] < need:
            return -1
        if l == r:
            return l
        mid = (l + r) >> 1
        left = find_first(node * 2, l, mid, qr, need)
        if left != -1:
            return left
        return find_first(node * 2 + 1, mid + 1, r, qr, need)

    build(1, 0, n - 1)

    def gather(k, max_row):
        if query_max(1, 0, n - 1, 0, max_row) < k:
            return []
        row = find_first(1, 0, n - 1, max_row, k)
        start = m - rem[row]
        rem[row] -= k
        update(1, 0, n - 1, row, rem[row])
        return [row, start]

    def scatter(k, max_row):
        if query_sum(1, 0, n - 1, 0, max_row) < k:
            return False
        while k > 0:
            row = find_first(1, 0, n - 1, max_row, 1)
            take = rem[row] if rem[row] < k else k
            rem[row] -= take
            update(1, 0, n - 1, row, rem[row])
            k -= take
        return True

    return {'gather': gather, 'scatter': scatter}

class TextEditor:
    def __init__(self):
        self.left = []   # characters to the left of the cursor
        self.right = []  # characters to the right of the cursor

    def addText(self, text: str) -> None:
        for ch in text:
            self.left.append(ch)

    def deleteText(self, k: int) -> int:
        cnt = min(k, len(self.left))
        for _ in range(cnt):
            self.left.pop()
        return cnt

    def cursorLeft(self, k: int) -> str:
        move = min(k, len(self.left))
        for _ in range(move):
            self.right.append(self.left.pop())
        return ''.join(self.left[-10:])

    def cursorRight(self, k: int) -> str:
        move = min(k, len(self.right))
        for _ in range(move):
            self.left.append(self.right.pop())
        return ''.join(self.left[-10:])

