        return False
    specials = {'!', '@', '#', '$', '%', '^', '&', '*', '(', ')', '-', '+'}
    has_lower = has_upper = has_digit = has_special = False
    for i in range(len(password)):
        ch = password[i]
        if i > 0 and ch == password[i - 1]:
            return False
        if not has_lower and 'a' <= ch <= 'z':
            has_lower = True
        elif not has_upper and 'A' <= ch <= 'Z':
            has_upper = True
        elif not has_digit and '0' <= ch <= '9':
            has_digit = True
        elif not has_special and ch in specials:
            has_special = True
    return has_lower and has_upper and has_digit and has_special

