def match_substring_after_replacement(s: str, sub: str, mappings: List[Tuple[str, str]]) -> bool:
    replace_map: Dict[str, Set[str]] = {}
    for old_char, new_char in mappings:
        if old_char not in replace_map:
            replace_map[old_char] = set()
        replace_map[old_char].add(new_char)
    n = len(s)
    m = len(sub)
    if m > n:
        return False
    for i in range(n - m + 1):
        ok = True
        for j in range(m):
            a = sub[j]
            b = s[i + j]
            if a == b:
                continue
            possible = replace_map.get(a)
            if possible and b in possible:
                continue
            ok = False
            break
        if ok:
            return True
    return False

