def calculate_tax(brackets: List[List[float]], income: float) -> float:
    tax = 0.0
    lower = 0.0
    for upper, percent in brackets:
        if income <= lower:
            break
        portion = min(income, upper) - lower
        tax += portion * percent / 100.0
        lower = upper
    return round(tax, 2)

