def distribute_cookies(cookies: List[int], k: int) -> int:
    cookies.sort(reverse=True)
    total = sum(cookies)
    max_bag = cookies[0]

    def can_fit(limit: int) -> bool:
        load = [0] * k

        def dfs(idx: int) -> bool:
            if idx == len(cookies):
                return True
            cur = cookies[idx]
            for i in range(k):
                if load[i] + cur <= limit:
                    load[i] += cur
                    if dfs(idx + 1):
                        return True
                    load[i] -= cur
                if load[i] == 0:
                    break
            return False

        return dfs(0)

    low, high = max_bag, total
    while low < high:
        mid = (low + high) // 2
        if can_fit(mid):
            high = mid
        else:
            low = mid + 1
    return low

def max_profit(m: int, n: int, prices: list[tuple[int, int, int]]) -> int:
    price_map = {}
    for h, w, p in prices:
        key = f"{h},{w}"
        cur = price_map.get(key, 0)
        if p > cur:
            price_map[key] = p
    memo = [[None] * (n + 1) for _ in range(m + 1)]
    def dfs(h: int, w: int) -> int:
        if memo[h][w] is not None:
            return memo[h][w]
        best = price_map.get(f"{h},{w}", 0)
        for cut in range(1, w):
            left = dfs(h, cut)
            right = dfs(h, w - cut)
            combined = left + right
            if combined > best:
                best = combined
        for cut in range(1, h):
            top = dfs(cut, w)
            bottom = dfs(h - cut, w)
            combined = top + bottom
            if combined > best:
                best = combined
        memo[h][w] = best
        return best
    return dfs(m, n)

