def distinct_names(ideas: List[str]) -> int:
    groups = [set() for _ in range(26)]
    for w in ideas:
        first = ord(w[0]) - 97
        suffix = w[1:]
        groups[first].add(suffix)

    answer = 0
    for i in range(26):
        if not groups[i]:
            continue
        for j in range(i + 1, 26):
            if not groups[j]:
                continue
            if len(groups[i]) < len(groups[j]):
                smaller, larger = groups[i], groups[j]
            else:
                smaller, larger = groups[j], groups[i]
            common = sum(1 for s in smaller if s in larger)
            cnt_i = len(groups[i])
            cnt_j = len(groups[j])
            answer += (cnt_i - common) * (cnt_j - common) * 2
    return answer

