def count_unreachable_pairs(n: int, edges: List[Tuple[int, int]]) -> int:
    parent = list(range(n))
    size = [1] * n

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a: int, b: int) -> None:
        ra = find(a)
        rb = find(b)
        if ra == rb:
            return
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        size[ra] += size[rb]

    for u, v in edges:
        union(u, v)

    comp_size = {}
    for i in range(n):
        root = find(i)
        comp_size[root] = comp_size.get(root, 0) + 1

    result = 0
    remaining = n
    for sz in comp_size.values():
        remaining -= sz
        result += sz * remaining
    return result

def count_distinct_roll_sequences(n):
    MOD = 1000000007
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a
    if n == 1:
        return 6
    dp = {}
    for a in range(1, 7):
        for b in range(1, 7):
            if a == b or gcd(a, b) != 1:
                continue
            key = (b, a)
            dp[key] = dp.get(key, 0) + 1
    for length in range(3, n + 1):
        ndp = {}
        for (prev, prevprev), cnt in dp.items():
            for v in range(1, 7):
                if v == prev or v == prevprev or gcd(v, prev) != 1:
                    continue
                nkey = (v, prev)
                ndp[nkey] = (ndp.get(nkey, 0) + cnt) % MOD
        dp = ndp
    return sum(dp.values()) % MOD

