def spiral_matrix(m, n, head):
    matrix = [[-1] * n for _ in range(m)]
    top = 0
    bottom = m - 1
    left = 0
    right = n - 1
    node = head
    while top <= bottom and left <= right:
        for col in range(left, right + 1):
            if node:
                matrix[top][col] = node.val
                node = node.next
        top += 1
        for row in range(top, bottom + 1):
            if node:
                matrix[row][right] = node.val
                node = node.next
        right -= 1
        if top <= bottom:
            for col in range(right, left - 1, -1):
                if node:
                    matrix[bottom][col] = node.val
                    node = node.next
            bottom -= 1
        if left <= right:
            for row in range(bottom, top - 1, -1):
                if node:
                    matrix[row][left] = node.val
                    node = node.next
            left += 1
    return matrix

def people_aware_of_secret(n: int, delay: int, forget: int) -> int:
    MOD = 1_000_000_007
    dp = [0] * (n + 1)
    start = [0] * (n + 1)
    end = [0] * (n + 1)

    dp[1] = 1
    if 1 + delay <= n:
        start[1 + delay] = 1
    if 1 + forget <= n:
        end[1 + forget] = 1

    active = 0

    for day in range(2, n + 1):
        active = (active + start[day]) % MOD
        active = (active - end[day] + MOD) % MOD
        dp[day] = active

        act_day = day + delay
        if act_day <= n:
            start[act_day] = (start[act_day] + dp[day]) % MOD
        fin_day = day + forget
        if fin_day <= n:
            end[fin_day] = (end[fin_day] + dp[day]) % MOD

    result = 0
    for i in range(1, n + 1):
        if i + forget > n:
            result = (result + dp[i]) % MOD
    return result

def decode_message(key: str, message: str) -> str:
