    for ch in key:
        if ch == ' ':
            continue
        if ch not in cipher_to_plain:
            cipher_to_plain[ch] = chr(next_plain_code)
            next_plain_code += 1
    decoded_chars = []
    for ch in message:
        decoded_chars.append(' ' if ch == ' ' else cipher_to_plain[ch])
    return ''.join(decoded_chars)

