def smallest_infinite_set():
    heap = []
    in_heap = set()
    next_num = 1

    def heap_push(val):
        heap.append(val)
        i = len(heap) - 1
        while i > 0:
            p = (i - 1) >> 1
            if heap[p] <= heap[i]:
                break
            heap[p], heap[i] = heap[i], heap[p]
            i = p

    def heap_pop():
        min_val = heap[0]
        last = heap.pop()
        if heap:
            heap[0] = last
            i = 0
            while True:
                l = i * 2 + 1
                r = i * 2 + 2
                smallest = i
                if l < len(heap) and heap[l] < heap[smallest]:
                    smallest = l
                if r < len(heap) and heap[r] < heap[smallest]:
                    smallest = r
                if smallest == i:
                    break
                heap[i], heap[smallest] = heap[smallest], heap[i]
                i = smallest
        return min_val

    def pop_smallest():
        nonlocal next_num
        if heap:
            val = heap_pop()
            in_heap.remove(val)
            return val
        val = next_num
        next_num += 1
        return val

    def add_back(num):
        if num < next_num and num not in in_heap:
            heap_push(num)
            in_heap.add(num)

    return {"pop_smallest": pop_smallest, "add_back": add_back}

