MOD = 10**9 + 7

def count_ideal_arrays(n: int, max_value: int) -> int:
    max_fact = n + max_value
    fact: List[int] = [1] * (max_fact + 1)
    for i in range(1, max_fact + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv_fact: List[int] = [1] * (max_fact + 1)
    inv_fact[max_fact] = pow(fact[max_fact], MOD - 2, MOD)
    for i in range(max_fact, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % MOD

    def comb(a: int, b: int) -> int:
        if b < 0 or b > a:
            return 0
        return fact[a] * inv_fact[b] % MOD * inv_fact[a - b] % MOD

    spf: List[int] = list(range(max_value + 1))
    limit = int(max_value ** 0.5) + 1
    for i in range(2, limit):
        if spf[i] == i:
            step = i
            start = i * i
            for j in range(start, max_value + 1, step):
                if spf[j] == j:
                    spf[j] = i

    ans = 0
    for v in range(1, max_value + 1):
        x = v
        ways = 1
        while x > 1:
            p = spf[x]
            e = 0
            while x % p == 0:
                x //= p
                e += 1
            ways = ways * comb(e + n - 1, e) % MOD
        ans = (ans + ways) % MOD

    return ans

