        s = 0
        while n > 0:
            s += n % 10
            n //= 10
        return s

    top: dict[int, list[int]] = {}
    best = -1

    for value in nums:
        d = digit_sum(value)

        if d not in top:
            top[d] = [value, -float('inf')]
        else:
            max1, max2 = top[d]
            best = max(best, max1 + value)
            if value > max1:
                top[d] = [value, max1]
            elif value > max2:
