def shortest_impossible_sequence(rolls: List[int], k: int) -> int:
    n = len(rolls)
    pos: List[List[int]] = [[] for _ in range(k + 1)]
    for i, v in enumerate(rolls):
        pos[v].append(i)

    for v in range(1, k + 1):
        if not pos[v]:
            return 1

    L = 2
    while True:
        if L > n:
            return L

        total_ld = 1.0
        for _ in range(L):
            total_ld *= float(k)

        comb_ld = 1.0
        for i in range(1, L + 1):
            comb_ld = comb_ld * (n - i + 1) / i
            if comb_ld > total_ld:
                break

        if total_ld > comb_ld:
            return L

        total = k ** L
        seq = [0] * L
        for id_ in range(total):
            tmp = id_
            for i in range(L - 1, -1, -1):
                seq[i] = (tmp % k) + 1
                tmp //= k

            cur = -1
            ok = True
            for val in seq:
                vec = pos[val]
                idx = bisect.bisect_right(vec, cur)
                if idx == len(vec):
                    ok = False
                    break
                cur = vec[idx]
            if not ok:
                return L

        L += 1
    return -1

def number_containers():
    index_to_num = {}
    num_to_heap = {}

    class MinHeap:
        def __init__(self):
            self.arr = []
        def peek(self):
            return self.arr[0]
        def push(self, val):
            a = self.arr
            a.append(val)
            i = len(a) - 1
            while i > 0:
                p = (i - 1) >> 1
                if a[p] <= a[i]: break
                a[p], a[i] = a[i], a[p]
                i = p
        def pop(self):
            a = self.arr
            if not a: return None
            root = a[0]
            last = a.pop()
            if a:
                a[0] = last
                i = 0
                while True:
                    l, r = i*2+1, i*2+2
                    smallest = i
                    if l < len(a) and a[l] < a[smallest]: smallest = l
                    if r < len(a) and a[r] < a[smallest]: smallest = r
                    if smallest == i: break
                    a[i], a[smallest] = a[smallest], a[i]
                    i = smallest
            return root
        def size(self):
            return len(self.arr)

    def add(number, index):
        # FIXED: original special-cased number==0 as a delete signal, silently failing
        # to store a legitimate 0 value - see js_algo fix note.
        index_to_num[index] = number
        if number not in num_to_heap:
            num_to_heap[number] = MinHeap()
        num_to_heap[number].push(index)

    def query(number):
        heap = num_to_heap.get(number)
        if not heap: return -1
        while heap.size() and index_to_num.get(heap.peek()) != number:
            heap.pop()
        return heap.peek() if heap.size() else -1

    return {"add": add, "query": query}

