def longest_cycle(edges: List[int]) -> int:
    n = len(edges)
    visited = [False] * n
    max_len = -1

    for start in range(n):
        if visited[start]:
            continue

        cur = start
        step = 0
        step_index: dict[int, int] = {}
        path: list[int] = []

        while cur != -1 and not visited[cur]:
            if cur in step_index:
                cycle_len = step - step_index[cur]
                if cycle_len > max_len:
                    max_len = cycle_len
                break
            step_index[cur] = step
            path.append(cur)
            cur = edges[cur]
            step += 1

        for node in path:
            visited[node] = True

    return max_len

