import heapq

def build_matrix(k: int, row_conditions: List[List[int]], col_conditions: List[List[int]]) -> List[List[int]]:
    def topo_sort(k: int, edges: List[List[int]]) -> List[int] | None:
        adj = [[] for _ in range(k + 1)]
        indeg = [0] * (k + 1)
        seen = set()
        for u, v in edges:
            if (u, v) in seen:
                continue
            seen.add((u, v))
            adj[u].append(v)
            indeg[v] += 1
        q = collections.deque([i for i in range(1, k + 1) if indeg[i] == 0])
        order = []
        while q:
            node = q.popleft()
            order.append(node)
            for nb in adj[node]:
                indeg[nb] -= 1
                if indeg[nb] == 0:
                    q.append(nb)
        if len(order) != k:
            return None
        return order

    # first obtain column order (deterministic using smallest node first)
    col_order = topo_sort(k, col_conditions)
    if col_order is None:
        return []
    col_pos = {num: idx for idx, num in enumerate(col_order)}

    # row order with tie‑breaker based on column positions
    adj = [[] for _ in range(k + 1)]
    indeg = [0] * (k + 1)
    seen = set()
    for u, v in row_conditions:
        if (u, v) in seen:
            continue
        seen.add((u, v))
        adj[u].append(v)
        indeg[v] += 1

    heap: List[tuple[int, int]] = []
    for i in range(1, k + 1):
        if indeg[i] == 0:
            heapq.heappush(heap, (col_pos[i], i))

    row_order: List[int] = []
    while heap:
        _, node = heapq.heappop(heap)
        row_order.append(node)
        for nb in adj[node]:
            indeg[nb] -= 1
            if indeg[nb] == 0:
                heapq.heappush(heap, (col_pos[nb], nb))

    if len(row_order) != k:
        return []

    row_pos = {num: idx for idx, num in enumerate(row_order)}

    matrix = [[0] * k for _ in range(k)]
    for num in range(1, k + 1):
        r = row_pos[num]
        c = col_pos[num]
        matrix[r][c] = num

    return matrix

