def max_rows_covered(matrix: list[list[int]], num_select: int) -> int:
    m = len(matrix)
    n = len(matrix[0])
    row_masks = [0] * m
    for i in range(m):
        mask = 0
        for j in range(n):
            if matrix[i][j] == 1:
                mask |= (1 << j)
        row_masks[i] = mask
    best = 0
    def dfs(start: int, chosen_mask: int, chosen_cnt: int):
        nonlocal best
        if chosen_cnt == num_select:
            covered = 0
            for i in range(m):
                if (row_masks[i] & ~chosen_mask) == 0:
                    covered += 1
            if covered > best:
                best = covered
            return
        for col in range(start, n):
            dfs(col + 1, chosen_mask | (1 << col), chosen_cnt + 1)
    dfs(0, 0, 0)
    return best

