def most_booked(n: int, meetings: List[List[int]]) -> int:
    meetings.sort(key=lambda x: x[0])

    def push_heap(heap, node, cmp):
        heap.append(node)
        i = len(heap) - 1
        while i > 0:
            p = (i - 1) >> 1
            if cmp(heap[p], node) <= 0:
                break
            heap[i] = heap[p]
            i = p
        heap[i] = node

    def pop_heap(heap, cmp):
        if not heap:
            return None
        top = heap[0]
        last = heap.pop()
        if heap:
            i = 0
            while True:
                left = i * 2 + 1
                if left >= len(heap):
                    break
                right = left + 1
                smallest = left
                if right < len(heap) and cmp(heap[right], heap[left]) < 0:
                    smallest = right
                if cmp(heap[smallest], last) >= 0:
                    break
                heap[i] = heap[smallest]
                i = smallest
            heap[i] = last
        return top

    free_rooms = []
    for i in range(n):
        push_heap(free_rooms, i, lambda a, b: a - b)

    busy_rooms = []

    count = [0] * n

    def cmp_busy(a, b):
        if a["end"] != b["end"]:
            return a["end"] - b["end"]
        return a["room"] - b["room"]

    for start, end in meetings:
        while busy_rooms and busy_rooms[0]["end"] <= start:
            freed = pop_heap(busy_rooms, cmp_busy)
            push_heap(free_rooms, freed["room"], lambda a, b: a - b)

        if free_rooms:
            room = pop_heap(free_rooms, lambda a, b: a - b)
            count[room] += 1
            push_heap(busy_rooms, {"end": end, "room": room}, cmp_busy)
        else:
            earliest = pop_heap(busy_rooms, cmp_busy)
            duration = end - start
            new_end = earliest["end"] + duration
            count[earliest["room"]] += 1
            push_heap(busy_rooms, {"end": new_end, "room": earliest["room"]}, cmp_busy)

    best_room = 0
    for i in range(1, n):
        if count[i] > count[best_room]:
            best_room = i
    return best_room

