def tiling_rectangle(n: int, m: int) -> int:
    if n == m:
        return 1

    # Ensure n <= m to reduce symmetry
    if n > m:
        n, m = m, n

    board: List[List[bool]] = [[False] * m for _ in range(n)]
    best = [float('inf')]

    def can_place(x: int, y: int, size: int) -> bool:
        if x + size > n or y + size > m:
            return False
        for i in range(x, x + size):
            for j in range(y, y + size):
                if board[i][j]:
                    return False
        return True

    def set_place(x: int, y: int, size: int, val: bool) -> None:
        for i in range(x, x + size):
            for j in range(y, y + size):
                board[i][j] = val

    def dfs(placed: int) -> None:
        # Prune if already worse than known best
        if placed >= best[0]:
            return

        # Find first empty cell
        for i in range(n):
            for j in range(m):
                if not board[i][j]:
                    x, y = i, j
                    break
            else:
                continue
            break
        else:
            # All filled
            best[0] = placed
            return

        # Try largest possible square at (x, y)
        max_len = min(n - x, m - y)
        for size in range(max_len, 0, -1):
            if can_place(x, y, size):
                set_place(x, y, size, True)
                dfs(placed + 1)
                set_place(x, y, size, False)

    dfs(0)
    return int(best[0])

