def _dfs(grid: List[List[int]], i: int, j: int) -> None:
    if i < 0 or i >= len(grid) or j < 0 or j >= len(grid[0]) or grid[i][j] != 0:
        return
    grid[i][j] = 1
    _dfs(grid, i + 1, j)
    _dfs(grid, i - 1, j)
    _dfs(grid, i, j + 1)
    _dfs(grid, i, j - 1)

