    if not grid or not grid[0]:
        return 0
    rows, cols = len(grid), len(grid[0])
    for i in range(rows):
        _dfs(grid, i, 0)
        _dfs(grid, i, cols - 1)
    for j in range(cols):
        _dfs(grid, 0, j)
        _dfs(grid, rows - 1, j)
    count = 0
    for i in range(1, rows - 1):
        for j in range(1, cols - 1):
            if grid[i][j] == 0:
                count += 1
                _dfs(grid, i, j)
    return count

