def reconstruct_matrix(upper: int, lower: int, colsum: List[int]) -> List[List[int]]:
    n = len(colsum)
    top = [0] * n
    bottom = [0] * n
    ones_idx: List[int] = []

    for i, val in enumerate(colsum):
        if val == 2:
            top[i] = 1
            bottom[i] = 1
            upper -= 1
            lower -= 1
        elif val == 1:
            ones_idx.append(i)
        elif val == 0:
            continue
        else:
            return []  # invalid colsum value

        if upper < 0 or lower < 0:
            return []

    for i in ones_idx:
        if upper > 0:
            top[i] = 1
            upper -= 1
        else:
            bottom[i] = 1
            lower -= 1

    if upper == 0 and lower == 0:
        return [top, bottom]
    return []  # impossible to satisfy constraints

