def max_score_words(words: List[str], letters: List[str], score: List[int]) -> int:
    letter_count: Dict[str, int] = {}
    for letter in letters:
        letter_count[letter] = letter_count.get(letter, 0) + 1

    max_score = 0

    def backtrack(index: int, current_score: int, current_letter_count: Dict[str, int]) -> None:
        nonlocal max_score
        if current_score > max_score:
            max_score = current_score
        for i in range(index, len(words)):
            word = words[i]
            word_score = 0
            word_letter_count: Dict[str, int] = {}
            for letter in word:
                word_letter_count[letter] = word_letter_count.get(letter, 0) + 1
                word_score += score[ord(letter) - 97]
            is_valid = True
            for letter, cnt in word_letter_count.items():
                if current_letter_count.get(letter, 0) < cnt:
                    is_valid = False
                    break
            if is_valid:
                new_letter_count = dict(current_letter_count)
                for letter, cnt in word_letter_count.items():
                    new_letter_count[letter] = new_letter_count.get(letter, 0) - cnt
                backtrack(i + 1, current_score + word_score, new_letter_count)

    backtrack(0, 0, letter_count)
    return max_score

