        self.val = val
        self.left = left
        self.right = right

def reverse_odd_levels(root: Optional[TreeNode]) -> Optional[TreeNode]:
    if not root:
        return None
    queue = deque([root])
    level = 0
    while queue:
        level_size = len(queue)
        current_level_nodes = []
        for _ in range(level_size):
            node = queue.popleft()
            current_level_nodes.append(node)
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        if level % 2 == 1:
            i, j = 0, len(current_level_nodes) - 1
            while i < j:
                current_level_nodes[i].val, current_level_nodes[j].val = (
                    current_level_nodes[j].val,
                    current_level_nodes[i].val,
                )
                i += 1
                j -= 1
        level += 1
    return root

