def can_equal_frequency(word: str) -> bool:
    # count each character
    char_cnt: Dict[str, int] = {}
    for ch in word:
        char_cnt[ch] = char_cnt.get(ch, 0) + 1

    # count how many characters have each frequency
    freq_cnt: Dict[int, int] = {}
    for cnt in char_cnt.values():
        freq_cnt[cnt] = freq_cnt.get(cnt, 0) + 1

    # if only one distinct frequency
    if len(freq_cnt) == 1:
        # all frequencies equal; can only succeed if that frequency is 1
        # (removing any one character leaves the rest unchanged)
        return 1 in freq_cnt

    # if more than two distinct frequencies, impossible
    if len(freq_cnt) > 2:
        return False

    # exactly two distinct frequencies
    (f1, c1), (f2, c2) = freq_cnt.items()

    # case 1: one character occurs once and can be removed entirely
    if (f1 == 1 and c1 == 1) or (f2 == 1 and c2 == 1):
        return True

    # case 2: frequencies differ by one and the higher frequency occurs only once
    if abs(f1 - f2) == 1:
        if (f1 > f2 and c1 == 1) or (f2 > f1 and c2 == 1):
            return True

    return False

