def number_of_good_paths(vals: List[int], edges: List[Tuple[int, int]]) -> int:
    n = len(vals)
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    parent = list(range(n))
    size = [1] * n

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a: int, b: int) -> None:
        ra, rb = find(a), find(b)
        if ra == rb:
            return
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        size[ra] += size[rb]

    # nodes grouped by value
    nodes_by_val = {}
    for i, v in enumerate(vals):
        nodes_by_val.setdefault(v, []).append(i)

    answer = 0
    for value in sorted(nodes_by_val):
        # union current value nodes with neighbors of <= value
        for node in nodes_by_val[value]:
            for nb in graph[node]:
                if vals[nb] <= value:
                    union(node, nb)

        # count roots for nodes with this exact value
        root_count = {}
        for node in nodes_by_val[value]:
            r = find(node)
            root_count[r] = root_count.get(r, 0) + 1

        for cnt in root_count.values():
            answer += cnt * (cnt - 1) // 2

    return answer + n
