def delete_string(s: str) -> int:
    n = len(s)
    # lcp[i][j] = length of longest common prefix of s[i:] and s[j:]
    lcp: List[List[int]] = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        si = s[i]
        row_i = lcp[i]
        row_ip1 = lcp[i + 1]
        for j in range(n - 1, -1, -1):
            if si == s[j]:
                row_i[j] = 1 + row_ip1[j + 1]
            else:
                row_i[j] = 0

    dp: List[int] = [0] * (n + 1)  # dp[i] = max operations to delete s[i:]
    dp[n] = 0  # empty string needs 0 operations
    for i in range(n - 1, -1, -1):
        # baseline: delete the whole remaining suffix in one operation
        best = 1
        max_len = (n - i) // 2
        for length in range(1, max_len + 1):
            if lcp[i][i + length] >= length:
                # we can delete the first 'length' characters and continue from i+length
                best = max(best, 1 + dp[i + length])
        dp[i] = best

    return dp[0]

