def count_paths(grid, k):
    m = len(grid)
    n = len(grid[0])
    # dp[j][r]: number of ways to reach column j in current row with remainder r
    dp = [[0] * k for _ in range(n)]
    start_rem = grid[0][0] % k
    dp[0][start_rem] = 1

    for i in range(m):
        for j in range(n):
            if i == 0 and j == 0:
                continue
            cur = [0] * k
            val = grid[i][j] % k
            if i > 0:
                top = dp[j]
                for r in range(k):
                    if top[r]:
                        nr = (r + val) % k
                        cur[nr] = (cur[nr] + top[r]) % MOD
            if j > 0:
                left = dp[j - 1]
                for r in range(k):
                    if left[r]:
                        nr = (r + val) % k
                        cur[nr] = (cur[nr] + left[r]) % MOD
            dp[j] = cur
    return dp[-1][0] % MOD

