def count_subarrays_with_median_k(nums: List[int], k: int) -> int:
    try:
        idx = nums.index(k)
    except ValueError:
        return 0

    # balances for suffixes to the right of idx
    right_counts: dict[int, int] = defaultdict(int)
    balance = 0
    right_counts[0] = 1  # empty suffix
    for i in range(idx + 1, len(nums)):
        if nums[i] > k:
            balance += 1
        elif nums[i] < k:
            balance -= 1
        # equal to k contributes 0
        right_counts[balance] += 1

    answer = 0
    left_balance = 0
    # iterate from idx down to 0 (including idx)
    for i in range(idx, -1, -1):
        if i != idx:
            if nums[i] > k:
                left_balance += 1
            elif nums[i] < k:
                left_balance -= 1
        # total balance must be 0 or 1
        answer += right_counts.get(-left_balance, 0) + right_counts.get(1 - left_balance, 0)

    return answer

