def magnificent_sets(n: int, edges: list[list[int]]) -> int:
    adj = [[] for _ in range(n + 1)]
    for e in edges:
        u, v = e[0], e[1]
        adj[u].append(v)
        adj[v].append(u)

    visited = [False] * (n + 1)
    color = [-1] * (n + 1)
    total_groups = 0

    for i in range(1, n + 1):
        if visited[i]:
            continue

        comp = []
        queue = [i]
        visited[i] = True
        color[i] = 0
        comp.append(i)
        bipartite = True
        q_idx = 0
        while q_idx < len(queue):
            u = queue[q_idx]
            q_idx += 1
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    color[v] = color[u] ^ 1
                    queue.append(v)
                    comp.append(v)
                elif color[v] == color[u]:
                    bipartite = False
        if not bipartite:
            return -1

        diameter = 0
        for start in comp:
            dist = [-1] * (n + 1)
            q = [start]
            dist[start] = 0
            idx = 0
            while idx < len(q):
                u = q[idx]
                idx += 1
                for v in adj[u]:
                    if dist[v] == -1:
                        dist[v] = dist[u] + 1
                        q.append(v)
            for node in comp:
                if dist[node] > diameter:
                    diameter = dist[node]

        total_groups += diameter + 1

    return total_groups

