def longest_square_streak(nums: List[int]) -> int:
    if not nums:
        return -1
    nums.sort()
    dp = {}
    max_len = 1
    for x in nums:
        root = math.isqrt(x)
        if root * root == x and root in dp:
            dp[x] = dp[root] + 1
        else:
            dp[x] = 1
        if dp[x] > max_len:
            max_len = dp[x]
    return max_len if max_len >= 2 else -1

