def min_score(n: int, roads: List[List[int]]):
    adj = [[] for _ in range(n + 1)]
    for u, v, w in roads:
        adj[u].append((v, w))
        adj[v].append((u, w))
    visited = [False] * (n + 1)
    stack = [1]
    visited[1] = True
    min_score = float('inf')
    while stack:
        node = stack.pop()
        for nbr, w in adj[node]:
            if w < min_score:
                min_score = w
            if not visited[nbr]:
                visited[nbr] = True
                stack.append(nbr)
    return min_score

from typing import List

def minimum_total_cost(nums1: List[int], nums2: List[int]) -> int:
    n = len(nums1)
    INF = 4_000_000_000_000_000_000
    cost = [[INF] * n for _ in range(n)]
    for p in range(n):
        for i in range(n):
            if nums1[p] == nums2[i]:
                continue
            if p == i:
                cost[p][i] = 0
            else:
                cost[p][i] = p + i

    u = [0] * (n + 1)
    v = [0] * (n + 1)
    p_match = [0] * (n + 1)
    way = [0] * (n + 1)

    for i in range(1, n + 1):
        p_match[0] = i
        j0 = 0
        minv = [INF] * (n + 1)
        used = [False] * (n + 1)
        while True:
            used[j0] = True
            i0 = p_match[j0]
            delta = INF
            j1 = 0
            for j in range(1, n + 1):
                if used[j]:
                    continue
                cur = cost[i0 - 1][j - 1] - u[i0] - v[j]
                if cur < minv[j]:
                    minv[j] = cur
                    way[j] = j0
                if minv[j] < delta:
                    delta = minv[j]
                    j1 = j
            for j in range(0, n + 1):
                if used[j]:
                    u[p_match[j]] += delta
                    v[j] -= delta
                else:
                    minv[j] -= delta
            j0 = j1
            if p_match[j0] == 0:
                break
        while True:
            j1 = way[j0]
            p_match[j0] = p_match[j1]
            j0 = j1
            if j0 == 0:
                break

    assignment = [-1] * n
    for j in range(1, n + 1):
        if p_match[j] != 0:
            assignment[p_match[j] - 1] = j - 1

    total = 0
    for i in range(n):
        c = cost[i][assignment[i]]
        if c >= INF // 2:
            return -1
        total += c
    return total // 2

