def min_cost(stones: List[int]) -> int:
    n = len(stones)
    if n <= 2:
        return stones[-1] - stones[0]
    max_gap = 0
    for i in range(n - 2):
        gap = stones[i + 2] - stones[i]
        if gap > max_gap:
            max_gap = gap
    return max_gap

