def memory_allocator(n):
    free = [{'start': 0, 'end': n - 1}]
    allocations = {}

    def free_interval(start, size):
        new_start = start
        new_end = start + size - 1
        i = 0
        while i < len(free) and free[i]['end'] < new_start - 1:
            i += 1
        if i > 0 and free[i - 1]['end'] + 1 >= new_start:
            new_start = free[i - 1]['start']
            new_end = max(new_end, free[i - 1]['end'])
            free.pop(i - 1)
            i -= 1
        while i < len(free) and free[i]['start'] <= new_end + 1:
            new_start = min(new_start, free[i]['start'])
            new_end = max(new_end, free[i]['end'])
            free.pop(i)
        free.insert(i, {'start': new_start, 'end': new_end})

    def allocate(size, mID):
        for i, interval in enumerate(free):
            length = interval['end'] - interval['start'] + 1
            if length >= size:
                alloc_start = interval['start']
                if length == size:
                    free.pop(i)
                else:
                    interval['start'] += size
                allocations.setdefault(mID, []).append((alloc_start, size))
                return alloc_start
        return -1

    def free_memory(mID):
        blocks = allocations.pop(mID, None)
        if not blocks:
            return 0
        freed = 0
        for start, size in blocks:
            free_interval(start, size)
            freed += size
        return freed

    return {'allocate': allocate, 'freeMemory': free_memory}

