def can_make_degrees_even(n: int, edges: List[List[int]]) -> bool:
    degree = [0] * (n + 1)
    edge_set: Set[Tuple[int, int]] = set()
    for u, v in edges:
        degree[u] += 1
        degree[v] += 1
        if u > v:
            u, v = v, u
        edge_set.add((u, v))

    odd_nodes = [i for i in range(1, n + 1) if degree[i] % 2 == 1]
    cnt = len(odd_nodes)

    if cnt == 0:
        return True
    if cnt == 2:
        a, b = odd_nodes
        if a > b:
            a, b = b, a
        if (a, b) not in edge_set:
            return True
        # need a third node c such that both edges are missing
        for c in range(1, n + 1):
            if c == a or c == b:
                continue
            ac = (a, c) if a < c else (c, a)
            bc = (b, c) if b < c else (c, b)
            if ac not in edge_set and bc not in edge_set:
                return True
        return False
    if cnt == 4:
        o = odd_nodes
        pairings = [((0, 1), (2, 3)), ((0, 2), (1, 3)), ((0, 3), (1, 2))]
        for (i1, j1), (i2, j2) in pairings:
            u1, v1 = o[i1], o[j1]
            if u1 > v1:
                u1, v1 = v1, u1
            u2, v2 = o[i2], o[j2]
            if u2 > v2:
                u2, v2 = v2, u2
            if (u1, v1) not in edge_set and (u2, v2) not in edge_set:
                return True
        return False
    return False

