def count_similar_pairs(words: List[str]) -> int:
    freq = {}
    for w in words:
        mask = 0
        for ch in w:
            mask |= 1 << (ord(ch) - 97)
        freq[mask] = freq.get(mask, 0) + 1
    pairs = 0
    for cnt in freq.values():
        pairs += cnt * (cnt - 1) // 2
    return pairs

def smallest_value(n: int) -> int:
    """Return the smallest value obtained by repeatedly replacing n with the sum of its prime factors."""
    def sum_prime_factors(x: int) -> int:
        total = 0
        d = 2
        while d * d <= x:
            while x % d == 0:
                total += d
                x //= d
            d += 1 if d == 2 else 2  # after 2, check only odd numbers
        if x > 1:
            total += x
        return total

    cur = n
    best = n
    while True:
        nxt = sum_prime_factors(cur)
        if nxt == cur:
            break
        cur = nxt
        if cur < best:
            best = cur
    return best
