def capture_forts(forts: List[int]) -> int:
    max_captured = 0
    prev_idx = -1
    for i, cur in enumerate(forts):
        if cur == 0:
            continue
        if prev_idx != -1 and cur != forts[prev_idx]:
            captured = i - prev_idx - 1
            if captured > max_captured:
                max_captured = captured
        prev_idx = i
    return max_captured

def top_students(positive_feedback, negative_feedback, report, student_id, k):
    pos_set = set(positive_feedback)
    neg_set = set(negative_feedback)
    points = {}
    for i in range(len(report)):
        sid = student_id[i]
        words = report[i].split(' ')
        score = 0
        for w in words:
            if w in pos_set:
                score += 3
            elif w in neg_set:
                score -= 1
        points[sid] = points.get(sid, 0) + score
    students = [{'id': sid, 'pt': pt} for sid, pt in points.items()]
    students.sort(key=lambda x: (-x['pt'], x['id']))
    result = []
    for i in range(min(k, len(students))):
        result.append(students[i]['id'])
    return result

