def maximum_tastiness(price: List[int], k: int) -> int:
    price.sort()
    def can_place(dist: int) -> bool:
        count = 1
        last = price[0]
        for p in price[1:]:
            if p - last >= dist:
                count += 1
                last = p
                if count == k:
                    return True
        return False
    low = 0
    high = price[-1] - price[0]
    while low < high:
        mid = (low + high + 1) // 2
        if can_place(mid):
            low = mid
        else:
            high = mid - 1
    return low

def min_minutes(s: str, k: int) -> int:
    n = len(s)
    total_a = s.count('a')
    total_b = s.count('b')
    total_c = s.count('c')
    if total_a < k or total_b < k or total_c < k:
        return -1
    allowed_a = total_a - k
    allowed_b = total_b - k
    allowed_c = total_c - k

    left = 0
    cnt_a = cnt_b = cnt_c = 0
    max_len = 0

    for right in range(n):
        ch = s[right]
        if ch == 'a':
            cnt_a += 1
        elif ch == 'b':
            cnt_b += 1
        else:
            cnt_c += 1

        while cnt_a > allowed_a or cnt_b > allowed_b or cnt_c > allowed_c:
            ch_left = s[left]
            if ch_left == 'a':
                cnt_a -= 1
            elif ch_left == 'b':
                cnt_b -= 1
            else:
                cnt_c -= 1
            left += 1

        current_len = right - left + 1
        if current_len > max_len:
            max_len = current_len

    return n - max_len

def count_anagrams(s: str) -> int:
    MOD = 1000000007
    words = s.split(' ')
    max_len = max(len(w) for w in words)
    fact = [1] * (max_len + 1)
    for i in range(1, max_len + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv_fact = [1] * (max_len + 1)
    inv_fact[max_len] = pow(fact[max_len], MOD - 2, MOD)
    for i in range(max_len, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % MOD
    ans = 1
    for w in words:
        ways = fact[len(w)]
        freq = {}
        for ch in w:
            freq[ch] = freq.get(ch, 0) + 1
        for c in freq.values():
            ways = ways * inv_fact[c] % MOD
        ans = ans * ways % MOD
    return ans

