def distinct_prime_factors(nums: List[int]) -> int:
    prime_set = set()
    for value in nums:
        n = value
        if n < 2:
            continue
        while n % 2 == 0:
            prime_set.add(2)
            n //= 2
        f = 3
        while f * f <= n:
            while n % f == 0:
                prime_set.add(f)
                n //= f
            f += 2
        if n > 1:
            prime_set.add(n)
    return len(prime_set)

