def shortest_distance(words: List[str], target: str, start_index: int) -> int:
    n = len(words)
    min_dist = float('inf')
    for i in range(n):
        if words[i] != target:
            continue
        clockwise = (i - start_index + n) % n
        counter = (start_index - i + n) % n
        dist = min(clockwise, counter)
        if dist < min_dist:
            min_dist = dist
    return -1 if min_dist == float('inf') else min_dist

def min_partitions(s: str, k: int) -> int:
    for ch in s:
        d = ord(ch) - 48
        if d > k:
            return -1
    parts = 0
    cur = 0
    for ch in s:
        d = ord(ch) - 48
        nxt = cur * 10 + d
        if nxt > k:
            parts += 1
            cur = d
        else:
            cur = nxt
    return 0 if len(s) == 0 else parts + 1

