def number_of_great_partitions(nums: List[int], k: int) -> int:
    MOD = 1000000007
    total = sum(nums)
    if total < 2 * k:
        return 0
    dp = [0] * (total + 1)
    dp[0] = 1
    for x in nums:
        for s in range(total, x - 1, -1):
            dp[s] = (dp[s] + dp[s - x]) % MOD
    ans = 0
    for s in range(k, total - k + 1):
        ans = (ans + dp[s]) % MOD
    return ans

