def max_min_power(stations: List[int], r: int, k: int) -> int:
    n = len(stations)
    # prefix sums for initial power calculation
    pref = [0] * (n + 1)
    for i, val in enumerate(stations):
        pref[i + 1] = pref[i] + val

    init_power = [0] * n
    for i in range(n):
        left = i - r
        if left < 0:
            left = 0
        right = i + r
        if right >= n:
            right = n - 1
        init_power[i] = pref[right + 1] - pref[left]

    def feasible(target: int) -> bool:
        diff = [0] * (n + 1)  # difference array for added stations effect
        cur_add = 0
        used = 0
        for i in range(n):
            cur_add += diff[i]
            total = init_power[i] + cur_add
            if total < target:
                need = target - total
                used += need
                if used > k:
                    return False
                cur_add += need
                pos = i + r
                if pos >= n:
                    pos = n - 1
                end = pos + r
                if end >= n:
                    end = n - 1
                diff[end + 1] -= need
        return True

    low = 0
    high = max(init_power) + k
    while low < high:
        mid = (low + high + 1) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid - 1
    return low

def data_stream():
    last_value = None
    run_length = 0

    def next_(val: int) -> None:
        nonlocal last_value, run_length
        if val == last_value:
            run_length += 1
        else:
            last_value = val
            run_length = 1

    def consecutive(k: int, value: int) -> bool:
        return value == last_value and run_length >= k

    return {"next": next_, "consecutive": consecutive}

