def closest_primes(left: int, right: int) -> List[int]:
    if right < 2 or left > right:
        return [-1, -1]
    is_prime = [True] * (right + 1)
    if right >= 0:
        is_prime[0] = False
    if right >= 1:
        is_prime[1] = False
    i = 2
    while i * i <= right:
        if is_prime[i]:
            j = i * i
            while j <= right:
                is_prime[j] = False
                j += i
        i += 1
    primes = []
    for num in range(left, right + 1):
        if is_prime[num]:
            primes.append(num)
    if len(primes) < 2:
        return [-1, -1]
    best_dist = 2**63 - 1
    best_idx = 0
    for idx in range(len(primes) - 1):
        d = primes[idx + 1] - primes[idx]
        if d < best_dist:
            best_dist = d
            best_idx = idx
    return [primes[best_idx], primes[best_idx + 1]]

def categorize_box(length: int, width: int, height: int, mass: int) -> str:
    is_bulky = length >= 10000 or width >= 10000 or height >= 10000 or length * width * height >= 1000000000
    is_heavy = mass >= 100
    if is_bulky and is_heavy:
        return "Both"
    if is_bulky:
        return "Bulky"
    if is_heavy:
        return "Heavy"
    return "Neither"

