def max_count(nums: List[int]) -> int:
    n = len(nums)
    lo, hi = 0, n
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] < 0:
            lo = mid + 1
        else:
            hi = mid
    first_non_neg = lo
    lo, hi = 0, n
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] <= 0:
            lo = mid + 1
        else:
            hi = mid
    first_pos = lo
    neg_count = first_non_neg
    pos_count = n - first_pos
    return max(neg_count, pos_count)

