def is_it_possible(word1: str, word2: str) -> bool:
    freq1 = [0] * 26
    freq2 = [0] * 26
    for ch in word1:
        freq1[ord(ch) - 97] += 1
    for ch in word2:
        freq2[ord(ch) - 97] += 1

    cnt1 = sum(1 for f in freq1 if f > 0)
    cnt2 = sum(1 for f in freq2 if f > 0)

    for x in range(26):
        if freq1[x] == 0:
            continue
        for y in range(26):
            if freq2[y] == 0:
                continue
            new1 = cnt1 - (freq1[x] == 1) + (freq1[y] == 0)
            new2 = cnt2 - (freq2[y] == 1) + (freq2[x] == 0)
            if new1 == new2:
                return True
    return False

