def difference_of_sum(nums: List[int]) -> int:
    element_sum = 0
    digit_sum = 0
    for i in range(len(nums)):
        val = nums[i]
        element_sum += val
        temp = val
        while temp > 0:
            digit_sum += temp % 10
            temp //= 10
    return abs(element_sum - digit_sum)

def is_circular_sentence(sentence: str) -> bool:
    words = sentence.split(' ')
    for i in range(len(words) - 1):
        if words[i][-1] != words[i + 1][0]:
            return False
    if words[-1][-1] != words[0][0]:
        return False
    return True

def closest_nodes(root, queries):
    sorted_values = []
    def in_order(node):
        if node:
            in_order(node.left)
            sorted_values.append(node.val)
            in_order(node.right)
    in_order(root)
    result = []
    for query in queries:
        mini = -1
        for i in range(len(sorted_values) - 1, -1, -1):
            if sorted_values[i] <= query:
                mini = sorted_values[i]
                break
        maxi = -1
        for i in range(len(sorted_values)):
            if sorted_values[i] >= query:
                maxi = sorted_values[i]
                break
        result.append([mini, maxi])
    return result

