def is_palindrome(substring: str) -> bool:
    return substring == substring[::-1]

def max_non_overlapping_palindrome_substrings(s: str, k: int) -> int:
    count = 0
    left = 0
    while left < len(s):
        found = False
        for right in range(left + k, len(s) + 1):
            substring = s[left:right]
            if is_palindrome(substring):
                count += 1
                left = right
                found = True
                break
        if not found:
            left += 1
    return count

