def minimum_fuel_cost(roads: List[List[int]], seats: int) -> int:
    graph = {}
    for i in range(len(roads)):
        a, b = roads[i][0], roads[i][1]
        if a not in graph:
            graph[a] = []
        if b not in graph:
            graph[b] = []
        graph[a].append(b)
        graph[b].append(a)
    res = 0
    def dfs(node: int, parent: int) -> int:
        nonlocal res
        representatives = 1
        for child in graph.get(node, []):
            if child != parent:
                representatives += dfs(child, node)
        if node != 0:
            res += math.ceil(representatives / seats)
        return representatives
    dfs(0, -1)
    return res

def count_palindromic_subsequence(s: str) -> int:
    MOD = 10**9 + 7
    n = len(s)
    count = 0
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                for l in range(k + 1, n):
                    for m in range(l + 1, n):
                        subsequence = s[i] + s[j] + s[k] + s[l] + s[m]
                        is_palindrome = True
                        for p in range(2):
                            if subsequence[p] != subsequence[4 - p]:
                                is_palindrome = False
                                break
                        if is_palindrome:
                            count = (count + 1) % MOD
    return count

def minimum_operations(root):
    result = 0
    queue = [root]
    while queue:
        level_size = len(queue)
        level_values = []
        for _ in range(level_size):
            node = queue.pop(0)
            level_values.append(node.val)
            if getattr(node, "left", None):
                queue.append(node.left)
            if getattr(node, "right", None):
                queue.append(node.right)
        sorted_level_values = sorted(level_values)
        index_mapping = {}
        for i, v in enumerate(level_values):
            index_mapping[v] = i
        visited = [False] * level_size
        for i in range(level_size):
            if visited[i] or level_values[i] == sorted_level_values[i]:
                continue
            cycle_size = 0
            j = i
            while not visited[j]:
                visited[j] = True
                j = index_mapping[sorted_level_values[j]]
                cycle_size += 1
            result += cycle_size - 1
    return result

