def beautiful_partitions(s: str, k: int, min_length: int) -> int:
    MOD = 1_000_000_007
    n = len(s)
    prime_digits = {'2', '3', '5', '7'}

    # dp[pos][cnt] = ways to partition first pos characters into cnt parts
    dp: List[List[int]] = [[0] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for start in range(n):
        if s[start] not in prime_digits:
            continue
        for cnt in range(k):
            if dp[start][cnt] == 0:
                continue
            # try all possible end positions respecting min_length
            min_end = start + min_length
            if min_end > n:
                continue
            for end in range(min_end, n + 1):
                if s[end - 1] in prime_digits:
                    continue  # must end with a non‑prime digit
                dp[end][cnt + 1] = (dp[end][cnt + 1] + dp[start][cnt]) % MOD

    return dp[n][k]  # type: ignore

