def cycle_length_queries(n: int, queries: List[Tuple[int, int]]) -> List[int]:
    def depth(node: int) -> int:
        return math.floor(math.log2(node))

    def lca(a: int, b: int) -> int:
        da, db = depth(a), depth(b)
        while da > db:
            a //= 2
            da -= 1
        while db > da:
            b //= 2
            db -= 1
        while a != b:
            a //= 2
            b //= 2
        return a

    result: List[int] = []
    for a, b in queries:
        ancestor = lca(a, b)
        cycle_len = depth(a) + depth(b) - 2 * depth(ancestor) + 1
        result.append(cycle_len)
    return result
# TIME: O(log N) per query SPACE: O(1)

