def minimum_operations(nums1: List[int], nums2: List[int], k: int) -> int:
    if k == 0:
        return 0 if nums1 == nums2 else -1

    if sum(nums1) != sum(nums2):
        return -1

    positive_sum = 0
    for a, b in zip(nums1, nums2):
        diff = a - b
        if diff % k != 0:
            return -1
        if diff > 0:
            positive_sum += diff

    return positive_sum // k

