def max_difference_between_max_and_min_price_sum(n: int, edges: List[List[int]], price: List[int]) -> int:
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    def dfs(start: int):
        dist = [0] * n
        parent = [-1] * n
        stack = [start]
        dist[start] = price[start]
        while stack:
            u = stack.pop()
            for v in adj[u]:
                if v == parent[u]:
                    continue
                parent[v] = u
                dist[v] = dist[u] + price[v]
                stack.append(v)
        return dist, parent

    first_dist, _ = dfs(0)
    A = 0
    for i in range(n):
        if first_dist[i] > first_dist[A]:
            A = i

    fromA_dist, _ = dfs(A)
    B = A
    for i in range(n):
        if fromA_dist[i] > fromA_dist[B]:
            B = i

    fromB_dist, _ = dfs(B)

    answer = 0
    for i in range(n):
        max_path = fromA_dist[i] if fromA_dist[i] > fromB_dist[i] else fromB_dist[i]
        cost = max_path - price[i]
        if cost > answer:
            answer = cost
    return answer

