def increment_submatrices(n: int, queries: List[List[int]]) -> List[List[int]]:
    diff = [[0] * (n + 1) for _ in range(n + 1)]
    for q in queries:
        r1, c1, r2, c2 = q
        diff[r1][c1] += 1
        diff[r1][c2 + 1] -= 1
        diff[r2 + 1][c1] -= 1
        diff[r2 + 1][c2 + 1] += 1
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            val = diff[i][j]
            if i > 0:
                val += result[i - 1][j]
            if j > 0:
                val += result[i][j - 1]
            if i > 0 and j > 0:
                val -= result[i - 1][j - 1]
            result[i][j] = val
    return result

