def can_disconnect(grid: List[List[int]]) -> bool:
    m = len(grid)
    n = len(grid[0])
    # reachable from start (0,0)
    reach_start = [[False] * n for _ in range(m)]
    for i in range(m):
        for j in range(n):
            if grid[i][j] != 1:
                continue
            if i == 0 and j == 0:
                reach_start[i][j] = True
            else:
                if i > 0 and reach_start[i - 1][j]:
                    reach_start[i][j] = True
                if j > 0 and reach_start[i][j - 1]:
                    reach_start[i][j] = True
    # already disconnected
    if not reach_start[m - 1][n - 1]:
        return True

    # reachable to end (m-1,n-1)
    reach_end = [[False] * n for _ in range(m)]
    for i in range(m - 1, -1, -1):
        for j in range(n - 1, -1, -1):
            if grid[i][j] != 1:
                continue
            if i == m - 1 and j == n - 1:
                reach_end[i][j] = True
            else:
                if i + 1 < m and reach_end[i + 1][j]:
                    reach_end[i][j] = True
                if j + 1 < n and reach_end[i][j + 1]:
                    reach_end[i][j] = True

    total_steps = (m - 1) + (n - 1)
    cnt = [0] * (total_steps + 1)
    for i in range(m):
        for j in range(n):
            if reach_start[i][j] and reach_end[i][j]:
                cnt[i + j] += 1

    for step in range(1, total_steps):
        if cnt[step] == 1:
            return True
    return False

