def count_ways(ranges: List[List[int]]) -> int:
    MOD = 1000000007
    ranges.sort(key=lambda x: (x[0], x[1]))
    components = 0
    cur_max_end = float('-inf')
    for s, e in ranges:
        if s > cur_max_end:
            components += 1
            cur_max_end = e
        else:
            if e > cur_max_end:
                cur_max_end = e
    result = 1
    base = 2
    exp = components
    while exp > 0:
        if exp & 1:
            result = (result * base) % MOD
        base = (base * base) % MOD
        exp >>= 1
    return result

