def find_string(lcp: List[List[int]]) -> str:
    n = len(lcp)
    if n == 0:
        return ""
    for i in range(n):
        if len(lcp[i]) != n:
            return ""
    for i in range(n):
        if lcp[i][i] != n - i:
            return ""
        for j in range(i + 1, n):
            if lcp[i][j] != lcp[j][i]:
                return ""
            if lcp[i][j] > min(n - i, n - j) or lcp[i][j] < 0:
                return ""
    class DSU:
        def __init__(self, n: int):
            self.p = list(range(n))
            self.sz = [1] * n
        def find(self, x: int) -> int:
            while self.p[x] != x:
                self.p[x] = self.p[self.p[x]]
                x = self.p[x]
            return x
        def unite(self, a: int, b: int) -> None:
            a = self.find(a)
            b = self.find(b)
            if a == b:
                return
            if self.sz[a] < self.sz[b]:
                a, b = b, a
            self.p[b] = a
            self.sz[a] += self.sz[b]
    dsu = DSU(n)
    for i in range(n):
        for j in range(i + 1, n):
            k = lcp[i][j]
            for t in range(k):
                dsu.unite(i + t, j + t)
    adj_map: dict[int, set[int]] = {}
    for i in range(n):
        for j in range(i + 1, n):
            k = lcp[i][j]
            max_len = min(n - i, n - j)
            if k < max_len:
                a = dsu.find(i + k)
                b = dsu.find(j + k)
                if a == b:
                    return ""
                adj_map.setdefault(a, set()).add(b)
                adj_map.setdefault(b, set()).add(a)
    comp_id = [0] * n
    root_to_idx: dict[int, int] = {}
    idx = 0
    for i in range(n):
        r = dsu.find(i)
        if r not in root_to_idx:
            root_to_idx[r] = idx
            idx += 1
        comp_id[i] = root_to_idx[r]
    m = idx
    adj = [[] for _ in range(m)]
    for u_root, neighbors in adj_map.items():
        u = root_to_idx[u_root]
        for v_root in neighbors:
            v = root_to_idx[v_root]
            adj[u].append(v)
    color = [-1] * m
    result_chars = ['a'] * n
    for i in range(n):
        c = comp_id[i]
        if color[c] == -1:
            used = [False] * 26
            for nb in adj[c]:
                if color[nb] != -1:
                    used[color[nb]] = True
            assign = -1
            for d in range(26):
                if not used[d]:
                    assign = d
                    break
            if assign == -1:
                return ""
            color[c] = assign
        result_chars[i] = chr(ord('a') + color[c])
    result = ''.join(result_chars)
    for i in range(n):
        for j in range(i, n):
            cnt = 0
            while i + cnt < n and j + cnt < n and result[i + cnt] == result[j + cnt]:
                cnt += 1
            if cnt != lcp[i][j]:
                return ""
    return result

