def count_possible_roots(edges: List[List[int]], guesses: List[List[int]], k: int) -> int:
    # determine number of nodes
    n = 0
    for a, b in edges:
        n = max(n, a, b)
    n += 1

    adj: List[List[int]] = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)

    guess_set: Set[Tuple[int, int]] = {(u, v) for u, v in guesses}

    parent = [-1] * n
    order: List[int] = []
    initial_correct = 0

    # iterative DFS from node 0 to set parents and count correct guesses for root 0
    stack = [0]
    parent[0] = -2  # mark visited
    while stack:
        node = stack.pop()
        order.append(node)
        for nb in adj[node]:
            if parent[nb] == -1:
                parent[nb] = node
                if (node, nb) in guess_set:
                    initial_correct += 1
                stack.append(nb)

    ans = 0

    def dfs(node: int, cur_correct: int) -> None:
        nonlocal ans
        if cur_correct >= k:
            ans += 1
        for nb in adj[node]:
            if nb == parent[node]:
                continue
            # re-rooting from node to nb
            new_correct = cur_correct
            if (node, nb) in guess_set:
                new_correct -= 1
            if (nb, node) in guess_set:
                new_correct += 1
            dfs(nb, new_correct)

    dfs(0, initial_correct)
    return ans

