def number_of_ways(target: int, types: List[List[int]]) -> int:
    dp = [0] * (target + 1)
    dp[0] = 1

    for cnt, marks in types:
        ndp = [0] * (target + 1)
        for s in range(target + 1):
            if dp[s]:
                max_k = min(cnt, (target - s) // marks)
                for k in range(max_k + 1):
                    ns = s + k * marks
                    ndp[ns] = (ndp[ns] + dp[s]) % MOD
