class Fenwick:
    def __init__(self, n: int):
        self.n = n
        self.bit = [0] * (n + 1)

    def add(self, idx: int, delta: int = 1) -> None:
        while idx <= self.n:
            self.bit[idx] += delta
            idx += idx & -idx

    def sum(self, idx: int) -> int:
        s = 0
        while idx > 0:
            s += self.bit[idx]
            idx -= idx & -idx
        return s

def minimum_time_to_complete_all_tasks(tasks: List[List[int]]) -> int:
    if not tasks:
        return 0
    # sort by end time
    tasks.sort(key=lambda x: x[1])
    max_time = max(end for _, end, _ in tasks)
    selected = [False] * (max_time + 1)  # 1-indexed
    ft = Fenwick(max_time)
    total_on = 0

    for start, end, dur in tasks:
        already = ft.sum(end) - ft.sum(start - 1)
        need = dur - already
        if need <= 0:
            continue
        # add needed points starting from the latest possible seconds
        t = end
        while need > 0 and t >= start:
            if not selected[t]:
                selected[t] = True
                ft.add(t, 1)
                total_on += 1
                need -= 1
            t -= 1
    return total_on

