def distribute_money(money: int, children: int) -> int:
    if money < children:
        return -1

    extra = money - children  # money left after giving each child $1
    max_exact = extra // 7    # each child with $8 needs 7 extra dollars
    if max_exact > children:
        max_exact = children

    # avoid giving any child exactly $4
    if extra % 7 == 3 and max_exact < children:
        max_exact -= 1

    # if all children would get $8 but total money is not exactly 8*children,
    # we must reduce one child to avoid an invalid distribution
    if max_exact == children and money != 8 * children:
        max_exact -= 1

    return max_exact

