        return -1
    queue = [root]
    head = 0
    level_sums = []
    while head < len(queue):
        level_size = len(queue) - head
        s = 0
        for _ in range(level_size):
            node = queue[head]
            head += 1
            s += node.val
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        level_sums.append(s)
    level_sums.sort(reverse=True)
    return level_sums[k - 1] if k <= len(level_sums) else -1

