            chosen = a
        else:
            # need to subtract a prime p where a - p <= limit and a - p >= 1
            # i.e., p >= a - limit and p <= a - 1
            low = a - limit
            high = a - 1
            p = None
            for cand in range(low, high + 1):
                if is_prime(cand):
                    p = cand
                    break
            if p is None:
                return False
            chosen = a - p
        next_val = chosen
    return True
# TIME: O(n * sqrt(max(nums))) SPACE: O(1)

