def collect_coins_in_tree(coins: List[int], edges: List[List[int]]) -> int:
    n = len(coins)
    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)

    degree = [len(adj[i]) for i in range(n)]
    removed = [False] * n
    queue: List[int] = []

    # Remove leaves without coins
    for i in range(n):
        if degree[i] == 1 and coins[i] == 0:
            queue.append(i)

    q_idx = 0
    while q_idx < len(queue):
        u = queue[q_idx]
        q_idx += 1
        if removed[u]:
            continue
        removed[u] = True
        for v in adj[u]:
            if removed[v]:
                continue
            degree[v] -= 1
            if degree[v] == 1 and coins[v] == 0:
                queue.append(v)

    # Remove leaves for two more rounds
    leaves = [i for i in range(n) if not removed[i] and degree[i] == 1]
    for _ in range(2):
        next_leaves: List[int] = []
        for u in leaves:
            if removed[u]:
                continue
            removed[u] = True
            for v in adj[u]:
                if removed[v]:
                    continue
                degree[v] -= 1
                if degree[v] == 1:
                    next_leaves.append(v)
        leaves = next_leaves

    remaining_edges = sum(degree[i] for i in range(n) if not removed[i]) // 2
    return remaining_edges * 2

