    prev_run_len = 0
    cur_run_len = 0

    for i in range(len(s)):
        c = s[i]
        if i == 0 or c == s[i - 1]:
            cur_run_len += 1
        else:
            if prev_run_char == '0' and c == '1':
                candidate = 2 * min(prev_run_len, cur_run_len)
                if candidate > max_len:
                    max_len = candidate
            prev_run_char = s[i - 1]
            prev_run_len = cur_run_len
            cur_run_len = 1

    if prev_run_char == '0' and s and s[-1] == '1':
        candidate = 2 * min(prev_run_len, cur_run_len)
        if candidate > max_len:
            max_len = candidate

    return max_len

