        return 0
    rows = len(nums)
    cols = len(nums[0])
    max_prime = 0
    for i in range(rows):
        if i < cols:
            val = nums[i][i]
            if isPrime(val) and val > max_prime:
                max_prime = val
        anti_col = cols - 1 - i
        if 0 <= anti_col < cols:
            if i != anti_col:
                val = nums[i][anti_col]
                if isPrime(val) and val > max_prime:
                    max_prime = val
    return max_prime

