def minimize_max_difference(nums: List[int], p: int) -> int:
    n = len(nums)
    if p == 0:
        return 0
    a = sorted(nums)
    low = 0
    high = a[-1] - a[0]

    def can_form(limit: int) -> int:
        cnt = 0
        i = 0
        while i < n - 1:
            if a[i + 1] - a[i] <= limit:
                cnt += 1
                i += 2
            else:
                i += 1
        return cnt

    while low < high:
        mid = (low + high) // 2
        if can_form(mid) >= p:
            high = mid
        else:
            low = mid + 1
    return low

