def cache_with_time_limit(actions: List[str], values: List[List[int]], timeDelays: List[int]) -> List[Any]:
    store: dict[int, tuple[int, int]] = {}  # key -> (value, expire_time)
    result: List[Any] = [None]  # first entry for constructor
    current_time = 0

    # helper to purge expired keys at a given moment
    def purge(t: int) -> None:
        expired_keys = [k for k, (_, exp) in store.items() if exp <= t]
        for k in expired_keys:
            del store[k]

    for i in range(1, len(actions)):
        current_time = timeDelays[i]  # absolute timestamp of this operation
        act = actions[i]

        if act == "set":
            key, value, duration = values[i]
            expire = current_time + duration
            existed_unexpired = key in store and store[key][1] > current_time
            store[key] = (value, expire)
            result.append(True if existed_unexpired else False)

        elif act == "get":
            key = values[i][0]
            if key in store:
                val, exp = store[key]
                if exp > current_time:
                    result.append(val)
                    continue
                else:
                    del store[key]
            result.append(-1)

        elif act == "count":
            purge(current_time)
            result.append(len(store))

    return result

