def sum_of_distances(nums: List[int]) -> List[int]:
    n = len(nums)
    ans = [0] * n
    groups = {}
    for i, v in enumerate(nums):
        if v not in groups:
            groups[v] = []
        groups[v].append(i)
    for idx_list in groups.values():
        m = len(idx_list)
        if m <= 1:
            continue
        pref = [0] * m
        pref[0] = idx_list[0]
        for k in range(1, m):
            pref[k] = pref[k - 1] + idx_list[k]
        total_sum = pref[-1]
        for p in range(m):
            i = idx_list[p]
            left_count = p
            left_sum = pref[p - 1] if p > 0 else 0
            right_count = m - p - 1
            right_sum = total_sum - left_sum - i
            ans[i] = i * left_count - left_sum + right_sum - i * right_count
    return ans

def memoize(fn):
    cache = {}
    call_count = 0
    def memoized(*args):
        nonlocal call_count
        key = '|'.join(map(str, args))
        if key in cache:
            return cache[key]
        result = fn(*args)
        cache[key] = result
        call_count += 1
        return result
    def get_call_count():
        return call_count
    memoized.get_call_count = get_call_count
    return memoized

