def graph(n, edges):
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    def add_edge(edge):
        u, v, w = edge
        adj[u].append((v, w))

    def shortest_path(src, dst):
        if src == dst:
            return 0
        dist = [float('inf')] * n
        dist[src] = 0
        heap = [(0, src)]
        while heap:
            d, u = heapq.heappop(heap)
            if d != dist[u]:
                continue
            if u == dst:
                return d
            for v, w in adj[u]:
                nd = d + w
                if nd < dist[v]:
                    dist[v] = nd
                    heapq.heappush(heap, (nd, v))
        return -1

    return {'add_edge': add_edge, 'shortest_path': shortest_path}

