        self.val = val
        self.left = left
        self.right = right

def replace_value_in_tree(root: Optional[TreeNode]) -> Optional[TreeNode]:
    if root is None:
        return None

    queue = collections.deque([(root, root.val)])
    while queue:
        level_size = len(queue)
        level_total = sum(node.val for node, _ in queue)

        for _ in range(level_size):
            node, parent_sum = queue.popleft()
            node.val = level_total - parent_sum

            child_sum = 0
            if node.left:
                child_sum += node.left.val
            if node.right:
                child_sum += node.right.val

            if node.left:
                queue.append((node.left, child_sum))
            if node.right:
                queue.append((node.right, child_sum))

    return root

