def substring_xor_queries(s: str, queries: List[List[int]]) -> List[List[int]]:
    n = len(s)
    # compute maximum target value needed
    max_target = 0
    for a, b in queries:
        max_target = max(max_target, a ^ b)

    # limit substring length: 30 bits are enough for values up to 10^9 (2^30 > 10^9)
    max_len = 30

    # map value -> (start, end) with minimal length (and minimal start for ties)
    best: dict[int, List[int]] = {}

    for i in range(n):
        val = 0
        for j in range(i, min(n, i + max_len)):
            val = (val << 1) | (s[j] == '1')
            if val > max_target:
                break
            cur_len = j - i + 1
            if val not in best or cur_len < best[val][1] - best[val][0] + 1:
                best[val] = [i, j]

    ans: List[List[int]] = []
    for a, b in queries:
        target = a ^ b
        ans.append(best.get(target, [-1, -1]))
    return ans
# TIME: O(n * 30) SPACE: O(min(2^30, n * 30))

