def min_cost(basket1: List[int], basket2: List[int]) -> int:
    freq1: dict[int, int] = {}
    freq2: dict[int, int] = {}
    for v in basket1:
        freq1[v] = freq1.get(v, 0) + 1
    for v in basket2:
        freq2[v] = freq2.get(v, 0) + 1

    # all values must appear in both baskets with even total difference
    to_swap: List[int] = []
    for val in set(freq1) | set(freq2):
        c1 = freq1.get(val, 0)
        c2 = freq2.get(val, 0)
        diff = abs(c1 - c2)
        if diff % 2:
            return -1
        # add the excess copies that need to be moved
        to_swap.extend([val] * (diff // 2))

    if not to_swap:
        return 0

    to_swap.sort()
    global_min = min(min(basket1), min(basket2))
    half = len(to_swap) // 2
    cost = 0
    for v in to_swap[:half]:
        cost += min(v, 2 * global_min)
    return cost

