    count_s = 0
    count_target = 0
    for i in range(len(s)):
        if s[i] == '1':
            count_s += 1
        if target[i] == '1':
            count_target += 1
    if count_s != count_target:
        return False

    visited = [False] * len(s)
    i = 0
    while i < len(s):
        if s[i] != target[i]:
            found = False
            for j in range(len(s)):
                if not visited[j] and s[j] == target[i]:
                    original_si = s[i]
                    original_sj = s[j]
                    new_i_char = '1' if (original_si == '1' or original_sj == '1') else '0'
                    s = s[:i] + new_i_char + s[i + 1:]
                    new_j_char = '1' if ((new_i_char == '0' and original_sj == '1') or (new_i_char == '1' and original_sj == '0')) else '0'
                    s = s[:j] + new_j_char + s[j + 1:]
                    visited[j] = True
                    found = True
                    break
            if not found:
                return False
