def max_number_of_fish(grid: List[List[int]]) -> int:
    if not grid:
        return 0
    rows, cols = len(grid), len(grid[0])
    visited = [[False] * cols for _ in range(rows)]

    def dfs(r: int, c: int) -> int:
        stack = [(r, c)]
        total = 0
        while stack:
            i, j = stack.pop()
            if visited[i][j]:
                continue
            visited[i][j] = True
            total += grid[i][j]
            if i > 0 and grid[i - 1][j] > 0 and not visited[i - 1][j]:
                stack.append((i - 1, j))
            if i + 1 < rows and grid[i + 1][j] > 0 and not visited[i + 1][j]:
                stack.append((i + 1, j))
            if j > 0 and grid[i][j - 1] > 0 and not visited[i][j - 1]:
                stack.append((i, j - 1))
            if j + 1 < cols and grid[i][j + 1] > 0 and not visited[i][j + 1]:
                stack.append((i, j + 1))
        return total

    max_fish = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] > 0 and not visited[i][j]:
                max_fish = max(max_fish, dfs(i, j))
    return max_fish

