import math

def min_operations(nums: List[int]) -> int:
    n = len(nums)
    # If any element is already 1, each non‑1 element can be turned into 1 in one operation.
    if 1 in nums:
        return n - nums.count(1)

    # Compute overall gcd; if it is greater than 1, impossible.
    overall_gcd = nums[0]
    for v in nums[1:]:
        overall_gcd = math.gcd(overall_gcd, v)
    if overall_gcd != 1:
        return -1

    # Find the shortest subarray with gcd equal to 1.
    min_len = n + 1
    for i in range(n):
        cur_gcd = nums[i]
        if cur_gcd == 1:
            min_len = 1
            break
        for j in range(i + 1, n):
            cur_gcd = math.gcd(cur_gcd, nums[j])
            if cur_gcd == 1:
                min_len = min(min_len, j - i + 1)
                break

    # Operations: (min_len‑1) to create a 1, then (n‑1) to turn the rest into 1.
    return (min_len - 1) + (n - 1)

