def cancellable(generator: Any) -> Tuple[Callable[[], None], asyncio.Future]:
    cancelled = False
    loop = asyncio.get_event_loop()
    promise = loop.create_future()

    def cancel() -> None:
        nonlocal cancelled
        cancelled = True
        try:
            generator.throw(Exception("Cancelled"))
        except StopIteration:
            pass
        except Exception:
            pass

    def step(send_value: Any = None, is_throw: bool = False) -> None:
        nonlocal cancelled
        if cancelled:
            try:
                generator.throw(Exception("Cancelled"))
            except StopIteration as e:
                promise.set_result(e.value)
            except Exception as e:
                promise.set_exception(e)
            return
        try:
            if is_throw:
                yielded = generator.throw(send_value)
            else:
                if send_value is None:
                    yielded = next(generator)
                else:
                    yielded = generator.send(send_value)
        except StopIteration as e:
            promise.set_result(e.value)
            return
        except Exception as e:
            promise.set_exception(e)
            return

        if asyncio.isfuture(yielded) or asyncio.iscoroutine(yielded):
            asyncio.ensure_future(_handle(yielded))
        else:
            step(yielded)

    async def _handle(awaitable: Any) -> None:
        nonlocal cancelled
        try:
            result = await awaitable
            if cancelled:
                try:
                    generator.throw(Exception("Cancelled"))
                except StopIteration as e:
                    promise.set_result(e.value)
                except Exception as e:
                    promise.set_exception(e)
            else:
                step(result)
        except Exception as err:
            try:
                generator.throw(err)
            except StopIteration as e:
                promise.set_result(e.value)
            except Exception as e:
                promise.set_exception(e)

    step()
    return cancel, promise

