def determine_winner(player1: List[int], player2: List[int]) -> int:
    def calculate_score(frames: List[int]) -> int:
        score = 0
        n = len(frames)
        i = 0
        while i < n:
            pins = frames[i]
            if pins == 10:  # strike
                bonus = 0
                if i + 1 < n:
                    bonus += frames[i + 1]
                if i + 2 < n:
                    bonus += frames[i + 2]
                score += 10 + bonus
            else:
                score += pins
            i += 1
        return score

    score1 = calculate_score(player1)
    score2 = calculate_score(player2)

    if score1 > score2:
        return 1
    if score1 < score2:
        return 2
    return 0

