def minimum_cost(start: List[int], target: List[int], special_roads: List[List[int]]) -> int:
    points = [tuple(start), tuple(target)]
    for road in special_roads:
        points.append((road[0], road[1]))
        points.append((road[2], road[3]))
    seen = {}
    unique_points = []
    for p in points:
        if p not in seen:
            seen[p] = None
            unique_points.append(p)
    points = unique_points
    graph: Dict[Tuple[int, int], Dict[Tuple[int, int], int]] = {}
    for point in points:
        graph[point] = {}
    for road in special_roads:
        a = (road[0], road[1])
        b = (road[2], road[3])
        graph[a][b] = road[4]
    n = len(points)
    for i in range(n):
        for j in range(n):
            if i != j:
                pi = points[i]
                pj = points[j]
                cost = abs(pi[0] - pj[0]) + abs(pi[1] - pj[1])
                if pj not in graph[pi] or graph[pi][pj] > cost:
                    graph[pi][pj] = cost
    distances: Dict[Tuple[int, int], int] = {}
    queue = [(tuple(start), 0)]
    while queue:
        queue.sort(key=lambda x: x[1])
        point, distance = queue.pop(0)
        if point in distances and distances[point] <= distance:
            continue
        distances[point] = distance
        for neighbor, w in graph[point].items():
            new_distance = distance + w
            if neighbor not in distances or new_distance < distances[neighbor]:
                queue.append((neighbor, new_distance))
    return distances[tuple(target)]

from typing import List

def smallest_beautiful_string(s: str, k: int) -> str:
    n: int = len(s)
    letters: List[str] = [chr(ord('a') + i) for i in range(k)]

    for i in range(n - 1, -1, -1):
        prefix: List[str] = list(s[:i])
        for cand in letters:
            if cand <= s[i]:
                continue
            # check constraints with previous two characters
            if i - 1 >= 0 and cand == prefix[-1]:
                continue
            if i - 2 >= 0 and cand == prefix[-2]:
                continue

            cur: List[str] = prefix + [cand]
            possible: bool = True

            for _ in range(i + 1, n):
                placed: bool = False
                for c in letters:
                    if c == cur[-1]:
                        continue
                    if len(cur) >= 2 and c == cur[-2]:
                        continue
                    cur.append(c)
                    placed = True
                    break
                if not placed:
                    possible = False
                    break

            if possible:
                return ''.join(cur)

    return ''

