def create_counter(init: int) -> Dict[str, Callable[[], int]]:
    current_value = init

    def increment() -> int:
        nonlocal current_value
        current_value += 1
        return current_value

    def decrement() -> int:
        nonlocal current_value
        current_value -= 1
        return current_value

    def reset() -> int:
        nonlocal current_value
        current_value = init
        return current_value

    return {
        "increment": increment,
        "decrement": decrement,
        "reset": reset,
    }

