def frequency_tracker():
    freq_count = {}
    count = {}

    def add(num):
        if num in freq_count:
            count[freq_count[num]] -= 1
            if count[freq_count[num]] == 0:
                del count[freq_count[num]]
        freq_count[num] = freq_count.get(num, 0) + 1
        count[freq_count[num]] = count.get(freq_count[num], 0) + 1

    def remove(num):
        if num not in freq_count:
            return
        count[freq_count[num]] -= 1
        if count[freq_count[num]] == 0:
            del count[freq_count[num]]
        freq_count[num] -= 1
        if freq_count[num] == 0:
            del freq_count[num]
        else:
            count[freq_count[num]] = count.get(freq_count[num], 0) + 1

    def query(num):
        return num in count

    return {"add": add, "remove": remove, "query": query}

