def maximum_or(nums, k):
    max_or = 0
    n = len(nums)
    for i in range(1 << (k * n)):
        temp = nums[:]
        operations = 0
        for j in range(n):
            for bit in range(k):
                if (i >> (j * k + bit)) & 1:
                    temp[j] *= 2
                    operations += 1
            if operations > k:
                break
        if operations > k:
            continue
        or_val = 0
        for num in temp:
            or_val |= num
        max_or = max(max_or, or_val)
    return max_or

