def does_valid_array_exist(derived: List[int]) -> bool:
    n = len(derived)
    original = [0] * n
    if n > 0:
        original[0] = 0
    if n > 1:
        original[1] = derived[0]
    for i in range(2, n):
        original[i] = derived[i - 1] ^ original[i - 1]
    for i in range(n):
        if derived[i] != (original[i] ^ original[(i + 1) % n]):
            return False
    return True

