def _dfs(graph: List[List[int]], visited: List[bool], node: int, component: List[int]) -> None:
    visited[node] = True
    component.append(node)
    for neighbor in graph[node]:
        if not visited[neighbor]:
            _dfs(graph, visited, neighbor, component)

def _is_complete(graph: List[List[int]], component: List[int]) -> bool:
    size = len(component)
    if size <= 1:
        return True
    comp_set = set(component)
    for v in component:
        count = 0
        for u in graph[v]:
            if u in comp_set:
                count += 1
        if count != size - 1:
            return False
    return True

def count_complete_components(n: int, edges: List[Tuple[int, int]]) -> int:
    graph = [[] for _ in range(n)]
    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)

    visited = [False] * n
    count = 0

    for i in range(n):
        if not visited[i]:
            component: List[int] = []
            _dfs(graph, visited, i, component)
            if _is_complete(graph, component):
                count += 1

    return count

