def maximum_moves(grid: List[List[int]]) -> int:
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    memo: List[List[int]] = [[-1] * cols for _ in range(rows)]

    def dfs(r: int, c: int) -> int:
        if memo[r][c] != -1:
            return memo[r][c]
        best = 0
        if c + 1 < cols:
            for nr in (r - 1, r, r + 1):
                if 0 <= nr < rows and grid[nr][c + 1] > grid[r][c]:
                    best = max(best, 1 + dfs(nr, c + 1))
        memo[r][c] = best
        return best

    answer = 0
    for r in range(rows):
        answer = max(answer, dfs(r, 0))
    return answer

