def punishment_number(n: int) -> int:
    def can_partition(num: int, target: int) -> bool:
        s = str(num)
        from functools import lru_cache
        @lru_cache(None)
        def dfs(idx: int, cur: int) -> bool:
            if idx == len(s):
                return cur == target
            for j in range(idx + 1, len(s) + 1):
                if dfs(j, cur + int(s[idx:j])):
                    return True
            return False
        return dfs(0, 0)
    result = 0
    for i in range(1, n + 1):
        sq = i * i
        if can_partition(sq, i):
            result += sq
    return result

