def difference_of_number_on_diagonals(grid: List[List[int]]) -> List[List[int]]:
    m = len(grid)
    n = len(grid[0])
    answer = [[0] * n for _ in range(m)]
    diagonal_counts = {}
    for r in range(m):
        for c in range(n):
            diagonal_key = r - c
            anti_diagonal_key = r + c
            if diagonal_key not in diagonal_counts:
                diagonal_counts[diagonal_key] = set()
            if anti_diagonal_key not in diagonal_counts:
                diagonal_counts[anti_diagonal_key] = set()
            diagonal_counts[diagonal_key].add(grid[r][c])
            diagonal_counts[anti_diagonal_key].add(grid[r][c])
    for r in range(m):
        for c in range(n):
            diagonal_key = r - c
            anti_diagonal_key = r + c
            answer[r][c] = abs(len(diagonal_counts[diagonal_key]) - len(diagonal_counts[anti_diagonal_key]))
    return answer

def event_emitter(actions, values):
    results = []
    listeners = {}
    for i in range(len(actions)):
        act = actions[i]
        val = values[i]
        if act == "EventEmitter":
            results.append([])
        elif act == "subscribe":
            event_name, fn_str = val
            fn = eval(fn_str)
            listeners.setdefault(event_name, []).append(fn)
            results.append(["subscribed"])
        elif act == "emit":
            event_name = val[0]
            args = val[1] if len(val) > 1 else []
            callbacks = listeners.get(event_name, [])
            emitted_values = []
            for cb in callbacks:
                emitted_values.append(cb(*args))
            results.append(["emitted", emitted_values])
    return results

