def calculate(actions, values):
    result = values[0]
    index = 1
    for i in range(1, len(actions) - 1):
        if actions[i] == 'add':
            result += values[index]
        elif actions[i] == 'subtract':
            result -= values[index]
        elif actions[i] == 'multiply':
            result *= values[index]
        elif actions[i] == 'divide':
            result /= values[index]
        elif actions[i] == 'power':
            result = result ** values[index]
        index += 1
    return result

