def robot_movement(nums: List[int], s: str, d: int) -> int:
    MOD = 10**9 + 7
    n = len(nums)
    positions = nums[:]
    directions = [-1 if c == 'L' else 1 for c in s]
    for _ in range(d):
        for j in range(n):
            positions[j] += directions[j]
        for j in range(n - 1):
            for k in range(j + 1, n):
                if positions[j] == positions[k]:
                    directions[j] *= -1
                    directions[k] *= -1
    total = 0
    for i in range(n):
        for j in range(i + 1, n):
            total = (total + abs(positions[i] - positions[j])) % MOD
    return total

def longest_semi_repetitive_substring(s: str) -> int:
    max_length = 0
    left = 0
    repeated_count = 0
    for right in range(len(s)):
        if right > 0 and s[right] == s[right - 1]:
            repeated_count += 1
        while repeated_count > 1:
            if s[left] == s[left + 1]:
                repeated_count -= 1
            left += 1
        max_length = max(max_length, right - left + 1)
    return max_length

def lexicographically_smallest_string(s: str) -> str:
    chars = list(s)
    n = len(chars)
    i = 0
    # find first character that is not 'a'
    while i < n and chars[i] == 'a':
        i += 1
    if i == n:  # all 'a'
        chars[-1] = 'z'
        return ''.join(chars)
    # decrement contiguous non-'a' segment
    while i < n and chars[i] != 'a':
        # shift character one step back, with wrap from 'a' to 'z'
        chars[i] = chr(ord(chars[i]) - 1) if chars[i] != 'a' else 'z'
        i += 1
    return ''.join(chars)

