def min_cost(nums: List[int], x: int) -> int:
    n = len(nums)
    best = float('inf')
    # try all possible numbers of rotations (k)
    for k in range(n):
        total = x * k
        # for each type t, find cheapest chocolate we could buy after at most k rotations
        for t in range(n):
            cheapest = nums[t]
            # look back up to k positions
            for d in range(1, k + 1):
                idx = (t - d) % n
                if nums[idx] < cheapest:
                    cheapest = nums[idx]
            total += cheapest
        if total < best:
            best = total
    return best

