def count_special_permutations(nums: List[int]) -> int:
    MOD = 10**9 + 7
    n = len(nums)
    if n == 0:
        return 0

    # adjacency: can go from i to j if nums[i] and nums[j] are divisible one by the other
    can = [[False] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j and (nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0):
                can[i][j] = True

    size = 1 << n
    dp = [[0] * n for _ in range(size)]

    for i in range(n):
        dp[1 << i][i] = 1

    for mask in range(size):
        for last in range(n):
            if not (mask & (1 << last)):
                continue
            cur = dp[mask][last]
            if cur == 0:
                continue
            for nxt in range(n):
                if mask & (1 << nxt):
                    continue
                if can[last][nxt]:
                    dp[mask | (1 << nxt)][nxt] = (dp[mask | (1 << nxt)][nxt] + cur) % MOD

    full_mask = size - 1
    ans = sum(dp[full_mask][i] for i in range(n)) % MOD
    return ans

def min_string_length(s: str) -> int:
    stack = []
    for ch in s:
        stack.append(ch)
        while len(stack) >= 2:
            a = stack[-2]
            b = stack[-1]
            if (a == 'A' and b == 'B') or (a == 'C' and b == 'D'):
                stack.pop()
                stack.pop()
            else:
                break
    return len(stack)

def smallest_palindrome(s: str) -> str:
    arr = list(s)
    i, j = 0, len(arr) - 1
    while i < j:
        if arr[i] != arr[j]:
            smaller = arr[i] if arr[i] < arr[j] else arr[j]
            arr[i] = arr[j] = smaller
        i += 1
        j -= 1
    return ''.join(arr)

