def longest_even_odd_subarray(nums: List[int], threshold: int) -> int:
    n = len(nums)
    best = 0
    for i in range(n):
        if nums[i] > threshold or nums[i] % 2 == 1:
            continue
        length = 1
        prev_parity = 0
        j = i + 1
        while j < n:
            if nums[j] > threshold:
                break
            cur_parity = nums[j] % 2
            if cur_parity == prev_parity:
                break
            length += 1
            prev_parity = cur_parity
            j += 1
        if length > best:
            best = length
    return best

