def relocate_marbles(nums: List[int], move_from: List[int], move_to: List[int]) -> List[int]:
    pos_count = {}
    for p in nums:
        pos_count[p] = pos_count.get(p, 0) + 1

    for i in range(len(move_from)):
        frm = move_from[i]
        to = move_to[i]
        cnt = pos_count.get(frm)
        if cnt is not None:
            pos_count[to] = pos_count.get(to, 0) + cnt
            del pos_count[frm]

    result = list(pos_count.keys())
    result.sort()
    return result

