def longest_alternating_subarray(nums: List[int]) -> int:
    max_len = -1
    cur_len = 1
    prev_diff = 0
    for i in range(1, len(nums)):
        diff = nums[i] - nums[i - 1]
        if abs(diff) == 1 and (prev_diff == 0 or diff * prev_diff == -1):
            cur_len += 1
        elif abs(diff) == 1:
            cur_len = 2
        else:
            cur_len = 1
        prev_diff = diff if abs(diff) == 1 else 0
        if cur_len > max_len:
            max_len = cur_len
    return max_len if max_len >= 2 else -1

