def prime_pairs(n: int) -> List[List[int]]:
    is_prime = [True] * (n + 1)
    if n >= 0:
        is_prime[0] = False
    if n >= 1:
        is_prime[1] = False
    i = 2
    while i * i <= n:
        if is_prime[i]:
            j = i * i
            while j <= n:
                is_prime[j] = False
                j += i
        i += 1

    result: List[List[int]] = []
    x = 2
    while x <= n // 2:
        y = n - x
        if is_prime[x] and is_prime[y]:
            result.append([x, y])
        x += 1

    return result

