def minimum_length(words: List[str]) -> int:
    n = len(words)
    if n == 0:
        return 0
    total_len = sum(len(w) for w in words)
    # dp[mask][last] = max overlaps for subset mask ending with last
    size = 1 << n
    dp = [[-1] * n for _ in range(size)]
    for i in range(n):
        dp[1 << i][i] = 0
    for mask in range(size):
        for last in range(n):
            cur = dp[mask][last]
            if cur < 0:
                continue
            for nxt in range(n):
                if mask & (1 << nxt):
                    continue
                add = 1 if words[last][-1] == words[nxt][0] else 0
                nxt_mask = mask | (1 << nxt)
                if dp[nxt_mask][nxt] < cur + add:
                    dp[nxt_mask][nxt] = cur + add
    full_mask = size - 1
    max_overlap = max(dp[full_mask][i] for i in range(n) if dp[full_mask][i] >= 0)
    return total_len - max_overlap

def min_beautiful_substrings(s: str) -> int:
    n = len(s)
    powers = []
    val = 1
    while True:
        b = bin(val)[2:]
        if len(b) > n:
            break
        powers.append(b)
        val *= 5
    INF = float('inf')
    dp = [INF] * (n + 1)
    dp[0] = 0
    for i in range(1, n + 1):
        for b in powers:
            l = len(b)
            if l <= i and s[i - l:i] == b:
                dp[i] = min(dp[i], dp[i - l] + 1)
    return -1 if dp[n] == INF else dp[n]

