def max_jumps(nums: List[int], target: int) -> int:
    n = len(nums)
    if n == 0:
        return -1
    if n == 1:
        return 0
    dp = [float('-inf')] * n
    dp[0] = 0
    for i in range(1, n):
        for j in range(i):
            if abs(nums[j] - nums[i]) <= target and dp[j] != float('-inf'):
                dp[i] = max(dp[i], dp[j] + 1)
    return -1 if dp[n - 1] == float('-inf') else dp[n - 1]

