def number_of_black_blocks(m: int, n: int, coordinates: List[Tuple[int, int]]) -> List[int]:
    ans = [0] * 5
    block_count = {}
    for x, y in coordinates:
        for dx in (-1, 0):
            for dy in (-1, 0):
                i = x + dx
                j = y + dy
                if i < 0 or j < 0 or i >= m - 1 or j >= n - 1:
                    continue
                key = f"{i},{j}"
                block_count[key] = block_count.get(key, 0) + 1
    for cnt in block_count.values():
        ans[cnt] += 1
    total_blocks = max(0, (m - 1) * (n - 1))
    non_zero = ans[1] + ans[2] + ans[3] + ans[4]
    ans[0] = total_blocks - non_zero
    return ans

