def longest_non_decreasing_subarray(nums1: List[int], nums2: List[int]) -> int:
    n = len(nums1)
    if n == 0:
        return 0
    prev_len1 = prev_len2 = 1
    ans = 1
    for i in range(1, n):
        cur_len1 = 1
        cur_len2 = 1
        if nums1[i - 1] <= nums1[i]:
            cur_len1 = max(cur_len1, prev_len1 + 1)
        if nums2[i - 1] <= nums1[i]:
            cur_len1 = max(cur_len1, prev_len2 + 1)
        if nums1[i - 1] <= nums2[i]:
            cur_len2 = max(cur_len2, prev_len1 + 1)
        if nums2[i - 1] <= nums2[i]:
            cur_len2 = max(cur_len2, prev_len2 + 1)
        ans = max(ans, cur_len1, cur_len2)
        prev_len1, prev_len2 = cur_len1, cur_len2
    return ans

