def minimum_valid_split(nums: List[int]) -> int:
    n = len(nums)
    candidate = None
    count = 0
    for i in range(n):
        if count == 0:
            candidate = nums[i]
            count = 1
        elif nums[i] == candidate:
            count += 1
        else:
            count -= 1
    dom = candidate
    total_dom = 0
    for v in nums:
        if v == dom:
            total_dom += 1
    left_count = 0
    for i in range(n - 1):
        if nums[i] == dom:
            left_count += 1
        left_len = i + 1
        right_len = n - left_len
        right_count = total_dom - left_count
        if left_count * 2 > left_len and right_count * 2 > right_len:
            return i
    return -1

