def longest_valid_substring(word, forbidden):
    forb_set = set(forbidden)
    left = 0
    best = 0
    n = len(word)
    for i in range(n):
        for l in range(1, 11):
            start = i - l + 1
            if start < 0:
                break
            if word[start:i+1] in forb_set:
                left = max(left, start + 1)
        best = max(best, i - left + 1)
    return best

