def visit_array_positions(nums: List[int], x: int) -> int:
    if not nums:
        return 0

    NEG_INF = -10**18
    best_even = NEG_INF
    best_odd = NEG_INF

    # initialize with first element
    dp = nums[0]
    if nums[0] % 2 == 0:
        best_even = dp
    else:
        best_odd = dp

    max_score = dp

    for val in nums[1:]:
        if val % 2 == 0:
            same = best_even
            opposite = best_odd - x if best_odd != NEG_INF else NEG_INF
        else:
            same = best_odd
            opposite = best_even - x if best_even != NEG_INF else NEG_INF

        best_prev = same if same > opposite else opposite
        dp = val + best_prev

        if val % 2 == 0:
            if dp > best_even:
                best_even = dp
        else:
            if dp > best_odd:
                best_odd = dp

        if dp > max_score:
            max_score = dp

    return max_score

def max_possible_element(nums: list[int]) -> int:
    stack = []
    max_val = 0
    for i in range(len(nums) - 1, -1, -1):
        cur = nums[i]
        while stack and cur <= stack[-1]:
            cur += stack.pop()
        stack.append(cur)
        if cur > max_val:
            max_val = cur
    return max_val

