def count_ways(n: int, x: int) -> int:
    MOD = 1000000007
    powers = []
    i = 1
    while True:
        v = i ** x
        if v > n:
            break
        powers.append(v)
        i += 1
    dp = [0] * (n + 1)
    dp[0] = 1
    for v in powers:
        for s in range(n, v - 1, -1):
            dp[s] = (dp[s] + dp[s - v]) % MOD
    return dp[n]

