def max_groups(usage_limits: List[int]) -> int:
    n = len(usage_limits)
    lo, hi = 0, n
    while lo < hi:
        mid = (lo + hi + 1) // 2
        total = 0
        for v in usage_limits:
            total += v if v < mid else mid
        if total >= mid * (mid + 1) // 2:
            lo = mid
        else:
            hi = mid - 1
    return lo

