def count_complete_subarrays(nums: List[int]) -> int:
    n = len(nums)
    total_distinct = len(set(nums))
    if total_distinct == 1:
        return n * (n + 1) // 2

    freq = {}
    distinct_in_window = 0
    ans = 0
    right = 0

    for left in range(n):
        while right < n and distinct_in_window < total_distinct:
            val = nums[right]
            cnt = freq.get(val, 0)
            if cnt == 0:
                distinct_in_window += 1
            freq[val] = cnt + 1
            right += 1

        if distinct_in_window == total_distinct:
            ans += n - right + 1

        val_left = nums[left]
        cnt_left = freq[val_left]
        if cnt_left == 1:
            distinct_in_window -= 1
            del freq[val_left]
        else:
            freq[val_left] = cnt_left - 1

    return ans

