import itertools

def minimum_string(a: str, b: str, c: str) -> str:
    # Helper: merge two strings with maximal overlap
    def merge(s1: str, s2: str) -> str:
        if s2 in s1:
            return s1
        max_ov = 0
        max_len = min(len(s1), len(s2))
        for k in range(max_len, 0, -1):
            if s1[-k:] == s2[:k]:
                max_ov = k
                break
        return s1 + s2[max_ov:]

    # Remove strings that are substrings of another
    strings = [a, b, c]
    filtered: List[str] = []
    for s in strings:
        if any(s != t and s in t for t in strings):
            continue
        filtered.append(s)

    # If after filtering we have less than 3 strings, pad with empty strings to keep permutations simple
    while len(filtered) < 3:
        filtered.append("")

    best = None
    for perm in itertools.permutations(filtered, 3):
        cur = perm[0]
        cur = merge(cur, perm[1])
        cur = merge(cur, perm[2])
        if best is None or len(cur) < len(best) or (len(cur) == len(best) and cur < best):
            best = cur
    return best if best is not None else ""

