MOD = 10**9 + 7

def decrement_str(s: str) -> str:
    if s == "0":
        return "0"
    lst = list(s)
    i = len(lst) - 1
    while i >= 0:
        if lst[i] == '0':
            lst[i] = '9'
            i -= 1
        else:
            lst[i] = str(int(lst[i]) - 1)
            break
    # remove leading zeros
    result = ''.join(lst).lstrip('0')
    return result if result else "0"

def count_up_to(s: str) -> int:
    n = len(s)

    @lru_cache(maxsize=None)
    def dfs(pos: int, tight: bool, started: bool, prev: int) -> int:
        if pos == n:
            return 1 if started else 0
        limit = int(s[pos]) if tight else 9
        total = 0
        for d in range(0, limit + 1):
            ntight = tight and (d == limit)
            if not started:
                if d == 0:
                    total += dfs(pos + 1, ntight, False, 10)
                else:
                    total += dfs(pos + 1, ntight, True, d)
            else:
                if abs(d - prev) == 1:
                    total += dfs(pos + 1, ntight, True, d)
        return total % MOD

    return dfs(0, True, False, 10)

