    data = sys.stdin.read().strip().split()
    if len(data) < 2:
        return
    low, high = data[0], data[1]
    low_minus_one = decrement_str(low)
    ans = (count_up_to(high) - count_up_to(low_minus_one)) % MOD
    print(ans)

