def minimum_seconds(nums: List[int]) -> int:
    n = len(nums)
    if n == 0:
        return 0
    positions = defaultdict(list)
    for i, v in enumerate(nums):
        positions[v].append(i)

    best = n  # upper bound
    for pos in positions.values():
        if len(pos) == n:
            return 0
        max_gap = 0
        for i in range(len(pos) - 1):
            gap = pos[i + 1] - pos[i] - 1
            if gap > max_gap:
                max_gap = gap
        wrap_gap = pos[0] + n - pos[-1] - 1
        if wrap_gap > max_gap:
            max_gap = wrap_gap
        seconds = (max_gap + 1) // 2
        if seconds < best:
            best = seconds
    return best

