def can_split_array(nums: list[int], m: int) -> bool:
    n = len(nums)
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + nums[i]
    def sum_range(l: int, r: int) -> int:
        return prefix[r + 1] - prefix[l]
    dp = [[False] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = True
    for length in range(2, n + 1):
        for l in range(0, n - length + 1):
            r = l + length - 1
            if sum_range(l, r) < m:
                continue
            for k in range(l, r):
                if dp[l][k] and dp[k + 1][r]:
                    dp[l][r] = True
                    break
    return dp[0][n - 1] if n > 0 else False

