import random
from typing import List

def minimum_absolute_difference(nums: List[int], x: int) -> int:
    class Node:
        __slots__ = ("key", "pri", "cnt", "left", "right")
        def __init__(self, key):
            self.key = key
            self.pri = random.random()
            self.cnt = 1
            self.left = None
            self.right = None

    def rotate_right(p):
        q = p.left
        p.left = q.right
        q.right = p
        return q

    def rotate_left(p):
        q = p.right
        p.right = q.left
        q.left = p
        return q

    def insert(node, key):
        if node is None:
            return Node(key)
        if key == node.key:
            node.cnt += 1
        elif key < node.key:
            node.left = insert(node.left, key)
            if node.left.pri < node.pri:
                node = rotate_right(node)
        else:
            node.right = insert(node.right, key)
            if node.right.pri < node.pri:
                node = rotate_left(node)
        return node

    def lower_bound(node, key):
        if node is None:
            return None
        if node.key >= key:
            left = lower_bound(node.left, key)
            return left if left is not None else node
        return lower_bound(node.right, key)

    def predecessor(node, key):
        if node is None:
            return None
        if node.key < key:
            right = predecessor(node.right, key)
            return right if right is not None else node
        return predecessor(node.left, key)

    root = None
    best = float('inf')
    for i in range(len(nums)):
        if i - x >= 0:
            root = insert(root, nums[i - x])
        lb = lower_bound(root, nums[i])
        if lb is not None:
            diff = lb.key - nums[i]
            if diff < 0:
                diff = -diff
            if diff < best:
                best = diff
        pred = predecessor(root, nums[i])
        if pred is not None:
            diff = pred.key - nums[i]
            if diff < 0:
                diff = -diff
            if diff < best:
                best = diff
    return 0 if best == float('inf') else int(best)

