def max_pair_sum(nums: List[int]) -> int:
    first = [-1] * 10
    second = [-1] * 10
    for n in nums:
        max_digit = 0
        if n == 0:
            max_digit = 0
        else:
            temp = n
            while temp > 0:
                d = temp % 10
                if d > max_digit:
                    max_digit = d
                temp //= 10
        if n > first[max_digit]:
            second[max_digit] = first[max_digit]
            first[max_digit] = n
        elif n > second[max_digit]:
            second[max_digit] = n
    best = -1
    for d in range(10):
        if second[d] != -1:
            s = first[d] + second[d]
            if s > best:
                best = s
    return best

