def maximum_safeness_factor(grid: List[List[int]]) -> int:
    n = len(grid)
    # Multi-source BFS to compute distance to nearest thief (cell with value 1)
    dist = [[-1] * n for _ in range(n)]
    q = collections.deque()
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                dist[i][j] = 0
                q.append((i, j))
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    while q:
        r, c = q.popleft()
        d = dist[r][c] + 1
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n and dist[nr][nc] == -1:
                dist[nr][nc] = d
                q.append((nr, nc))
    max_dist = max(max(row) for row in dist)

    def can_reach(threshold: int) -> bool:
        if dist[0][0] < threshold or dist[n - 1][n - 1] < threshold:
            return False
        visited = [[False] * n for _ in range(n)]
        dq = collections.deque()
        dq.append((0, 0))
        visited[0][0] = True
        while dq:
            r, c = dq.popleft()
            if r == n - 1 and c == n - 1:
                return True
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n and not visited[nr][nc] and dist[nr][nc] >= threshold:
                    visited[nr][nc] = True
                    dq.append((nr, nc))
        return False

    low, high = 0, max_dist
    while low < high:
        mid = (low + high + 1) // 2
        if can_reach(mid):
            low = mid
        else:
            high = mid - 1
    return low

