def beautiful_integers(low: int, high: int, k: int) -> int:
    """Return the count of integers x in [low, high] such that:
       - the number of even digits equals the number of odd digits,
       - x is divisible by k.
    """
    def count_upto(limit: int) -> int:
        if limit < 0:
            return 0
        digits = list(map(int, str(limit)))
        n = len(digits)

        @lru_cache(maxsize=None)
        def dfs(pos: int, diff: int, rem: int, started: bool, tight: bool) -> int:
            if pos == n:
                return int(started and diff == 0 and rem == 0)
            max_digit = digits[pos] if tight else 9
            total = 0
            for d in range(max_digit + 1):
                ntight = tight and (d == max_digit)
                nstarted = started or d != 0
                ndiff = diff
                nrem = rem
                if nstarted:
                    ndiff += 1 if d % 2 else -1
                    nrem = (rem * 10 + d) % k
                total += dfs(pos + 1, ndiff, nrem, nstarted, ntight)
            return total

        return dfs(0, 0, 0, False, True)

    return count_upto(high) - count_upto(low - 1)

