def can_make_equal(s1: str, s2: str) -> bool:
    if len(s1) != len(s2):
        return False

    a_code = ord('a')
    diff = [0] * 26          # net difference between s1 and s2
    freq = [0] * 26          # frequency in s1 (same as in s2 if diff ends zero)

    for ch1, ch2 in zip(s1, s2):
        idx1 = ord(ch1) - a_code
        idx2 = ord(ch2) - a_code
        diff[idx1] += 1
        diff[idx2] -= 1
        freq[idx1] += 1

    # strings must have identical character multiset
    for v in diff:
        if v != 0:
            return False

    # check for any duplicate character in the strings
    for count in freq:
        if count >= 2:
            return True

    # no duplicates: only possible if strings are already equal
    return s1 == s2

def max_sum_almost_unique(nums: list[int], m: int, k: int) -> int:
    if k > len(nums):
        return 0
    freq: dict[int, int] = {}
    distinct_count = 0
    window_sum = 0
    best = 0
    for i, right in enumerate(nums):
        window_sum += right
        right_freq = freq.get(right, 0) + 1
        freq[right] = right_freq
        if right_freq == 1:
            distinct_count += 1
        if i >= k:
            left = nums[i - k]
            window_sum -= left
            left_freq = freq[left] - 1
            if left_freq == 0:
                del freq[left]
                distinct_count -= 1
            else:
                freq[left] = left_freq
        if i >= k - 1:
            if distinct_count >= m and window_sum > best:
                best = window_sum
    return best

