def min_operations(nums: List[int], target: int) -> int:
    MAX_BITS = 31
    cnt = [0] * MAX_BITS
    for v in nums:
        e = 0
        while v > 1:
            v >>= 1
            e += 1
        cnt[e] += 1
    ops = 0
    for i in range(MAX_BITS):
        if (target >> i) & 1:
            if cnt[i] > 0:
                cnt[i] -= 1
            else:
                j = i + 1
                while j < MAX_BITS and cnt[j] == 0:
                    j += 1
                if j == MAX_BITS:
                    return -1
                while j > i:
                    cnt[j] -= 1
                    cnt[j - 1] += 2
                    ops += 1
                    j -= 1
                cnt[i] -= 1
        if i + 1 < MAX_BITS:
            cnt[i + 1] += cnt[i] // 2
    return ops

