def min_operations(num: str) -> int:
    n = len(num)
    answer = n  # worst case: delete all but one digit
    targets = ["00", "25", "50", "75"]
    for t in targets:
        # find rightmost occurrence of the second digit
        i = n - 1
        while i >= 0 and num[i] != t[1]:
            i -= 1
        if i < 0:
            continue
        # find rightmost occurrence of the first digit to the left of i
        j = i - 1
        while j >= 0 and num[j] != t[0]:
            j -= 1
        if j < 0:
            continue
        deletions = (n - 1 - i) + (i - 1 - j)
        if deletions < answer:
            answer = deletions
    # also consider keeping a single '0' (making the number 0)
    if '0' in num:
        answer = min(answer, n - 1)
    return answer

