def min_moves(grid: List[List[int]]) -> int:
    stones = []
    for i in range(3):
        for j in range(3):
            for _ in range(grid[i][j]):
                stones.append((i, j))
    # there are exactly 9 stones
    targets = [(i, j) for i in range(3) for j in range(3)]
    n = 9
    cost = [[0] * n for _ in range(n)]
    for i in range(n):
        sx, sy = stones[i]
        for j in range(n):
            tx, ty = targets[j]
            cost[i][j] = abs(sx - tx) + abs(sy - ty)
    INF = 10 ** 9
    dp = [INF] * (1 << n)
    dp[0] = 0
    for mask in range(1 << n):
        k = mask.bit_count()
        if k >= n:
            continue
        cur = dp[mask]
        if cur == INF:
            continue
        for j in range(n):
            if not (mask >> j) & 1:
                new_mask = mask | (1 << j)
                new_cost = cur + cost[k][j]
                if new_cost < dp[new_mask]:
                    dp[new_mask] = new_cost
    return dp[(1 << n) - 1]

