MOD = 1000000007

def count_transform_ways(s: str, t: str, k: int) -> int:
    # Verify strings have same length
    if len(s) != len(t):
        return 0

    # Build mapping from characters in s to characters in t
    mapping = {}
    for ch_s, ch_t in zip(s, t):
        if ch_s in mapping:
            if mapping[ch_s] != ch_t:
                return 0
        else:
            mapping[ch_s] = ch_t

    # Determine distinct characters that actually appear
    distinct_chars = set(s) | set(t)
    d = len(distinct_chars)

    # Find cycles in the permutation defined by mapping
    visited = set()
    m = 0  # minimal number of swaps needed
    for ch in distinct_chars:
        if ch in visited:
            continue
        # follow the cycle starting at ch
        cur = ch
        cycle_len = 0
        while cur not in visited:
            visited.add(cur)
            cycle_len += 1
            cur = mapping.get(cur, cur)  # fixed points stay the same
        if cycle_len > 1:
            m += cycle_len - 1

    if k < m:
        return 0

    # Pre‑compute factorials up to k
    fact = [1] * (k + 1)
    for i in range(2, k + 1):
        fact[i] = fact[i - 1] * i % MOD

    # Compute modular inverse of (k‑m)! using Fermat's little theorem
    inv_fact_km = pow(fact[k - m], MOD - 2, MOD)

    # Number of ways: k! / (k‑m)! * d^{k‑m}
    ans = fact[k] * inv_fact_km % MOD
    ans = ans * pow(d, k - m, MOD) % MOD
    return ans

