def max_complete_subset_sum(nums: List[int]) -> int:
    n = len(nums)
    # smallest prime factor for each number up to n
    spf = [0] * (n + 1)
    for i in range(2, n + 1):
        if spf[i] == 0:
            for j in range(i, n + 1, i):
                if spf[j] == 0:
                    spf[j] = i
    def square_free(x: int) -> int:
        res = 1
        while x > 1:
            p = spf[x]
            cnt = 0
            while x % p == 0:
                x //= p
                cnt ^= 1  # keep parity only
            if cnt:
                res *= p
        return res
    group_sum = defaultdict(int)
    for idx, val in enumerate(nums, start=1):
        sf = square_free(idx)
        group_sum[sf] += val
    return max(group_sum.values()) if group_sum else 0

