def solve(n: int, k: int, budget: int, composition: List[List[int]], stock: List[int], cost: List[int]) -> int:
    total_stock_value = sum(stock[i] * cost[i] for i in range(n))
    min_cost_per_alloy = min(
        sum(composition[i][j] * cost[j] for j in range(n)) for i in range(k)
    )
    high = (budget + total_stock_value) // min_cost_per_alloy + 1

    def feasible(x: int) -> bool:
        for i in range(k):
            total = 0
            comp = composition[i]
            for j in range(n):
                need = comp[j] * x - stock[j]
                if need > 0:
                    total += need * cost[j]
                    if total > budget:
                        break
            if total <= budget:
                return True
        return False

    low = 0
    while low < high:
        mid = (low + high + 1) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid - 1
    return low
