def count_valid_paths(n: int, edges):
    is_prime = bytearray(n + 1)
    if n >= 2:
        is_prime[2:] = b'\x01' * (n - 1)
        i = 2
        while i * i <= n:
            if is_prime[i]:
                step = i
                start = i * i
                for j in range(start, n + 1, step):
                    is_prime[j] = 0
            i += 1

    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    comp_id = [0] * (n + 1)
    comp_size = [0] * (n + 1)
    comp_cnt = 0
    stack = []
    for i in range(1, n + 1):
        if is_prime[i] or comp_id[i]:
            continue
        comp_cnt += 1
        size = 0
        stack.append(i)
        comp_id[i] = comp_cnt
        while stack:
            node = stack.pop()
            size += 1
            for nb in adj[node]:
                if not is_prime[nb] and not comp_id[nb]:
                    comp_id[nb] = comp_cnt
                    stack.append(nb)
        comp_size[comp_cnt] = size

    answer = 0
    for p in range(1, n + 1):
        if not is_prime[p]:
            continue
        total = 0
        sum_sq = 0
        for nb in adj[p]:
            if is_prime[nb]:
                continue
            sz = comp_size[comp_id[nb]]
            total += sz
            sum_sq += sz * sz
        if total == 0:
            continue
        contribution = total + (total * total - sum_sq) // 2
        answer += contribution

    return answer

