def max_k_divisible_components(n: int, edges: List[Tuple[int, int]], values: List[int], k: int) -> int:
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    def dfs(u: int, parent: int) -> Tuple[int, int]:
        sum_mod = values[u] % k
        comps = 0
        for v in adj[u]:
            if v == parent:
                continue
            child_mod, child_comps = dfs(v, u)
            if child_mod == 0:
                comps += child_comps + 1
            else:
                comps += child_comps
                sum_mod = (sum_mod + child_mod) % k
        return sum_mod, comps

    root_mod, root_comps = dfs(0, -1)
    return root_comps + (1 if root_mod == 0 else 0)

