    answer = [0] * n
    root_reversals = 0
    stack = [(0, -1)]
    while stack:
        node, parent = stack.pop()
        for nei, cost in adj[node]:
            if nei == parent:
                continue
            root_reversals += cost
            stack.append((nei, node))
    answer[0] = root_reversals

    stack2 = [(0, -1)]
    while stack2:
        node, parent = stack2.pop()
        for nei, cost in adj[node]:
            if nei == parent:
                continue
            answer[nei] = answer[node] + (1 if cost == 0 else -1)
            stack2.append((nei, node))

    return answer

