def shortest_beautiful_substring(s: str, k: int) -> str:
    n = len(s)
    left = 0
    ones = 0
    min_len = float('inf')
    for right in range(n):
        if s[right] == '1':
            ones += 1
        while ones > k:
            if s[left] == '1':
                ones -= 1
            left += 1
        while ones == k and s[left] == '0':
            left += 1
        if ones == k:
            cur_len = right - left + 1
            if cur_len < min_len:
                min_len = cur_len
    if min_len == float('inf'):
        return ""
    best = ""
    count_ones = 0
    for i in range(min_len):
        if s[i] == '1':
            count_ones += 1
    if count_ones == k:
        best = s[:min_len]
    for start in range(1, n - min_len + 1):
        if s[start - 1] == '1':
            count_ones -= 1
        if s[start + min_len - 1] == '1':
            count_ones += 1
        if count_ones == k:
            sub = s[start:start + min_len]
            if best == "" or sub < best:
                best = sub
    return best

