def longest_unequal_adjacent_groups_subsequence(words: List[str], groups: List[int]) -> List[str]:
    n = len(words)
    if n == 0:
        return []
    # dp_len[i]: length of best subsequence ending at i
    dp_len: List[int] = [1] * n
    # dp_seq[i]: the actual best subsequence (as list of words) ending at i
    dp_seq: List[List[str]] = [[words[i]] for i in range(n)]

    for i in range(n):
        for j in range(i):
            if groups[j] != groups[i]:
                cand_len = dp_len[j] + 1
                cand_seq = dp_seq[j] + [words[i]]
                if cand_len > dp_len[i] or (cand_len == dp_len[i] and cand_seq < dp_seq[i]):
                    dp_len[i] = cand_len
                    dp_seq[i] = cand_seq

    # choose the overall best subsequence
    best_seq: List[str] = dp_seq[0]
    best_len = dp_len[0]
    for i in range(1, n):
        if dp_len[i] > best_len or (dp_len[i] == best_len and dp_seq[i] < best_seq):
            best_len = dp_len[i]
            best_seq = dp_seq[i]

