def min_changes(s: str, k: int) -> int:
    n = len(s)
    if k >= n:
        return 0
    cost = [[0] * n for _ in range(n)]
    for length in range(2, n + 1):
        for i in range(0, n - length + 1):
            j = i + length - 1
            if s[i] == s[j]:
                cost[i][j] = 0 if length == 2 else cost[i + 1][j - 1]
            else:
                cost[i][j] = 1 if length == 2 else cost[i + 1][j - 1] + 1
    INF = 10 ** 9
    dp = [[INF] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 0
    for p in range(1, k + 1):
        for i in range(1, n + 1):
            for t in range(p - 1, i):
                prev = dp[p - 1][t]
                if prev == INF:
                    continue
                cur = prev + cost[t][i - 1]
                if cur < dp[p][i]:
                    dp[p][i] = cur
    return dp[k][n]

