def max_length(x: int, y: int, z: int) -> int:
    @lru_cache(None)
    def dfs(a: int, b: int, c: int, last: str, run: int) -> int:
        best = 0

        def can_add(piece: str):
            nonlocal last, run
            cur_last, cur_run = last, run
            for ch in piece:
                if cur_last == ch:
                    cur_run += 1
                else:
                    cur_last = ch
                    cur_run = 1
                if cur_run == 3:
                    return None
            return cur_last, cur_run

        if a > 0:
            res = can_add("AA")
            if res is not None:
                nl, nr = res
                best = max(best, 2 + dfs(a - 1, b, c, nl, nr))
        if b > 0:
            res = can_add("BB")
            if res is not None:
                nl, nr = res
                best = max(best, 2 + dfs(a, b - 1, c, nl, nr))
        if c > 0:
            res = can_add("AB")
            if res is not None:
                nl, nr = res
                best = max(best, 2 + dfs(a, b, c - 1, nl, nr))
        return best

    return dfs(x, y, z, "", 0)

