def count_beautiful_pairs(nums: List[int]) -> int:
    def first_digit(x: int) -> int:
        if x == 0:
            return 0
        while x >= 10:
            x //= 10
        return x

    def last_digit(x: int) -> int:
        return abs(x) % 10

    def gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    n = len(nums)
    count = 0
    for i in range(n):
        fd_i = first_digit(nums[i])
        for j in range(i + 1, n):
            ld_j = last_digit(nums[j])
            if gcd(fd_i, ld_j) == 1:
                count += 1
    return count

def min_operations(num1: int, num2: int) -> int:
    if num1 == 0:
        return 0
    # try all possible operation counts k
    for k in range(0, 61):
        remaining = num1 - k * num2
        if remaining < 0:
            continue
        # smallest sum of k powers of two is k (all ones)
        if remaining < k:
            continue
        # popcount gives minimal number of powers needed
        if (remaining.bit_count() if hasattr(int, "bit_count") else bin(remaining).count("1")) <= k:
            return k
    return -1

