from collections import Counter

def min_groups_for_valid_assignment(balls: List[int]) -> int:
    if not balls:
        return 0

    freq = list(Counter(balls).values())
    max_freq = max(freq)

    def feasible(s: int) -> bool:
        # For each frequency f, need an integer g with f/(s+1) <= g <= f/s
        # This is equivalent to floor(f/s) >= ceil(f/(s+1))
        for f in freq:
            if f // s < (f + s) // (s + 1):
                return False
        return True

    lo, hi = 1, max_freq
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid - 1

    s = lo
    total_groups = sum((f + s) // (s + 1) for f in freq)
    return total_groups

