def maximum_points(edges: List[List[int]], coins: List[int], k: int) -> int:
    sys.setrecursionlimit(200000)

    n = len(coins)
    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)

    # Build rooted tree (root = 0)
    parent = [-1] * n
    order = [0]
    parent[0] = 0
    for u in order:
        for v in adj[u]:
            if v != parent[u]:
                parent[v] = u
                order.append(v)

    children = [[] for _ in range(n)]
    for v in range(1, n):
        children[parent[v]].append(v)

    @lru_cache(maxsize=None)
    def dp(node: int, cur_val: int) -> int:
        # Option 1: take all coins, pay k
        total1 = cur_val - k
        for ch in children[node]:
            total1 += dp(ch, coins[ch])

        # Option 2: take half, halve children's coins
        total2 = cur_val // 2
        for ch in children[node]:
            total2 += dp(ch, coins[ch] // 2)

        return max(total1, total2)

    return dp(0, coins[0])

