def max_balanced_subsequence_sum(nums: List[int]) -> int:
    n = len(nums)
    a = [nums[i] - i for i in range(n)]

    uniq = sorted(set(a), reverse=True)
    rank = {v: i + 1 for i, v in enumerate(uniq)}  # 1‑based Fenwick indices

    m = len(uniq)
    NEG_INF = -10**30
    tree = [NEG_INF] * (m + 1)

    def query(i: int) -> int:
        """maximum dp value for ranks ≤ i (i.e., a_j ≥ current a)"""
        res = NEG_INF
        while i:
            if tree[i] > res:
                res = tree[i]
            i -= i & -i
        return res

    def update(i: int, val: int) -> None:
        """store max value at rank i"""
        while i <= m:
            if val > tree[i]:
                tree[i] = val
            i += i & -i

    best_overall = NEG_INF
    for i in range(n):
        idx = rank[a[i]]
        best_prev = query(idx)          # best dp where a_j ≥ a_i
        if best_prev == NEG_INF:
            cur = nums[i]                # start new subsequence
        else:
            cur = max(nums[i], nums[i] + best_prev)
        if cur > best_overall:
            best_overall = cur
        update(idx, cur)

    return best_overall

