    def try_case(end1, end2):
        ops = 0
        for i in range(n - 1):
            a, b = nums1[i], nums2[i]
            no_swap_ok = a <= end1 and b <= end2
            swap_ok = b <= end1 and a <= end2
            if no_swap_ok:
                continue
            elif swap_ok:
                ops += 1
            else:
                return -1
        return ops
