def maximum_strong_pair_xor(nums: List[int]) -> int:
    nums.sort()
    MAX_BIT = 20
    root = {'children': [None, None], 'cnt': 0}
    def insert(val: int) -> None:
        node = root
        node['cnt'] += 1
        for i in range(MAX_BIT, -1, -1):
            bit = (val >> i) & 1
            if not node['children'][bit]:
                node['children'][bit] = {'children': [None, None], 'cnt': 0}
            node = node['children'][bit]
            node['cnt'] += 1
    def remove(val: int) -> None:
        node = root
        node['cnt'] -= 1
        for i in range(MAX_BIT, -1, -1):
            bit = (val >> i) & 1
            node = node['children'][bit]
            node['cnt'] -= 1
    def query(val: int) -> int:
        node = root
        xor = 0
        for i in range(MAX_BIT, -1, -1):
            bit = (val >> i) & 1
            toggled = bit ^ 1
            child = node['children'][toggled]
            if child and child['cnt'] > 0:
                xor |= (1 << i)
                node = child
            else:
                node = node['children'][bit]
        return xor
    ans = 0
    left = 0
    for right in range(len(nums)):
        while nums[right] > 2 * nums[left]:
            remove(nums[left])
            left += 1
        insert(nums[right])
        cur = query(nums[right])
        if cur > ans:
            ans = cur
    return ans

