def find_meeting_building(heights: List[int], queries: List[List[int]]) -> List[int]:
    n = len(heights)
    if n == 0:
        return [-1] * len(queries)

    size = 1
    while size < n:
        size <<= 1
    seg = [0] * (2 * size)

    # build segment tree (max)
    for i in range(n):
        seg[size + i] = heights[i]
    for i in range(size - 1, 0, -1):
        seg[i] = seg[i << 1] if seg[i << 1] >= seg[(i << 1) | 1] else seg[(i << 1) | 1]

    def first_greater(pos: int, threshold: int) -> int:
        """Return leftmost index >= pos with height > threshold, or -1."""
        # internal recursive search
        def _search(node: int, l: int, r: int) -> int:
            if r < pos or seg[node] <= threshold:
                return -1
            if l == r:
                return l
            mid = (l + r) >> 1
            left_res = _search(node << 1, l, mid)
            if left_res != -1:
                return left_res
            return _search((node << 1) | 1, mid + 1, r)

        return _search(1, 0, size - 1)

    result: List[int] = []
    for a, b in queries:
        if a == b:
            result.append(a)
            continue
        # ensure a is the smaller index
        if a > b:
            a, b = b, a
        # now b is the larger index
        if heights[b] > heights[a]:
            result.append(b)
            continue
        # need a building to the right of b
        idx = first_greater(b + 1, max(heights[a], heights[b]))
        result.append(idx if idx != -1 else -1)

    return result

