def number_of_sets(n: int, max_distance: int, roads: List[List[int]]) -> int:
    INF = 10 ** 15
    # store roads for reuse
    road_list = [(u, v, w) for u, v, w in roads]

    total = 0
    # iterate over all subsets of closed branches
    for mask in range(1 << n):
        # active nodes are those not closed
        active = [i for i in range(n) if not (mask >> i) & 1]
        if len(active) <= 1:
            total += 1
            continue

        # initialise distance matrix for active nodes
        d = [[INF] * n for _ in range(n)]
        for i in active:
            d[i][i] = 0

        # add edges that connect two active nodes
        for u, v, w in road_list:
            if (mask >> u) & 1:  # u closed
                continue
            if (mask >> v) & 1:  # v closed
                continue
            if w < d[u][v]:
                d[u][v] = d[v][u] = w

        # Floyd‑Warshall on the active set
        for k in active:
            dk = d[k]
            for i in active:
                dik = d[i][k]
                if dik == INF:
                    continue
                di = d[i]
                for j in active:
                    nd = dik + dk[j]
                    if nd < di[j]:
                        di[j] = nd

        # check if all pairwise distances are within max_distance
        ok = True
        for i in active:
            for j in active:
                if d[i][j] > max_distance:
                    ok = False
                    break
            if not ok:
                break

        if ok:
            total += 1

    return total

