def min_cost_to_make_equalindromic(nums: List[int]) -> int:
    if not nums:
        return 0

    n = len(nums)
    sorted_nums = sorted(nums)

    # Helper to build palindrome from prefix
    def build_pal(prefix: int, odd: bool) -> int:
        s = str(prefix)
        if odd:
            return int(s + s[-2::-1])  # exclude middle char when mirroring
        else:
            return int(s + s[::-1])

    # Find nearest palindromes to a given value
    def nearest_palindromes(x: int) -> List[int]:
        s = str(x)
        length = len(s)
        odd = length % 2 == 1
        half_len = (length + 1) // 2
        prefix = int(s[:half_len])

        candidates = set()
        for delta in (-1, 0, 1):
            p = prefix + delta
            if p <= 0:
                continue
            pal = build_pal(p, odd)
            candidates.add(pal)

        # Edge cases: 9...9 (one less digit) and 1...01 (one more digit)
        candidates.add(10 ** (length - 1) - 1)          # e.g., 99 -> 9, 1000 -> 999
        candidates.add(10 ** length + 1)               # e.g., 99 -> 101, 999 -> 1001

        return list(candidates)

    # Determine median candidates
    median_vals = {sorted_nums[(n - 1) // 2], sorted_nums[n // 2]}

    best_cost = float('inf')
    for med in median_vals:
        for pal in nearest_palindromes(med):
            cost = sum(abs(num - pal) for num in nums)
            if cost < best_cost:
                best_cost = cost

    return int(best_cost)  # type: ignore

