import sys

def placed_coins(edges: List[List[int]], cost: List[int]) -> List[int]:
    sys.setrecursionlimit(10 ** 6)
    n = len(cost)
    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)

    result = [0] * n

    def dfs(u: int, parent: int):
        # keep top three largest values (descending) and bottom two smallest values (ascending)
        largest = [cost[u]]
        smallest = [cost[u]]
        size = 1

        for v in adj[u]:
            if v == parent:
                continue
            child_largest, child_smallest, child_size = dfs(v, u)
            size += child_size

            # merge largest (keep at most 3 descending)
            for val in child_largest:
                # insert val into largest keeping descending order
                inserted = False
                for i in range(len(largest)):
                    if val > largest[i]:
                        largest.insert(i, val)
                        inserted = True
                        break
                if not inserted:
                    largest.append(val)
                if len(largest) > 3:
                    largest.pop()  # remove smallest among kept

            # merge smallest (keep at most 2 ascending)
            for val in child_smallest:
                inserted = False
                for i in range(len(smallest)):
                    if val < smallest[i]:
                        smallest.insert(i, val)
                        inserted = True
                        break
                if not inserted:
                    smallest.append(val)
                if len(smallest) > 2:
                    smallest.pop()  # remove largest among kept

        # compute answer for node u
        if size < 3:
            ans = 1
        else:
            cand = []
            if len(largest) >= 3:
                cand.append(largest[0] * largest[1] * largest[2])
            if len(smallest) >= 2 and len(largest) >= 1:
                cand.append(smallest[0] * smallest[1] * largest[0])
            max_prod = max(cand) if cand else 0
            ans = max_prod if max_prod > 0 else 0
        result[u] = ans
        return largest, smallest, size

    dfs(0, -1)
    return result

