import heapq

def minimum_cost(source: str, target: str,
                 original: List[str], changed: List[str],
                 cost: List[int]) -> int:
    n = len(source)
    # group operations by length
    ops_by_len = {}
    for o, c, w in zip(original, changed, cost):
        L = len(o)
        ops_by_len.setdefault(L, []).append((o, c, w))

    # adjacency list for each length: original string -> list of (changed, cost)
    adj_by_len = {}
    for L, ops in ops_by_len.items():
        adj = {}
        for o, c, w in ops:
            adj.setdefault(o, []).append((c, w))
        adj_by_len[L] = adj

    INF = 10 ** 18
    # memo for interval costs
    interval_cost = [[None] * n for _ in range(n)]

    def cost_interval(l: int, r: int) -> int:
        """minimum cost to convert source[l..r] to target[l..r]"""
        if interval_cost[l][r] is not None:
            return interval_cost[l][r]

        src = source[l:r+1]
        tgt = target[l:r+1]
        if src == tgt:
            interval_cost[l][r] = 0
            return 0

        L = r - l + 1
        if L not in adj_by_len:
            interval_cost[l][r] = INF
            return INF

        adj = adj_by_len[L]

        # start must be an original of some operation, otherwise impossible
        if src not in adj:
            interval_cost[l][r] = INF
            return INF

        # Dijkstra
        heap = [(0, src)]
        dist = {src: 0}
        while heap:
            d, cur = heapq.heappop(heap)
            if d != dist[cur]:
                continue
            if cur == tgt:
                break
            for nxt, w in adj.get(cur, []):
                nd = d + w
                if nd < dist.get(nxt, INF):
                    dist[nxt] = nd
                    heapq.heappush(heap, (nd, nxt))

        ans = dist.get(tgt, INF)
        interval_cost[l][r] = ans
        return ans

    dp = [INF] * (n + 1)
    dp[0] = 0
    for i in range(1, n + 1):
        best = INF
        for j in range(i):
            c = cost_interval(j, i - 1)
            if c != INF and dp[j] + c < best:
                best = dp[j] + c
        dp[i] = best

    return -1 if dp[n] == INF else dp[n]
# TIME: O(n^2 * (E log V)) SPACE: O(n^2)

