def min_cost_to_convert_string(source: str, target: str, original: List[str], changed: List[str], cost: List[int]) -> int:
    INF = 10**18
    n = 26
    dist = [[INF] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0

    for o, c, w in zip(original, changed, cost):
        u = ord(o) - 97
        v = ord(c) - 97
        if w < dist[u][v]:
            dist[u][v] = w

    for k in range(n):
        dk = dist[k]
        for i in range(n):
            di = dist[i]
            ik = di[k]
            if ik == INF:
                continue
            nd_base = ik
            for j in range(n):
                kj = dk[j]
                if kj == INF:
                    continue
                nd = nd_base + kj
                if nd < di[j]:
                    di[j] = nd

    total = 0
    for s_char, t_char in zip(source, target):
        if s_char == t_char:
            continue
        d = dist[ord(s_char) - 97][ord(t_char) - 97]
        if d == INF:
            return -1
        total += d
    return total

