from collections import Counter

def can_make_palindrome(s: str, queries: List[List[int]]) -> List[bool]:
    n = len(s)
    half = n // 2
    result: List[bool] = []

    for a, b, c, d in queries:
        # count characters that can be rearranged
        cnt = Counter(s[a:b + 1]) + Counter(s[c:d + 1])

        possible = True

        for i in range(half):
            j = n - 1 - i
            i_flex = (a <= i <= b) or (c <= i <= d)
            j_flex = (a <= j <= b) or (c <= j <= d)

            if not i_flex and not j_flex:
                if s[i] != s[j]:
                    possible = False
                    break
            elif i_flex and not j_flex:
                need = s[j]
                if cnt[need] == 0:
                    possible = False
                    break
                cnt[need] -= 1
            elif not i_flex and j_flex:
                need = s[i]
                if cnt[need] == 0:
                    possible = False
                    break
                cnt[need] -= 1
            # else both flexible – handled later

        if possible:
            mid_flex = (a <= half <= b) or (c <= half <= d) if n % 2 == 1 else False
            odd_counts = sum(v % 2 for v in cnt.values())
            if mid_flex:
                possible = odd_counts <= 1
            else:
                possible = odd_counts == 0

        result.append(possible)

    return result

def min_operations(x, y):
    if x == y:
        return 0
    queue = [(x, 0)]
    visited = {x}
    head = 0
    while head < len(queue):
        current, steps = queue[head]
        head += 1
        if current == y:
            return steps
        nxts = []
        if current % 5 == 0:
            nxts.append(current // 5)
        if current % 11 == 0:
            nxts.append(current // 11)
        nxts.append(current + 1)
        nxts.append(current - 1)
        for nxt in nxts:
            if nxt <= 0 or nxt in visited:
                continue
            visited.add(nxt)
            queue.append((nxt, steps + 1))
    return -1

