def min_moves_to_capture_the_queen(a: int, b: int, c: int, d: int, e: int, f: int) -> int:
    INF = 10 ** 9

    def between(p1: int, p2: int, x: int) -> bool:
        """Return True if x lies strictly between p1 and p2."""
        return (p1 < x < p2) or (p2 < x < p1)

    def blocked_rook(pos: Tuple[int, int], target: Tuple[int, int], blocker: Tuple[int, int]) -> bool:
        """True if blocker lies on the rook line between pos and target."""
        if pos[0] == target[0] == blocker[0] and between(pos[1], target[1], blocker[1]):
            return True
        if pos[1] == target[1] == blocker[1] and between(pos[0], target[0], blocker[0]):
            return True
        return False

    def blocked_bishop(pos: Tuple[int, int], target: Tuple[int, int], blocker: Tuple[int, int]) -> bool:
        """True if blocker lies on the bishop diagonal between pos and target."""
        if abs(pos[0] - target[0]) == abs(pos[1] - target[1]) and \
           abs(pos[0] - blocker[0]) == abs(pos[1] - blocker[1]) and \
           between(pos[0], target[0], blocker[0]):
            return True
        return False

    def can_capture_direct(pos: Tuple[int, int], target: Tuple[int, int], blocker: Tuple[int, int], piece: str) -> bool:
        if piece == "rook":
            if pos[0] == target[0] or pos[1] == target[1]:
                return not blocked_rook(pos, target, blocker)
        else:  # bishop
            if abs(pos[0] - target[0]) == abs(pos[1] - target[1]):
                return not blocked_bishop(pos, target, blocker)
        return False

    def min_moves_piece(start: Tuple[int, int], blocker: Tuple[int, int], target: Tuple[int, int], piece: str) -> int:
        if start == target:
            return 0
        if can_capture_direct(start, target, blocker, piece):
            return 1

        # generate all squares reachable in one move
        dirs = []
        if piece == "rook":
            dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]
        else:  # bishop
            dirs = [(1, 1), (1, -1), (-1, 1), (-1, -1)]

        for dx, dy in dirs:
            x, y = start
            while True:
                x += dx
                y += dy
                if not (1 <= x <= 8 and 1 <= y <= 8):
                    break
                if (x, y) == blocker:
                    break  # cannot land on or pass through blocker
                # from (x,y) try to capture target in one move
                if can_capture_direct((x, y), target, blocker, piece):
                    return 2
        return INF

    rook_start = (a, b)
    bishop_start = (c, d)
    queen = (e, f)

    rook_moves = min_moves_piece(rook_start, bishop_start, queen, "rook")
    bishop_moves = min_moves_piece(bishop_start, rook_start, queen, "bishop")

    ans = min(rook_moves, bishop_moves)
    return -1 if ans >= INF else ans

def max_partitions(s: str, k: int) -> int:
    max_partitions = 1
    for i in range(len(s)):
        changed = False
        for j in range(97, 123):
            char = chr(j)
            if char == s[i]:
                continue
            new_s = s[:i] + char + s[i + 1:]
            partition_count = 0
            current_distinct = set()
            for m in range(len(new_s)):
                current_distinct.add(new_s[m])
                if len(current_distinct) > k:
                    partition_count += 1
                    current_distinct = {new_s[m]}
            partition_count += 1
            if partition_count > max_partitions:
                max_partitions = partition_count
            changed = True
        if not changed:
            partition_count = 0
            current_distinct = set()
            for m in range(len(s)):
                current_distinct.add(s[m])
                if len(current_distinct) > k:
                    partition_count += 1
                    current_distinct = {s[m]}
            partition_count += 1
            if partition_count > max_partitions:
                max_partitions = partition_count
    return max_partitions

