def find_grid_region_average(image: List[List[int]], threshold: int) -> List[List[int]]:
    m = len(image)
    n = len(image[0])
    sum_grid = [[0] * n for _ in range(m)]
    cnt = [[0] * n for _ in range(m)]
    for i in range(m - 2):
        for j in range(n - 2):
            ok = True
            for r in range(3):
                if not ok:
                    break
                for c in range(3):
                    cur = image[i + r][j + c]
                    if c < 2 and abs(cur - image[i + r][j + c + 1]) > threshold:
                        ok = False
                        break
                    if r < 2 and abs(cur - image[i + r + 1][j + c]) > threshold:
                        ok = False
                        break
            if not ok:
                continue
            region_sum = 0
            for r in range(3):
                for c in range(3):
                    region_sum += image[i + r][j + c]
            region_avg = region_sum // 9
            for r in range(3):
                for c in range(3):
                    x = i + r
                    y = j + c
                    sum_grid[x][y] += region_avg
                    cnt[x][y] += 1
    result = [[0] * n for _ in range(m)]
    for i in range(m):
        for j in range(n):
            result[i][j] = image[i][j] if cnt[i][j] == 0 else sum_grid[i][j] // cnt[i][j]
    return result

