def minimum_time_to_revert(word, k):
    n = len(word)
    max_t = math.ceil(n / k)
    for t in range(1, max_t + 1):
        d = k * t
        if d > n:
            return t
        ok = True
        for i in range(n - d):
            if word[i] != word[i + d]:
                ok = False
                break
        if ok:
            return t
    return max_t

