def minimum_time(word: str, k: int) -> int:
    n = len(word)
    pi = [0] * n
    for i in range(1, n):
        j = pi[i - 1]
        while j > 0 and word[i] != word[j]:
            j = pi[j - 1]
        if word[i] == word[j]:
            j += 1
        pi[i] = j
    borders = [0]
    length = pi[n - 1] if n > 0 else 0
    while length > 0:
        borders.append(length)
        length = pi[length - 1]
    ans = math.ceil(n / k)
    for L in borders:
        diff = n - L
        if diff > 0 and diff % k == 0:
            t = diff // k
            if t < ans:
                ans = t
    return ans

