def number_of_subarrays(nums: List[int], pattern: List[int]) -> int:
    n = len(nums)
    m = len(pattern)

    if m == 0:
        return n
    if m > n - 1:
        return 0

    diff = [0] * (n - 1)
    for i in range(n - 1):
        delta = nums[i + 1] - nums[i]
        diff[i] = 1 if delta > 0 else -1 if delta < 0 else 0

    lps = [0] * m
    i = 1
    length = 0
    while i < m:
        if pattern[i] == pattern[length]:
            length += 1
            lps[i] = length
            i += 1
        elif length:
            length = lps[length - 1]
        else:
            lps[i] = 0
            i += 1

    count = 0
    i = 0
    j = 0
    while i < len(diff):
        if diff[i] == pattern[j]:
            i += 1
            j += 1
            if j == m:
                count += 1
                j = lps[j - 1]
        elif j:
            j = lps[j - 1]
        else:
            i += 1

    return count

def max_palindromes(words):
    freq = [0] * 26
    for w in words:
        for c in w:
            freq[ord(c) - ord('a')] += 1
    total_pairs = 0
    total_singles = 0
    for cnt in freq:
        total_pairs += cnt // 2
        total_singles += cnt % 2
    lengths = [len(w) for w in words]
    lengths.sort()
    count = 0
    for length in lengths:
        need_pairs = length // 2
        if length % 2 == 0:
            if total_pairs >= need_pairs:
                total_pairs -= need_pairs
                count += 1
        else:
            extra = 0 if total_singles > 0 else 1
            if total_pairs >= need_pairs + extra:
                total_pairs -= need_pairs
                if total_singles > 0:
                    total_singles -= 1
                else:
                    total_pairs -= 1
                count += 1
    return count

