def count_matching_subarrays(nums: List[int], pattern: List[int]) -> int:
    n = len(nums)
    m = len(pattern)
    if m == 0 or n < m + 1:
        return 0

    # Build diff array of signs
    diff = [0] * (n - 1)
    for i in range(n - 1):
        d = nums[i + 1] - nums[i]
        if d > 0:
            diff[i] = 1
        elif d < 0:
            diff[i] = -1
        else:
            diff[i] = 0

    # Prefix function for pattern (KMP)
    pi = [0] * m
    j = 0
    for i in range(1, m):
        while j > 0 and pattern[i] != pattern[j]:
            j = pi[j - 1]
        if pattern[i] == pattern[j]:
            j += 1
            pi[i] = j

    # KMP search
    count = 0
    j = 0
    for val in diff:
        while j > 0 and val != pattern[j]:
            j = pi[j - 1]
        if val == pattern[j]:
            j += 1
            if j == m:
                count += 1
                j = pi[j - 1]
    return count

