def _feasible(s: int, nums: List[int], pos: List[List[int]], n: int) -> bool:
    tasks = []
    total_decrements = 0
    for i in range(1, n + 1):
        v = pos[i]
        if not v:
            return False
        idx = bisect_right(v, s) - 1
        if idx < 0:
            return False
        latest = v[idx]
        tasks.append((latest - 1, nums[i - 1]))
        total_decrements += nums[i - 1]
    if total_decrements > s - n:
        return False
    tasks.sort(key=lambda x: x[0])
    cum = 0
    for deadline, need in tasks:
        cum += need
        if cum > deadline:
            return False
    return True

