    lo, hi, ans = 1, m, -1
    while lo <= hi:
        mid = (lo + hi) // 2
        if _feasible(mid, nums, pos, n):
            ans = mid
            hi = mid - 1
        else:
            lo = mid + 1
    return ans

import heapq

def earliestSecondToMarkIndices(nums, changeIndices):
    n = len(nums)
    m = len(changeIndices)
    numsSum = sum(nums)

    # earliest second (0-indexed) each index first appears in changeIndices (only while nums[idx]>0)
    indexToFirstSecond = {}
    for s in range(m):
        idx = changeIndices[s] - 1
        if nums[idx] > 0 and idx not in indexToFirstSecond:
            indexToFirstSecond[idx] = s
    secondToIndex = {s: idx for idx, s in indexToFirstSecond.items()}

    def canMark(maxSecond):
        # scan backward; bank "marks" when there's nothing to zero at this second,
        # spend a mark (or evict the least-valuable heap candidate if none banked) otherwise
        minHeap = []
        marks = 0
        for second in range(maxSecond - 1, -1, -1):
            if second in secondToIndex:
                idx = secondToIndex[second]
                heapq.heappush(minHeap, nums[idx])
                if marks == 0:
                    heapq.heappop(minHeap)  # least beneficial candidate gets demoted
                    marks += 1
                else:
                    marks -= 1
            else:
                marks += 1
        heapSum = sum(minHeap)
        heapSize = len(minHeap)
        # indices left in the heap get "zero via changeIndices + mark" (2 seconds each);
        # the rest need full decrement (nums[i] seconds) + 1 mark second
        decrementAndMarkCost = (numsSum - heapSum) + (n - heapSize)
        zeroAndMarkCost = heapSize * 2
        return decrementAndMarkCost + zeroAndMarkCost <= maxSecond

    lo, hi = 0, m + 1
    while lo < hi:
        mid = (lo + hi) // 2
        if canMark(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo if lo <= m else -1

