def max_sum(nums: List[int], k: int, edges: List[List[int]]) -> int:
    base_sum = sum(nums)
    pos_sum = 0
    pos_cnt = 0
    min_pos = None          # smallest positive diff
    max_neg = None          # largest (closest to zero) negative diff

    for x in nums:
        y = x ^ k
        diff = y - x
        if diff > 0:
            pos_sum += diff
            pos_cnt += 1
            if min_pos is None or diff < min_pos:
                min_pos = diff
        else:
            if max_neg is None or diff > max_neg:
                max_neg = diff

    if pos_cnt % 2 == 0:
        return base_sum + pos_sum

    # need to adjust parity
    cand_drop = base_sum + pos_sum - (min_pos if min_pos is not None else 0)
    cand_add = base_sum + pos_sum + (max_neg if max_neg is not None else -10**18)
    return max(cand_drop, cand_add)

