class Solution:
    def maximumStrength(self, nums: list[int], k: int) -> int:
        NEG_INF = float('-inf')
        n = len(nums)
        f = [[[NEG_INF, NEG_INF] for _ in range(k+1)] for _ in range(n+1)]
        f[0][0][0] = 0
        for i in range(1, n+1):
            x = nums[i-1]
            for j in range(0, k+1):
                sign = 1 if j % 2 == 1 else -1
                val = sign * x * (k - j + 1)
                f[i][j][0] = max(f[i-1][j][0], f[i-1][j][1])
                f[i][j][1] = f[i-1][j][1] + val if f[i-1][j][1] != NEG_INF else NEG_INF
                if j > 0:
                    prev_best = max(f[i-1][j-1][0], f[i-1][j-1][1])
                    if prev_best != NEG_INF:
                        f[i][j][1] = max(f[i][j][1], prev_best + val)
        return max(f[n][k][0], f[n][k][1])

