MOD = 10**9 + 7

def sum_power_subsequences(nums: List[int], k: int) -> int:
    n = len(nums)
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for val in nums:
        for t in range(n, 0, -1):
            for s in range(k, val - 1, -1):
                dp[t][s] = (dp[t][s] + dp[t - 1][s - val]) % MOD

    ans = 0
    for t in range(n + 1):
        cnt = dp[t][k]
        if cnt:
            ans = (ans + cnt * pow(2, n - t, MOD)) % MOD
    return ans

