    root = new_node()
    for i, word in enumerate(words_container):
        w_len = len(word)
        cur = root
        update_best(cur, i, w_len)
        for p in range(w_len - 1, -1, -1):
            ch = word[p]
            if ch not in cur['children']:
                cur['children'][ch] = new_node()
            cur = cur['children'][ch]
            update_best(cur, i, w_len)

    answer = [0] * len(words_query)
    for q, query in enumerate(words_query):
        cur = root
        for p in range(len(query) - 1, -1, -1):
            ch = query[p]
            if ch not in cur['children']:
                break
            cur = cur['children'][ch]
        answer[q] = cur['bestIdx']
    return answer

