def most_frequent_ids(nums: List[int], freq: List[int]) -> List[int]:
    id_count = {}
    freq_count = {}
    max_freq = 0
    ans = [0] * len(nums)

    for i in range(len(nums)):
        id_ = nums[i]
        delta = freq[i]
        old_cnt = id_count.get(id_, 0)
        new_cnt = old_cnt + delta

        if old_cnt > 0:
            old_freq_num = freq_count.get(old_cnt, 0) - 1
            if old_freq_num == 0:
                del freq_count[old_cnt]
            else:
                freq_count[old_cnt] = old_freq_num

        if new_cnt > 0:
            id_count[id_] = new_cnt
            freq_count[new_cnt] = freq_count.get(new_cnt, 0) + 1
        else:
            if id_ in id_count:
                del id_count[id_]

        if new_cnt > max_freq:
            max_freq = new_cnt
        while max_freq > 0 and freq_count.get(max_freq, 0) == 0:
            max_freq -= 1

        ans[i] = max_freq

    return ans

