def shortest_subarray_with_or_at_least_k(nums: List[int], k: int) -> int:
    n = len(nums)
    if n == 0:
        return -1
    if k == 0:
        return 1

    INF = n + 1
    ans = INF
    bit_counts = [0] * 31
    cur_or = 0
    left = 0

    for right, val in enumerate(nums):
        v = val
        b = 0
        while v:
            if v & 1:
                if bit_counts[b] == 0:
                    cur_or |= (1 << b)
                bit_counts[b] += 1
            v >>= 1
            b += 1

        while left <= right and cur_or >= k:
            cur_len = right - left + 1
            if cur_len < ans:
                ans = cur_len
                if ans == 1:
                    return 1
            # remove nums[left] from window
            v = nums[left]
            b = 0
            while v:
                if v & 1:
                    bit_counts[b] -= 1
                    if bit_counts[b] == 0:
                        cur_or &= ~(1 << b)
                v >>= 1
                b += 1
            left += 1

    return -1 if ans == INF else ans

