def shortest_subarray(nums: List[int], k: int) -> int:
    n = len(nums)
    INF = 10**9
    ans = INF
    left = 0
    bit_cnt = [0] * 32
    current_or = 0

    for right in range(n):
        val = nums[right]
        for b in range(32):
            if val & (1 << b):
                bit_cnt[b] += 1
        current_or = 0
        for b in range(32):
            if bit_cnt[b] > 0:
                current_or |= (1 << b)

        while left <= right and current_or >= k:
            ans = min(ans, right - left + 1)
            remove_val = nums[left]
            for b in range(32):
                if remove_val & (1 << b):
                    bit_cnt[b] -= 1
            left += 1
            current_or = 0
            for b in range(32):
                if bit_cnt[b] > 0:
                    current_or |= (1 << b)

    return -1 if ans == INF else ans

