MOD = 10**9 + 7

def sum_of_powers(nums: List[int], k: int) -> int:
    a = sorted(nums)
    n = len(a)

    # all possible gaps (including zero)
    gaps_set = {0}
    for i in range(n):
        for j in range(i + 1, n):
            gaps_set.add(a[j] - a[i])
    gaps = sorted(gaps_set)          # ascending order

    # count_at_least[d] = number of subsequences of length k whose
    # consecutive chosen elements differ by at least d
    count_at_least = {}

    for d in gaps:
        # dp[t][i] = ways to pick t elements ending at index i
        dp = [[0] * n for _ in range(k + 1)]
        for i in range(n):
            dp[1][i] = 1

        for t in range(2, k + 1):
            for i in range(n):
                total = 0
                for j in range(i):
                    if a[i] - a[j] >= d:
                        total += dp[t - 1][j]
                dp[t][i] = total % MOD

        total_k = sum(dp[k][i] for i in range(n)) % MOD
        count_at_least[d] = total_k

    # convert "at least" counts to "exact" counts and accumulate answer
    ans = 0
    for idx in range(len(gaps) - 1):
        d = gaps[idx]
        next_d = gaps[idx + 1]
        exact = (count_at_least[d] - count_at_least[next_d]) % MOD
        ans = (ans + d * exact) % MOD

    # largest gap contributes its whole "at least" count as exact
    last_gap = gaps[-1]
    ans = (ans + last_gap * count_at_least[last_gap]) % MOD

    return ans
# TIME: O(m * n^2 * k) SPACE: O(n * k) where m = number of distinct gaps (≤ n·(n‑1)/2 + 1)

