def minimum_cost_walk(n: int, edges: List[List[int]], query: List[List[int]]) -> List[int]:
    parent = list(range(n))
    sz = [1] * n
    comp_and = [-1] * n  # -1 works as all bits set for bitwise AND

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def unite(a: int, b: int, w: int) -> None:
        ra = find(a)
        rb = find(b)
        if ra == rb:
            comp_and[ra] &= w
            return
        new_and = comp_and[ra] & comp_and[rb] & w
        if sz[ra] < sz[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        sz[ra] += sz[rb]
        comp_and[ra] = new_and

    for u, v, w in edges:
        unite(u, v, w)

    ans: List[int] = []
    for s, t in query:
        if find(s) != find(t):
            ans.append(-1)
        else:
            ans.append(comp_and[find(s)])
    return ans

