def _gcd_uint64(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return a

def _lcm_uint64(a: int, b: int, limit: int) -> int:
    g = _gcd_uint64(a, b)
    div = a // g
    if div > limit // b:
        return limit + 1
    return div * b

def _count_le(X: int, coins: List[int]) -> int:
    n = len(coins)
    total = 0
    limit = X
    for mask in range(1, 1 << n):
        cur_lcm = 1
        overflow = False
        i = 0
        m = mask
        while m:
            if m & 1:
                cur_lcm = _lcm_uint64(cur_lcm, coins[i], limit)
                if cur_lcm > limit:
                    overflow = True
                    break
            i += 1
            m >>= 1
        if overflow:
            continue
        add = X // cur_lcm
        if bin(mask).count('1') & 1:
            total += add
        else:
            total -= add
    return total

