def max_prime_difference(nums: List[int]) -> int:
    def is_prime(x: int) -> bool:
        if x < 2:
            return False
        if x == 2:
            return True
        if x % 2 == 0:
            return False
        limit = int(math.sqrt(x))
        d = 3
        while d <= limit:
            if x % d == 0:
                return False
            d += 2
        return True

    first = -1
    last = -1
    for i in range(len(nums)):
        if is_prime(nums[i]):
            if first == -1:
                first = i
            last = i
    if first == -1:
        return 0
    return last - first

