def minimum_sum(nums: List[int], and_values: List[int]) -> int:
    n = len(nums)
    m = len(and_values)
    if m == 0:
        return 0
    if m > n:
        return -1

    INF = 4 * 10**18
    dp = [[INF] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(1, n + 1):
        cur_and = 0
        # iterate left boundary backwards to compute AND of subarray [left-1 .. i-1]
        for left in range(i, 0, -1):
            if left == i:
                cur_and = nums[i - 1]
            else:
                cur_and &= nums[left - 1]

            # try to close a segment ending at i with this left
            for k in range(1, m + 1):
                if cur_and == and_values[k - 1]:
                    prev = dp[left - 1][k - 1]
                    if prev != INF:
                        cand = prev + nums[i - 1]
                        if cand < dp[i][k]:
                            dp[i][k] = cand

    ans = dp[n][m]
    return ans if ans != INF else -1

