def _dijkstra(n: int, src: int, adj: List[List[tuple]]) -> List[int]:
    INF = 10**18
    dist = [INF] * n
    dist[src] = 0
    pq = [(0, src)]
    while pq:
        d, u = heapq.heappop(pq)
        if d != dist[u]:
            continue
        for v, w in adj[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(pq, (nd, v))
    return dist

def find_edges_in_shortest_paths(n: int, edges: List[List[int]]) -> List[bool]:
    adj = [[] for _ in range(n)]
    for e in edges:
        u, v, w = e
        adj[u].append((v, w))
        adj[v].append((u, w))
    dist_start = _dijkstra(n, 0, adj)
    dist_end = _dijkstra(n, n - 1, adj)
    INF = 10**18
    answer = [False] * len(edges)
    shortest = dist_start[n - 1]
    if shortest == INF:
        return answer
    for i, e in enumerate(edges):
        u, v, w = e
        wll = w
        if dist_start[u] != INF and dist_end[v] != INF:
            if dist_start[u] + wll + dist_end[v] == shortest:
                answer[i] = True
                continue
        if dist_start[v] != INF and dist_end[u] != INF:
            if dist_start[v] + wll + dist_end[u] == shortest:
                answer[i] = True
    return answer

