    win1 = [0] * (one + 1)
    for i in range(zero + 1):
        if i > 0:
            remove_idx = i - 1 - limit
            for j in range(one + 1):
                win1[j] = (win1[j] + dp1[i - 1][j]) % MOD
                if remove_idx >= 0:
                    win1[j] = (win1[j] - dp1[remove_idx][j] + MOD) % MOD
        for j in range(one + 1):
