def median_uniqueness(nums: List[int]) -> int:
    n = len(nums)
    total = n * (n + 1) // 2
    k = (total + 1) // 2

    def count_at_most(limit: int) -> int:
        freq = {}
        left = 0
        distinct = 0
        cnt = 0
        for right, val in enumerate(nums):
            cur = freq.get(val, 0)
            if cur == 0:
                distinct += 1
            freq[val] = cur + 1
            while distinct > limit:
                lval = nums[left]
                lcur = freq[lval]
                if lcur == 1:
                    distinct -= 1
                freq[lval] = lcur - 1
                left += 1
            cnt += right - left + 1
        return cnt

    low, high = 1, n
    while low < high:
        mid = (low + high) // 2
        if count_at_most(mid) >= k:
            high = mid
        else:
            low = mid + 1
    return low

