def min_cost_permutation(nums: List[int]) -> List[int]:
    n = len(nums)
    full_mask = (1 << n) - 1
    INF = 10**15

    cost = [[abs(i - nums[j]) for j in range(n)] for i in range(n)]

    dp = [[INF] * n for _ in range(1 << n)]
    dp[1 << 0][0] = 0

    for mask in range(full_mask + 1):
        for last in range(n):
            cur = dp[mask][last]
            if cur == INF:
                continue
            for nxt in range(n):
                if mask & (1 << nxt):
                    continue
                new_mask = mask | (1 << nxt)
                new_cost = cur + cost[last][nxt]
                if new_cost < dp[new_mask][nxt]:
                    dp[new_mask][nxt] = new_cost

    best_total = INF
    for last in range(n):
        cur = dp[full_mask][last]
        if cur == INF:
            continue
        total = cur + cost[last][0]
        if total < best_total:
            best_total = total

    extra = [[-1] * n for _ in range(1 << n)]

    def extra_cost(mask: int, last: int) -> int:
        if extra[mask][last] != -1:
            return extra[mask][last]
        if mask == full_mask:
            extra[mask][last] = cost[last][0]
            return extra[mask][last]
        best = INF
        for nxt in range(n):
            if mask & (1 << nxt):
                continue
            cand = cost[last][nxt] + extra_cost(mask | (1 << nxt), nxt)
            if cand < best:
                best = cand
        extra[mask][last] = best
        return best

    perm = [0]
    mask = 1 << 0
    last = 0
    while mask != full_mask:
        for nxt in range(n):
            if mask & (1 << nxt):
                continue
            cur = dp[mask][last]
            cand_total = cur + cost[last][nxt] + extra_cost(mask | (1 << nxt), nxt)
            if cand_total == best_total:
                perm.append(nxt)
                mask |= 1 << nxt
                last = nxt
                break

    return perm

