        max_freq = 0
        for j in range(i - 1, -1, -1):
            idx = ord(s[j]) - ord('a')
            cnt[idx] += 1
            if cnt[idx] > max_freq:
                max_freq = cnt[idx]
            balanced = True
            for k in range(26):
