def count_peaks(nums: List[int], queries: List[List[int]]) -> List[int]:
    n = len(nums)

    class Fenwick:
        def __init__(self, size: int):
            self.bit = [0] * (size + 1)

        def add(self, idx: int, delta: int) -> None:
            idx += 1
            while idx < len(self.bit):
                self.bit[idx] += delta
                idx += idx & -idx

        def sum_prefix(self, idx: int) -> int:
            idx += 1
            res = 0
            while idx > 0:
                res += self.bit[idx]
                idx -= idx & -idx
            return res

        def range_sum(self, l: int, r: int) -> int:
            if l > r:
                return 0
            left = self.sum_prefix(l - 1) if l else 0
            return self.sum_prefix(r) - left

    ft = Fenwick(n)
    is_peak = [0] * n

    def compute(i: int) -> int:
        if i <= 0 or i >= n - 1:
            return 0
        return 1 if (nums[i] > nums[i - 1] and nums[i] > nums[i + 1]) else 0

    for i in range(1, n - 1):
        is_peak[i] = compute(i)
        if is_peak[i]:
            ft.add(i, 1)

    answer: List[int] = []
    for q in queries:
        typ = q[0]
        if typ == 1:
            l, r = q[1], q[2]
            left = l + 1
            right = r - 1
            answer.append(ft.range_sum(left, right))
        elif typ == 2:
            pos, val = q[1], q[2]
            nums[pos] = val
            for i in range(pos - 1, pos + 2):
                if i <= 0 or i >= n - 1:
                    continue
                new_peak = compute(i)
                if new_peak != is_peak[i]:
                    ft.add(i, new_peak - is_peak[i])
                    is_peak[i] = new_peak
    return answer

