def count_permutations(n: int, requirements: List[List[int]]) -> int:
    MOD = 1000000007
    req_cnt = [-1] * n
    max_cnt = 0
    for r in requirements:
        endi, cnti = r[0], r[1]
        req_cnt[endi] = cnti
        if cnti > max_cnt:
            max_cnt = cnti
    dp = [[0] * (max_cnt + 1) for _ in range(n + 1)]
    dp[0][0] = 1
    for i in range(1, n + 1):
        pref = [0] * (max_cnt + 1)
        pref[0] = dp[i - 1][0]
        for k in range(1, max_cnt + 1):
            pref[k] = pref[k - 1] + dp[i - 1][k]
            if pref[k] >= MOD:
                pref[k] -= MOD
        for k in range(0, max_cnt + 1):
            left = k - (i - 1)
            val = pref[k]
            if left > 0:
                val -= pref[left - 1]
                if val < 0:
                    val += MOD
            dp[i][k] = val
        end_idx = i - 1
        if req_cnt[end_idx] != -1:
            need = req_cnt[end_idx]
            if need > end_idx * (end_idx + 1) // 2:
                return 0
            for k in range(0, max_cnt + 1):
                if k != need:
                    dp[i][k] = 0
    final_need = req_cnt[n - 1]
    if final_need == -1:
        return 0
    return dp[n][final_need]

