def min_area_three_rectangles(grid: List[List[int]]) -> int:
    R = len(grid)
    C = len(grid[0])

    def box(r1: int, r2: int, c1: int, c2: int) -> int:
        minR, maxR = R, -1
        minC, maxC = C, -1
        for i in range(r1, r2 + 1):
            for j in range(c1, c2 + 1):
                if grid[i][j] == 1:
                    if i < minR:
                        minR = i
                    if i > maxR:
                        maxR = i
                    if j < minC:
                        minC = j
                    if j > maxC:
                        maxC = j
        if maxR == -1:
            return -1
        return (maxR - minR + 1) * (maxC - minC + 1)

    ans = 10**30

    for i in range(R - 2):
        for j in range(i + 1, R - 1):
            a1 = box(0, i, 0, C - 1)
            a2 = box(i + 1, j, 0, C - 1)
            a3 = box(j + 1, R - 1, 0, C - 1)
            if a1 != -1 and a2 != -1 and a3 != -1:
                s = a1 + a2 + a3
                if s < ans:
                    ans = s

    for i in range(C - 2):
        for j in range(i + 1, C - 1):
            a1 = box(0, R - 1, 0, i)
            a2 = box(0, R - 1, i + 1, j)
            a3 = box(0, R - 1, j + 1, C - 1)
            if a1 != -1 and a2 != -1 and a3 != -1:
                s = a1 + a2 + a3
                if s < ans:
                    ans = s

    for r in range(R - 1):
        for c in range(C - 1):
            tl = box(0, r, 0, c)
            tr = box(0, r, c + 1, C - 1)
            bl = box(r + 1, R - 1, 0, c)
            br = box(r + 1, R - 1, c + 1, C - 1)
            has = [tl != -1, tr != -1, bl != -1, br != -1]
            cnt = sum(has)
            if cnt == 3:
                s = (tl if has[0] else 0) + (tr if has[1] else 0) + (bl if has[2] else 0) + (br if has[3] else 0)
                if s < ans:
                    ans = s

    return ans

