def is_path_possible(x_corner: int, y_corner: int, circles: List[List[int]]) -> bool:
    n = len(circles)
    # indices for the four sides
    left_idx = n
    right_idx = n + 1
    bottom_idx = n + 2
    top_idx = n + 3

    parent = list(range(n + 4))
    rank = [0] * (n + 4)

    def find(v: int) -> int:
        while parent[v] != v:
            parent[v] = parent[parent[v]]
            v = parent[v]
        return v

    def unite(a: int, b: int) -> None:
        ra, rb = find(a), find(b)
        if ra == rb:
            return
        if rank[ra] < rank[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        if rank[ra] == rank[rb]:
            rank[ra] += 1

    # helper to check if a circle touches a side segment
    def touches_side(x: int, y: int, r: int, side: str) -> bool:
        if side == "left":
            dx = x
            dy = 0
            if y < 0:
                dy = -y
            elif y > y_corner:
                dy = y - y_corner
            # else dy stays 0
        elif side == "right":
            dx = x - x_corner
            dy = 0
            if y < 0:
                dy = -y
            elif y > y_corner:
                dy = y - y_corner
        elif side == "bottom":
            dy = y
            dx = 0
            if x < 0:
                dx = -x
            elif x > x_corner:
                dx = x - x_corner
        else:  # top
            dy = y - y_corner
            dx = 0
            if x < 0:
                dx = -x
            elif x > x_corner:
                dx = x - x_corner
        return dx * dx + dy * dy <= r * r

    # union circles with sides they intersect
    for i, (x, y, r) in enumerate(circles):
        if touches_side(x, y, r, "left"):
            unite(i, left_idx)
        if touches_side(x, y, r, "right"):
            unite(i, right_idx)
        if touches_side(x, y, r, "bottom"):
            unite(i, bottom_idx)
        if touches_side(x, y, r, "top"):
            unite(i, top_idx)

    # union overlapping circles
    for i in range(n):
        xi, yi, ri = circles[i]
        for j in range(i + 1, n):
            xj, yj, rj = circles[j]
            dx = xi - xj
            dy = yi - yj
            if dx * dx + dy * dy <= (ri + rj) * (ri + rj):
                unite(i, j)

    # check blocking connections
    if find(left_idx) == find(right_idx):
        return False
    if find(bottom_idx) == find(top_idx):
        return False
    if find(left_idx) == find(bottom_idx):
        return False
    if find(right_idx) == find(top_idx):
        return False
    return True

