def time_taken(edges):
    n = len(edges) + 1
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    result = [0] * n
    for src in range(n):
        dist = [-1] * n
        dist[src] = 0
        stack = [src]
        max_dist = 0
        while stack:
            cur = stack.pop()
            for nb in adj[cur]:
                if dist[nb] == -1:
                    w = 2 if nb % 2 == 0 else 1
                    dist[nb] = dist[cur] + w
                    if dist[nb] > max_dist:
                        max_dist = dist[nb]
                    stack.append(nb)
        result[src] = max_dist
    return result

