        for i in range(n):
            if i + 1 < n and dist[i] + 1 < dist[i + 1]:
                dist[i + 1] = dist[i] + 1
            for to in adj[i]:
                if dist[i] + 1 < dist[to]:
                    dist[to] = dist[i] + 1
        results.append(dist[n - 1])
