def count_good_nodes(edges: List[List[int]]) -> int:
    n = len(edges) + 1
    adj = [[] for _ in range(n)]
    for e in edges:
        a, b = e[0], e[1]
        adj[a].append(b)
        adj[b].append(a)

    good = 0

    def dfs(u: int, parent: int) -> int:
        nonlocal good
        child_sizes = []
        for v in adj[u]:
            if v == parent:
                continue
            sz = dfs(v, u)
            child_sizes.append(sz)

        is_good = True
        if child_sizes:
            first = child_sizes[0]
            for s in child_sizes[1:]:
                if s != first:
                    is_good = False
                    break
        if is_good:
            good += 1

        total = 1 + sum(child_sizes)
        return total

    dfs(0, -1)
    return good

def find_smallest_missing_integer(nums: list[int]) -> int:
    longest_prefix_sum = 0
    longest_prefix_length = 0
    for i in range(len(nums)):
        current_prefix_sum = 0
        current_prefix_length = 0
        for j in range(i, len(nums)):
            if j == i or nums[j] == nums[j - 1] + 1:
                current_prefix_sum += nums[j]
                current_prefix_length += 1
            else:
                break
        if current_prefix_length > longest_prefix_length:
            longest_prefix_length = current_prefix_length
            longest_prefix_sum = current_prefix_sum
    num_set = set(nums)
    smallest_missing_integer = longest_prefix_sum
    while smallest_missing_integer in num_set:
        smallest_missing_integer += 1
    return smallest_missing_integer

class NeighborSum:
    def __init__(self, grid):
        self.grid = grid
        self.n = len(grid)
        self.pos = {}
        for i in range(self.n):
            for j in range(self.n):
                self.pos[grid[i][j]] = (i, j)
    def adjacentSum(self, value: int) -> int:
        if value not in self.pos:
            return 0
        i, j = self.pos[value]
        total = 0
        if i > 0: total += self.grid[i-1][j]
        if i < self.n-1: total += self.grid[i+1][j]
        if j > 0: total += self.grid[i][j-1]
        if j < self.n-1: total += self.grid[i][j+1]
        return total

