def count_dominant_ones(s: str) -> int:
    n = len(s)
    pref_ones = [0] * (n + 1)
    pref_zeros = [0] * (n + 1)
    for i, ch in enumerate(s):
        pref_ones[i + 1] = pref_ones[i] + (1 if ch == '1' else 0)
        pref_zeros[i + 1] = pref_zeros[i] + (1 if ch == '0' else 0)
    max_zeros = int(math.floor(math.sqrt(n)))
    ans = 0
    for r in range(n):
        l = r
        while True:
            zeros = pref_zeros[r + 1] - pref_zeros[l]
            if zeros > max_zeros:
                break
            ones = pref_ones[r + 1] - pref_ones[l]
            if ones >= zeros * zeros:
                ans += 1
            if l == 0:
                break
            l -= 1
    return ans

