def alternating_groups(colors: List[int], queries: List[List[int]]) -> List[int]:
    n = len(colors)
    diff = [0] * n
    for i in range(n):
        diff[i] = 1 if colors[i] != colors[(i + 1) % n] else 0
    result = []
    for q in queries:
        if q[0] == 1:
            k = q[1]
            L = k - 1
            ans = 0
            cur = 0
            for i in range(2 * n):
                idx = i % n
                if diff[idx] == 1:
                    cur += 1
                else:
                    cur = 0
                if cur >= L:
                    start = i - (L - 1)
                    if start < n:
                        ans += 1
            result.append(ans)
        else:
            i = q[1]
            v = q[2]
            if colors[i] == v:
                continue
            colors[i] = v
            left = (i - 1 + n) % n
            diff[left] = 1 if colors[left] != colors[i] else 0
            diff[i] = 1 if colors[i] != colors[(i + 1) % n] else 0
    return result

