def maximum_value_sum(board: List[List[int]]) -> int:
    m = len(board)
    n = len(board[0])
    NEG_INF = -(1 << 60)
    answer = NEG_INF

    if m <= n:
        for i in range(m):
            for j in range(i + 1, m):
                for k in range(j + 1, m):
                    rows = (i, j, k)
                    dp = [NEG_INF] * 8
                    dp[0] = 0
                    for col in range(n):
                        ndp = dp[:]
                        for mask in range(8):
                            cur = dp[mask]
                            if cur == NEG_INF:
                                continue
                            for r in range(3):
                                if mask & (1 << r):
                                    continue
                                nmask = mask | (1 << r)
                                val = cur + board[rows[r]][col]
                                if val > ndp[nmask]:
                                    ndp[nmask] = val
                        dp = ndp
                    if dp[7] > answer:
                        answer = dp[7]
    else:
        for c1 in range(n):
            for c2 in range(c1 + 1, n):
                for c3 in range(c2 + 1, n):
                    cols = (c1, c2, c3)
                    dp = [NEG_INF] * 8
                    dp[0] = 0
                    for row in range(m):
                        ndp = dp[:]
                        for mask in range(8):
                            cur = dp[mask]
                            if cur == NEG_INF:
                                continue
                            for c in range(3):
                                if mask & (1 << c):
                                    continue
                                nmask = mask | (1 << c)
                                val = cur + board[row][cols[c]]
                                if val > ndp[nmask]:
                                    ndp[nmask] = val
                        dp = ndp
                    if dp[7] > answer:
                        answer = dp[7]

    return answer

def power_of_k_size_subarrays(nums: list[int], k: int) -> list[int]:
    n = len(nums)
    inc = [0] * n
    for i in range(1, n):
        inc[i] = 1 if nums[i] > nums[i - 1] else 0
    sum_inc = 0
    for i in range(1, k):
        sum_inc += inc[i]
    results = []
    target = k - 1
    for start in range(0, n - k + 1):
        if sum_inc == target:
            results.append(nums[start + k - 1])
        else:
            results.append(-1)
        if start < n - k:
            remove_idx = start + 1
            add_idx = start + k
            sum_inc = sum_inc - inc[remove_idx] + inc[add_idx]
    return results

