def count_k_constraint_substrings(s: str, k: int, queries: List[List[int]]) -> List[int]:
    n = len(s)
    r0 = [0] * n
    r1 = [0] * n

    right = -1
    zeros = 0
    for left in range(n):
        while right + 1 < n and zeros + (1 if s[right + 1] == '0' else 0) <= k:
            right += 1
            if s[right] == '0':
                zeros += 1
        r0[left] = right
        if right >= left:
            if s[left] == '0':
                zeros -= 1
        else:
            right = left - 1

    right = -1
    ones = 0
    for left in range(n):
        while right + 1 < n and ones + (1 if s[right + 1] == '1' else 0) <= k:
            right += 1
            if s[right] == '1':
                ones += 1
        r1[left] = right
        if right >= left:
            if s[left] == '1':
                ones -= 1
        else:
            right = left - 1

    max_good = [max(r0[i], r1[i]) for i in range(n)]

    class Fenwick:
        def __init__(self, size: int):
            self.n = size
            self.bit = [0] * (size + 1)

        def add(self, idx: int, delta: int):
            i = idx
            while i <= self.n:
                self.bit[i] += delta
                i += i & -i

        def sum(self, idx: int) -> int:
            res = 0
            i = idx
            while i > 0:
                res += self.bit[i]
                i -= i & -i
            return res

        def range_sum(self, l: int, r: int) -> int:
            return self.sum(r + 1) - self.sum(l)

    bit_cnt = Fenwick(n)
    bit_sum = Fenwick(n)

    q_objs = [{'l': q[0], 'r': q[1], 'idx': i} for i, q in enumerate(queries)]
    q_objs.sort(key=lambda x: x['r'])

    ans = [0] * len(queries)
    pos = 0
    for q in q_objs:
        while pos < n and max_good[pos] <= q['r']:
            bit_cnt.add(pos + 1, 1)
            bit_sum.add(pos + 1, max_good[pos])
            pos += 1
        l = q['l']
        r = q['r']
        length = r - l + 1
        cnt_le = bit_cnt.range_sum(l, r)
        sum_le = bit_sum.range_sum(l, r)
        cnt_gt = length - cnt_le
        sum_min = sum_le + r * cnt_gt
        sum_i = (l + r) * length // 2
        ans[q['idx']] = sum_min + length - sum_i

    return ans

from typing import List

def _heap_swap(heap: List[List[int]], i: int, j: int) -> None:
    heap[i], heap[j] = heap[j], heap[i]

def _heap_less(a: List[int], b: List[int]) -> bool:
    if a[0] != b[0]:
        return a[0] < b[0]
    return a[1] < b[1]

def _heapify_up(heap: List[List[int]], pos: int) -> None:
    while pos > 0:
        parent = (pos - 1) >> 1
        if _heap_less(heap[pos], heap[parent]):
            _heap_swap(heap, pos, parent)
            pos = parent
        else:
            break

def _heapify_down(heap: List[List[int]], pos: int) -> None:
    size = len(heap)
    while True:
        left = pos * 2 + 1
        right = left + 1
        smallest = pos
        if left < size and _heap_less(heap[left], heap[smallest]):
            smallest = left
        if right < size and _heap_less(heap[right], heap[smallest]):
            smallest = right
        if smallest != pos:
            _heap_swap(heap, pos, smallest)
            pos = smallest
        else:
            break

def final_array_state(nums: List[int], k: int, multiplier: int) -> List[int]:
    n = len(nums)
    if n == 0:
        return []
    heap: List[List[int]] = []
    for i in range(n):
        heap.append([nums[i], i])
        _heapify_up(heap, len(heap) - 1)
    for _ in range(k):
        node = heap[0]
        node[0] *= multiplier
        nums[node[1]] = node[0]
        _heapify_down(heap, 0)
    return nums

def largest_palindrome(n: int, k: int) -> str:
    if k == 0:
        return ""
    m = (n + 1) // 2
    pow10 = [0] * n
    pow10[0] = 1 % k
    for i in range(1, n):
        pow10[i] = (pow10[i - 1] * 10) % k
    weight = [0] * m
    for i in range(m):
        j = n - 1 - i
        if i == j:
            weight[i] = pow10[i] % k
        else:
            weight[i] = (pow10[i] + pow10[j]) % k
    reachable = [[False] * k for _ in range(m + 1)]
    reachable[m][0] = True
    for i in range(m - 1, -1, -1):
        for r in range(k):
            if not reachable[i + 1][r]:
                continue
            for d in range(10):
                if i == 0 and d == 0:
                    continue
                nr = (d * weight[i] + r) % k
                reachable[i][nr] = True
    if not reachable[0][0]:
        return ""
    first_half = [''] * m
    need = 0
    for i in range(m):
        for d in range(9, -1, -1):
            if i == 0 and d == 0:
                continue
            contrib = (d * weight[i]) % k
            suffix = (need - contrib) % k
            if reachable[i + 1][suffix]:
                first_half[i] = chr(ord('0') + d)
                need = suffix
                break
    res = []
    res.extend(first_half)
    start = m - 1 if n % 2 == 0 else m - 2
    for i in range(start, -1, -1):
        res.append(first_half[i])
    return ''.join(res)

from typing import List, Set

def count_pairs(nums: List[int]) -> int:
    """Return the number of index pairs (i, j) with i < j such that
    nums[i] and nums[j] are *almost equal*.
    Two numbers are almost equal if they are already identical or
    one can become the other after swapping any two *different* decimal
    digits of one of the numbers at most once.
    """
    # Pre‑compute, for each number, the set of values reachable by at most one swap.
    reachable: List[Set[int]] = []
    for num in nums:
        s = str(num)
        n = len(s)
        cur: Set[int] = {num}
        chars = list(s)
        for i in range(n):
            for j in range(i + 1, n):
                if chars[i] == chars[j]:
                    continue          # swapping identical digits would change nothing
                swapped = chars.copy()
                swapped[i], swapped[j] = swapped[j], swapped[i]
                cur.add(int(''.join(swapped)))   # leading zeros are dropped automatically
        reachable.append(cur)

    count = 0
    m = len(nums)
    for i in range(m):
        for j in range(i + 1, m):
            if nums[j] in reachable[i] or nums[i] in reachable[j]:
                count += 1
    return count

from typing import List, Set, Dict

def count_almost_equal_pairs_ii(nums: List[int]) -> int:
    def generate(num: int) -> Set[int]:
        s = str(num)
        L = len(s)
        result: Set[int] = {num}
        arr = list(s)
        for i in range(L):
            for j in range(i + 1, L):
                arr[i], arr[j] = arr[j], arr[i]
                swapped = ''.join(arr).lstrip('0')
                val = 0 if swapped == '' else int(swapped)
                result.add(val)
                arr[i], arr[j] = arr[j], arr[i]
        return result

    n = len(nums)
    reachable: List[Set[int]] = [generate(x) for x in nums]
    value_map: Dict[int, List[int]] = {}
    for i, reach in enumerate(reachable):
        for v in reach:
            value_map.setdefault(v, []).append(i)

    seen_pairs: Set[int] = set()
    ans = 0
    for idx_list in value_map.values():
        m = len(idx_list)
        for a in range(m):
            i = idx_list[a]
            for b in range(a + 1, m):
                j = idx_list[b]
                code = i * n + j
                if code not in seen_pairs:
                    seen_pairs.add(code)
                    ans += 1
    return ans

def kth_nearest_obstacle(queries, k):
    heap = []
    results = []

    def swap(i, j):
        heap[i], heap[j] = heap[j], heap[i]

    def bubble_up(idx):
        i = idx
        while i > 0:
            p = (i - 1) >> 1
            if heap[p] >= heap[i]:
                break
            swap(p, i)
            i = p

    def bubble_down(idx):
        i = idx
        while True:
            largest = i
            l = i * 2 + 1
            r = i * 2 + 2
            if l < len(heap) and heap[l] > heap[largest]:
                largest = l
            if r < len(heap) and heap[r] > heap[largest]:
                largest = r
            if largest == i:
                break
            swap(i, largest)
            i = largest

    def push(val):
        heap.append(val)
        bubble_up(len(heap) - 1)

    def pop_max():
        max_val = heap[0]
        end = heap.pop()
        if heap:
            heap[0] = end
            bubble_down(0)
        return max_val

    def peek():
        return heap[0]

    for p in queries:
        dist = abs(p[0]) + abs(p[1])
        if len(heap) < k:
            push(dist)
        elif dist < peek():
            pop_max()
            push(dist)
        results.append(peek() if len(heap) == k else -1)

    return results

def hash_divided_string(s: str, k: int) -> str:
    n = len(s)
    result = []
    for i in range(0, n, k):
        total = 0
        for j in range(i, i + k):
            total += ord(s[j]) - ord('a')
        hashed_char = chr((total % 26) + ord('a'))
        result.append(hashed_char)
    return ''.join(result)

