def max_score(grid: List[List[int]]) -> int:
    rows = len(grid)
    cols = len(grid[0])
    max_mask = 1 << cols
    NEG = -2_147_483_647
    dp = [NEG] * max_mask
    dp[0] = 0
    for i in range(rows):
        ndp = dp[:]
        for mask in range(max_mask):
            if dp[mask] == NEG:
                continue
            for j in range(cols):
                if (mask & (1 << j)) == 0:
                    nmask = mask | (1 << j)
                    ndp[nmask] = max(ndp[nmask], dp[mask] + grid[i][j])
        dp = ndp
    ans = 0
    for mask in range(1, max_mask):
        ans = max(ans, dp[mask])
    return ans

def maximum_xor_score(nums, queries):
    n = len(nums)
    score = [[0] * n for _ in range(n)]
    best = [[0] * n for _ in range(n)]
    for i in range(n):
        score[i][i] = nums[i]
        best[i][i] = nums[i]
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            score[i][j] = score[i][j - 1] ^ score[i + 1][j]
            best[i][j] = max(score[i][j], best[i][j - 1], best[i + 1][j])
    return [best[l][r] for l, r in queries]

