import sys

def max_moves(kx, ky, positions):
    N = 50
    p = len(positions)
    nodes = [(kx, ky)] + [(pos[0], pos[1]) for pos in positions]
    m = p + 1
    dist = [[0] * m for _ in range(m)]
    dx = [2, 2, 1, 1, -1, -1, -2, -2]
    dy = [1, -1, 2, -2, 2, -2, 1, -1]

    for s in range(m):
        d = [[-1] * N for _ in range(N)]
        q = deque()
        sx, sy = nodes[s]
        d[sx][sy] = 0
        q.append((sx, sy))
        while q:
            x, y = q.popleft()
            for dir in range(8):
                nx = x + dx[dir]
                ny = y + dy[dir]
                if nx < 0 or ny < 0 or nx >= N or ny >= N:
                    continue
                if d[nx][ny] == -1:
                    d[nx][ny] = d[x][y] + 1
                    q.append((nx, ny))
        for t in range(m):
            tx, ty = nodes[t]
            dist[s][t] = d[tx][ty]

    full_mask = (1 << p) - 1
    dp = [[-1] * m for _ in range(1 << p)]
    sys.setrecursionlimit(10000)

    def solve(mask, cur):
        if mask == full_mask:
            return 0
        if dp[mask][cur] != -1:
            return dp[mask][cur]
        alice_turn = (bin(mask).count('1') % 2 == 0)
        if alice_turn:
            res = -1000000
        else:
            res = 1000000
        for nxt in range(1, m):
            bit = 1 << (nxt - 1)
            if mask & bit:
                continue
            cost = dist[cur][nxt]
            total = cost + solve(mask | bit, nxt)
            if alice_turn:
                if total > res:
                    res = total
            else:
                if total < res:
                    res = total
        dp[mask][cur] = res
        return res

    return solve(0, 0)

