def longest_increasing_path(coordinates, k):
    n = len(coordinates)
    points = [(coordinates[i][0], coordinates[i][1], i) for i in range(n)]
    points.sort(key=lambda p: (p[0], -p[1]))
    target_pos = -1
    for i in range(n):
        if points[i][2] == k:
            target_pos = i
            break
    forward = [1] * n
    for i in range(n):
        xi, yi, _ = points[i]
        for j in range(i):
            xj, yj, _ = points[j]
            if xj < xi and yj < yi:
                if forward[j] + 1 > forward[i]:
                    forward[i] = forward[j] + 1
    backward = [1] * n
    for i in range(n - 1, -1, -1):
        xi, yi, _ = points[i]
        for j in range(n - 1, i, -1):
            xj, yj, _ = points[j]
            if xi < xj and yi < yj:
                if backward[j] + 1 > backward[i]:
                    backward[i] = backward[j] + 1
    return forward[target_pos] + backward[target_pos] - 1

