def count_substrings(word1: str, word2: str) -> int:
    n = len(word1)
    m = len(word2)
    if m > n:
        return 0
    need = [0] * 26
    have = [0] * 26
    for c in word2:
        need[ord(c) - 97] += 1
    missing = sum(need)
    ans = 0
    R = 0
    for L in range(n):
        while R < n and missing > 0:
            idx = ord(word1[R]) - 97
            if have[idx] < need[idx]:
                missing -= 1
            have[idx] += 1
            R += 1
        if missing == 0:
            ans += n - (R - 1)
        else:
            break
        idxL = ord(word1[L]) - 97
        if have[idxL] <= need[idxL]:
            missing += 1
        have[idxL] -= 1
    return ans

