def get_lexicographically_smallest_valid_sequence(word1: str, word2: str) -> List[int]:
    n = len(word1)
    m = len(word2)
    if m == 0:
        return []
    dp = [[{'reachable': False, 'seq': []} for _ in range(2)] for _ in range(m + 1)]
    dp[0][0]['reachable'] = True
    for idx in range(n):
        for i in range(m - 1, -1, -1):
            for err in range(2):
                state = dp[i][err]
                if not state['reachable']:
                    continue
                last_pos = -1 if not state['seq'] else state['seq'][-1]
                if last_pos >= idx:
                    continue
                new_err = err + (word1[idx] != word2[i])
                if new_err > 1:
                    continue
                cand = state['seq'] + [idx]
                next_state = dp[i + 1][new_err]
                if (not next_state['reachable']) or (cand < next_state['seq']):
                    next_state['reachable'] = True
                    next_state['seq'] = cand
    best: List[int] = []
    found = False
    for err in range(2):
        state = dp[m][err]
        if not state['reachable']:
            continue
        if not found or state['seq'] < best:
            best = state['seq']
            found = True
    return best if found else []

