        mismatches = 0
        for i in range(m):
            if s[start + i] != pattern[i]:
                mismatches += 1
                if mismatches > 1:
                    break
        if mismatches <= 1:
            return start
    return -1

def kth_character(k: int) -> str:
    if k <= 0:
        return '\0'
    length = 1
    while length < k:
        length <<= 1

    def solve(pos: int, cur_len: int) -> str:
        if cur_len == 1:
            return 'a'
        half = cur_len >> 1
        if pos <= half:
            return solve(pos, half)
        c = solve(pos - half, half)
        return 'a' if c == 'z' else chr(ord(c) + 1)

    return solve(k, length)

