def count_vowel_consonant_substrings(word: str, k: int) -> int:
    import bisect

    vowels = {'a', 'e', 'i', 'o', 'u'}
    n = len(word)

    prefC = [0] * (n + 1)
    for i, ch in enumerate(word):
        prefC[i + 1] = prefC[i] + (0 if ch in vowels else 1)

    last = {v: -1 for v in vowels}
    positions = {0: [0]}
    ans = 0

    for i, ch in enumerate(word):
        if ch in vowels:
            last[ch] = i
        min_last = min(last.values())
        if min_last != -1:
            target = prefC[i + 1] - k
            arr = positions.get(target)
            if arr:
                ans += bisect.bisect_right(arr, min_last)
        positions.setdefault(prefC[i + 1], []).append(i + 1)

    return ans

def count_vowel_consonant_substrings(word: str, k: int) -> int:
    n = len(word)

    def vowel_index(c: str) -> int:
        if c == 'a':
            return 0
        if c == 'e':
            return 1
        if c == 'i':
            return 2
        if c == 'o':
            return 3
        if c == 'u':
            return 4
        return -1

    latest = [-1] * 5
    left_at_most_k = 0
    left_at_most_km1 = 0
    cnt_con_k = 0
    cnt_con_km1 = 0
    answer = 0

    for r in range(n):
        v_idx = vowel_index(word[r])
        if v_idx == -1:
            cnt_con_k += 1
            cnt_con_km1 += 1
        else:
            latest[v_idx] = r

        while cnt_con_k > k:
            if vowel_index(word[left_at_most_k]) == -1:
                cnt_con_k -= 1
            left_at_most_k += 1

        if k > 0:
            while cnt_con_km1 > k - 1:
                if vowel_index(word[left_at_most_km1]) == -1:
                    cnt_con_km1 -= 1
                left_at_most_km1 += 1

        min_pos = n
        for i in range(5):
            if latest[i] == -1:
                min_pos = -1
                break
            if latest[i] < min_pos:
                min_pos = latest[i]

        cnt_at_most_k = 0
        cnt_at_most_km1 = 0
        if min_pos >= left_at_most_k:
            cnt_at_most_k = min_pos - left_at_most_k + 1
        if k > 0 and min_pos >= left_at_most_km1:
            cnt_at_most_km1 = min_pos - left_at_most_km1 + 1

        answer += cnt_at_most_k - cnt_at_most_km1

    return answer

