def remove_methods(n: int, k: int, invocations: List[Tuple[int, int]]) -> List[int]:
    adj: List[List[int]] = [[] for _ in range(n)]
    for a, b in invocations:
        adj[a].append(b)

    suspicious: Set[int] = set()
    stack: List[int] = [k]
    while stack:
        cur = stack.pop()
        if cur in suspicious:
            continue
        suspicious.add(cur)
        for nxt in adj[cur]:
            if nxt not in suspicious:
                stack.append(nxt)

    for a, b in invocations:
        if a not in suspicious and b in suspicious:
            return list(range(n))

    remaining: List[int] = [i for i in range(n) if i not in suspicious]
    return remaining

