def sorted_gcd_pair_queries(nums: List[int], queries: List[int]) -> List[int]:
    n = len(nums)
    max_val = 0
    for v in nums:
        if v > max_val:
            max_val = v
    freq = [0] * (max_val + 1)
    for v in nums:
        freq[v] += 1
    cnt_div = [0] * (max_val + 1)
    for d in range(1, max_val + 1):
        s = 0
        for m in range(d, max_val + 1, d):
            s += freq[m]
        cnt_div[d] = s
    exact = [0] * (max_val + 1)
    for d in range(max_val, 0, -1):
        total = cnt_div[d] * (cnt_div[d] - 1) // 2
        for m in range(d * 2, max_val + 1, d):
            total -= exact[m]
        exact[d] = total
    prefix = [0] * (max_val + 1)
    for d in range(1, max_val + 1):
        prefix[d] = prefix[d - 1] + exact[d]
    answer = []
    for q in queries:
        target = q + 1
        d = bisect_left(prefix, target, 1)
        answer.append(d)
    return answer

MOD = 1000000007

def count_winning_sequences(s: str) -> int:
    n = len(s)
    offset = n
    range_ = 2 * n + 1

    def idx(c: str) -> int:
        if c == 'F':
            return 0
        if c == 'W':
            return 1
        return 2  # 'E'

    alice = [idx(ch) for ch in s]

    win = [[0] * 3 for _ in range(3)]
    for b in range(3):
        for a in range(3):
            if b == a:
                win[b][a] = 0
            elif (b == 0 and a == 2) or (b == 1 and a == 0) or (b == 2 and a == 1):
                win[b][a] = 1
            else:
                win[b][a] = -1

    dp_prev = [[0] * range_ for _ in range(4)]
    dp_prev[3][offset] = 1

    for i in range(n):
        dp_curr = [[0] * range_ for _ in range(4)]
        for prev in range(4):
            row_prev = dp_prev[prev]
            for sc in range(range_):
                ways = row_prev[sc]
                if not ways:
                    continue
                for cur in range(3):
                    if prev != 3 and cur == prev:
                        continue
                    delta = win[cur][alice[i]]
                    nsc = sc + delta
                    if nsc < 0 or nsc >= range_:
                        continue
                    val = dp_curr[cur][nsc] + ways
                    if val >= MOD:
                        val -= MOD
                    dp_curr[cur][nsc] = val
        dp_prev = dp_curr

    ans = 0
    for prev in range(3):
        row = dp_prev[prev]
        for sc in range(offset + 1, range_):
            ans += row[sc]
            if ans >= MOD:
                ans -= MOD
    return ans % MOD

