def find_x_sum(nums: List[int], k: int, x: int) -> List[int]:
    n = len(nums)
    result: List[int] = []
    for i in range(n - k + 1):
        freq: Dict[int, int] = {}
        window_sum = 0
        for v in nums[i:i + k]:
            window_sum += v
            freq[v] = freq.get(v, 0) + 1

        if len(freq) <= x:
            result.append(window_sum)
        else:
            # sort by frequency descending, then value descending for tie‑break
            items: List[Tuple[int, int]] = sorted(freq.items(), key=lambda kv: (-kv[1], -kv[0]))
            x_sum = sum(val * cnt for val, cnt in items[:x])
            result.append(x_sum)
    return result

