_spf_all = None

def minimum_operations(nums: List[int]) -> int:
    global _spf_all
    MAXV = 1000000
    if _spf_all is None:
        spf = [i for i in range(MAXV + 1)]
        limit = int(MAXV ** 0.5)
        for i in range(2, limit + 1):
            if spf[i] == i:
                step = i
                start = i * i
                for j in range(start, MAXV + 1, step):
                    if spf[j] == j:
                        spf[j] = i
        _spf_all = spf
    spf = _spf_all

    INF = 10 ** 9
    n = len(nums)
    if n == 0:
        return 0

    prev_orig = nums[0]
    prev_spf = 1 if nums[0] == 1 else spf[nums[0]]
    prev_has_spf = prev_spf != prev_orig

    dp0 = 0
    dp1 = 1 if prev_has_spf else INF

    for i in range(1, n):
        cur_orig = nums[i]
        cur_spf = 1 if nums[i] == 1 else spf[nums[i]]
        cur_has_spf = cur_spf != cur_orig

        ndp0 = INF
        ndp1 = INF

        if dp0 < INF:
            if prev_orig <= cur_orig:
                ndp0 = min(ndp0, dp0)
            if cur_has_spf and prev_orig <= cur_spf:
                ndp1 = min(ndp1, dp0 + 1)

        if dp1 < INF:
            if prev_spf <= cur_orig:
                ndp0 = min(ndp0, dp1)
            if cur_has_spf and prev_spf <= cur_spf:
