def max_points(n: int, k: int, stay_score: List[List[int]], travel_score: List[List[int]]) -> int:
    if k == 0:
        return 0
    dp_prev = stay_score[0][:]
    neg_inf = -10**18
    for day in range(1, k):
        dp_curr = [neg_inf] * n
        for c in range(n):
            stay = dp_prev[c] + stay_score[day][c]
            best_travel = neg_inf
            for p in range(n):
                if p == c:
                    continue
                cand = dp_prev[p] + travel_score[p][c]
                if cand > best_travel:
                    best_travel = cand
            dp_curr[c] = stay if stay > best_travel else best_travel
        dp_prev = dp_curr
    return max(dp_prev)

