        cnt[idx] = (cnt[idx] + 1) % MOD
    for _ in range(t):
        new_cnt = [0] * 26
        for i in range(26):
            val = cnt[i]
            if val == 0:
                continue
            if i == 25:
                new_cnt[0] = (new_cnt[0] + val * 2) % MOD
            else:
                new_cnt[i + 1] = (new_cnt[i + 1] + val) % MOD
        cnt = new_cnt
    return sum(cnt) % MOD

