        prod = 1
        temp = cur
        if temp == 0:
            prod = 0
        while temp > 0:
            digit = temp % 10
            prod *= digit
            temp //= 10
            if prod == 0:
                break
        if prod % t == 0:
            return cur
        cur += 1

