        return False
    inc = [0] * (n - 1)
    for i in range(n - 1):
        inc[i] = 1 if nums[i] < nums[i + 1] else 0
    pref = [0] * n
    for i in range(n - 1):
        pref[i + 1] = pref[i] + inc[i]
    for a in range(0, n - 2 * k + 1):
        sum1 = pref[a + k - 1] - pref[a]
        sum2 = pref[a + 2 * k - 1] - pref[a + k]
        if sum1 == k - 1 and sum2 == k - 1:
            return True
    return False

