def max_frequency(nums: List[int], k: int, num_operations: int) -> int:
    if k == 0:
        cnt = {}
        best = 0
        for v in nums:
            cnt[v] = cnt.get(v, 0) + 1
            if cnt[v] > best:
                best = cnt[v]
        return best

    groups = {}
    for v in nums:
        r = v % k
        base = (v - r) // k
        groups.setdefault(r, []).append(base)

    answer = 0
    for bases in groups.values():
        bases.sort()
        total = 0
        left = 0
        for right in range(len(bases)):
            total += bases[right]
            while bases[right] * (right - left + 1) - total > num_operations:
                total -= bases[left]
                left += 1
            length = right - left + 1
            if length > answer:
                answer = length
    return answer

