    for i in range(n - 2, -1, -1):
        inc[i] = inc[i + 1] + 1 if nums[i] < nums[i + 1] else 1
    def can(k: int) -> bool:
        limit = n - 2 * k
        for i in range(limit + 1):
            if inc[i] >= k and inc[i + k] >= k:
                return True
        return False
    low, high = 0, n // 2
    while low < high:
        mid = (low + high + 1) // 2
        if can(mid):
            low = mid
        else:
            high = mid - 1
    return low

