def count_k_reducible_numbers(s: str, k: int) -> int:
    MOD = 1000000007
    L = len(s)

    C = [[0] * (L + 1) for _ in range(L + 1)]
    for i in range(L + 1):
        C[i][0] = 1
        C[i][i] = 1
        for j in range(1, i):
            C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD

    steps = [0] * (L + 1)
    if L >= 1:
        steps[1] = 0
    for c in range(2, L + 1):
        pc = bin(c).count('1')
        steps[c] = 1 + steps[pc]

    good = [c for c in range(1, L + 1) if steps[c] <= k - 1]

    def count_less_than(target: int) -> int:
        ans = 0
        ones_so_far = 0
        for i, ch in enumerate(s):
            if ch == '1':
                remaining = L - i - 1
                need = target - ones_so_far
                if 0 <= need <= remaining:
                    ans = (ans + C[remaining][need]) % MOD
                ones_so_far += 1
                if ones_so_far > target:
                    break
        return ans

    total = 0
    for c in good:
        total = (total + count_less_than(c)) % MOD
    return total

