    base = 0
    INF = 10**18
    minV = INF
    maxV = -INF
    for i in range(n - 1):
        a = nums[i]
        b = nums[i + 1]
        if a != -1 and b != -1:
            diff = abs(a - b)
            if diff > base:
                base = diff
        if a == -1 and b != -1:
            if b < minV:
                minV = b
            if b > maxV:
                maxV = b
        if a != -1 and b == -1:
            if a < minV:
                minV = a
            if a > maxV:
                maxV = a
    if minV == INF:
        return 0
    diff = maxV - minV
    kDiff = (diff + 1) // 2
    return max(base, kDiff)

