def minArraySum(nums: List[int], k: int, op1: int, op2: int) -> int:
    n = len(nums)
    @lru_cache(maxsize=None)
    def dp(i, o1, o2):
        if i == n:
            return 0
        x = nums[i]
        res = x + dp(i + 1, o1, o2)
        if o1 > 0:
            res = min(res, (x + 1) // 2 + dp(i + 1, o1 - 1, o2))
        if o2 > 0 and x >= k:
            res = min(res, x - k + dp(i + 1, o1, o2 - 1))
        if o1 > 0 and o2 > 0:
            half = (x + 1) // 2
            if half >= k:
                res = min(res, half - k + dp(i + 1, o1 - 1, o2 - 1))
            if x >= k:
                res = min(res, (x - k + 1) // 2 + dp(i + 1, o1 - 1, o2 - 1))
        return res
    return dp(0, op1, op2)

