        for a, b in edges:
            adj[a].append(b)
            adj[b].append(a)
        return adj

    adj1 = build_adj(n, edges1)
    adj2 = build_adj(m, edges2)

    def all_pairs_dist(num, adj):
        dist = [[-1] * num for _ in range(num)]
        from collections import deque
        for s in range(num):
            d = dist[s]
            dq = deque()
            d[s] = 0
            dq.append(s)
            while dq:
                u = dq.popleft()
                du = d[u]
                for v in adj[u]:
                    if d[v] == -1:
                        d[v] = du + 1
                        dq.append(v)
        return dist

    dist1 = all_pairs_dist(n, adj1)
    dist2 = all_pairs_dist(m, adj2)

    count_first = [0] * n
    for i in range(n):
