            if d != -1 and d <= k:
                cnt[d] += 1
        for r in range(1, k + 1):
            cnt[r] += cnt[r - 1]
        for r in range(k + 1):
            if cnt[r] > best_second[r]:
                best_second[r] = cnt[r]

    answer = [0] * n
