def smallest_all_set_bits(n: int) -> int:
    if n <= 0:
        return 0
    num = n if n >= 0 else n + (1 << 64)
    length = 0
    tmp = num
    while tmp > 0:
        tmp >>= 1
        length += 1
    ULLONG_MAX = (1 << 64) - 1
    if length >= 64:
        candidate = ULLONG_MAX
    else:
        candidate = (1 << length) - 1
    if candidate >= num:
        return candidate
    if length + 1 >= 64:
        result = ULLONG_MAX
    else:
        result = (1 << (length + 1)) - 1
    return result

