def minimum_transformation_cost(n: int, m: int) -> int:
    sn = str(n)
    sm = str(m)
    len_n = len(sn)
    len_m = len(sm)
    if len_n != len_m:
        return -1
    d = len_n

    if is_prime(n) or is_prime(m):
        return -1
    if n == m:
        return n

    max_val = 1
    for _ in range(d):
        max_val *= 10
    max_val -= 1

    INF = 1 << 60
    dist = [INF] * (max_val + 1)
    visited = [False] * (max_val + 1)

    import heapq
    heap = []
    dist[n] = n
    heapq.heappush(heap, (n, n))

    while heap:
        cur_dist, u = heapq.heappop(heap)
        if visited[u]:
            continue
        visited[u] = True
        if u == m:
            return cur_dist

        s = str(u).zfill(d)

        for i in range(d):
            digit = ord(s[i]) - ord('0')
            # decrease
            if digit > 0:
                if not (i == 0 and digit == 1):
                    t = list(s)
                    t[i] = chr(ord('0') + digit - 1)
                    v = int(''.join(t))
                    if not is_prime(v) and cur_dist + v < dist[v]:
                        dist[v] = cur_dist + v
                        heapq.heappush(heap, (dist[v], v))
            # increase
            if digit < 9:
                t = list(s)
                t[i] = chr(ord('0') + digit + 1)
                v = int(''.join(t))
                if not is_prime(v) and cur_dist + v < dist[v]:
                    dist[v] = cur_dist + v
                    heapq.heappush(heap, (dist[v], v))

    return -1

