def count_components(nums: List[int], threshold: int) -> int:
    n = len(nums)
    parent = list(range(n))
    rank = [0] * n

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def unite(a: int, b: int) -> None:
        ra = find(a)
        rb = find(b)
        if ra == rb:
            return
        if rank[ra] < rank[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        if rank[ra] == rank[rb]:
            rank[ra] += 1

    rep = [-1] * (threshold + 1)
    for i, val in enumerate(nums):
        if val > threshold:
            continue
        mult = val
        while mult <= threshold:
            if rep[mult] == -1:
                rep[mult] = i
            else:
                unite(i, rep[mult])
            mult += val

    components = set()
    for i in range(n):
        components.add(find(i))
    return len(components)

