def min_operations_to_make_good(s: str) -> int:
    n = len(s)
    freq = [0] * 26
    for ch in s:
        freq[ord(ch) - ord('a')] += 1
    sorted_freq = sorted(freq, reverse=True)
    best = n
    for k in range(1, min(26, n) + 1):
        sum_top = sum(sorted_freq[:k])
        extra = n - sum_top
        for f in range(1, n + 1):
            surplus = extra
            deficit = 0
            for i in range(k):
                cur = sorted_freq[i]
                if cur > f:
                    surplus += cur - f
                else:
                    deficit += f - cur
            ops = surplus if surplus > deficit else deficit
            if ops < best:
                best = ops
    return best

