    n = len(grid[0])
    max_xor = 16

    dp_prev = [[0] * max_xor for _ in range(n)]
    dp_prev[0][grid[0][0]] = 1

    for j in range(1, n):
        cur = [0] * max_xor
        val = grid[0][j]
        left = dp_prev[j - 1]
        for x in range(max_xor):
            if left[x] != 0:
                nx = x ^ val
                cur[nx] = (cur[nx] + left[x]) % MOD
        dp_prev[j] = cur

    for i in range(1, m):
        dp_curr = [[0] * max_xor for _ in range(n)]
        val_first_col = grid[i][0]
        above_first = dp_prev[0]
        for x in range(max_xor):
            if above_first[x] != 0:
                nx = x ^ val_first_col
                dp_curr[0][nx] = (dp_curr[0][nx] + above_first[x]) % MOD

        for j in range(1, n):
            val = grid[i][j]
            cur = dp_curr[j]
            above = dp_prev[j]
            left = dp_curr[j - 1]

            for x in range(max_xor):
                if above[x] != 0:
                    nx = x ^ val
                    cur[nx] = (cur[nx] + above[x]) % MOD

            for x in range(max_xor):
                if left[x] != 0:
                    nx = x ^ val
                    cur[nx] = (cur[nx] + left[x]) % MOD

        dp_prev = dp_curr

    return dp_prev[n - 1][k] % MOD

