def min_longest_block(s: str, num_ops: int) -> int:
    n = len(s)
    # Precompute run lengths
    runs = []
    i = 0
    while i < n:
        j = i
        while j < n and s[j] == s[i]:
            j += 1
        runs.append(j - i)
        i = j

    # If no operations allowed, answer is current maximum run length
    if num_ops == 0:
        return max(runs)

    low, high = 1, n
    while low < high:
        mid = (low + high) // 2
        needed = 0
        limit = mid + 1
        for length in runs:
            needed += length // limit
            if needed > num_ops:  # early stop
                break
        if needed <= num_ops:
            high = mid
        else:
            low = mid + 1
    return low

