def smallest_longest_substring(s: str, num_ops: int) -> int:
    n = len(s)

    def can(limit: int) -> bool:
        flips = 0
        cur = s[0]
        run = 1
        for i in range(1, n):
            ch = s[i]
            if ch == cur:
                run += 1
            else:
                cur = ch
                run = 1
            if run > limit:
                flips += 1
                cur = '1' if cur == '0' else '0'
                run = 1
                if flips > num_ops:
                    return False
        return flips <= num_ops

    low, high, ans = 1, n, n
    while low <= high:
        mid = (low + high) // 2
        if can(mid):
            ans = mid
            high = mid - 1
        else:
            low = mid + 1
    return ans

