def substring_matching_pattern(s: str, p: str) -> bool:
    star_pos = p.find('*')
    pre = p[:star_pos]
    suf = p[star_pos + 1:]

    if len(pre) == 0 and len(suf) == 0:
        return True

    if len(pre) == 0:
        return s.find(suf) != -1

    if len(suf) == 0:
        return s.find(pre) != -1

    for i in range(0, len(s) - len(pre) + 1):
        if s[i:i + len(pre)] == pre:
            after = i + len(pre)
            if s.find(suf, after) != -1:
                return True
    return False

def count_arrays(n: int, m: int, k: int) -> int:
    MOD = 1_000_000_007

    if k < 0 or k > n - 1:
        return 0

    # pre‑compute factorials and inverse factorials up to n
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD

    def mod_pow(a: int, e: int) -> int:
        res = 1
        a %= MOD
        while e:
            if e & 1:
                res = res * a % MOD
            a = a * a % MOD
            e >>= 1
        return res

    inv_fact = [1] * (n + 1)
    inv_fact[n] = mod_pow(fact[n], MOD - 2)
    for i in range(n, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % MOD

    def comb(nn: int, rr: int) -> int:
        if rr < 0 or rr > nn:
            return 0
        return fact[nn] * inv_fact[rr] % MOD * inv_fact[nn - rr] % MOD

    ways_choose = comb(n - 1, k)
    runs = n - k
    colorings = m * mod_pow(m - 1, runs - 1) % MOD
    return ways_choose * colorings % MOD

class TaskManager:
    def __init__(self, tasks):
        self.heap = []
        self.task_map = {}
        for user_id, task_id, priority in tasks:
            node = {'userId': user_id, 'taskId': task_id, 'priority': priority, 'idx': len(self.heap)}
            self.heap.append(node)
            self.task_map[task_id] = node
        for i in range((len(self.heap) >> 1) - 1, -1, -1):
            self._heapify_down(i)

    def _less(self, a, b):
        if a['priority'] != b['priority']:
            return a['priority'] > b['priority']
        return a['taskId'] > b['taskId']

    def _swap(self, i, j):
        self.heap[i], self.heap[j] = self.heap[j], self.heap[i]
        self.heap[i]['idx'] = i
        self.heap[j]['idx'] = j

    def _heapify_up(self, i):
        while i > 0:
            p = (i - 1) >> 1
            if self._less(self.heap[i], self.heap[p]):
                self._swap(i, p); i = p
            else:
                break

    def _heapify_down(self, i):
        n = len(self.heap)
        while True:
            left, right, best = i * 2 + 1, i * 2 + 2, i
            if left < n and self._less(self.heap[left], self.heap[best]): best = left
            if right < n and self._less(self.heap[right], self.heap[best]): best = right
            if best != i:
                self._swap(i, best); i = best
            else:
                break

    def _remove_at(self, idx):
        self._swap(idx, len(self.heap) - 1)
        removed = self.heap.pop()
        del self.task_map[removed['taskId']]
        if idx < len(self.heap):
            self._heapify_up(idx); self._heapify_down(idx)

    def add(self, userId, taskId, priority):
        if taskId in self.task_map:
            return
        node = {'userId': userId, 'taskId': taskId, 'priority': priority, 'idx': len(self.heap)}
        self.heap.append(node); self.task_map[taskId] = node
        self._heapify_up(node['idx'])

    def edit(self, taskId, newPriority):
        node = self.task_map.get(taskId)
        if not node:
            return
        node['priority'] = newPriority
        self._heapify_up(node['idx']); self._heapify_down(node['idx'])

    def rmv(self, taskId):
        node = self.task_map.get(taskId)
        if not node:
            return
        self._remove_at(node['idx'])

    def execTop(self):
        if not self.heap:
            return -1
        user_id = self.heap[0]['userId']
        self._remove_at(0)
        return user_id

