def max_subarray_sum_after_removal(nums: List[int]) -> int:
    # Kadane's algorithm for the original array
    cur = best = nums[0]
    for x in nums[1:]:
        cur = max(cur + x, x)
        best = max(best, cur)
    answer = best

    distinct = set(nums)
    for v in distinct:
        cur_v = None
        best_v = None
        for x in nums:
            if x == v:
                continue
            if cur_v is None:
                cur_v = best_v = x
            else:
                cur_v = max(cur_v + x, x)
                best_v = max(best_v, cur_v)
        if best_v is not None:
            answer = max(answer, best_v)
    return answer

