def maximum_subarray_with_equal_products(nums: List[int]) -> int:
    primes = [2, 3, 5, 7]
    n = len(nums)
    # precompute exponent of each prime for each number
    exp = [[0] * len(primes) for _ in range(n)]
    for i, val in enumerate(nums):
        x = val
        for idx, p in enumerate(primes):
            cnt = 0
            while x % p == 0:
                cnt += 1
                x //= p
            exp[i][idx] = cnt

    best = 0
    for i in range(n):
        sum_e = [0] * len(primes)
        max_e = [0] * len(primes)
        min_e = [float('inf')] * len(primes)
        for j in range(i, n):
            for idx in range(len(primes)):
                e = exp[j][idx]
                sum_e[idx] += e
                if e > max_e[idx]:
                    max_e[idx] = e
                if e < min_e[idx]:
                    min_e[idx] = e
            ok = True
            for idx in range(len(primes)):
                if sum_e[idx] != max_e[idx] + min_e[idx]:
                    ok = False
                    break
            if ok:
                best = max(best, j - i + 1)
    return best

def longest_subsequence_with_decreasing_adjacent_difference(nums: list[int]) -> int:
    n = len(nums)
    MAX_DIFF = 300
    dp = [[0] * (MAX_DIFF + 1) for _ in range(n)]
    suffix = [[0] * (MAX_DIFF + 1) for _ in range(n)]
    answer = 1
    for i in range(n):
        for j in range(i):
            d = abs(nums[i] - nums[j])
            best = 2
            prev = suffix[j][d]
            if prev > 0:
                cand = prev + 1
                if cand > best:
                    best = cand
            if best > dp[i][d]:
                dp[i][d] = best
                if best > answer:
                    answer = best
        cur_max = 0
        for d in range(MAX_DIFF, -1, -1):
            if dp[i][d] > cur_max:
                cur_max = dp[i][d]
            suffix[i][d] = cur_max
    return answer

