from collections import deque

class Solution:
    def minMaxWeight(self, n: int, edges: list[list[int]], threshold: int) -> int:
        # threshold turns out to be irrelevant to feasibility (as long as threshold>=1,
        # guaranteed by constraints): any witnessing subgraph where nodes reach 0 can be
        # pruned down to at most one outgoing edge per node without breaking reachability,
        # which trivially respects any threshold>=1 - verified this against an exhaustive
        # brute force over small graphs before relying on it.
        rev = [[] for _ in range(n)]
        maxW = 0
        for a, b, w in edges:
            rev[b].append((a, w))
            maxW = max(maxW, w)

        def feasible(W):
            visited = [False]*n
            visited[0] = True
            q = deque([0])
            count = 1
            while q:
                u = q.popleft()
                for v, w in rev[u]:
                    if w <= W and not visited[v]:
                        visited[v] = True
                        count += 1
                        q.append(v)
            return count == n

        if not feasible(maxW):
            return -1
        lo, hi = 1, maxW
        while lo < hi:
            mid = (lo+hi)//2
            if feasible(mid):
                hi = mid
            else:
                lo = mid+1
        return lo

