def count_non_decreasing_subarrays(nums: List[int], k: int) -> int:
    n = len(nums)
    answer = 0
    for i in range(n):
        cur_max = nums[i]
        cost = 0
        answer += 1
        for j in range(i + 1, n):
            if nums[j] >= cur_max:
                cur_max = nums[j]
            else:
                cost += cur_max - nums[j]
                if cost > k:
                    break
            if cost <= k:
                answer += 1
    return answer

