def max_earnings(coins: List[List[int]]) -> int:
    if not coins:
        return 0
    m, n = len(coins), len(coins[0])
    NEG_INF = -10**15

    # dp[j][k] for current row, column j, k skips used
    dp = [[NEG_INF] * 3 for _ in range(n)]

    # initialize (0,0)
    dp[0][0] = coins[0][0]
    dp[0][1] = 0  # use a skip on the starting cell

    for i in range(m):
        for j in range(n):
            if i == 0 and j == 0:
                continue
            new_vals = [NEG_INF] * 3
            for k in range(3):
                # from top
                if i > 0:
                    # without using a new skip
                    if dp[j][k] != NEG_INF:
                        new_vals[k] = max(new_vals[k], dp[j][k] + coins[i][j])
                    # using a skip on this cell
                    if k > 0 and dp[j][k - 1] != NEG_INF:
                        new_vals[k] = max(new_vals[k], dp[j][k - 1])
                # from left
                if j > 0:
                    # without using a new skip
                    if dp[j - 1][k] != NEG_INF:
                        new_vals[k] = max(new_vals[k], dp[j - 1][k] + coins[i][j])
                    # using a skip on this cell
                    if k > 0 and dp[j - 1][k - 1] != NEG_INF:
                        new_vals[k] = max(new_vals[k], dp[j - 1][k - 1])
            dp[j] = new_vals
    return max(dp[n - 1])

