def minCost(n, cost):
    half = n // 2
    # dp: (colorLeft, colorRight) -> min cost for the current mirror pair (cL != cR always)
    dp = {}
    for cL in range(3):
        for cR in range(3):
            if cL != cR:
                dp[(cL, cR)] = cost[0][cL] + cost[n - 1][cR]
    for i in range(1, half):
        j = n - 1 - i
        new_dp = {}
        for cL in range(3):
            for cR in range(3):
                if cL == cR:
                    continue
                best = float('inf')
                for pL in range(3):
                    for pR in range(3):
                        # adjacency: new left color must differ from previous left color (and same for right)
                        if pL == pR or pL == cL or pR == cR:
                            continue
                        if (pL, pR) in dp:
                            best = min(best, dp[(pL, pR)])
                if best < float('inf'):
                    new_dp[(cL, cR)] = best + cost[i][cL] + cost[j][cR]
        dp = new_dp
    return min(dp.values())

