def max_free_time(event_time: int, k: int, start_time: List[int], end_time: List[int]) -> int:
    n = len(start_time)
    m = n + 1
    gaps = [0] * m
    gaps[0] = start_time[0]
    for i in range(1, n):
        gaps[i] = start_time[i] - end_time[i - 1]
    gaps[m - 1] = event_time - end_time[n - 1]
    total_free = sum(gaps)
    if k >= m - 1:
        return total_free
    sorted_pairs = [(v, idx) for idx, v in enumerate(gaps)]
    sorted_pairs.sort(key=lambda x: x[0], reverse=True)
    prefix = [0] * (m + 1)
    for i in range(m):
        prefix[i + 1] = prefix[i] + sorted_pairs[i][0]
    rank = [0] * m
    for i in range(m):
        rank[sorted_pairs[i][1]] = i
    answer = 0
    for i in range(m):
        if rank[i] < k:
            sum_top_k = prefix[k + 1] - gaps[i]
        else:
            sum_top_k = prefix[k]
        candidate = gaps[i] + sum_top_k
        if candidate > answer:
            answer = candidate
    return answer

