def max_frequency_after_subarray_operation(nums: list[int], k: int) -> int:
    n = len(nums)
    original_count = 0
    delta_set = {0}
    for i in range(n):
        if nums[i] == k:
            original_count += 1
        delta_set.add(k - nums[i])
    answer = original_count
    for delta in delta_set:
        if delta == 0:
            continue
        cur = 0
        best = 0
        target = k - delta
        for i in range(n):
            if nums[i] == k:
                cur -= 1
            elif nums[i] == target:
                cur += 1
            if cur < 0:
                cur = 0
            if cur > best:
                best = cur
        candidate = original_count + best
        if candidate > answer:
            answer = candidate
    return answer

