def max_manhattan_distance_after_k_changes(s: str, k: int) -> int:
    x = y = 0
    inward = 0
    answer = 0
    for c in s:
        if c == 'N':
            outward = y >= 0
        elif c == 'S':
            outward = y <= 0
        elif c == 'E':
            outward = x >= 0
        else:  # 'W'
            outward = x <= 0
        if not outward:
            inward += 1
        if c == 'N':
            y += 1
        elif c == 'S':
            y -= 1
        elif c == 'E':
            x += 1
        else:  # 'W'
            x -= 1
        dist = abs(x) + abs(y)
        best = dist + 2 * min(k, inward)
        if best > answer:
            answer = best
    return answer

