def sort_matrix_by_diagonals(grid: List[List[int]]) -> List[List[int]]:
    n = len(grid)
    for k in range(-(n - 1), n):
        values = []
        positions = []
        for i in range(n):
            j = i - k
            if 0 <= j < n:
                values.append(grid[i][j])
                positions.append((i, j))
        if k >= 0:
            values.sort(reverse=True)
        else:
            values.sort()
        for idx, (i, j) in enumerate(positions):
            grid[i][j] = values[idx]
    return grid

