def assign_elements(groups: List[int], elements: List[int]) -> List[int]:
    MAXV = 100000
    INF = 10**9
    first_idx = [INF] * (MAXV + 1)
    for i, v in enumerate(elements):
        if v <= MAXV and first_idx[v] == INF:
            first_idx[v] = i
    result = []
    for g in groups:
        best = INF
        d = 1
        while d * d <= g:
            if g % d == 0:
                if d <= MAXV and first_idx[d] < best:
                    best = first_idx[d]
                d2 = g // d
                if d2 != d and d2 <= MAXV and first_idx[d2] < best:
                    best = first_idx[d2]
            d += 1
        result.append(-1 if best == INF else best)
    return result

