def max_score(points: List[int], m: int) -> int:
    maxP = 0
    for v in points:
        if v > maxP:
            maxP = v
    low = 0
    high = maxP * m
    while low < high:
        mid = (low + high + 1) // 2
        need = 0
        for v in points:
            need += (mid + v - 1) // v
            if need > m:
                break
        if need <= m:
            low = mid
        else:
            high = mid - 1
    return low

def count_divisible_substrings(s: str) -> int:
    cnt = [[] for _ in range(10)]
    for d in range(1, 10):
        cnt[d] = [0] * d
    answer = 0
    for ch in s:
        cur = ord(ch) - 48
        ndcnt = [[] for _ in range(10)]
        for d in range(1, 10):
            ndcnt[d] = [0] * d
            for r in range(d):
                ways = cnt[d][r]
                if ways:
                    nr = (r * 10 + cur) % d
                    ndcnt[d][nr] += ways
            nr = cur % d
            ndcnt[d][nr] += 1
        if cur != 0:
            answer += ndcnt[cur][0]
        cnt = ndcnt
    return answer

