def sum_good_numbers(nums: List[int], k: int) -> int:
    n = len(nums)
    total = 0
    for i in range(n):
        good = True
        left = i - k
        if left >= 0 and not (nums[i] > nums[left]):
            good = False
        right = i + k
        if right < n and not (nums[i] > nums[right]):
            good = False
        if good:
            total += nums[i]
    return total

