def separate_squares(squares: List[List[int]]) -> float:
    total = 0.0
    low = float('inf')
    high = -float('inf')
    for sq in squares:
        y = sq[1]
        l = sq[2]
        total += l * l
        low = min(low, y)
        high = max(high, y + l)

    half = total / 2.0

    def area_above(h: float) -> float:
        s = 0.0
        for sq in squares:
            y = sq[1]
            l = sq[2]
            if h <= y:
                s += l * l
            elif h < y + l:
                s += (y + l - h) * l
        return s

    lo, hi = low, high
    for _ in range(100):
        mid = (lo + hi) / 2.0
        if area_above(mid) > half:
            lo = mid
        else:
            hi = mid

    return round((lo + hi) / 2.0, 5)

def find_special_substring(s: str, k: int) -> bool:
    if k <= 0:
        return False
    consecutive = 1
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            consecutive += 1
        else:
            consecutive = 1
        if consecutive >= k:
            return True
    return False

def shortest_matching_substring(s: str, p: str) -> int:
    first = p.find('*')
    second = p.find('*', first + 1)
    A = p[:first]
    B = p[first + 1:second]
    C = p[second + 1:]
    n = len(s)

    def find_matches(sub: str):
        if not sub:
            return list(range(n + 1))
        m = len(sub)
        res = []
        for i in range(n - m + 1):
            if s[i:i + m] == sub:
                res.append(i)
        return res

    startsA = find_matches(A)
    startsB = find_matches(B)
    startsC = find_matches(C)

    nextB = [-1] * (n + 1)
    idxB = 0
    for pos in range(n + 1):
        while idxB < len(startsB) and startsB[idxB] < pos:
            idxB += 1
        if idxB < len(startsB):
            nextB[pos] = startsB[idxB]

    nextC = [-1] * (n + 1)
    idxC = 0
    for pos in range(n + 1):
        while idxC < len(startsC) and startsC[idxC] < pos:
            idxC += 1
        if idxC < len(startsC):
            nextC[pos] = startsC[idxC]

    best = float('inf')
    lenA = len(A)
    lenB = len(B)
    lenC = len(C)

    for i in startsA:
        posB = i + lenA
        if posB > n:
            continue
        j = nextB[posB]
        if j == -1:
            continue
        posC = j + lenB
        if posC > n:
            continue
        k = nextC[posC]
        if k == -1:
            continue
        length = (k + lenC) - i
        if length < best:
            best = length

    return -1 if best == float('inf') else best

def separate_squares_ii(squares):
    import bisect
    def lower_bound(arr, target):
        return bisect.bisect_left(arr, target)

    def union_area(rects):
        if not rects:
            return 0.0
        events = []
        y_vals = []
        for r in rects:
            x1, x2, y1, y2 = r
            events.append((x1, 1, y1, y2))
            events.append((x2, -1, y1, y2))
            y_vals.append(y1)
            y_vals.append(y2)
        events.sort(key=lambda e: e[0])
        y_vals.sort()
        uniq_y = []
        for v in y_vals:
            if not uniq_y or v != uniq_y[-1]:
                uniq_y.append(v)
        m = len(uniq_y) - 1 if len(uniq_y) > 0 else 0
        if m == 0:
            return 0.0
        size = (m + 2) * 4
        cnt = [0] * size
        length = [0.0] * size

        def update(node, l, r, ql, qr, delta):
            if ql > r or qr < l:
                return
            if ql <= l and r <= qr:
                cnt[node] += delta
            else:
                mid = (l + r) >> 1
                update(node * 2, l, mid, ql, qr, delta)
                update(node * 2 + 1, mid + 1, r, ql, qr, delta)
            if cnt[node] > 0:
                length[node] = uniq_y[r + 1] - uniq_y[l]
            elif l == r:
                length[node] = 0.0
            else:
                length[node] = length[node * 2] + length[node * 2 + 1]

        area = 0.0
        prev_x = events[0][0]
        for e in events:
            x, typ, y1, y2 = e
            dx = x - prev_x
            if dx != 0.0:
                area += length[1] * dx
            y1_idx = lower_bound(uniq_y, y1)
            y2_idx = lower_bound(uniq_y, y2)
            if y2_idx > 0:
                y2_idx -= 1
            if y1_idx <= y2_idx:
                update(1, 0, m - 1, y1_idx, y2_idx, typ)
            prev_x = x
        return area

    full_rects = []
    for s in squares:
        x, y, l = s
        full_rects.append([x, x + l, y, y + l])
    total_area = union_area(full_rects)
    half_area = total_area / 2.0

    low = float('inf')
    high = -float('inf')
    for s in squares:
        x, y, l = s
        if y < low:
            low = y
        if y + l > high:
            high = y + l

    for _ in range(60):
        mid = (low + high) * 0.5
        rects = []
        for s in squares:
            x, y, l = s
            y2 = y + l if y + l < mid else mid
            if y2 > y:
                rects.append([x, x + l, y, y2])
        area_below = union_area(rects)
        if area_below >= half_area:
            high = mid
        else:
            low = mid
    return high

def select_k_disjoint_special_substrings(s: str, k: int) -> bool:
    freq = {}
    for ch in s:
        freq[ch] = freq.get(ch, 0) + 1
    unique_count = sum(1 for v in freq.values() if v == 1)
    return unique_count >= k

class Solution:
    def lenOfVDiagonal(self, grid: list[list[int]]) -> int:
        m, n = len(grid), len(grid[0])
        dirs = [1, 1, -1, -1, 1]
        memo = {}

        def dfs(i, j, k, cnt):
            key = (i, j, k, cnt)
            if key in memo:
                return memo[key]
            target = 0 if grid[i][j] == 2 else 2
            best = 0
            x, y = i + dirs[k], j + dirs[k+1]
            if 0 <= x < m and 0 <= y < n and grid[x][y] == target:
                best = dfs(x, y, k, cnt) + 1
            if cnt == 0:
                k2 = (k+1) % 4
                x2, y2 = i + dirs[k2], j + dirs[k2+1]
                if 0 <= x2 < m and 0 <= y2 < n and grid[x2][y2] == target:
                    best = max(best, dfs(x2, y2, k2, 1) + 1)
            memo[key] = best
            return best

        ans = 0
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1:
                    for k in range(4):
                        ans = max(ans, dfs(i, j, k, 0) + 1)
        return ans

def are_digits_equal(s: str) -> bool:
