def max_min_manhattan_distance(side, points, k):
    P = 4 * side
    s = []
    for x, y in points:
        if y == 0:
            pos = x
        elif x == side:
            pos = side + y
        elif y == side:
            pos = 3 * side - x
        else:
            pos = 4 * side - y
        s.append(pos)
    s.sort()
    N = len(s)
    dup = s + [v + P for v in s]

    def lower_bound(arr, target, start):
        l = start
        r = len(arr)
        while l < r:
            m = (l + r) >> 1
            if arr[m] < target:
                l = m + 1
            else:
                r = m
        return l

    def feasible(d):
        for i in range(N):
            cnt = 1
            last_pos = dup[i]
            idx = i
            while cnt < k:
                target = last_pos + d
                j = lower_bound(dup, target, idx + 1)
                if j >= i + N:
                    break
                cnt += 1
                last_pos = dup[j]
                idx = j
            if cnt == k:
                span = last_pos - dup[i]
                if span <= P - d:
                    return True
        return False

    low = 0
    high = P // 2
    while low < high:
        mid = (low + high + 1) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid - 1
    return low

