def smallest_generated_string(str1: str, str2: str) -> str:
    n = len(str1)
    m = len(str2)
    L = n + m - 1
    word = [None] * L
    for i in range(n):
        if str1[i] == 'T':
            for j in range(m):
                pos = i + j
                c = str2[j]
                if word[pos] is None:
                    word[pos] = c
                elif word[pos] != c:
                    return ""
    for i in range(n):
        if str1[i] == 'F':
            already_diff = False
            for j in range(m):
                pos = i + j
                c = str2[j]
                if word[pos] is not None and word[pos] != c:
                    already_diff = True
                    break
            if already_diff:
                continue
            changed = False
            for j in range(m - 1, -1, -1):
                pos = i + j
                if word[pos] is None:
                    c = str2[j]
                    word[pos] = 'b' if c == 'a' else 'a'
                    changed = True
                    break
            if not changed:
                return ""
    for i in range(L):
        if word[i] is None:
            word[i] = 'a'
    return ''.join(word)

