def minimum_removal_cost(nums: List[int]) -> int:
    n = len(nums)
    max_pos = [[0] * n for _ in range(n)]
    for i in range(n):
        max_pos[i][i] = i
        for j in range(i + 1, n):
            prev = max_pos[i][j - 1]
            max_pos[i][j] = j if nums[j] > nums[prev] else prev

    dp = [[0] * n for _ in range(n)]
    for length in range(1, n + 1):
        for l in range(0, n - length + 1):
            r = l + length - 1
            if l == r:
                dp[l][r] = nums[l]
            else:
                m = max_pos[l][r]
                left = dp[l][m - 1] if m > l else 0
                right = dp[m + 1][r] if m < r else 0
                dp[l][r] = nums[m] + min(left, right)
    return dp[0][n - 1]

def longest_palindrome_subseq_after_operations(s: str, k: int) -> int:
    n = len(s)
    K = k
    def dist(a: str, b: str) -> int:
        diff = abs(ord(a) - ord(b))
        return diff if diff <= 13 else 26 - diff
    dp = [[[0] * (K + 1) for _ in range(n)] for _ in range(n)]
    for i in range(n):
        for c in range(K + 1):
            dp[i][i][c] = 1
    for length in range(2, n + 1):
        for l in range(0, n - length + 1):
            r = l + length - 1
            d = dist(s[l], s[r])
            for c in range(K + 1):
                best = dp[l + 1][r][c] if l + 1 <= r else 0
                if l <= r - 1:
                    best = max(best, dp[l][r - 1][c])
                if c >= d:
                    inner = dp[l + 1][r - 1][c - d] if l + 1 <= r - 1 else 0
                    best = max(best, inner + 2)
                dp[l][r][c] = best
    ans = 0
    for c in range(K + 1):
        ans = max(ans, dp[0][n - 1][c])
    return ans

