def count_unplaced_fruits(fruits: List[int], baskets: List[int]) -> int:
    n = len(fruits)
    sorted_baskets = sorted(baskets)
    parent = list(range(n + 1))

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def upper_bound(arr: List[int], target: int) -> int:
        lo, hi = 0, len(arr)
        while lo < hi:
            mid = (lo + hi) >> 1
            if arr[mid] <= target:
                lo = mid + 1
            else:
                hi = mid
        return lo

    unplaced = 0
    for need in fruits:
        idx = upper_bound(sorted_baskets, need)
        avail = find(idx)
        if avail == n:
            unplaced += 1
        else:
            parent[avail] = find(avail + 1)
    return unplaced

