def max_subarrays(n: int, conflicting_pairs: List[Tuple[int, int]]) -> int:
    def count_valid(pairs: List[Tuple[int, int]]) -> int:
        ending: List[List[int]] = [[] for _ in range(n + 1)]
        for a, b in pairs:
            if a > b:
                a, b = b, a
            ending[b].append(a)
        left = 1
        total = 0
        for r in range(1, n + 1):
            for a in ending[r]:
                if a + 1 > left:
                    left = a + 1
            if left <= r:
                total += r - left + 1
        return total

    best = 0
    m = len(conflicting_pairs)
    for remove_idx in range(m):
        remaining = [conflicting_pairs[i] for i in range(m) if i != remove_idx]
        cur = count_valid(remaining)
        if cur > best:
            best = cur
    return best

