def minimum_queries_to_zero_array(nums: List[int], queries: List[List[int]]) -> int:
    cur = nums[:]
    def all_zero() -> bool:
        for v in cur:
            if v != 0:
                return False
        return True
    if all_zero():
        return 0
    for i, q in enumerate(queries):
        l, r, val = q
        for j in range(l, r + 1):
            cur[j] = max(0, cur[j] - val)
        if all_zero():
            return i + 1
    return -1

