def longest_common_prefix(words: List[str], k: int) -> List[int]:
    n = len(words)
    if n - 1 < k:
        return [0] * n

    nodes = [{'next': [-1] * 26, 'cnt': 0, 'depth': 0}]
    max_word_len = 0

    for w in words:
        cur = 0
        d = 0
        for ch in w:
            idx = ord(ch) - 97
            if nodes[cur]['next'][idx] == -1:
                new_node = {'next': [-1] * 26, 'cnt': 0, 'depth': d + 1}
                nodes.append(new_node)
                nodes[cur]['next'][idx] = len(nodes) - 1
            cur = nodes[cur]['next'][idx]
            d += 1
            nodes[cur]['cnt'] += 1
        if len(w) > max_word_len:
            max_word_len = len(w)

    good_count = [0] * (max_word_len + 1)
    global_max_depth = 0
    for i in range(1, len(nodes)):
        node = nodes[i]
        if node['cnt'] >= k:
            good_count[node['depth']] += 1
            if node['depth'] > global_max_depth:
                global_max_depth = node['depth']

    answer = [0] * n

    for i in range(n):
        w = words[i]
        cur = 0
        for ch in w:
            idx = ord(ch) - 97
            cur = nodes[cur]['next'][idx]
            node = nodes[cur]
            if node['cnt'] == k:
                good_count[node['depth']] -= 1
                if node['depth'] == global_max_depth and good_count[node['depth']] == 0:
                    while global_max_depth > 0 and good_count[global_max_depth] == 0:
                        global_max_depth -= 1
            node['cnt'] -= 1

        answer[i] = global_max_depth

        cur = 0
        for ch in w:
            idx = ord(ch) - 97
            cur = nodes[cur]['next'][idx]
            node = nodes[cur]
            node['cnt'] += 1
            if node['cnt'] == k:
                good_count[node['depth']] += 1
                if node['depth'] > global_max_depth:
                    global_max_depth = node['depth']

    return answer

from functools import lru_cache

def beautiful_numbers(l: int, r: int) -> int:
    """Return the count of beautiful numbers in the inclusive range [l, r].

    A number is beautiful if product_of_digits(number) is divisible by
    sum_of_digits(number).
    """
    def count_upto(x: int) -> int:
        """Count beautiful numbers in [1, x]."""
        if x <= 0:
            return 0
        digits = [int(ch) for ch in str(x)]
        n = len(digits)
        max_sum = 9 * n          # maximal possible digit sum for numbers ≤ x
        total = 0

        for S in range(1, max_sum + 1):
            @lru_cache(maxsize=None)
            def dfs(pos: int, cur_sum: int, prod_mod: int,
                    tight: bool, started: bool) -> int:
                """Digit DP returning how many ways to finish the number."""
                if pos == n:
                    # valid only if we have started, sum equals S and product % S == 0
                    return int(started and cur_sum == S and prod_mod == 0)

                limit = digits[pos] if tight else 9
                ans = 0
                for d in range(limit + 1):
                    ntight = tight and (d == limit)
                    nstarted = started or d != 0

                    nsum = cur_sum
                    nprod = prod_mod
                    if nstarted:
                        nsum = cur_sum + d
                        if nsum > S:
                            continue
                        if started:
                            nprod = (prod_mod * d) % S
                        else:
                            # first non‑zero digit, product starts from 1
                            nprod = d % S
                    # else: still leading zeros, keep sum and product unchanged
                    ans += dfs(pos + 1, nsum, nprod, ntight, nstarted)
                return ans

            # product of an empty prefix is 1, we keep it modulo S
            total += dfs(0, 0, 1 % S, True, False)

        return total

    return count_upto(r) - count_upto(l - 1)

def calculate_reverse_degree(s: str) -> int:
    total = 0
    for i, ch in enumerate(s):
        rev_value = 123 - ord(ch)
        total += (i + 1) * rev_value
    return total

