from typing import List

def number_of_components(properties: List[List[int]], k: int) -> int:
    n = len(properties)
    if n == 0:
        return 0
    sets = [set(p) for p in properties]
    parent = list(range(n))
    rank = [0] * n

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def unite(a: int, b: int) -> None:
        ra = find(a)
        rb = find(b)
        if ra == rb:
            return
        if rank[ra] < rank[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        if rank[ra] == rank[rb]:
            rank[ra] += 1

    for i in range(n):
        for j in range(i + 1, n):
            a = sets[i]
            b = sets[j]
            if len(a) > len(b):
                small, large = b, a
            else:
                small, large = a, b
            common = 0
            for val in small:
                if val in large:
                    common += 1
                    if common >= k:
                        break
            if common >= k:
                unite(i, j)

    roots = set()
    for i in range(n):
        roots.add(find(i))
    return len(roots)

def is_pal(s: str) -> bool:
    i = 0
    j = len(s)
    if j == 0:
        return True
    j -= 1
    while i < j:
        if s[i] != s[j]:
            return False
        i += 1
        j -= 1
    return True

def longest_palindrome_after_concat(s: str, t: str) -> int:
    n = len(s)
    m = len(t)
    max_len = 0
    for i in range(n + 1):
        for j in range(i, n + 1):
            sub_s = s[i:j]
            for p in range(m + 1):
                for q in range(p, m + 1):
                    sub_t = t[p:q]
                    combined = sub_s + sub_t
                    length = len(combined)
                    if length > max_len and is_pal(combined):
                        max_len = length
    return max_len

