def max_product_alternating_sum(nums: List[int], k: int, limit: int) -> int:
    dp_even: dict[int, int] = {}
    dp_odd: dict[int, int] = {}
    for x in nums:
        next_even = dp_even.copy()
        next_odd = dp_odd.copy()
        val = x
        if val <= limit:
            if val not in next_odd or val > next_odd[val]:
                next_odd[val] = val
        for sum_val, cur_prod in dp_even.items():
            if val != 0 and cur_prod > limit // val:
                continue
            new_prod = cur_prod * val
            new_sum = sum_val + val
            if new_sum not in next_odd or new_prod > next_odd[new_sum]:
                next_odd[new_sum] = new_prod
        for sum_val, cur_prod in dp_odd.items():
            if val != 0 and cur_prod > limit // val:
                continue
            new_prod = cur_prod * val
            new_sum = sum_val - val
            if new_sum not in next_even or new_prod > next_even[new_sum]:
                next_even[new_sum] = new_prod
        dp_even = next_even
        dp_odd = next_odd
    ans = -1
    if k in dp_even:
        ans = max(ans, dp_even[k])
    if k in dp_odd:
        ans = max(ans, dp_odd[k])
    return ans

