def min_operations(nums: List[int]) -> int:
    if not nums:
        return 0
    tails: List[int] = []
    for x in nums:
        lo, hi = 0, len(tails)
        while lo < hi:
            mid = (lo + hi) // 2
            if tails[mid] <= x:
                lo = mid + 1
            else:
                hi = mid
        if lo == len(tails):
            tails.append(x)
        else:
            tails[lo] = x
    return len(nums) - len(tails)

def minimum_operations_to_make_non_decreasing(nums: list[int]) -> int:
