        return 0
    dp = [1] * n
    longest = 1
    for i in range(n):
        for j in range(i):
            if nums[j] <= nums[i]:
                dp[i] = max(dp[i], dp[j] + 1)
        longest = max(longest, dp[i])
    return n - longest

import collections, bisect

def router(commands):
    queue = collections.deque()
    packet_set = set()
    dest_map = {}
    limit = None
    results = []
    for cmd in commands:
        if not cmd:
            continue
        name = cmd[0]
        if name == "Router":
            limit = cmd[1]
        elif name == "addPacket":
            source, destination, timestamp = cmd[1], cmd[2], cmd[3]
            key = (source, destination, timestamp)
            if key in packet_set:
                results.append(False)
                continue
            if limit is not None and len(queue) == limit:
                old = queue.popleft()
                old_key = (old[0], old[1], old[2])
                packet_set.remove(old_key)
                lst = dest_map.get(old[1])
                if lst is not None:
                    idx = bisect.bisect_left(lst, old[2])
                    if idx < len(lst) and lst[idx] == old[2]:
                        lst.pop(idx)
                    if not lst:
                        del dest_map[old[1]]
            queue.append((source, destination, timestamp))
            packet_set.add(key)
            lst = dest_map.setdefault(destination, [])
            bisect.insort(lst, timestamp)
            results.append(True)
        elif name == "forwardPacket":
            if not queue:
                results.append([])
                continue
            p = queue.popleft()
            key = (p[0], p[1], p[2])
            packet_set.remove(key)
            lst = dest_map.get(p[1])
            if lst is not None:
                idx = bisect.bisect_left(lst, p[2])
                if idx < len(lst) and lst[idx] == p[2]:
                    lst.pop(idx)
                if not lst:
                    del dest_map[p[1]]
            results.append([p[0], p[1], p[2]])
        elif name == "getCount":
            destination, start_time, end_time = cmd[1], cmd[2], cmd[3]
            lst = dest_map.get(destination)
            if not lst:
                results.append(0)
            else:
                lo = bisect.bisect_left(lst, start_time)
                hi = bisect.bisect_right(lst, end_time)
                results.append(hi - lo)
    return results

def count_unique_xor_triplets(nums: list[int]) -> int:
    LIMIT = 2048
    present = [0] * LIMIT
    for x in nums:
        if 0 <= x < LIMIT:
            present[x] = 1

    pair_xor = [0] * LIMIT
    for a in range(LIMIT):
        if present[a]:
            for b in range(LIMIT):
                if present[b]:
                    pair_xor[a ^ b] = 1

    result = [0] * LIMIT
    for v in range(LIMIT):
        if present[v]:
            result[v] = 1

    for p in range(LIMIT):
        if pair_xor[p]:
            for c in range(LIMIT):
                if present[c]:
                    result[p ^ c] = 1

    return sum(result)

def smallest_palindromic_permutation(s: str) -> str:
    freq = [0] * 256
    for ch in s:
        freq[ord(ch)] += 1
    left_half = ""
    middle = ""
    for code in range(256):
        count = freq[code]
        if count == 0:
            continue
        half = count >> 1
        if half > 0:
            left_half += chr(code) * half
        if count & 1:
            middle = chr(code)
    right_half = left_half[::-1]
    return left_half + middle + right_half

