INF = 2000000000000000000
_comb_table = []

def _build_comb(n: int) -> None:
    global _comb_table
    _comb_table = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        _comb_table[i][0] = _comb_table[i][i] = 1
        for j in range(1, i):
            v = _comb_table[i - 1][j - 1] + _comb_table[i - 1][j]
            _comb_table[i][j] = v if v < INF else INF

def _count_perms(cnt, total):
    res = 1
    remaining = total
    for c in cnt:
        if c == 0:
            continue
        ways = _comb_table[remaining][c]
        if res > INF // ways:
            return INF
        res *= ways
        if res >= INF:
            return INF
        remaining -= c
    return res

def smallest_palindromic_rearrangement_ii(s: str, k: int) -> str:
    if k <= 0:
        return ""
    freq = [0] * 26
    for ch in s:
        freq[ord(ch) - 97] += 1

    middle = []
    half_cnt = [0] * 26
    for i in range(26):
        if freq[i] % 2 == 1:
            middle.append(chr(97 + i))
        half_cnt[i] = freq[i] // 2

    half_len = sum(half_cnt)
    _build_comb(half_len)

    total_perms = _count_perms(half_cnt, half_len)
    if k > total_perms:
        return ""

    left = []
    for pos in range(half_len):
        for i in range(26):
            if half_cnt[i] == 0:
                continue
            half_cnt[i] -= 1
            cnt_perm = _count_perms(half_cnt, half_len - pos - 1)
            if k > cnt_perm:
                k -= cnt_perm
                half_cnt[i] += 1
            else:
                left.append(chr(97 + i))
                break

    right = list(reversed(left))
    return "".join(left) + "".join(middle) + "".join(right)

