MOD = 1000000007

def decimal_to_base(s: str, b: int):
    if s == "0":
        return [0]
    cur = s
    rev = []
    while not (len(cur) == 1 and cur[0] == '0'):
        next_chars = []
        carry = 0
        for ch in cur:
            num = carry * 10 + (ord(ch) - 48)
            q = num // b
            carry = num % b
            if next_chars or q != 0:
                next_chars.append(chr(48 + q))
        rev.append(carry)
        cur = ''.join(next_chars) if next_chars else "0"
    rev.reverse()
    return rev

def decrement_string(s: str):
    res = list(s)
    i = len(res) - 1
    while i >= 0 and res[i] == '0':
        res[i] = '9'
        i -= 1
    if i >= 0:
        res[i] = chr(ord(res[i]) - 1)
    pos = 0
    while pos < len(res) and res[pos] == '0':
        pos += 1
    if pos == len(res):
        return "0"
    return ''.join(res[pos:])

def count_up_to(digits, b: int):
    n = len(digits)
    memo = [[[-1 for _ in range(2)] for _ in range(b)] for _ in range(n)]
    import sys
    sys.setrecursionlimit(10000)
    def dfs(idx: int, prev: int, tight: bool, started: bool):
        if idx == n:
            return 1
        if not tight and memo[idx][prev][started] != -1:
            return memo[idx][prev][started]
        limit = digits[idx] if tight else b - 1
        res = 0
        for d in range(limit + 1):
            nstarted = started or d != 0
            ntight = tight and (d == limit)
            if not nstarted:
                res += dfs(idx + 1, 0, ntight, False)
            else:
                if not started:
                    res += dfs(idx + 1, d, ntight, True)
                else:
                    if d >= prev:
                        res += dfs(idx + 1, d, ntight, True)
            if res >= MOD:
                res -= MOD
        if not tight:
            memo[idx][prev][started] = res % MOD
        return res % MOD
    return dfs(0, 0, True, False) % MOD

def solve():
    import sys
    data = sys.stdin.read().split()
    if not data:
        return
    l, r, b_str = data[0], data[1], data[2]
    b = int(b_str)
    r_digits = decimal_to_base(r, b)
    cnt_r = count_up_to(r_digits, b)
    cnt_l_minus = 0
    if l != "0":
        l_minus = decrement_string(l)
        l_digits = decimal_to_base(l_minus, b)
        cnt_l_minus = count_up_to(l_digits, b)
    ans = (cnt_r - cnt_l_minus) % MOD
    sys.stdout.write(str(ans))

if __name__ == "__main__":
    solve()

from typing import List

def count_cells(grid: List[List[str]], pattern: str) -> int:
    m = len(grid)
    if m == 0:
        return 0
    n = len(grid[0])
    M = m * n
    L = len(pattern)
    if L > M or L == 0:
        return 0

    # Build row-major string
    row_str = []
    for i in range(m):
        row_str.extend(grid[i])
    row_str = ''.join(row_str)

    # Build column-major string
    col_str = []
    for j in range(n):
        for i in range(m):
            col_str.append(grid[i][j])
    col_str = ''.join(col_str)

    # KMP prefix function (lps)
    lps = [0] * L
    i = 1
    length = 0
    while i < L:
        if pattern[i] == pattern[length]:
            length += 1
            lps[i] = length
            i += 1
        elif length:
            length = lps[length - 1]
        else:
            lps[i] = 0
            i += 1

    def get_starts(text: str) -> List[int]:
        starts: List[int] = []
        N = len(text)
        i = 0
        j = 0
        while i < N:
            if text[i] == pattern[j]:
                i += 1
                j += 1
                if j == L:
                    starts.append(i - L)
                    j = lps[j - 1]
            elif j:
                j = lps[j - 1]
            else:
                i += 1
        return starts

    hor_diff = [0] * (M + 1)
    ver_diff = [0] * (M + 1)

    for start in get_starts(row_str):
        hor_diff[start] += 1
        if start + L <= M:
            hor_diff[start + L] -= 1

    for start in get_starts(col_str):
        ver_diff[start] += 1
        if start + L <= M:
            ver_diff[start + L] -= 1

    hor_cover = [0] * M
    ver_cover = [0] * M

    cur = 0
    for i in range(M):
        cur += hor_diff[i]
        hor_cover[i] = 1 if cur > 0 else 0

    cur = 0
    for i in range(M):
        cur += ver_diff[i]
        ver_cover[i] = 1 if cur > 0 else 0

    answer = 0
    for i in range(m):
        for j in range(n):
            idx_row = i * n + j
            idx_col = j * m + i
            if hor_cover[idx_row] and ver_cover[idx_col]:
                answer += 1

    return answer

