def find_x_value(nums: List[int], k: int) -> List[int]:
    result = [0] * k
    dp = [0] * k

    for v in nums:
        new_dp = [0] * k
        single_rem = v % k
        new_dp[single_rem] += 1

        for r in range(k):
            cnt = dp[r]
            if cnt == 0:
                continue
            new_rem = (r * v) % k
            new_dp[new_rem] += cnt

        for r in range(k):
            if new_dp[r] != 0:
                result[r] += new_dp[r]

        dp = new_dp

    return result

def path_existence_queries(n, nums, max_diff, queries):
    parent = list(range(n))
    rank = [0] * n

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union_sets(a, b):
        ra = find(a)
        rb = find(b)
        if ra == rb:
            return
        if rank[ra] < rank[rb]:
            parent[ra] = rb
        elif rank[ra] > rank[rb]:
            parent[rb] = ra
        else:
            parent[rb] = ra
            rank[ra] += 1

    for i in range(1, n):
        if nums[i] - nums[i - 1] <= max_diff:
            union_sets(i, i - 1)

    answer = []
    for u, v in queries:
        answer.append(find(u) == find(v))
    return answer

