def base_unit_conversion(conversions: List[List[int]]) -> List[int]:
    MOD = 1_000_000_007
    if not conversions:
        return []
    # determine number of units
    max_idx = 0
    for src, tgt, _ in conversions:
        if src > max_idx:
            max_idx = src
        if tgt > max_idx:
            max_idx = tgt
    n = max_idx + 1

    adj: List[List[tuple[int, int]]] = [[] for _ in range(n)]
    for src, tgt, factor in conversions:
        adj[src].append((tgt, factor))

    result: List[int] = [0] * n
    result[0] = 1
    stack: List[int] = [0]
    while stack:
        u = stack.pop()
        for v, factor in adj[u]:
            result[v] = (result[u] * factor) % MOD
            stack.append(v)
    return result

