def max_profit(n: int, edges: List[Tuple[int, int]], score: List[int]) -> int:
    pre_mask = [0] * n
    for u, v in edges:
        pre_mask[v] |= 1 << u

    total_mask = (1 << n) - 1
    NEG_INF = -10**30
    dp = [NEG_INF] * (1 << n)
    dp[0] = 0

    for mask in range(total_mask + 1):
        placed = dp[mask]
        if placed == NEG_INF:
            continue
        pos = mask.bit_count() + 1
        for v in range(n):
            if mask & (1 << v):
                continue
            if pre_mask[v] & ~mask:
                continue
            next_mask = mask | (1 << v)
            profit = placed + score[v] * pos
            if profit > dp[next_mask]:
                dp[next_mask] = profit

    return dp[total_mask]

