_MX = 30
_MOD = 10**9 + 7
_f = [1] + [0] * _MX
_g = [1] + [0] * _MX
for _i in range(1, _MX + 1):
    _f[_i] = _f[_i - 1] * _i % _MOD
    _g[_i] = pow(_f[_i], _MOD - 2, _MOD)

def _comb(m: int, n: int) -> int:
    return _f[m] * _g[n] * _g[m - n] % _MOD

class Solution:
    def magicalSum(self, m: int, k: int, nums: list[int]) -> int:
        @cache
        def dfs(i: int, j: int, k: int, st: int) -> int:
            if k < 0 or (i == len(nums) and j > 0):
                return 0
            if i == len(nums):
                while st:
                    k -= st & 1
                    st >>= 1
                return int(k == 0)
            res = 0
            for t in range(j + 1):
                nt = t + st
                p = pow(nums[i], t, _MOD)
                nk = k - (nt & 1)
                res += _comb(j, t) * p * dfs(i + 1, j - t, nk, nt >> 1)
                res %= _MOD
            return res

        ans = dfs(0, m, k, 0)
        dfs.cache_clear()
        return ans

def most_frequent_vowel_consonant(s: str) -> int:
    vowel_set = {'a', 'e', 'i', 'o', 'u'}
    freq = [0] * 26
    for ch in s:
        idx = ord(ch) - ord('a')
        if 0 <= idx < 26:
            freq[idx] += 1
    max_vowel = 0
    max_consonant = 0
    for i in range(26):
        count = freq[i]
        ch = chr(ord('a') + i)
        if ch in vowel_set:
            if count > max_vowel:
                max_vowel = count
        else:
            if count > max_consonant:
                max_consonant = count
    return max_vowel + max_consonant

