def max_weighted_k_edge_path(n: int, edges: List[List[int]], k: int, t: int) -> int:
    """
    Returns the maximum total weight of a path that uses exactly `k` edges,
    where the total weight must be strictly less than `t`. If no such path
    exists, returns -1.
    """
    # dp[i][v] = maximum weight to reach vertex v using exactly i edges
    dp: List[List[int]] = [[-1] * n for _ in range(k + 1)]
    for v in range(n):
        dp[0][v] = 0

    for i in range(1, k + 1):
        for u, v, w in edges:
            prev = dp[i - 1][u]
            if prev != -1:
                cand = prev + w
                if cand < t and cand > dp[i][v]:
                    dp[i][v] = cand

    ans = -1
    for v in range(n):
        if dp[k][v] > ans:
            ans = dp[k][v]
    return ans

