def can_partition_grid(grid: List[List[int]]) -> bool:
    """
    Returns True if the grid can be split by a single horizontal, vertical,
    or diagonal (chessboard parity) cut into two connected parts with equal sum.
    """
    if not grid or not grid[0]:
        return False

    m, n = len(grid), len(grid[0])

    total = sum(sum(row) for row in grid)
    if total % 2 != 0:
        return False
    half = total // 2

    # Horizontal cuts
    prefix = 0
    for i in range(m - 1):
        prefix += sum(grid[i])
        if prefix == half:
            return True

    # Vertical cuts
    col_sums = [0] * n
    for row in grid:
        for j, val in enumerate(row):
            col_sums[j] += val
    prefix = 0
    for j in range(n - 1):
        prefix += col_sums[j]
        if prefix == half:
            return True

    # Diagonal (chessboard parity) cut
    parity_sum = 0
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if (i + j) % 2 == 0:
                parity_sum += val
    if parity_sum == half:
        return True

    return False

