def min_swaps(nums: list[int]) -> int:
    def digit_sum(n: int) -> int:
        s = 0
        while n > 0:
            s += n % 10
            n //= 10
        return s

    with_keys = [
        {"value": v, "digitSum": digit_sum(v), "originalIdx": i}
        for i, v in enumerate(nums)
    ]

    with_keys.sort(key=lambda obj: (obj["digitSum"], obj["value"]))

    target_pos = {}
    for idx, obj in enumerate(with_keys):
        target_pos[obj["value"]] = idx

    visited = [False] * len(nums)
    swaps = 0

    for i in range(len(nums)):
        if visited[i]:
            continue
        cycle_len = 0
        j = i
        while not visited[j]:
            visited[j] = True
            next_value = nums[j]
            j = target_pos[next_value]
            cycle_len += 1
        if cycle_len > 1:
            swaps += cycle_len - 1

    return swaps

def resulting_string(s: str) -> str:
    """
    Returns the string after repeatedly removing any two adjacent characters
    that are consecutive in the circular alphabet.
    """
    def consecutive(a: str, b: str) -> bool:
        # Direct neighbours or the wrap‑around a‑z
        return abs(ord(a) - ord(b)) == 1 or (a == 'a' and b == 'z') or (a == 'z' and b == 'a')

    stack: list[str] = []
    for ch in s:
        if stack and consecutive(stack[-1], ch):
            stack.pop()
        else:
            stack.append(ch)
    return ''.join(stack)

