def min_moves(matrix: List[str]) -> int:
    if not matrix:
        return -1
    m, n = len(matrix), len(matrix[0])
    # Collect portal positions
    portals = defaultdict(list)  # letter -> list of (i, j)
    for i, row in enumerate(matrix):
        for j, ch in enumerate(row):
            if 'A' <= ch <= 'Z':
                portals[ch].append((i, j))
    visited = [[False] * n for _ in range(m)]
    used_portal = set()
    dq = deque()
    dq.append((0, 0, 0))  # i, j, distance
    visited[0][0] = True

    while dq:
        i, j, d = dq.popleft()
        if i == m - 1 and j == n - 1:
            return d

        ch = matrix[i][j]
        if 'A' <= ch <= 'Z' and ch not in used_portal:
            for x, y in portals[ch]:
                if not visited[x][y]:
                    visited[x][y] = True
                    dq.appendleft((x, y, d))
            used_portal.add(ch)

        for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ni, nj = i + di, j + dj
            if 0 <= ni < m and 0 <= nj < n and not visited[ni][nj]:
                if matrix[ni][nj] != '#':
                    visited[ni][nj] = True
                    dq.append((ni, nj, d + 1))

    return -1

