def number_of_ways(edges: List[List[int]]) -> int:
    n = len(edges) + 1
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    max_depth = 0
    stack = [(1, 0, 0)]  # node, parent, depth
    while stack:
        node, parent, depth = stack.pop()
        if depth > max_depth:
            max_depth = depth
        for nei in adj[node]:
            if nei != parent:
                stack.append((nei, node, depth + 1))

    if max_depth == 0:
        return 0
    return pow(2, max_depth - 1, MOD)

