def smallest_string_after_removals(s: str) -> str:
    n = len(s)
    if n == 0:
        return ""
    def is_consecutive(a: str, b: str) -> bool:
        diff = abs(ord(a) - ord(b))
        return diff == 1 or diff == 25
    can = [[False] * n for _ in range(n)]
    for length in range(2, n + 1):
        for i in range(0, n - length + 1):
            j = i + length - 1
            for k in range(i + 1, j + 1):
                if (
                    is_consecutive(s[i], s[k])
                    and (i + 1 > k - 1 or can[i + 1][k - 1])
                    and (k + 1 > j or can[k + 1][j])
                ):
                    can[i][j] = True
                    break
    best = [[""] * n for _ in range(n)]
    for i in range(n):
        best[i][i] = s[i]
    for length in range(2, n + 1):
        for i in range(0, n - length + 1):
            j = i + length - 1
            if can[i][j]:
                best[i][j] = ""
                continue
            cur = s[i:j + 1]
            for m in range(i, j):
                cand = best[i][m] + best[m + 1][j]
                if cand < cur:
                    cur = cand
            best[i][j] = cur
    return best[0][n - 1]

