def can_partition(nums: List[int], target: int) -> bool:
    n = len(nums)
    # total product must be target squared
    total = 1
    for v in nums:
        total *= v
    if total != target * target:
        return False

    # sort descending to prune faster
    nums.sort(reverse=True)

    def dfs(idx: int, prod: int, cnt: int) -> bool:
        if prod == target:
            # non‑empty proper subset
            return 0 < cnt < n
        if prod > target or idx == n:
            return False
        # choose current element
        if dfs(idx + 1, prod * nums[idx], cnt + 1):
            return True
        # skip current element
        if dfs(idx + 1, prod, cnt):
            return True
        return False

    return dfs(0, 1, 0)

