from typing import List

def minimumMoves(classroom: List[str], energy: int) -> int:
    m = len(classroom)
    n = len(classroom[0])
    start = None
    litter_positions = []
    for i in range(m):
        for j in range(n):
            ch = classroom[i][j]
            if ch == 'S':
                start = (i, j)
            elif ch == 'L':
                litter_positions.append((i, j))
    if start is None:
        return -1

    litter_index = {pos: idx for idx, pos in enumerate(litter_positions)}
    total_litter = len(litter_positions)
    all_mask = (1 << total_litter) - 1

    # initial mask (in case start is on a litter, though spec says S is unique)
    init_mask = 0
    if classroom[start[0]][start[1]] == 'L':
        init_mask |= 1 << litter_index[start]

    # BFS state: (row, col, remaining_energy, mask)
    dq = collections.deque()
    dq.append((start[0], start[1], energy, init_mask, 0))
    visited = set()
    visited.add((start[0], start[1], energy, init_mask))

    dirs = [(1,0), (-1,0), (0,1), (0,-1)]

    while dq:
        r, c, cur_e, mask, dist = dq.popleft()
        if mask == all_mask:
            return dist
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if not (0 <= nr < m and 0 <= nc < n):
                continue
            cell = classroom[nr][nc]
            if cell == 'X':
                continue
            if cur_e == 0:
                # cannot move unless we are on a reset cell, but we would have reset earlier
                continue
            new_e = cur_e - 1
            new_mask = mask
            if cell == 'L':
                new_mask |= 1 << litter_index[(nr, nc)]
            if cell == 'R':
                new_e = energy  # reset
            state = (nr, nc, new_e, new_mask)
            if state not in visited:
                visited.add(state)
                dq.append((nr, nc, new_e, new_mask, dist + 1))
    return -1

