def maximum_good_subtree_score(vals: List[int], par: List[int]) -> int:
    n = len(vals)
    MOD = 1000000007
    children = [[] for _ in range(n)]
    for i in range(1, n):
        children[par[i]].append(i)

    node_mask = [0] * n
    for i in range(n):
        v = vals[i]
        mask = 0
        ok = True
        while v > 0:
            d = v % 10
            if mask & (1 << d):
                ok = False
                break
            mask |= 1 << d
            v //= 10
        node_mask[i] = mask if ok else -1

    max_score = [0] * n

    def dfs(u: int) -> List[int]:
        dp = [-float('inf')] * 1024
        dp[0] = 0
        for v in children[u]:
            child_dp = dfs(v)
            new_dp = [-float('inf')] * 1024
            for m1 in range(1024):
                if dp[m1] == -float('inf'):
                    continue
                for m2 in range(1024):
                    if child_dp[m2] == -float('inf'):
                        continue
                    if (m1 & m2) != 0:
                        continue
                    nm = m1 | m2
                    val = dp[m1] + child_dp[m2]
                    if val > new_dp[nm]:
                        new_dp[nm] = val
            for m in range(1024):
                if new_dp[m] > dp[m]:
                    dp[m] = new_dp[m]

        mask = node_mask[u]
        if mask != -1:
            for m in range(1024):
                if dp[m] == -float('inf'):
                    continue
                if (m & mask) != 0:
                    continue
                nm = m | mask
                val = dp[m] + vals[u]
                if val > dp[nm]:
                    dp[nm] = val

        best = 0
        for m in range(1024):
            if dp[m] > best:
                best = dp[m]
        max_score[u] = best
        return dp

    dfs(0)

    total = 0
    for i in range(n):
        total = (total + max_score[i]) % MOD
    return total

