def max_profit(prices: List[int], k: int) -> int:
    n = len(prices)
    if n == 0 or k == 0:
        return 0

    # dp[t][state] where state: 0 = no position, 1 = holding long, 2 = holding short
    neg_inf = -10**18
    dp = [[neg_inf, neg_inf, neg_inf] for _ in range(k + 1)]
    dp[0][0] = 0  # zero profit with zero transactions and no holdings

    for price in prices:
        # copy current dp to start new day (do nothing)
        new_dp = [row[:] for row in dp]

        for t in range(k + 1):
            # open a long position (buy) without increasing transaction count
            if dp[t][0] != neg_inf:
                new_dp[t][1] = max(new_dp[t][1], dp[t][0] - price)

            # open a short position (sell) without increasing transaction count
            if dp[t][0] != neg_inf:
                new_dp[t][2] = max(new_dp[t][2], dp[t][0] + price)

            # close a long position (sell) -> completes a transaction
            if t + 1 <= k and dp[t][1] != neg_inf:
                new_dp[t + 1][0] = max(new_dp[t + 1][0], dp[t][1] + price)

            # close a short position (buy to cover) -> completes a transaction
            if t + 1 <= k and dp[t][2] != neg_inf:
                new_dp[t + 1][0] = max(new_dp[t + 1][0], dp[t][2] - price)

        dp = new_dp

    # answer is the best profit with no holding after up to k transactions
    return max(dp[t][0] for t in range(k + 1))

