def weighted_median_node(n: int, edges: List[Tuple[int, int, int]], queries: List[Tuple[int, int]]) -> List[int]:
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))
        adj[v].append((u, w))

    LOG = math.ceil(math.log2(n)) + 1
    parent = [[-1] * n for _ in range(LOG)]
    upDist = [[0] * n for _ in range(LOG)]
    depth = [0] * n
    dist = [0] * n

    stack = [0]
    visited = [False] * n
    visited[0] = True
    while stack:
        node = stack.pop()
        for nei, w in adj[node]:
            if not visited[nei]:
                visited[nei] = True
                parent[0][nei] = node
                upDist[0][nei] = w
                depth[nei] = depth[node] + 1
                dist[nei] = dist[node] + w
                stack.append(nei)

    for k in range(1, LOG):
        for v in range(n):
            mid = parent[k - 1][v]
            if mid != -1:
                parent[k][v] = parent[k - 1][mid]
                upDist[k][v] = upDist[k - 1][v] + upDist[k - 1][mid]

    def lca(a: int, b: int) -> int:
        if depth[a] < depth[b]:
            a, b = b, a
        diff = depth[a] - depth[b]
        for k in range(LOG - 1, -1, -1):
            if (diff >> k) & 1:
                a = parent[k][a]
        if a == b:
            return a
        for k in range(LOG - 1, -1, -1):
            if parent[k][a] != -1 and parent[k][a] != parent[k][b]:
                a = parent[k][a]
                b = parent[k][b]
        return parent[0][a]

    def climb_exact(node: int, need: int) -> int:
        for k in range(LOG - 1, -1, -1):
            if parent[k][node] != -1 and upDist[k][node] <= need:
                need -= upDist[k][node]
                node = parent[k][node]
        return node

    ans = []
    for u, v in queries:
        w = lca(u, v)
        total = dist[u] + dist[v] - 2 * dist[w]
        target = (total + 1) // 2
        du = dist[u] - dist[w]
        if target <= du:
            cur = u
            need = target
            for k in range(LOG - 1, -1, -1):
                if parent[k][cur] != -1 and upDist[k][cur] < need:
                    need -= upDist[k][cur]
                    cur = parent[k][cur]
            ans.append(parent[0][cur])
        else:
            up_needed = total - target
            node = climb_exact(v, up_needed)
            ans.append(node)
    return ans

