def min_swaps(nums: List[int]) -> int:
    n = len(nums)
    even_pos = []
    odd_pos = []
    for i in range(n):
        if nums[i] % 2 == 0:
            even_pos.append(i)
        else:
            odd_pos.append(i)
    even_cnt = len(even_pos)
    odd_cnt = len(odd_pos)
    if abs(even_cnt - odd_cnt) > 1:
        return -1
    patterns = []
    if even_cnt >= odd_cnt:
        patterns.append('evenFirst')
    if odd_cnt >= even_cnt:
        patterns.append('oddFirst')
    answer = float('inf')
    for pat in patterns:
        target_even = []
        if pat == 'evenFirst':
            for i in range(0, n, 2):
                target_even.append(i)
        else:
            for i in range(1, n, 2):
                target_even.append(i)
        swaps = 0
        for i in range(even_cnt):
            swaps += abs(even_pos[i] - target_even[i])
        answer = min(answer, swaps)
    return int(answer)

