def max_triangle_area(points: List[List[int]]) -> int:
    n = len(points)
    if n < 3:
        return -1

    # Dictionaries to store min and max y for each x, and min and max x for each y
    x_min_y = {}
    x_max_y = {}
    y_min_x = {}
    y_max_x = {}

    # Global extremes
    global_min_x = float('inf')
    global_max_x = -float('inf')
    global_min_y = float('inf')
    global_max_y = -float('inf')

    for x, y in points:
        # Update global extremes
        if x < global_min_x:
            global_min_x = x
        if x > global_max_x:
            global_max_x = x
        if y < global_min_y:
            global_min_y = y
        if y > global_max_y:
            global_max_y = y

        # Update per‑x min/max y
        if x in x_min_y:
            if y < x_min_y[x]:
                x_min_y[x] = y
            if y > x_max_y[x]:
                x_max_y[x] = y
        else:
            x_min_y[x] = y
            x_max_y[x] = y

        # Update per‑y min/max x
        if y in y_min_x:
            if x < y_min_x[y]:
                y_min_x[y] = x
            if x > y_max_x[y]:
                y_max_x[y] = x
        else:
            y_min_x[y] = x
            y_max_x[y] = x

    ans = -1

    # Consider vertical sides (same x)
    for x, min_y in x_min_y.items():
        base = x_max_y[x] - min_y
        if base <= 0:
            continue
        height = max(x - global_min_x, global_max_x - x)
        if height <= 0:
            continue
        area2 = base * height
        if area2 > ans:
            ans = area2

    # Consider horizontal sides (same y)
    for y, min_x in y_min_x.items():
        base = y_max_x[y] - min_x
        if base <= 0:
            continue
        height = max(y - global_min_y, global_max_y - y)
        if height <= 0:
            continue
        area2 = base * height
        if area2 > ans:
            ans = area2

    return ans

