def _sieve(n):
    is_p = [True] * (n + 1)
    is_p[0] = is_p[1] = False
    for i in range(2, int(n**0.5) + 1):
        if is_p[i]:
            for j in range(i * i, n + 1, i):
                is_p[j] = False
    return is_p

_MAXV = 100000
_IS_PRIME = _sieve(_MAXV)

def countPrimeGapBalancedSubarrays(nums, k):
    n = len(nums)
    max_dq = deque()
    min_dq = deque()
    prime_positions = []
    left = 0
    ans = 0
    for right in range(n):
        if nums[right] <= _MAXV and _IS_PRIME[nums[right]]:
            while max_dq and nums[max_dq[-1]] <= nums[right]: max_dq.pop()
            max_dq.append(right)
            while min_dq and nums[min_dq[-1]] >= nums[right]: min_dq.pop()
            min_dq.append(right)
            prime_positions.append(right)
        while max_dq and min_dq and nums[max_dq[0]] - nums[min_dq[0]] > k:
            left += 1
            if max_dq[0] < left: max_dq.popleft()
            if min_dq[0] < left: min_dq.popleft()
        m = len(prime_positions)
        if m >= 2:
            second_last = prime_positions[m - 2]
            valid_starts = second_last - left + 1
            if valid_starts > 0:
                ans += valid_starts
    return ans

