def recover_denominations(numWays: List[int]) -> List[int]:
    n = len(numWays)
    dp = [0] * (n + 1)
    dp[0] = 1
    denominations = []
    for i in range(1, n + 1):
        cur = dp[i]
        target = numWays[i - 1]
        if target < cur:
            return []
        if target == cur:
            continue
        if target == cur + 1:
            denominations.append(i)
            for j in range(i, n + 1):
                dp[j] += dp[j - i]
        else:
            return []
    for i in range(1, n + 1):
        if dp[i] != numWays[i - 1]:
            return []
    return denominations

