def min_nodes_to_increase(n: int, edges: List[List[int]], cost: List[int]) -> int:
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    children = [[] for _ in range(n)]
    parent = [-1] * n
    order = []

    stack = [0]
    parent[0] = 0
    while stack:
        node = stack.pop()
        order.append(node)
        for nb in adj[node]:
            if nb == parent[node]:
                continue
            parent[nb] = node
            children[node].append(nb)
            stack.append(nb)

    max_sum = [0] * n
    touches = [0] * n

    for node in reversed(order):
        childs = children[node]
        if not childs:
            max_sum[node] = cost[node]
            touches[node] = 0
        else:
            max_child_sum = float('-inf')
            for ch in childs:
                if max_sum[ch] > max_child_sum:
                    max_child_sum = max_sum[ch]
            total = 0
            for ch in childs:
                total += touches[ch]
                if max_sum[ch] < max_child_sum:
                    total += 1
            max_sum[node] = cost[node] + max_child_sum
            touches[node] = total

    return touches[0]

