def max_stability(n: int, edges: List[List[int]], k: int) -> int:
    class DSU:
        __slots__ = ("parent", "size")
        def __init__(self, n: int):
            self.parent = list(range(n))
            self.size = [1] * n
        def find(self, x: int) -> int:
            while self.parent[x] != x:
                self.parent[x] = self.parent[self.parent[x]]
                x = self.parent[x]
            return x
        def union(self, a: int, b: int) -> bool:
            ra = self.find(a)
            rb = self.find(b)
            if ra == rb:
                return False
            if self.size[ra] < self.size[rb]:
                ra, rb = rb, ra
            self.parent[rb] = ra
            self.size[ra] += self.size[rb]
            return True

    max_possible = max(2 * s for _, _, s, _ in edges)

    def feasible(x: int) -> bool:
        dsu = DSU(n)
        used = 0
        upgrades = 0

        # process mandatory edges (must == 1)
        for u, v, s, must in edges:
            if must == 1:
                if s < x:          # cannot upgrade mandatory edges
                    return False
                if not dsu.union(u, v):
                    return False   # cycle among mandatory edges
                used += 1

        # optional edges without upgrade
        for u, v, s, must in edges:
            if must == 0 and s >= x:
                if dsu.union(u, v):
                    used += 1
                    if used == n - 1:
                        return upgrades <= k

        # optional edges with upgrade
        for u, v, s, must in edges:
            if must == 0 and 2 * s >= x:
                if dsu.union(u, v):
                    used += 1
                    upgrades += 1
                    if upgrades > k:
                        return False
                    if used == n - 1:
                        return upgrades <= k

        return used == n - 1 and upgrades <= k

    lo, hi = 0, max_possible + 1
    while lo < hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            lo = mid + 1
        else:
            hi = mid
    return lo - 1

