def minimum_time(n: int, edges: List[List[int]]) -> int:
    if n == 0:
        return -1
    if n == 1:
        return 0

    adj = [[] for _ in range(n)]
    for u, v, start, end in edges:
        adj[u].append((v, start, end))

    INF = 10**18
    dist = [INF] * n
    dist[0] = 0
    heap = [(0, 0)]  # (arrival_time, node)

    while heap:
        cur_time, u = heapq.heappop(heap)
        if cur_time != dist[u]:
            continue
        if u == n - 1:
            return cur_time
        for v, start, end in adj[u]:
            if cur_time > end:
                continue
            depart = cur_time if cur_time >= start else start
            if depart > end:
                continue
            arrival = depart + 1
            if arrival < dist[v]:
                dist[v] = arrival
                heapq.heappush(heap, (arrival, v))

    return -1 if dist[n - 1] == INF else dist[n - 1]

