def minimum_stability_factor(nums: List[int], maxC: int) -> int:
    n = len(nums)
    if maxC >= n:
        return 0

    # Build sparse table for range GCD queries
    log = (n).bit_length()
    st = [[0] * n for _ in range(log)]
    st[0] = nums[:]
    for k in range(1, log):
        span = 1 << (k - 1)
        limit = n - (1 << k) + 1
        row = st[k]
        prev = st[k - 1]
        for i in range(limit):
            row[i] = math.gcd(prev[i], prev[i + span])

    def range_gcd(l: int, r: int) -> int:
        length = r - l + 1
        k = length.bit_length() - 1
        return math.gcd(st[k][l], st[k][r - (1 << k) + 1])

    def feasible(L: int) -> bool:
        # Need to hit every interval of length L+1 whose GCD >= 2
        needed = 0
        last_selected = -1
        window_len = L + 1
        for i in range(0, n - L):
            if range_gcd(i, i + L) >= 2:
                if i > last_selected:
                    needed += 1
                    if needed > maxC:
                        return False
                    last_selected = i + L
        return True

    low, high = 0, n
    while low < high:
        mid = (low + high) // 2
        if feasible(mid):
            high = mid
        else:
            low = mid + 1
    return low

