def min_moves_grid(sx: int, sy: int, tx: int, ty: int) -> int:
    if sx == tx and sy == ty:
        return 0
    queue = []
    visited = set()
    queue.append((sx, sy, 0))
    visited.add(f"{sx},{sy}")
    while queue:
        x, y, d = queue.pop(0)
        m = max(x, y)
        candidates = [(x + m, y), (x, y + m)]
        for nx, ny in candidates:
            if nx > tx or ny > ty:
                continue
            if nx == tx and ny == ty:
                return d + 1
            key = f"{nx},{ny}"
            if key not in visited:
                visited.add(key)
                queue.append((nx, ny, d + 1))
    return -1

