import bisect

def power_grid_maintenance(c: int, connections: List[Tuple[int, int]], queries: List[Tuple[int, int]]) -> List[int]:
    parent = list(range(c + 1))
    rank = [0] * (c + 1)

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a: int, b: int) -> None:
        ra, rb = find(a), find(b)
        if ra == rb:
            return
        if rank[ra] < rank[rb]:
            parent[ra] = rb
        elif rank[ra] > rank[rb]:
            parent[rb] = ra
        else:
            parent[rb] = ra
            rank[ra] += 1

    for u, v in connections:
        union(u, v)

    # group nodes by component
    comp_nodes: Dict[int, List[int]] = {}
    for i in range(1, c + 1):
        r = find(i)
        comp_nodes.setdefault(r, []).append(i)

    # successor DSU for each component
    succ_parent: Dict[int, List[int]] = {}
    for r, arr in comp_nodes.items():
        succ_parent[r] = list(range(len(arr) + 1))  # extra sentinel at len(arr)

    def succ_find(r: int, x: int) -> int:
        p = succ_parent[r]
        while p[x] != x:
            p[x] = p[p[x]]
            x = p[x]
        return x

    ans: List[int] = []
    for typ, x in queries:
        r = find(x)
        arr = comp_nodes[r]
        if typ == 2:  # take node offline
            idx = bisect.bisect_left(arr, x)
            # union idx with idx+1 in successor structure
            succ_parent[r][idx] = idx + 1
        else:  # query
            pos = bisect.bisect_left(arr, x)
            nxt = succ_find(r, pos)
            if nxt == len(arr):
                ans.append(-1)
            else:
                ans.append(arr[nxt])
    return ans
# TIME: O((c+q) α) SPACE: O(c)

