def process_string(s: str) -> str:
    out = []
    deleted = []
    for ch in s:
        if 'a' <= ch <= 'z':
            out.append(ch)
        elif ch == '#':
            if out:
                deleted.append(out.pop())
        elif ch == '%':
            if deleted:
                out.append(deleted.pop())
        elif ch == '*':
            deleted.clear()
    return ''.join(out)

