def get_kth_char(s: str, k: int) -> str:
    n = len(s)
    length = [0] * (n + 1)
    for i in range(1, n + 1):
        ch = s[i - 1]
        prev = length[i - 1]
        if 'a' <= ch <= 'z':
            length[i] = prev + 1
        elif ch == '*':
            length[i] = prev - 1 if prev > 0 else 0
        elif ch == '#':
            length[i] = prev * 2
        elif ch == '%':
            length[i] = prev
    if k >= length[n]:
        return '.'
    for i in range(n, 0, -1):
        ch = s[i - 1]
        prev = length[i - 1]
        if 'a' <= ch <= 'z':
            if k == prev:
                return ch
        elif ch == '*':
            pass
        elif ch == '#':
            if k >= prev:
                k = k - prev
        elif ch == '%':
            k = prev - 1 - k
    return '.'

