            return False
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        size[ra] += size[rb]
        return True

    edges.sort(key=lambda e: e[2])
    components = n
    answer = 0

    for u, v, w in edges:
        if union(u, v):
            answer = w
            components -= 1
            if components == k:
                break

    return answer

from typing import List, Set, Tuple

def longest_palindromic_path(n: int, edges: List[List[int]], label: str) -> int:
    adj: List[List[int]] = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    total_masks = 1 << n
    dp: List[Set[Tuple[int, int]]] = [set() for _ in range(total_masks)]

    # single node palindromes (center of odd length)
    for i in range(n):
        dp[1 << i].add((i, i))

    # two‑node palindromes (even length, adjacent nodes with same label)
    for u, v in edges:
        if label[u] == label[v]:
            m = (1 << u) | (1 << v)
            dp[m].add((u, v))
            dp[m].add((v, u))

    for mask in range(total_masks):
        if not dp[mask]:
            continue
        for left, right in dp[mask]:
            for nl in adj[left]:
                if mask >> nl & 1:
                    continue
                for nr in adj[right]:
                    if mask >> nr & 1:
                        continue
                    if nl == nr:
                        continue
                    if label[nl] != label[nr]:
                        continue
                    new_mask = mask | (1 << nl) | (1 << nr)
                    dp[new_mask].add((nl, nr))

    ans = 0
    for mask in range(total_masks):
        if dp[mask]:
            cnt = bin(mask).count("1")
            if cnt > ans:
                ans = cnt
    return ans

