def count_islands(grid: List[List[int]], k: int) -> int:
    rows = len(grid)
    if rows == 0:
        return 0
    cols = len(grid[0])
    visited = [[False] * cols for _ in range(rows)]
    island_count = 0
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] > 0 and not visited[r][c]:
                total = 0
                stack = [(r, c)]
                visited[r][c] = True

                while stack:
                    cr, cc = stack.pop()
                    total += grid[cr][cc]

                    for dr, dc in dirs:
                        nr = cr + dr
                        nc = cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] > 0 and not visited[nr][nc]:
                            visited[nr][nc] = True
                            stack.append((nr, nc))

                if total % k == 0:
                    island_count += 1

    return island_count

