def network_recovery_pathways(edges: List[List[int]], online: List[bool], k: int) -> int:
    n = len(online)
    adj: List[List[Tuple[int, int]]] = [[] for _ in range(n)]
    max_cost = 0
    for u, v, c in edges:
        adj[u].append((v, c))
        if c > max_cost:
            max_cost = c

    def feasible(b: int) -> bool:
        if not online[0] or not online[n - 1]:
            return False
        INF = 10 ** 19
        dist = [INF] * n
        dist[0] = 0
        heap = [(0, 0)]
        while heap:
            d, u = heapq.heappop(heap)
            if d != dist[u]:
                continue
            if d > k:
                continue
            if u == n - 1:
                return True
            for v, c in adj[u]:
                if c >= b and online[v]:
                    nd = d + c
                    if nd < dist[v]:
                        dist[v] = nd
                        heapq.heappush(heap, (nd, v))
        return dist[n - 1] <= k

    if not feasible(0):
        return -1

    low, high = 0, max_cost
    while low < high:
        mid = (low + high + 1) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid - 1
    return low
