def split_array_by_prime_indices(nums: list[int]) -> int:
    n = len(nums)
    is_prime = [False] * n
    if n > 2:
        prime_flag = [True] * n
        prime_flag[0] = prime_flag[1] = False
        i = 2
        while i * i < n:
            if prime_flag[i]:
                for j in range(i * i, n, i):
                    prime_flag[j] = False
            i += 1
        for i in range(2, n):
            if prime_flag[i]:
                is_prime[i] = True
    sum_prime = 0
    sum_non_prime = 0
    for i in range(n):
        if is_prime[i]:
            sum_prime += nums[i]
        else:
            sum_non_prime += nums[i]
    return abs(sum_prime - sum_non_prime)

def count_number_of_trapezoids(points):
    n = len(points)
    slope_map = {}  # slope_key -> {'total': int, 'point_deg': {idx: int}, 'line_map': {line_key: {...}}}
    mid_map = {}    # midpoint_key -> count

    def gcd(a, b):
        while b != 0:
            a, b = b, a % b
        return a

    for i in range(n):
        xi, yi = points[i]
        for j in range(i + 1, n):
            xj, yj = points[j]
            dx = xj - xi
            dy = yj - yi
            g = gcd(abs(dx), abs(dy))
            dx //= g
            dy //= g
            if dx < 0:
                dx = -dx
                dy = -dy
            elif dx == 0 and dy < 0:
                dy = -dy
            slope_key = (dy, dx)

            c = dy * xi - dx * yi
            line_key = (dy, dx, c)

            mid_key = (xi + xj, yi + yj)
            mid_map[mid_key] = mid_map.get(mid_key, 0) + 1

            slope_entry = slope_map.get(slope_key)
            if slope_entry is None:
                slope_entry = {
                    'total': 0,
                    'point_deg': {},
                    'line_map': {}
                }
                slope_map[slope_key] = slope_entry
            slope_entry['total'] += 1

            point_deg = slope_entry['point_deg']
            point_deg[i] = point_deg.get(i, 0) + 1
            point_deg[j] = point_deg.get(j, 0) + 1

            line_map = slope_entry['line_map']
            line_entry = line_map.get(line_key)
            if line_entry is None:
                line_entry = {
                    'count': 0,
                    'point_deg_line': {}
                }
                line_map[line_key] = line_entry
            line_entry['count'] += 1
            pd_line = line_entry['point_deg_line']
            pd_line[i] = pd_line.get(i, 0) + 1
            pd_line[j] = pd_line.get(j, 0) + 1

    trapezoid_pairs = 0
    for slope_entry in slope_map.values():
        m = slope_entry['total']
        total_pairs = m * (m - 1) // 2

        share_point = 0
        for deg in slope_entry['point_deg'].values():
            share_point += deg * (deg - 1) // 2

        same_line_pairs = 0
        same_line_share_point = 0
        for line_entry in slope_entry['line_map'].values():
            t = line_entry['count']
            same_line_pairs += t * (t - 1) // 2
            for deg_l in line_entry['point_deg_line'].values():
                same_line_share_point += deg_l * (deg_l - 1) // 2

        valid = total_pairs - share_point - same_line_pairs + same_line_share_point
        trapezoid_pairs += valid

    parallelogram_count = 0
    for cnt in mid_map.values():
        if cnt > 1:
            parallelogram_count += cnt * (cnt - 1) // 2

    result = trapezoid_pairs - parallelogram_count
    return result

