def is_trionic_array(nums: List[int]) -> bool:
    n = len(nums)
    if n < 3:
        return False

    # inc_prefix[i] is True if nums[0..i] is strictly increasing
    inc_prefix: List[bool] = [False] * n
    inc_prefix[0] = True
    for i in range(1, n):
        inc_prefix[i] = inc_prefix[i - 1] and nums[i - 1] < nums[i]

    # inc_suffix[i] is True if nums[i..n-1] is strictly increasing
    inc_suffix: List[bool] = [False] * n
    inc_suffix[-1] = True
    for i in range(n - 2, -1, -1):
        inc_suffix[i] = inc_suffix[i + 1] and nums[i] < nums[i + 1]

    # try every possible decreasing segment [i, j] with length at least 2
    for i in range(1, n - 2):
        if not inc_prefix[i - 1]:
            continue
        # expand decreasing segment
        for j in range(i + 1, n - 1):
            if nums[j - 1] <= nums[j]:
                break
            if inc_suffix[j + 1]:
                return True
    return False

