from typing import List, Dict

def threshold_majority_queries(nums: List[int], queries: List[List[int]]) -> List[int]:
    n = len(nums)

    # positions of each value
    pos: Dict[int, List[int]] = {}
    for i, v in enumerate(nums):
        pos.setdefault(v, []).append(i)

    # segment tree storing (candidate, vote)
    size = 1
    while size < n:
        size <<= 1
    tree = [(0, 0)] * (2 * size)

    def combine(a, b):
        if a[0] == b[0]:
            return (a[0], a[1] + b[1])
        if a[1] > b[1]:
            return (a[0], a[1] - b[1])
        else:
            return (b[0], b[1] - a[1])

    # build leaves
    for i in range(n):
        tree[size + i] = (nums[i], 1)
    for i in range(size - 1, 0, -1):
        tree[i] = combine(tree[i << 1], tree[i << 1 | 1])

    def query(l: int, r: int):
        l += size
        r += size + 1
        left_res = (0, 0)
        right_res = (0, 0)
        while l < r:
            if l & 1:
                left_res = combine(left_res, tree[l])
                l += 1
            if r & 1:
                r -= 1
                right_res = combine(tree[r], right_res)
            l >>= 1
            r >>= 1
        return combine(left_res, right_res)

    ans = []
    for l, r, threshold in queries:
        cand, _ = query(l, r)
        if cand not in pos:
            ans.append(-1)
            continue
        lst = pos[cand]
        cnt = bisect.bisect_right(lst, r) - bisect.bisect_left(lst, l)
        ans.append(cand if cnt >= threshold else -1)

    return ans

