def max_balanced_shipments(weight: List[int]) -> int:
    n = len(weight)
    i = 0
    shipments = 0
    while i < n:
        max_so_far = weight[i]
        j = i + 1
        while j < n:
            if weight[j] > max_so_far:
                max_so_far = weight[j]
            elif weight[j] < max_so_far:
