class Solution:
    EVEN_DIGITS = [2, 4, 6, 8]
    ODD_CHOICES = [None, 1, 3, 5, 7, 9]

    def _all_multisets(self):
        result = []
        for r in range(len(self.EVEN_DIGITS) + 1):
            for combo in combinations(self.EVEN_DIGITS, r):
                for odd in self.ODD_CHOICES:
                    digits = list(combo) + ([odd] if odd else [])
                    if not digits:
                        continue
                    counts = {d: d for d in digits}
                    result.append((sum(counts.values()), counts))
        return result

    def _half_multiset(self, counts):
        half, middle = {}, None
        for d, c in counts.items():
            if c % 2 == 1:
                middle = d
            half[d] = c // 2
        return half, middle

    def _min_arrangement(self, counts):
        half, middle = self._half_multiset(counts)
        half_digits = []
        for d in sorted(half):
            half_digits.extend([str(d)] * half[d])
        half_digits.sort()
        prefix = ''.join(half_digits)
        mid = str(middle) if middle is not None else ''
        return prefix + mid + prefix[::-1]

    def _best_greater_arrangement(self, counts, n_str):
        from itertools import permutations
        L = sum(counts.values())
        half, middle = self._half_multiset(counts)
        half_items = []
        for d in sorted(half):
            half_items.extend([str(d)] * half[d])
        best = None
        for perm in set(permutations(half_items)) if half_items else {()}:
            prefix = ''.join(perm)
            mid = str(middle) if middle is not None else ''
            full = prefix + mid + prefix[::-1]
            if len(full) != L:
                continue
            if full > n_str and (best is None or full < best):
                best = full
        return best

    def nextSpecialPalindrome(self, n: int) -> int:
        n_str = str(n)
        L0 = len(n_str)
        multisets = self._all_multisets()
        by_len = {}
        for l, counts in multisets:
            by_len.setdefault(l, []).append(counts)

        if L0 in by_len:
            best = None
            for counts in by_len[L0]:
                res = self._best_greater_arrangement(counts, n_str)
                if res is not None and (best is None or res < best):
                    best = res
            if best is not None:
                return int(best)

        for l in sorted(by_len):
            if l <= L0:
                continue
            best = None
            for counts in by_len[l]:
                arr = self._min_arrangement(counts)
                if best is None or arr < best:
                    best = arr
            return int(best)

