def can_partition_k_distinct(arr: List[int], k: int) -> bool:
    n = len(arr)
    if k <= 0 or n % k != 0:
        return False
    groups = n // k
    freq: dict[int, int] = {}
    for val in arr:
        freq[val] = freq.get(val, 0) + 1
    max_freq = 0
    for count in freq.values():
        if count > max_freq:
