def max_product(nums: List[int]) -> int:
    if len(nums) < 2:
        return 0
    max_val = 0
    freq = {}
    for x in nums:
        if x > max_val:
            max_val = x
        freq[x] = freq.get(x, 0) + 1
    bits = 0
    while (1 << bits) <= max_val:
        bits += 1
    if bits == 0:
        bits = 1
    size = 1 << bits
    best = [-1] * size
    for x in nums:
        if best[x] < x:
            best[x] = x
    for i in range(bits):
        bit = 1 << i
        for mask in range(size):
            if mask & bit:
                val = best[mask ^ bit]
                if val > best[mask]:
                    best[mask] = val
    ans = 0
    full_mask = size - 1
    for x in nums:
        complement = full_mask ^ x
        y = best[complement]
        if y == -1:
            continue
        if y == x and freq[x] < 2:
            continue
        prod = x * y
        if prod > ans:
            ans = prod
    return ans

from math import inf
def balanced_k_factor_decomposition(n, k):
    def get_divisors(x):
        divs = []
        i = 1
        while i * i <= x:
            if x % i == 0:
                divs.append(i)
                if i != x // i:
                    divs.append(x // i)
            i += 1
        return divs
    best = [None]
    path = [0] * k
    def dfs(i, x, mi, mx):
        if i == 0:
            d = max(mx, x) - min(mi, x)
            if best[0] is None or d < best[0][0]:
                path[i] = x
                best[0] = (d, path[:])
            return
        for y in get_divisors(x):
            path[i] = y
            dfs(i - 1, x // y, min(mi, y), max(mx, y))
    dfs(k - 1, n, inf, 0)
    return best[0][1]

from typing import List

def count_bowl_subarrays(arr: List[int]) -> int:
    n = len(arr)
    if n < 3:
        return 0

    next_greater = [-1] * n
    stack = []
    for i in range(n):
        while stack and arr[stack[-1]] < arr[i]:
            next_greater[stack.pop()] = i
        stack.append(i)

    prev_greater = [-1] * n
    stack = []
    for i in range(n - 1, -1, -1):
        while stack and arr[stack[-1]] < arr[i]:
            prev_greater[stack.pop()] = i
        stack.append(i)

    count = 0
    for l in range(n):
        r = next_greater[l]
        if r != -1 and r - l >= 2:
            count += 1
    for r in range(n):
        l = prev_greater[r]
        if l != -1 and r - l >= 2:
            count += 1
    return count

