def count_binary_palindromes(N: int) -> int:
    if N < 0:
        return 0
    if N == 0:
        return 1

    def build_palindrome(prefix: int, total_len: int) -> int:
        half_len = (total_len + 1) // 2
        bits = format(prefix, "b").zfill(half_len)
        if total_len % 2 == 0:
            rev = bits[::-1]
        else:
            rev = bits[:-1][::-1]
        return int(bits + rev, 2)

    total = 1  # count the palindrome 0
    bin_len = N.bit_length()

    for length in range(1, bin_len):
        half = (length + 1) // 2
        total += 1 << (half - 1)

    half_len = (bin_len + 1) // 2
    start = 1 << (half_len - 1)
    end = 1 << half_len
    for prefix in range(start, end):
        if build_palindrome(prefix, bin_len) <= N:
            total += 1

    return total
# TIME: O(sqrt(N)) SPACE: O(1)

from typing import List

def maximum_xor(arr: List[int]) -> int:
    MAX_BIT = 60
    basis = [0] * (MAX_BIT + 1)
    for num in arr:
        x = num
        for b in range(MAX_BIT, -1, -1):
            if ((x >> b) & 1) == 0:
                continue
            if basis[b] == 0:
                basis[b] = x
                break
            x ^= basis[b]
    result = 0
    for b in range(MAX_BIT, -1, -1):
        if (result ^ basis[b]) > result:
            result ^= basis[b]
    return result

from collections import defaultdict

class Solution:
    def minArrivalsToDiscard(self, arrivals: list[int], w: int, m: int) -> int:
        n = len(arrivals)
        kept = [False] * n
        cnt = defaultdict(int)
        discards = 0
        for i in range(n):
            x = arrivals[i]
            left = i - w
            if left >= 0 and kept[left]:
                cnt[arrivals[left]] -= 1
            if cnt[x] >= m:
                discards += 1
                kept[i] = False
            else:
                cnt[x] += 1
                kept[i] = True
        return discards

class Solution:
    def generateSchedule(self, n: int) -> list[list[int]]:
        if n <= 4:
            return []
        remaining = {}
        deg = [0]*n
        for a in range(n):
            for b in range(n):
                if a != b:
                    remaining[(a, b)] = True
                    deg[a] += 1
                    deg[b] += 1

        seq = []
        last = None
        total = n*(n-1)
        for _ in range(total):
            best, best_score = None, -1
            for (a, b), avail in remaining.items():
                if not avail:
                    continue
                if last is not None and (a in last or b in last):
                    continue
                score = deg[a] + deg[b]
                if score > best_score:
                    best_score, best = score, (a, b)
            if best is None:
                return []  # shouldn't happen for n >= 5, kept as a safety net
            a, b = best
            remaining[(a, b)] = False
            deg[a] -= 1
            deg[b] -= 1
            seq.append([a, b])
            last = (a, b)
        return seq

from collections import deque

def minSplitMerge(nums1, nums2):
    n = len(nums1)
    start = tuple(nums1)
    target = tuple(nums2)
    if start == target:
        return 0
    # n <= 6 (per constraints), so BFS over the full state space of array configurations is feasible
    visited = {start}
    q = deque([start])
    steps = 0
    while q:
        steps += 1
        for _ in range(len(q)):
            cur = q.popleft()
            for l in range(n):
                for r in range(l, n):
                    sub = cur[l:r + 1]
                    rest = cur[:l] + cur[r + 1:]
                    for pos in range(len(rest) + 1):
                        new_state = rest[:pos] + sub + rest[pos:]
                        if new_state == target:
                            return steps
                        if new_state not in visited:
                            visited.add(new_state)
                            q.append(new_state)
    return -1

