def majority_frequency_chars(s: str) -> str:
    if not s:
        return ""
    freq: Dict[str, int] = {}
    for ch in s:
        freq[ch] = freq.get(ch, 0) + 1

    freq_to_chars: Dict[int, List[str]] = {}
    for ch, cnt in freq.items():
        freq_to_chars.setdefault(cnt, []).append(ch)

    for cnt in sorted(freq_to_chars.keys(), reverse=True):
        chars = freq_to_chars[cnt]
        if len(chars) >= 2:
            return "".join(sorted(chars))

    max_cnt = max(freq_to_chars.keys())
    return "".join(sorted(freq_to_chars[max_cnt]))

