def max_alternating_sum(arr, swaps):
    n = len(arr)
    parent = list(range(n))
    rank = [0] * n

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra = find(a)
        rb = find(b)
        if ra == rb:
            return
        if rank[ra] < rank[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        if rank[ra] == rank[rb]:
            rank[ra] += 1

    for u, v in swaps:
        union(u, v)

    groups = {}
    for i in range(n):
        r = find(i)
        groups.setdefault(r, []).append(i)

    total = 0
    for idx_list in groups.values():
        values = [arr[i] for i in idx_list]
        values.sort(reverse=True)
        pos_cnt = sum(1 for i in idx_list if i % 2 == 0)
        pos_sum = 0
        neg_sum = 0
        for k, val in enumerate(values):
            if k < pos_cnt:
                pos_sum += val
            else:
                neg_sum += val
        total += pos_sum - neg_sum

    return total

def climbStairs(n, costs):
    INF = float('inf')
    f = [INF] * (n + 1)
    f[0] = 0
    for i in range(1, n + 1):
        x = costs[i - 1]
        for j in range(max(0, i - 3), i):
            f[i] = min(f[i], f[j] + x + (i - j) ** 2)
    return f[n]

class Solution:
    def maxTotalValue(self, nums: list[int], k: int) -> int:
        n = len(nums)
        values = []
        for l in range(n):
            mx = mn = nums[l]
            for r in range(l, n):
                mx = max(mx, nums[r])
                mn = min(mn, nums[r])
                values.append(mx - mn)
        values.sort(reverse=True)
        return sum(values[:k])

