def split_array(nums: List[int]) -> int:
    n = len(nums)
    if n < 2:
        return -1
    s = [0] * n
    s[0] = nums[0]
    f = [True] * n   # f[i]: nums[0..i] strictly increasing
    g = [True] * n   # g[i]: nums[i..n-1] strictly decreasing
    for i in range(1, n):
        s[i] = s[i - 1] + nums[i]
        f[i] = f[i - 1] and nums[i] > nums[i - 1]
    for i in range(n - 2, -1, -1):
        g[i] = g[i + 1] and nums[i] > nums[i + 1]
    ans = None
    for i in range(n - 1):
        if f[i] and g[i + 1]:
            left_sum = s[i]
            right_sum = s[n - 1] - s[i]
            diff = abs(left_sum - right_sum)
            if ans is None or diff < ans:
                ans = diff
    return -1 if ans is None else ans

def longest_subseq_non_zero_xor(arr: list[int]) -> int:
    n = len(arr)
    if n == 0:
        return 0
    total_xor = 0
    for i in range(n):
        total_xor ^= arr[i]
    if total_xor != 0:
        return n
    for i in range(n):
        if arr[i] != 0:
            return n - 1
    return 0

MOD = 10**9 + 7

class Solution:
    def zigZagArrays(self, n: int, l: int, r: int) -> int:
        d = r - l + 1
        if n == 1:
            return d % MOD
        if n == 2:
            return (d * (d - 1)) % MOD

        size = 2 * d
        # State (v, 0..d-1) = "last move was up, currently at value v" (value v mapped to 0-indexed).
        # State (d+v) = "last move was down, currently at value v".
        vec = [0] * size
        for v in range(d):
            vec[v] = v            # up-state at v: number of valid smaller starting values v0<v
            vec[d + v] = d - 1 - v  # down-state at v: number of valid larger starting values v0>v

        M = [[0] * size for _ in range(size)]
        for v0 in range(d):
            for v1 in range(v0):        # from up-state at v0, next must go down: v1 < v0
                M[d + v1][v0] += 1
            for v1 in range(v0 + 1, d): # from down-state at v0, next must go up: v1 > v0
                M[v1][d + v0] += 1

        def mat_mult(A, B):
            n_, k_, m_ = len(A), len(B), len(B[0])
            C = [[0] * m_ for _ in range(n_)]
            for i in range(n_):
                Ai = A[i]
                for t in range(k_):
                    a = Ai[t]
                    if a == 0:
                        continue
                    bt = B[t]
                    Ci = C[i]
                    for j in range(m_):
                        if bt[j]:
                            Ci[j] = (Ci[j] + a * bt[j]) % MOD
            return C

        def mat_vec(A, v):
            res = [0] * len(A)
            for i, Ai in enumerate(A):
                s = 0
                for j, x in enumerate(v):
                    if Ai[j] and x:
                        s += Ai[j] * x
                res[i] = s % MOD
            return res

        def mat_pow(A, p):
            n_ = len(A)
            R = [[1 if i == j else 0 for j in range(n_)] for i in range(n_)]
            while p:
                if p & 1:
                    R = mat_mult(R, A)
                A = mat_mult(A, A)
                p >>= 1
            return R

        Mp = mat_pow(M, n - 2)
        return sum(mat_vec(Mp, vec)) % MOD

def count_no_zero_pairs(n: int) -> int:
    def has_zero(x: int) -> bool:
        while x:
            if x % 10 == 0:
                return True
            x //= 10
        return False

    count = 0
    for a in range(1, n):
        b = n - a
        if not has_zero(a) and not has_zero(b):
            count += 1
    return count

import bisect
class ExamTracker:
    def __init__(self):
        self.times = []
        self.prefix = [0]
    def record(self, time, score):
        self.times.append(time)
        self.prefix.append(self.prefix[-1] + score)
    def totalScore(self, startTime, endTime):
        lo = bisect.bisect_left(self.times, startTime)
        hi = bisect.bisect_right(self.times, endTime)
        if lo >= hi:
            return 0
        return self.prefix[hi] - self.prefix[lo]

class Solution:
    def removeSubstring(self, s: str, k: int) -> str:
        stack = []
        for c in s:
            if stack and stack[-1][0] == c:
                stack[-1][1] += 1
            else:
                stack.append([c, 1])
            if c == ')' and len(stack) > 1:
                top = stack[-1]
                prev = stack[-2]
                if top[1] == k and prev[0] == '(' and prev[1] >= k:
                    stack.pop()
                    prev[1] -= k
                    if prev[1] == 0:
                        stack.pop()
        return ''.join(ch * cnt for ch, cnt in stack)

