def equal_score_substring(s: str) -> bool:
    total = sum(ord(ch) - ord('a') + 1 for ch in s)
    prefix = 0
    # split point must be between characters, both sides non‑empty
    for i in range(len(s) - 1):
        prefix += ord(s[i]) - ord('a') + 1
        if prefix * 2 == total:
            return True
    return False

def longest_fibonacci_subarray(arr: list[int]) -> int:
    n = len(arr)
    if n <= 2:
        return n
    max_len = 2
    cur_len = 2
    for i in range(2, n):
        if arr[i] == arr[i - 1] + arr[i - 2]:
            cur_len += 1
        else:
            cur_len = 2
        if cur_len > max_len:
            max_len = cur_len
    return max_len

