class Solution:
    def sumOfAncestors(self, n: int, edges: list[list[int]], nums: list[int]) -> int:
        def squarefree(num):
            i = 2
            while i * i <= num:
                while num % (i * i) == 0:
                    num //= (i * i)
                i += 1
            return num

        vals = [squarefree(x) for x in nums]
        graph = [[] for _ in range(n)]
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)

        ans = 0
        history = {}

        def dfs(u, p):
            nonlocal ans
            v = vals[u]
            ans += history.get(v, 0)
            history[v] = history.get(v, 0) + 1
            for w in graph[u]:
                if w != p:
                    dfs(w, u)
            history[v] -= 1

        dfs(0, -1)
        return ans

