def maximum_partition_factor(points: List[List[int]]) -> int:
    if len(points) < 2:
        return 0
    max_sum = -10**18
    min_sum = 10**18
    max_diff = -10**18
    min_diff = 10**18
    for x, y in points:
        s = x + y
        d = x - y
        if s > max_sum:
            max_sum = s
        if s < min_sum:
            min_sum = s
        if d > max_diff:
            max_diff = d
        if d < min_diff:
            min_diff = d
    return max(max_sum - min_sum, max_diff - min_diff)

