from collections import Counter

def smallest_permutation_greater(s: str, target: str) -> str:
    if len(s) != len(target):
        return ""
    n = len(s)
    counts = Counter(s)

    def build(pos: int, greater: bool) -> Optional[str]:
        if pos == n:
            return "" if greater else None
        if greater:
            # smallest suffix when we have already exceeded target
            return "".join(ch * counts[ch] for ch in sorted(counts))
        # need to match target at this position
        for ch in sorted(counts):
            if counts[ch] == 0 or ch < target[pos]:
                continue
            counts[ch] -= 1
            if ch > target[pos]:
                # we exceed here; fill the rest with smallest remaining chars
                suffix = "".join(c * counts[c] for c in sorted(counts))
                counts[ch] += 1
                return ch + suffix
            else:  # ch == target[pos]
                suffix = build(pos + 1, False)
                if suffix is not None:
                    counts[ch] += 1
                    return ch + suffix
            counts[ch] += 1
        return None

    result = build(0, False)
    return result if result is not None else ""

