def max_sum_squares(n: int, s: int) -> str:
    if s < 0 or s > 9 * n:
        return ""
    nine_count = s // 9
    remainder = s % 9
    parts = []
    parts.append('9' * nine_count)
    if remainder:
        parts.append(str(remainder))
    zeros = n - nine_count - (1 if remainder else 0)
    if zeros > 0:
        parts.append('0' * zeros)
    return ''.join(parts)

