MOD = 10**9 + 7

def count_ways(rows: List[List[int]]) -> int:
    """
    Returns the number of ways to choose exactly one integer from each row such that
    the greatest common divisor of all chosen integers is 1.
    """
    if not rows:
        return 0

    n = len(rows)
    max_val = 0
    for row in rows:
        if row:
            max_val = max(max_val, max(row))

    # mobius function up to max_val
    mu = [1] * (max_val + 1)
    primes: List[int] = []
    is_composite = [False] * (max_val + 1)
    for i in range(2, max_val + 1):
        if not is_composite[i]:
            primes.append(i)
            mu[i] = -1
        for p in primes:
            if i * p > max_val:
                break
            is_composite[i * p] = True
            if i % p == 0:
                mu[i * p] = 0
                break
            else:
                mu[i * p] = -mu[i]

    # counts[i][d] = how many numbers in row i are divisible by d
    counts: List[List[int]] = [[0] * (max_val + 1) for _ in range(n)]
    for i, row in enumerate(rows):
        for x in row:
            d = 1
            while d * d <= x:
                if x % d == 0:
                    counts[i][d] += 1
                    other = x // d
                    if other != d:
                        counts[i][other] += 1
                d += 1

    ans = 0
    for d in range(1, max_val + 1):
        if mu[d] == 0:
            continue
        prod = 1
        for i in range(n):
            cnt = counts[i][d]
            if cnt == 0:
                prod = 0
                break
            prod = (prod * cnt) % MOD
        ans = (ans + mu[d] * prod) % MOD

    return ans % MOD
# TIME: O(n * max_val * sqrt(max_val)) SPACE: O(n * max_val)

def remove_zeros(n: int) -> int:
    s = str(n)
    result = ''
    for i in range(len(s)):
