def longest_balanced_subarray(nums):
    n = len(nums)
    best = 0
    for i in range(n):
        evens = set()
        odds = set()
        for j in range(i, n):
            x = nums[j]
            if x % 2 == 0:
                evens.add(x)
            else:
                odds.add(x)
            if len(evens) == len(odds):
                length = j - i + 1
                if length > best:
                    best = length
    return best

def min_operations(nums1, nums2):
    n = len(nums1)
    base = sum(abs(nums1[i] - nums2[i]) for i in range(n))
    target = nums2[n]
    best_extra = None
    for i in range(n):
        lo, hi = min(nums1[i], nums2[i]), max(nums1[i], nums2[i])
        if target < lo:
            extra = lo - target
        elif target > hi:
            extra = target - hi
        else:
            extra = 0
        if best_extra is None or extra < best_extra:
            best_extra = extra
    return base + 1 + best_extra

from typing import List

def count_distinct_subarrays_divisible_by_k(arr: List[int], K: int) -> int:
    n = len(arr)
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + arr[i]
    seen = set()
    for start in range(n):
        for end in range(start, n):
            total = prefix[end + 1] - prefix[start]
            if total % K == 0:
                key = ','.join(map(str, arr[start:end + 1]))
                seen.add(key)
    return len(seen)

from typing import List

def find_missing_elements(arr: List[int]) -> List[int]:
    if not isinstance(arr, list) or len(arr) == 0:
        return []
    sorted_arr = sorted(arr)
    missing: List[int] = []
    for i in range(len(sorted_arr) - 1):
        current = sorted_arr[i]
        nxt = sorted_arr[i + 1]
        if nxt - current > 1:
            for val in range(current + 1, nxt):
                missing.append(val)
    return missing

def max_product_algo(nums):
    HI, LO = 100000, -100000
    n = len(nums)
    best = float('-inf')
    for i in range(n):
        for repl in (HI, LO):
            arr = nums[:]
            arr[i] = repl
            for x in range(n):
                for y in range(x+1, n):
                    for z in range(y+1, n):
                        best = max(best, arr[x]*arr[y]*arr[z])
    return best


