import sys

def smallest_palindromic_permutation_greater(s: str, t: str) -> str:
    n = len(s)
    if n != len(t):
        return ""
    # count characters
    cnt: Dict[str, int] = {}
    for ch in s:
        cnt[ch] = cnt.get(ch, 0) + 1
    # check palindrome feasibility
    odd = sum(v % 2 for v in cnt.values())
    if (n % 2 == 0 and odd != 0) or (n % 2 == 1 and odd != 1):
        return ""
    half_len = n // 2
    sorted_chars: List[str] = sorted(cnt.keys())
    left_chars: List[str] = []
    sys.setrecursionlimit(1_000_000)

    def dfs(pos: int, greater_flag: bool) -> bool:
        if pos == half_len:
            # build full palindrome and compare
            left = ''.join(left_chars)
            if n % 2 == 1:
                middle = ''
                for ch in sorted_chars:
                    if cnt.get(ch, 0) > 0:
                        middle = ch
                        break
                pal = left + middle + left[::-1]
            else:
                pal = left + left[::-1]
            return pal > t
        target_char = t[pos] if not greater_flag else None
        for ch in sorted_chars:
            if cnt.get(ch, 0) < 2:
                continue
            if not greater_flag:
                if ch < target_char:  # type: ignore
                    continue
                next_greater = ch > target_char  # type: ignore
            else:
                next_greater = True
            cnt[ch] -= 2
            left_chars.append(ch)
            if dfs(pos + 1, greater_flag or next_greater):
                return True
            left_chars.pop()
            cnt[ch] += 2
        return False

    if not dfs(0, False):
        return ""
    # construct result from the successful left_chars
    left = ''.join(left_chars)
    if n % 2 == 1:
        middle = ''
        for ch in sorted_chars:
            if cnt.get(ch, 0) > 0:
                middle = ch
                break
        return left + middle + left[::-1]
    else:
        return left + left[::-1]

# TIME: O(k * 26) SPACE: O(k) where k = n/2 (half length)

def count_subarrays(nums: list[int], x: int) -> int:
    n = len(nums)
    pref = [0] * (n + 1)
    for i in range(n):
        pref[i + 1] = pref[i] + (1 if nums[i] == x else -1)

    uniq = sorted(set(pref))
    comp = {v: i + 1 for i, v in enumerate(uniq)}

    bit = [0] * (len(uniq) + 2)

    def add(i: int, delta: int) -> None:
        while i < len(bit):
            bit[i] += delta
            i += i & -i

    def sum_(i: int) -> int:
        s = 0
        while i > 0:
            s += bit[i]
            i -= i & -i
        return s

    ans = 0
    add(comp[pref[0]], 1)
    for i in range(1, n + 1):
        idx = comp[pref[i]]
        ans += sum_(idx - 1)
        add(idx, 1)
    return ans

import math
class Solution:
    def minTime(self, d: list[int], r: list[int]) -> int:
        d1, d2 = d
        r1, r2 = r
        lcm = r1 * r2 // math.gcd(r1, r2)
        def feasible(T):
            a1 = T - T // r1
            a2 = T - T // r2
            atotal = T - T // lcm
            return a1 >= d1 and a2 >= d2 and atotal >= d1 + d2
        lo, hi = 1, 4_000_000_000
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

NEG = float('-inf')
def max_cyclic_partition_score(nums, k):
    n = len(nums)
    def linear(a):
        f = [[NEG] * 3 for _ in range(k + 1)]
        f[0][1] = 0
        for x in a:
            g = [row[:] for row in f]
            for c in range(k + 1):
                for bi in range(3):
                    cur = f[c][bi]
                    if cur == NEG:
                        continue
                    b = bi - 1
                    for sign in (1, -1):
                        nb = b + sign
                        if nb < -1 or nb > 1:
                            continue
                        nc = c + (1 if nb == 0 else 0)
                        if nc > k:
                            continue
                        val = cur + sign * x
                        if val > g[nc][nb + 1]:
                            g[nc][nb + 1] = val
            f = g
        return max(f[c][1] for c in range(k + 1))
    return max(linear(nums[r:] + nums[:r]) for r in range(n))

def longest_non_decreasing_after_one_replace(arr: list[int]) -> int:
    n = len(arr)
    if n <= 2:
        return n
    left = [0] * n
    right = [0] * n
    left[0] = 1
    for i in range(1, n):
        left[i] = left[i - 1] + 1 if arr[i] >= arr[i - 1] else 1
    right[n - 1] = 1
    for i in range(n - 2, -1, -1):
        right[i] = right[i + 1] + 1 if arr[i] <= arr[i + 1] else 1
    best = 1
    for i in range(n):
        best = max(best, left[i])
    for i in range(n):
        if i > 0:
            best = max(best, left[i - 1] + 1)
        if i < n - 1:
            best = max(best, right[i + 1] + 1)
        if i > 0 and i < n - 1 and arr[i - 1] <= arr[i + 1]:
            best = max(best, left[i - 1] + 1 + right[i + 1])
    return min(best, n)

