def max_path_score(grid: List[List[int]], k: int) -> int:
    rows = len(grid)
    cols = len(grid[0])
    # If the destination cell value exceeds the allowed limit, no valid path exists.
    if grid[rows - 1][cols - 1] > k:
        return -1

    dp = [0] * cols
    for i in range(rows):
        for j in range(cols):
            if i == 0 and j == 0:
                dp[j] = grid[0][0]
            elif i == 0:
                dp[j] = dp[j - 1] + grid[i][j]
            elif j == 0:
                dp[j] = dp[j] + grid[i][j]
            else:
                dp[j] = max(dp[j], dp[j - 1]) + grid[i][j]
    return dp[cols - 1]

