def solve(n, edges, good):
    weight = [1 if g else -1 for g in good]
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    down = [0]*n
    parent = [-1]*n

    def dfs_down(u, p):
        parent[u] = p
        total = weight[u]
        for v in adj[u]:
            if v == p:
                continue
            dfs_down(v, u)
            if down[v] > 0:
                total += down[v]
        down[u] = total
    dfs_down(0, -1)

    answer = [0]*n
    up = [0]*n

    def dfs_up(u):
        answer[u] = weight[u] + up[u]
        for v in adj[u]:
            if v == parent[u]:
                continue
            if down[v] > 0:
                answer[u] += down[v]

        children = [v for v in adj[u] if v != parent[u]]
        pos_children = [down[v] if down[v] > 0 else 0 for v in children]
        prefix = [0]
        for val in pos_children:
            prefix.append(prefix[-1] + val)
        suffix = [0]*(len(pos_children)+1)
        for i in range(len(pos_children)-1, -1, -1):
            suffix[i] = suffix[i+1] + pos_children[i]

        for idx, v in enumerate(children):
            others = up[u] + weight[u] + (prefix[idx] + suffix[idx+1])
            up[v] = others if others > 0 else 0
            dfs_up(v)
    dfs_up(0)
    return answer

def largestPrime(n):
    def is_prime(x):
        if x < 2:
            return False
        if x < 4:
            return True
        if x % 2 == 0:
            return False
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True

    best = 0
    total = 0
    p = 2
    while total <= n:
        if is_prime(p):
            total += p
            if total > n:
                break
            if is_prime(total):
                best = total
        p += 1
    return best

