def total_interaction_cost(n: int, edges: List[Tuple[int, int]], values: List[int]) -> int:
    from collections import defaultdict

    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    total_freq: Dict[int, int] = defaultdict(int)
    for val in values:
        total_freq[val] += 1

    total = 0

    def dfs(node: int, parent: int) -> Tuple[Dict[int, int], int]:
        nonlocal total
        freq = {values[node]: 1}
        size = 1
        for nb in adj[node]:
            if nb == parent:
                continue
            child_freq, child_size = dfs(nb, node)

            # count pairs with equal values crossing this edge
            equal = 0
            for v, cnt in child_freq.items():
                equal += cnt * (total_freq[v] - cnt)
            total += equal

            # merge child frequencies into current node's frequency map (small-to-large)
            if len(freq) < len(child_freq):
                freq, child_freq = child_freq, freq
            for v, cnt in child_freq.items():
                freq[v] = freq.get(v, 0) + cnt

            size += child_size
        return freq, size

    dfs(0, -1)
    return total

from functools import lru_cache

def numberOfBalancedIntegers(low, high):
    def count_le_length(x, length):
        # count balanced numbers with EXACTLY `length` digits that are <= x
        if x < 10 ** (length - 1):
            return 0
        x = min(x, 10 ** length - 1)
        digits = list(map(int, str(x)))
        if len(digits) != length:
            return 0

        @lru_cache(maxsize=None)
        def dfs(pos, diff, tight):
            if pos == length:
                return 1 if diff == 0 else 0
            lo = 0 if pos > 0 else 1  # no leading zero for a fixed-length representation
            hi = digits[pos] if tight else 9
            total = 0
            for d in range(lo, hi + 1):
                sign = 1 if pos % 2 == 0 else -1  # pos0->position1(odd)->+; pos1->position2(even)->-
                total += dfs(pos + 1, diff + sign * d, tight and d == hi)
            return total

        res = dfs(0, 0, True)
        dfs.cache_clear()
        return res

    def count_upto(n):
        if n < 10:
            return 0
        total = 0
        for length in range(2, len(str(n)) + 1):
            total += count_le_length(n, length)
        return total

    return count_upto(high) - count_upto(low - 1)

