def min_subarray_length(arr: List[int], K: int) -> int:
    left = 0
    distinct_sum = 0
    freq: dict[int, int] = {}
    best = float('inf')

    for right in range(len(arr)):
        val = arr[right]
        cnt = freq.get(val, 0)
        freq[val] = cnt + 1
        if cnt == 0:
            distinct_sum += val

        while distinct_sum >= K:
            best = min(best, right - left + 1)
            left_val = arr[left]
            left_cnt = freq[left_val]
            if left_cnt == 1:
                distinct_sum -= left_val
                del freq[left_val]
            else:
                freq[left_val] = left_cnt - 1
            left += 1

    return -1 if best == float("inf") else best

def maxValueOfSequence(n, restrictions, diff):
    INF = float('inf')
    a = [INF] * n
    a[0] = 0
    # apply hard caps from restrictions first
    for idx, maxVal in restrictions:
        a[idx] = min(a[idx], maxVal)
    # forward pass: propagate the diff constraint left-to-right (upper bound from the left)
    for i in range(1, n):
        a[i] = min(a[i], a[i - 1] + diff[i - 1])
    # backward pass: propagate the diff constraint right-to-left (upper bound from the right)
    for i in range(n - 2, -1, -1):
        a[i] = min(a[i], a[i + 1] + diff[i])
    return max(a)

