    def alternatingXOR(self, nums: list[int], target1: int, target2: int) -> int:
        MOD = 10**9 + 7
        cnt1 = {}
        cnt2 = {0: 1}
        pre = 0
        ans = 0
        for x in nums:
            pre ^= x
            a = cnt2.get(pre ^ target1, 0)
            b = cnt1.get(pre ^ target2, 0)
            ans = (a + b) % MOD
            cnt1[pre] = (cnt1.get(pre, 0) + a) % MOD
            cnt2[pre] = (cnt2.get(pre, 0) + b) % MOD
        return ans

