    best_coord = [-1, -1]
    sx, sy = start
    for x, y, h in towers:
        dist = abs(x - sx) + abs(y - sy)
        if dist <= max_steps:
            if h > best_height:
                best_height = h
                best_coord = [x, y]
            elif h == best_height:
