def rotate_non_negative(arr: List[int], k: int) -> List[int]:
    non_neg_indices: List[int] = []
    non_neg_values: List[int] = []
    for i, val in enumerate(arr):
        if val >= 0:
            non_neg_indices.append(i)
            non_neg_values.append(val)

    n = len(non_neg_values)
    if n <= 1:
        return arr

    shift = k % n
    rotated = non_neg_values[shift:] + non_neg_values[:shift]

    for idx, val in zip(non_neg_indices, rotated):
        arr[idx] = val

    return arr

