def longest_alternating_subarray(nums):
    n = len(nums)
    if n == 0:
        return 0
    l1 = [1] * n  # ends at i, last comparison was "up" (nums[i-1] < nums[i])
    l2 = [1] * n  # ends at i, last comparison was "down" (nums[i-1] > nums[i])
    r1 = [1] * n  # starts at i, next comparison is "up" (nums[i] < nums[i+1])
    r2 = [1] * n  # starts at i, next comparison is "down" (nums[i] > nums[i+1])
    ans = 1 if n > 0 else 0
    for i in range(1, n):
        if nums[i-1] < nums[i]:
            l1[i] = l2[i-1] + 1
        elif nums[i-1] > nums[i]:
            l2[i] = l1[i-1] + 1
        ans = max(ans, l1[i], l2[i])
    for i in range(n-2, -1, -1):
        if nums[i+1] > nums[i]:
            r1[i] = r2[i+1] + 1
        elif nums[i+1] < nums[i]:
            r2[i] = r1[i+1] + 1
    for i in range(1, n-1):
        if nums[i-1] < nums[i+1]:
            ans = max(ans, l2[i-1] + r2[i+1])
        elif nums[i-1] > nums[i+1]:
            ans = max(ans, l1[i-1] + r1[i+1])
    return ans

def house_robber_v(root):
    def dfs(node):
        if not node:
            return (0, 0)
        left_rob, left_skip = dfs(node.left)
        right_rob, right_skip = dfs(node.right)
        rob = node.val + left_skip + right_skip
        skip = max(left_rob, left_skip) + max(right_rob, right_skip)
        return (rob, skip)
    rob, skip = dfs(root)
    return max(rob, skip)

