def longest_almost_palindromic_substring(s: str) -> int:
    n = len(s)
    best = 0

    def can_be_pal(l: int, r: int, skip_allowed: bool) -> bool:
        while l < r:
            if s[l] == s[r]:
                l += 1
                r -= 1
            else:
                if not skip_allowed:
                    return False
                # try deleting left character or right character
                return (can_be_pal(l + 1, r, False) or can_be_pal(l, r - 1, False))
        return True

    for i in range(n):
        # try longer substrings first
        for j in range(n - 1, i - 1, -1):
            length = j - i + 1
            if length <= best:
                break
            if can_be_pal(i, j, True):
                best = length
                break  # no longer substring starting at i can be better
    return best

