def make_parity_alternating(nums):
    n = len(nums)
    parity = [x % 2 for x in nums]
    mismA = mismB = 0
    for i in range(n):
        expA = i % 2
        expB = 1 - i % 2
        if parity[i] != expA:
            mismA += 1
        if parity[i] != expB:
            mismB += 1
    best_ops = min(mismA, mismB)
    candidates = []
    if mismA == best_ops:
        candidates.append(0)
    if mismB == best_ops:
        candidates.append(1)

    def best_range_for_pattern(startParity):
        fixed_vals = []
        mism_vals = []
        for i in range(n):
            exp = (i % 2) if startParity == 0 else (1 - i % 2)
            if parity[i] == exp:
                fixed_vals.append(nums[i])
            else:
                mism_vals.append(nums[i])
        if not mism_vals:
            return max(fixed_vals) - min(fixed_vals) if fixed_vals else 0
        lo = min(fixed_vals) if fixed_vals else min(v - 1 for v in mism_vals)
        hi = max(fixed_vals) if fixed_vals else max(v - 1 for v in mism_vals)
        chosen = [v - 1 for v in mism_vals]
        allvals = fixed_vals + chosen
        lo_bound, hi_bound = 0, max(allvals) - min(allvals)

        def feasible(W):
            base_lo, base_hi = hi - W, lo
            if base_lo > base_hi:
                return False
            events = []
            for v in mism_vals:
                a_lo, a_hi = v - 1 - W, v - 1
                b_lo, b_hi = v + 1 - W, v + 1
                if a_hi + 1 >= b_lo:
                    events.append((a_lo, 1))
                    events.append((b_hi + 1, -1))
                else:
                    events.append((a_lo, 1)); events.append((a_hi + 1, -1))
                    events.append((b_lo, 1)); events.append((b_hi + 1, -1))
            pts = sorted(set(e[0] for e in events) | {base_lo, base_hi})
            events_sorted = sorted(events)
            idx = 0
            cur = 0
            needed = len(mism_vals)
            for p in pts:
                while idx < len(events_sorted) and events_sorted[idx][0] <= p:
                    cur += events_sorted[idx][1]
                    idx += 1
                if base_lo <= p <= base_hi and cur >= needed:
                    return True
            return False

        while lo_bound < hi_bound:
            mid = (lo_bound + hi_bound) // 2
            if feasible(mid):
                hi_bound = mid
            else:
                lo_bound = mid + 1
        return lo_bound

    best_range = min(best_range_for_pattern(sp) for sp in candidates)
    return [best_ops, best_range]

