def minCost(s, encCost, flatCost):
    n = len(s)
    pre = [0] * (n + 1)
    for i in range(n):
        pre[i + 1] = pre[i] + (1 if s[i] == '1' else 0)

    def seg_cost(x, y):
        L = y - x
        X = pre[y] - pre[x]
        if X == 0:
            return flatCost
        return L * X * encCost

    memo = {}
    def dfs(x, y):
        if (x, y) in memo:
            return memo[(x, y)]
        # dfs(x,y): min cost to partition s[x..y-1], choosing between keeping it whole
        # or (only if length is even) splitting into two equal halves recursively
        whole = seg_cost(x, y)
        L = y - x
        if L % 2 == 0:
            mid = x + L // 2
            split = dfs(x, mid) + dfs(mid, y)
            res = min(whole, split)
        else:
            res = whole
        memo[(x, y)] = res
        return res

    return dfs(0, n)

def longest_arithmetic_algo(nums):
    n = len(nums)
    if n <= 2:
        return n
    best = 2
    diff_set = set()
    for a in range(n):
        for b in range(n):
            if a != b:
                diff_set.add(nums[b] - nums[a])
    diff_set.add(0)
    for i in range(n):
        candidates = {nums[i]}
        for d in diff_set:
            if i > 0:
                candidates.add(nums[i-1] + d)
            if i < n - 1:
                candidates.add(nums[i+1] - d)
        for repl in candidates:
            arr = nums[:]
            arr[i] = repl
            cur = 1
            local_best = 1
            for j in range(1, n):
                if j >= 2 and arr[j] - arr[j-1] == arr[j-1] - arr[j-2]:
                    cur += 1
                else:
                    cur = 2
                local_best = max(local_best, cur)
            best = max(best, local_best)
    return best


