def max_points_activated(points):
    parent = {}
    size = {}
    def find(x):
        if x not in parent:
            parent[x] = x
            size[x] = 1
        root = x
        while parent[root] != root:
            root = parent[root]
        while parent[x] != root:
            parent[x], x = root, parent[x]
        return root
    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        size[ra] += size[rb]
    M = 3_000_000_000
    for x, y in points:
        union(x, y + M)
    cnt = {}
    for x, y in points:
        r = find(x)
        cnt[r] = cnt.get(r, 0) + 1
    mx1 = mx2 = 0
    for v in cnt.values():
        if v > mx1:
            mx2 = mx1
            mx1 = v
        elif v > mx2:
            mx2 = v
    return mx1 + mx2 + 1

