def min_cost_to_equalize_arrays(A: List[int], B: List[int]) -> int:
    if len(A) != len(B):
        return -1

    diff = Counter()
    for x in A:
        diff[x] += 1
    for y in B:
        diff[y] -= 1

    swaps_needed = 0
    for d in diff.values():
        if d % 2:
            return -1
        if d > 0:
            swaps_needed += d // 2

    return swaps_needed

def count_commas(L: int, R: int) -> int:
    def total_up_to(N):
        N = int(N)
        total = 0
        d = 1
        while True:
            start = 10 ** (d - 1)
            if start > N:
                break
            end = min(N, 10 ** d - 1)
            count = end - start + 1
            commas = (d - 1) // 3
            total += count * commas
            d += 1
        return total
    return total_up_to(R) - total_up_to(L - 1)

