def min_removals(arr: List[int], target: int) -> int:
    n = len(arr)
    dp = {0: 0}
    for v in arr:
        nxt = dict(dp)
        for xor_val, size in dp.items():
            new_xor = xor_val ^ v
            new_size = size + 1
            existing = nxt.get(new_xor)
            if existing is None or new_size > existing:
                nxt[new_xor] = new_size
        dp = nxt
    best = dp.get(target)
    if best is None:
        return -1
    return n - best

import bisect

class EventManager:
    def __init__(self):
        self.by_name = {}
        self.sorted_ts = []
        self.ts_to_name = {}

    def addEvent(self, name, timestamp):
        if name in self.by_name:
            return
        self.by_name[name] = timestamp
        bisect.insort(self.sorted_ts, timestamp)
        self.ts_to_name[timestamp] = name

    def deleteEvent(self, name):
        if name not in self.by_name:
            return
        ts = self.by_name.pop(name)
        idx = bisect.bisect_left(self.sorted_ts, ts)
        self.sorted_ts.pop(idx)
        del self.ts_to_name[ts]

    def getNextEvent(self, name):
        if name not in self.by_name:
            return -1
        ts = self.by_name[name]
        idx = bisect.bisect_left(self.sorted_ts, ts)
        if idx + 1 < len(self.sorted_ts):
            return self.ts_to_name[self.sorted_ts[idx + 1]]
        return -1

    def getPreviousEvent(self, name):
        if name not in self.by_name:
            return -1
        ts = self.by_name[name]
        idx = bisect.bisect_left(self.sorted_ts, ts)
        if idx - 1 >= 0:
            return self.ts_to_name[self.sorted_ts[idx - 1]]
        return -1

class Solution:
    def sortableIntegers(self, nums: list[int]) -> int:
        n = len(nums)
        total = 0
        for k in range(1, n + 1):
            if n % k != 0:
                continue
            d = n // k
            ok = True
            prev_max = float('-inf')
            for b in range(d):
                sub = nums[b*k:(b+1)*k]
                descents = sum(1 for i in range(k) if sub[i] > sub[(i+1) % k])
                if descents > 1:
                    ok = False
                    break
                cur_min, cur_max = min(sub), max(sub)
                if cur_min < prev_max:
                    ok = False
                    break
                prev_max = cur_max
            if ok:
                total += k
        return total

