from math import gcd

def _check(nums, p):
    n = len(nums)
    # only multiples of p can ever belong to a GCD-exactly-p subsequence
    filtered = [(i, nums[i] // p) for i in range(n) if nums[i] % p == 0]
    if not filtered:
        return False
    if len(filtered) < n:
        # not forced to exclude anything for the length<n rule -- use ALL multiples of p,
        # since more elements can only reduce (never increase) the combined GCD
        g = 0
        for _, v in filtered:
            g = gcd(g, v)
        return g == 1
    else:
        # every element is a multiple of p, so we're forced to exclude at least one index;
        # check every 'leave-one-out' GCD via prefix/suffix GCD arrays
        vals = [v for _, v in filtered]
        pre = [0] * (n + 1)
        for i in range(n):
            pre[i + 1] = gcd(pre[i], vals[i])
        suf = [0] * (n + 1)
        for i in range(n - 1, -1, -1):
            suf[i] = gcd(suf[i + 1], vals[i])
        for i in range(n):
            if gcd(pre[i], suf[i + 1]) == 1:
                return True
        return False

def goodSubsequences(nums, p, queries):
