def triangle_angles(sides: List[int]) -> List[float]:
    if len(sides) != 3:
        return []
    a, b, c = sorted(sides)
    if a <= 0:
        return []
    if a + b <= c:
        return []
    def angle(opposite: int, side1: int, side2: int) -> float:
        cos_val = (side1 * side1 + side2 * side2 - opposite * opposite) / (2 * side1 * side2)
        cos_val = max(-1.0, min(1.0, cos_val))
        return round(math.degrees(math.acos(cos_val)), 4)
    return [angle(a, b, c), angle(b, a, c), angle(c, a, b)]

