def count_even_connected_subgraphs(values: List[int], edges: List[Tuple[int, int]]) -> int:
    n = len(values)
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    sum_mask = [0] * (1 << n)
    for mask in range(1, 1 << n):
        lsb = mask & -mask
        idx = lsb.bit_length() - 1
        sum_mask[mask] = sum_mask[mask ^ lsb] + values[idx]

    answer = 0
    visited = [0] * n

    for mask in range(1, 1 << n):
        if sum_mask[mask] & 1:
            continue

        start = 0
        while ((mask >> start) & 1) == 0:
            start += 1

        queue = [start]
        for i in range(n):
            visited[i] = 0
        visited[start] = 1
        visited_count = 0

        while queue:
            v = queue.pop()
            visited_count += 1
            for nb in adj[v]:
                if visited[nb]:
                    continue
                if (mask >> nb) & 1:
                    visited[nb] = 1
                    queue.append(nb)

        if visited_count == mask.bit_count():
            answer += 1

    return answer

