from typing import List

def minCosts(nums: List[int], queries: List[List[int]]) -> List[int]:
    n = len(nums)
    closest = [0] * n
    for i in range(n):
        if i == 0:
            closest[i] = 1
        elif i == n - 1:
            closest[i] = n - 2
        else:
            dl = nums[i] - nums[i - 1]
            dr = nums[i + 1] - nums[i]
            closest[i] = i - 1 if dl <= dr else i + 1

    adj = [[] for _ in range(n)]
    for i in range(n - 1):
        w = nums[i + 1] - nums[i]
        adj[i].append((i + 1, w))
        adj[i + 1].append((i, w))
    for i in range(n):
        adj[i].append((closest[i], 1))

    def dijkstra(src):
        dist = [float('inf')] * n
        dist[src] = 0
        pq = [(0, src)]
        while pq:
            d, u = heapq.heappop(pq)
            if d > dist[u]:
                continue
            for v, w in adj[u]:
                nd = d + w
                if nd < dist[v]:
                    dist[v] = nd
                    heapq.heappush(pq, (nd, v))
        return dist

    ans = []
    cache = {}
    for l, r in queries:
        if l not in cache:
            cache[l] = dijkstra(l)
        ans.append(cache[l][r])
    return ans

