def min_generations(starts: List[List[int]], target: List[int]) -> int:
    target_t: Tuple[int, ...] = tuple(target)
    points = {tuple(p) for p in starts}
    if target_t in points:
        return 0
    # limit generations to avoid infinite loops; problem constraints guarantee small depth
    for gen in range(1, 31):
        new_points = set()
        pts = list(points)
        n = len(pts)
        for i in range(n):
            for j in range(i, n):
                a = pts[i]
                b = pts[j]
                avg = tuple((a[k] + b[k]) // 2 for k in range(len(a)))
                new_points.add(avg)
        points.update(new_points)
        if target_t in points:
            return gen
    return -1

