            j = i
            while j < n:
                cj = s[j]
                if cj == ' ':
                    break
                if cj == '-':
                    joiner = (j > i) and s[j-1].islower() and (j+1 < n) and s[j+1].islower()
                    if not joiner:
                        break
                j += 1
            word = s[i:j]
            cnt[word] = cnt.get(word, 0) + 1
            i = j
        return [cnt.get(q, 0) for q in queries]

