def minimize_array_sum(arr: List[int]) -> int:
    n = len(arr)
    if n == 0:
        return 0
    max_val = max(arr)
    exists = bytearray(max_val + 1)
    for v in arr:
        exists[v] = 1
    INF = 10**18
    min_div = [INF] * (max_val + 1)
    for d in range(1, max_val + 1):
        if not exists[d]:
            continue
        for m in range(d, max_val + 1, d):
            if exists[m] and d < min_div[m]:
                min_div[m] = d
    total = 0
    for v in arr:
        total += min_div[v]
    return total

