def count_kth_roots(L: int, R: int, K: int) -> int:
    l = int(L)
    r = int(R)
    k = int(K)

    def pow_limit(base: int, exp: int, limit: int) -> int:
        """Return base**exp, but stop and return limit+1 if it exceeds limit."""
        res = 1
        for _ in range(exp):
            res *= base
            if res > limit:
                return limit + 1
        return res

    def kth_root_floor(limit: int) -> int:
        """Largest x such that x**k <= limit."""
        if limit < 0:
            return -1
        low = 0
        high = 1
        # increase high until high**k > limit
        while pow_limit(high, k, limit) <= limit:
            high <<= 1
        # binary search in [low, high)
        while low < high:
            mid = (low + high + 1) // 2
            if pow_limit(mid, k, limit) <= limit:
                low = mid
            else:
                high = mid - 1
        return low

    # count = floor_R - floor_(L-1)
    floor_r = kth_root_floor(r)
    floor_l_minus_one = kth_root_floor(l - 1)
    return max(0, floor_r - floor_l_minus_one)  # TIME: O(log max(R, L)) SPACE: O(1)

