def smallest_unique_subarray(nums: List[int]) -> int:
    n = len(nums)
    if n == 0:
        return -1
    MOD1, MOD2, BASE, OFFSET = 1_000_000_007, 1_000_000_009, 91138233, 10**9 + 7
    pow1 = [1] * (n + 1)
    pow2 = [1] * (n + 1)
    for i in range(1, n + 1):
        pow1[i] = (pow1[i - 1] * BASE) % MOD1
        pow2[i] = (pow2[i - 1] * BASE) % MOD2
    pref1 = [0] * (n + 1)
    pref2 = [0] * (n + 1)
    for i, v in enumerate(nums):
        val = v + OFFSET
        pref1[i + 1] = (pref1[i] * BASE + val) % MOD1
        pref2[i + 1] = (pref2[i] * BASE + val) % MOD2
    def sub_hash(l, r):
        h1 = (pref1[r] - pref1[l] * pow1[r - l]) % MOD1
        h2 = (pref2[r] - pref2[l] * pow2[r - l]) % MOD2
        return (h1, h2)
    for length in range(1, n + 1):
        count = {}
        for start in range(0, n - length + 1):
            h = sub_hash(start, start + length)
            count[h] = count.get(h, 0) + 1
        if any(occ == 1 for occ in count.values()):
            return length
    return n

class Solution:
    def maxIntersectionSum(self, grid):
        m = len(grid); n = len(grid[0])
        dp = {}
        for r1 in range(m):
            for r2 in range(m):
                lo = max(0, r2)
                hi = min(r1, m-1)
                contrib = sum(grid[r][0] for r in range(lo, hi+1)) if lo <= hi else 0
                key = (r1, r2)
                if key not in dp or dp[key] < contrib:
                    dp[key] = contrib
        for c in range(1, n):
            ndp = {}
            for (pr1, pr2), val in dp.items():
                for r1 in range(pr1, m):
                    for r2 in range(0, pr2+1):
                        lo = max(pr1, r2)
                        hi = min(r1, pr2)
                        contrib = sum(grid[r][c] for r in range(lo, hi+1)) if lo <= hi else 0
                        nkey = (r1, r2)
                        nv = val + contrib
                        if nkey not in ndp or ndp[nkey] < nv:
                            ndp[nkey] = nv
            dp = ndp
        return dp.get((m-1, 0), 0)

