def number_of_pairs_after_increment(arr_a: List[int], arr_b: List[int], queries: List[List[int]]) -> List[int]:
    # frequency maps for current values
    freq_a: Dict[int, int] = {}
    for v in arr_a:
        freq_a[v] = freq_a.get(v, 0) + 1

    freq_b: Dict[int, int] = {}
    for v in arr_b:
        freq_b[v] = freq_b.get(v, 0) + 1

    results: List[int] = []

    for q in queries:
        if not q:
            continue
        if q[0] == 1:
            # increment operation on arr_b: [1, l, r, x]
            _, l, r, x = q
            l = max(l, 0)
            r = min(r, len(arr_b) - 1)
            for i in range(l, r + 1):
                old_val = arr_b[i]
                new_val = old_val + x
                # update frequency map for b
                freq_b[old_val] -= 1
                if freq_b[old_val] == 0:
                    del freq_b[old_val]
                freq_b[new_val] = freq_b.get(new_val, 0) + 1
                # update the array
                arr_b[i] = new_val
        elif q[0] == 2:
            # query operation: [2, k]
            _, k = q
            total = 0
            # iterate over smaller frequency map for efficiency
            if len(freq_a) <= len(freq_b):
                for val_a, cnt_a in freq_a.items():
                    cnt_b = freq_b.get(k - val_a, 0)
                    total += cnt_a * cnt_b
            else:
                for val_b, cnt_b in freq_b.items():
                    cnt_a = freq_a.get(k - val_b, 0)
                    total += cnt_a * cnt_b
            results.append(total)
        else:
            continue

    return results

