def min_operations(nums: List[int], k: int) -> int:
    n = len(nums)
    residues = [v % k for v in nums]
    best = float('inf')
    for x in range(k):
        for y in range(k):
            if x == y:
                continue
            cost = 0
            for i in range(n):
                target = x if i % 2 == 0 else y
                diff = abs(residues[i] - target)
                cost += min(diff, k - diff)
            if cost < best:
                best = cost
    return best

