def kth_largest_element(nums: List[int], k: int) -> int:
    heap: List[int] = []

    def parent(i: int) -> int:
        return (i - 1) >> 1

    def left(i: int) -> int:
        return i * 2 + 1

    def right(i: int) -> int:
        return i * 2 + 2

    def swap(i: int, j: int) -> None:
        heap[i], heap[j] = heap[j], heap[i]

    def heapify_up(i: int) -> None:
        while i > 0 and heap[parent(i)] > heap[i]:
            swap(i, parent(i))
            i = parent(i)

    def heapify_down(i: int) -> None:
        while True:
            smallest = i
            l = left(i)
            r = right(i)
            if l < len(heap) and heap[l] < heap[smallest]:
                smallest = l
            if r < len(heap) and heap[r] < heap[smallest]:
                smallest = r
            if smallest == i:
                break
            swap(i, smallest)
            i = smallest

    def push(val: int) -> None:
        heap.append(val)
        heapify_up(len(heap) - 1)

    def pop() -> int:
        if len(heap) == 1:
            return heap.pop()
        top = heap[0]
        heap[0] = heap.pop()
        heapify_down(0)
        return top

    def peek() -> int:
        return heap[0]

    for i in range(len(nums)):
        push(nums[i])
        if len(heap) > k:
            pop()

    return peek()

