    def build(node, l, r):
        if l == r:
            tree[node] = nums[l]
            return
        mid = (l + r) // 2
        build(node * 2, l, mid)
        build(node * 2 + 1, mid + 1, r)
        tree[node] = tree[node * 2] + tree[node * 2 + 1]

    def update(node, l, r, idx, val):
        if l == r:
            tree[node] = val
            return
        mid = (l + r) // 2
        if idx <= mid:
            update(node * 2, l, mid, idx, val)
        else:
            update(node * 2 + 1, mid + 1, r, idx, val)
        tree[node] = tree[node * 2] + tree[node * 2 + 1]

    def query(node, l, r, ql, qr):
        if ql <= l and r <= qr:
            return tree[node]
        if r < ql or l > qr:
            return 0
        mid = (l + r) // 2
        return query(node * 2, l, mid, ql, qr) + query(node * 2 + 1, mid + 1, r, ql, qr)

    if n:
        build(1, 0, n - 1)

    answers = []
    for q in queries:
        if q[0] == 'update':
            idx = q[1]
            val = q[2]
            update(1, 0, n - 1, idx, val)
        else:
            left = q[1]
            right = q[2]
            answers.append(query(1, 0, n - 1, left, right))
    return answers

