def min_cost(nums: List[int]) -> int:
    n = len(nums)
    min_cost_val = float('inf')
    for i in range(n - 2):
        for j in range(i + 1, n - 1):
            cost = nums[0] + nums[i + 1] + nums[j + 1]
            min_cost_val = min(min_cost_val, cost)
    return min_cost_val

