def min_operations(nums: List[int], k: int) -> int:
    xor_val = 0
    for num in nums:
        xor_val ^= num
    diff = xor_val ^ k
    return diff.bit_count()

from typing import List

def maximum_good_subarray_sum(nums: List[int], k: int) -> int:
    max_sum = float('-inf')
    prefix_sum = [0]
    for i in range(len(nums)):
        prefix_sum.append(prefix_sum[i] + nums[i])
    for i in range(len(nums)):
        for j in range(i, len(nums)):
            if abs(nums[i] - nums[j]) == k:
                current_sum = prefix_sum[j + 1] - prefix_sum[i]
                if current_sum > max_sum:
                    max_sum = current_sum
    return 0 if max_sum == float('-inf') else max_sum

