def beautiful_indices(s: str, a: str, b: str, k: int) -> List[int]:
    beautiful = []
    len_s = len(s)
    len_a = len(a)
    len_b = len(b)
    for i in range(len_s - len_a + 1):
        if s[i:i + len_a] == a:
            for j in range(len_s - len_b + 1):
                if s[j:j + len_b] == b and abs(i - j) <= k:
                    beautiful.append(i)
                    break
    return sorted(set(beautiful))

