def count_set_bits(x: int) -> int:
    count = 0
    while x:
        count += x & 1
        x >>= 1
    return count

def can_sort_array(nums: List[int]) -> bool:
    sorted_nums = sorted(nums)
    set_bits_count = [0] * len(nums)
    for i in range(len(nums)):
        set_bits_count[i] = count_set_bits(nums[i])
    sorted_set_bits_count = [0] * len(nums)
    for i in range(len(nums)):
        sorted_set_bits_count[i] = count_set_bits(sorted_nums[i])
    for i in range(len(nums)):
        if set_bits_count[i] != sorted_set_bits_count[i]:
            return False
    return True
